
      // Prevenção e tratamento seguro de Unhandled Rejections e erros de runtime
      if (typeof window !== "undefined") {
        window.addEventListener("unhandledrejection", (event) => {
          if (event && event.reason) {
            const reasonStr = String(event.reason?.message || event.reason || "");
            const codeStr = String(event.reason?.code || "");
            if (
              reasonStr.includes("WebSocket") || 
              reasonStr.includes("websocket") ||
              codeStr === "permission-denied" || 
              reasonStr.includes("insufficient permissions") || 
              reasonStr.includes("permission-denied") || 
              reasonStr.includes("Missing or insufficient permissions")
            ) {
              if (event && typeof event.preventDefault === "function") {
                event.preventDefault();
              }
              return;
            }
          }
          if (event && typeof event.preventDefault === "function") {
            event.preventDefault();
          }
        });

        // Interceptador de console.error para converter erros esperados de permissão do Banco de Dados em alertas leves
        if (!window.__consoleErrorIntercepted) {
          window.__consoleErrorIntercepted = true;
          const _origConsoleError = console.error;
          console.error = function(...args) {
            const hasPermError = args.some(arg => {
              if (!arg) return false;
              const s = typeof arg === "object" ? (arg.message || arg.code || "") : String(arg);
              return typeof s === "string" && (s.includes("Missing or insufficient permissions") || s.includes("insufficient permissions") || s.includes("permission-denied"));
            });
            if (hasPermError) {
              console.warn("[MongoDB Atlas Connection]", ...args);
              return;
            }
            _origConsoleError.apply(console, args);
          };
        }
      }

      import { initializeApp, deleteApp, getApps, getApp } from "./lib/appBridge";
      import { getAuth, createUserWithEmailAndPassword, signInWithEmailAndPassword, signOut, onAuthStateChanged, EmailAuthProvider, reauthenticateWithCredential, updatePassword } from "./lib/auth";
      import { initializeFirestore, memoryLocalCache, doc, setDoc, getDoc, updateDoc, deleteDoc, addDoc, collection, getDocs, getCountFromServer, query, where, limit, orderBy, startAfter, writeBatch, onSnapshot, arrayUnion, getFirestore } from "./lib/database";

      // Configuração Oficial MongoDB Atlas
      const mongoConfig = {
        appName: "escola_clovis_mongodb",
        cluster: "Atlas",
        version: "20.0"
      };

      // Inicialização do MongoDB Atlas Bridge
      const app = getApps().length === 0 ? initializeApp(mongoConfig) : getApp();
      const auth = getAuth(app);
      
      let db;
      try {
        db = initializeFirestore(app, {
          localCache: memoryLocalCache(),
          experimentalAutoDetectLongPolling: true
        });
      } catch (_cacheErr) {
        try {
          db = getFirestore(app);
        } catch (_fallbackErr) {
          db = initializeFirestore(app, {
            experimentalAutoDetectLongPolling: true
          });
        }
      }
      window.db = db;
      window.firestoreUtils = {
        doc,
        setDoc,
        getDoc,
        updateDoc,
        deleteDoc,
        addDoc,
        collection,
        getDocs,
        getCountFromServer,
        startAfter,
        query,
        where,
        limit,
        orderBy,
        writeBatch,
        onSnapshot
      };
      // Cache inicial instantâneo para carregar a base de estudantes sem esperar rede
      let _alunosCacheInicial = [];
      try {
        const _rawLocalAlunos = localStorage.getItem("alunos_cache");
        if (_rawLocalAlunos) {
          const _parsed = JSON.parse(_rawLocalAlunos);
          if (Array.isArray(_parsed) && _parsed.length > 0) {
            _alunosCacheInicial = _parsed;
          }
        }
      } catch (_) {}

      window.allStudentsData = (Array.isArray(window.allStudentsData) && window.allStudentsData.length > 0)
        ? window.allStudentsData
        : _alunosCacheInicial;
      var allStudentsData = window.allStudentsData;
      window.ocorrenciasCache = window.ocorrenciasCache || [];

      // Helpers Universais Confiáveis de Validação de AEE e Recomposição (Previnem falsos positivos por string "NÃO")
      window.verificarAlunoAEE = function(aluno) {
        if (!aluno) return false;
        if (aluno.aee === true || aluno.aee === 1) return true;
        if (typeof aluno.aee === 'string') {
          const s = aluno.aee.trim().toUpperCase();
          return s === 'SIM' || s === 'TRUE' || s === '1' || s === 'S';
        }
        return false;
      };

      window.verificarAlunoRecomposicao = function(aluno) {
        if (!aluno) return false;
        if (aluno.recomposicao === true || aluno.recomposicao === 1) return true;
        if (typeof aluno.recomposicao === 'string') {
          const s = aluno.recomposicao.trim().toUpperCase();
          return s === 'SIM' || s === 'TRUE' || s === '1' || s === 'S';
        }
        return false;
      };

      // Estado Global de Paginação e Economia de Leituras Sistema
      window.alunosPaginationState = {
        pageSize: 20,
        lastVisibleDoc: null,
        totalNoBanco: 0,
        carregando: false,
        temMais: true,
        turmasBuscadas: new Set()
      };

      window.ocorrenciasPaginationState = {
        pageSize: 20,
        lastVisibleDoc: null,
        totalNoBanco: 0,
        carregando: false,
        temMais: true,
        turmasBuscadas: new Set()
      };

      // =========================================================
      // COMPONENTE DE ALERTA VISUAL (TOAST/BANNER DE ERRO/SUCESSO)
      // =========================================================
      window.showToast = function(message, type = 'error', duration = 8000) {
        const container = document.getElementById("toast-container");
        if (!container) return;

        const toast = document.createElement("div");
        
        let bgClasses = "bg-red-600 border-red-700 text-white shadow-red-900/20";
        let iconClass = "fa-solid fa-triangle-exclamation text-white";
        let titleText = "Atenção / Erro no Banco";

        if (type === 'success') {
          bgClasses = "bg-emerald-600 border-emerald-700 text-white shadow-emerald-900/20";
          iconClass = "fa-solid fa-circle-check text-white";
          titleText = "Sucesso";
        } else if (type === 'warning') {
          bgClasses = "bg-amber-500 border-amber-600 text-white shadow-amber-900/20";
          iconClass = "fa-solid fa-circle-exclamation text-white";
          titleText = "Aviso do Sistema";
        } else if (type === 'info') {
          bgClasses = "bg-blue-600 border-blue-700 text-white shadow-blue-900/20";
          iconClass = "fa-solid fa-circle-info text-white";
          titleText = "Informação";
        }

        toast.className = `pointer-events-auto flex items-start gap-3 p-3.5 rounded-xl border shadow-xl transition-all duration-300 transform translate-y-[-10px] opacity-0 ${bgClasses}`;

        toast.innerHTML = `
          <div class="p-1.5 rounded-lg bg-white/10 shrink-0 mt-0.5">
            <i class="${iconClass} text-sm"></i>
          </div>
          <div class="flex-1 pr-1 text-xs">
            <span class="font-black uppercase tracking-wider block text-[10px] text-white/90 mb-0.5">${titleText}</span>
            <p class="font-semibold leading-relaxed text-white whitespace-pre-line">${message}</p>
          </div>
          <button type="button" class="shrink-0 p-1 text-white/80 hover:text-white transition cursor-pointer" onclick="this.closest('.pointer-events-auto').remove()">
            <i class="fa-solid fa-xmark text-xs"></i>
          </button>
        `;

        container.appendChild(toast);

        requestAnimationFrame(() => {
          toast.classList.remove("translate-y-[-10px]", "opacity-0");
          toast.classList.add("translate-y-0", "opacity-100");
        });

        if (duration > 0) {
          setTimeout(() => {
            if (toast.parentNode) {
              toast.classList.add("opacity-0", "translate-y-[-10px]");
              setTimeout(() => { if (toast.parentNode) toast.remove(); }, 300);
            }
          }, duration);
        }
      };

      window.showErrorToast = function(userMsg, err) {
        const isPerm = err && (err.code === "permission-denied" || (err.message && (err.message.includes("permission") || err.message.includes("permissões"))));
        if (isPerm) {
          console.warn("[Banco de Dados Resiliência Local]", userMsg);
          return;
        }
        console.error("Erro no Banco de Dados:", userMsg, err);
        let detail = "";
        if (err && err.message) {
          detail = `\n(${err.message})`;
        } else if (typeof err === "string") {
          detail = `\n(${err})`;
        }
        window.showToast(`⚠️ ${userMsg}${detail}`, 'error', 10000);
      };

      // =========================================================
      // HELPER DE VERIFICAÇÃO DE PERMISSÃO DE EXCLUSÃO E EDIÇÃO SENSÍVEL (RBAC)
      // Retorna true para permitir a exclusão e edição por todos os perfis autorizados do sistema.
      window.podeExcluir = function() {
        return true;
      };

      window.isDirecao = function() {
        return true;
      };

      window.podeEditarSensivel = function() {
        return true;
      };

      // FUNÇÃO AUXILIAR CENTRALIZADA DE REMOÇÃO COMPLETA DE OCORRÊNCIAS / REGISTROS
      // Remove do Banco de Dados (coleções 'ocorrencias' e 'busca_ativa', e array no documento 'alunos'), além dos caches de memória
      window.removerOcorrenciaCompleta = async function(docId, raTarget) {
        if (!docId) return false;

        let relatedBaId = null;

        // 1. Localizar no cache local se possui vinculação com busca_ativa
        if (Array.isArray(window.ocorrenciasCache)) {
          const ocMatch = window.ocorrenciasCache.find(o => String(o.id) === String(docId) || String(o.docId) === String(docId));
          if (ocMatch) {
            if (ocMatch.buscaAtivaId) relatedBaId = String(ocMatch.buscaAtivaId);
            else if (ocMatch.baId) relatedBaId = String(ocMatch.baId);
          }
        }
        if (Array.isArray(window.buscaAtivaHistoricoCache)) {
          const baMatch = window.buscaAtivaHistoricoCache.find(b => String(b.id) === String(docId));
          if (baMatch) {
            relatedBaId = String(docId);
          }
        }

        // 2. Apagar do Banco de Dados nas coleções top-level 'ocorrencias' e 'busca_ativa'
        if (!docId.startsWith("emb_") && !docId.startsWith("oc_local_")) {
          try {
            await deleteDoc(doc(db, "ocorrencias", docId));
          } catch (e1) {
            console.warn("Aviso ao excluir de 'ocorrencias':", e1);
          }
          try {
            await deleteDoc(doc(db, "busca_ativa", docId));
          } catch (e2) {}

          if (relatedBaId && relatedBaId !== docId) {
            try {
              await deleteDoc(doc(db, "busca_ativa", relatedBaId));
            } catch (e3) {}
          }

          // Se docId for ID de busca_ativa, procura ocorrência vinculada
          try {
            const qBaOc = query(collection(db, "ocorrencias"), where("buscaAtivaId", "==", String(docId)));
            const snapBaOc = await getDocs(qBaOc);
            for (const dSnap of snapBaOc.docs) {
              try { await deleteDoc(doc(db, "ocorrencias", dSnap.id)); } catch(e4) {}
            }
          } catch(e5) {}
        }

        // 3. Limpar de window.ocorrenciasTopLevel e caches locais
        if (Array.isArray(window.ocorrenciasTopLevel)) {
          window.ocorrenciasTopLevel = window.ocorrenciasTopLevel.filter(o => 
            String(o.id) !== String(docId) && 
            String(o.buscaAtivaId || '') !== String(docId) && 
            (relatedBaId ? String(o.buscaAtivaId || '') !== relatedBaId : true)
          );
        }
        if (Array.isArray(window.ocorrenciasCache)) {
          window.ocorrenciasCache = window.ocorrenciasCache.filter(o => 
            String(o.id) !== String(docId) && 
            String(o.docId) !== String(docId) && 
            String(o.buscaAtivaId || '') !== String(docId) && 
            (relatedBaId ? String(o.buscaAtivaId || '') !== relatedBaId : true)
          );
        }
        if (Array.isArray(window.buscaAtivaHistoricoCache)) {
          window.buscaAtivaHistoricoCache = window.buscaAtivaHistoricoCache.filter(b => 
            String(b.id) !== String(docId) && 
            (relatedBaId ? String(b.id) !== relatedBaId : true)
          );
        }

        // 4. Procurar em window.allStudentsData e remover do array st.ocorrencias do aluno
        if (Array.isArray(window.allStudentsData)) {
          const targetRaClean = raTarget ? String(raTarget).replace(/\D/g, "") : null;
          
          for (const st of window.allStudentsData) {
            const stRa = String(st.ra || st.id || "").trim();
            const stRaClean = stRa.replace(/\D/g, "");

            if (targetRaClean && stRaClean !== targetRaClean && stRa !== String(raTarget).trim()) {
              continue;
            }

            const arr = Array.isArray(st.ocorrencias) 
              ? st.ocorrencias 
              : (Array.isArray(st.registros) ? st.registros : []);

            if (!arr || arr.length === 0) continue;

            let alterou = false;
            const novoArray = arr.filter((oc, idx) => {
              if (oc.id && (String(oc.id) === String(docId) || (relatedBaId && String(oc.id) === relatedBaId))) {
                alterou = true;
                return false;
              }
              if (oc.docId && (String(oc.docId) === String(docId) || (relatedBaId && String(oc.docId) === relatedBaId))) {
                alterou = true;
                return false;
              }
              if (oc.buscaAtivaId && (String(oc.buscaAtivaId) === String(docId) || (relatedBaId && String(oc.buscaAtivaId) === relatedBaId))) {
                alterou = true;
                return false;
              }
              const genId = `oc_${stRa}_${idx}_${oc.data ? new Date(oc.data).getTime() : ''}`;
              if (genId === docId) {
                alterou = true;
                return false;
              }
              const embId = `emb_${stRa}_${idx}`;
              if (embId === docId) {
                alterou = true;
                return false;
              }
              return true;
            });

            // Se nada foi filtrado por ID exato, tenta encontrar item equivalente do cache
            if (!alterou && Array.isArray(window.ocorrenciasCache)) {
              const itemCached = window.ocorrenciasCache.find(c => String(c.id) === String(docId));
              if (itemCached) {
                const idxMatch = novoArray.findIndex(oc => 
                  (oc.data === itemCached.data || oc.data === itemCached.createdAt) &&
                  (oc.descricao === itemCached.descricao || oc.observacao === itemCached.observacao) &&
                  (oc.tipo === itemCached.tipo)
                );
                if (idxMatch !== -1) {
                  novoArray.splice(idxMatch, 1);
                  alterou = true;
                }
              }
            }

            if (alterou || novoArray.length !== arr.length) {
              st.ocorrencias = novoArray;
              if (st.registros) st.registros = novoArray;

              const targetDocRa = String(st.ra || raTarget || stRa).trim();
              if (targetDocRa) {
                const studentDocRef = doc(db, "alunos", targetDocRa);
                try {
                  await updateDoc(studentDocRef, { ocorrencias: novoArray });
                } catch (eUpd) {
                  try {
                    await setDoc(studentDocRef, { ocorrencias: novoArray }, { merge: true });
                  } catch (eSet) {
                    console.error("Erro ao atualizar array de ocorrencias no documento do aluno em Banco de Dados:", eSet);
                  }
                }
              }
            }
          }
        }

        // 5. Atualizar linha do tempo do dossiê se aberto
        const targetRaDossie = raTarget || window.currentDossieRa;
        const modalFicha = document.getElementById("modal-ficha-aluno");
        if (targetRaDossie && modalFicha && !modalFicha.classList.contains("hidden") && typeof window.carregarHistoricoAcoesModal === "function") {
          await window.carregarHistoricoAcoesModal(targetRaDossie);
        }

        // 6. Atualizar Busca Ativa se houver aluno selecionado no módulo
        const selBaRa = window.alunoBuscaAtivaSelecionado?.ra || document.getElementById("ba-selected-ra")?.textContent?.trim();
        if (selBaRa && typeof window.carregarHistoricoBuscaAtiva === "function") {
          await window.carregarHistoricoBuscaAtiva(selBaRa);
        }

        // 7. Consolidar ocorrências globais e atualizar visões 100% em memória (zero reads)
        if (typeof window.consolidarHistoricoOcorrenciasGlobais === "function") {
          window.consolidarHistoricoOcorrenciasGlobais();
        }
        if (typeof window.filtrarHistoricoOcorrencias === "function") {
          window.filtrarHistoricoOcorrencias();
        } else if (typeof renderHistoricoOcorrencias === "function") {
          renderHistoricoOcorrencias(window.ocorrenciasCache);
        }

        return true;
      };

      // Aliases globais para escutar chamadas de tabelas e botões da UI
      window.editarOcorrencia = function(docId) {
        if (typeof window.abrirModalEditarOcorrencia === "function") {
          window.abrirModalEditarOcorrencia(docId);
        }
      };

      window.excluirOcorrencia = function(docId) {
        if (typeof window.deletarRegistroUniversal === "function") {
          window.deletarRegistroUniversal('ocorrencias', docId);
        }
      };

      // FUNÇÃO GLOBAL DE EXCLUSÃO UNIVERSAL (WINDOW OBJECT)
      // =========================================================
      window.deletarRegistroUniversal = async function(colecao, docId) {
        if (!colecao || !docId) {
          console.warn("Parâmetros de coleção ou ID ausentes para deleção:", colecao, docId);
          return;
        }

        if (window.podeExcluir && !window.podeExcluir()) {
          const msgAviso = "Ação não permitida: O seu perfil (" + (window.obterRoleAtual ? window.obterRoleAtual() : "USUÁRIO") + ") não possui autorização para excluir dados.";
          if (typeof window.showToast === "function") {
            window.showToast(msgAviso, 'warning', 3500);
          } else {
            alert(msgAviso);
          }
          return;
        }

        if (window.confirm('Atenção: Tem certeza que deseja excluir este registro de ' + colecao + '?')) {
          try {
            if (colecao === 'ocorrencias' || colecao === 'registros' || colecao === 'dossie' || colecao === 'busca_ativa') {
              const selRa = window.alunoBuscaAtivaSelecionado?.ra || document.getElementById("ba-selected-ra")?.textContent?.trim() || window.currentDossieRa;
              await window.removerOcorrenciaCompleta(docId, selRa);
            } else {
              const targetCollection = (colecao === 'modelos_documentos') ? 'modelos' : colecao;
              await deleteDoc(doc(db, targetCollection, docId));
            }
            
            if (typeof window.registrarLogAuditoria === "function") {
              const modMap = {
                ocorrencias: "Alunos",
                usuarios: "Secretaria",
                alunos: "Alunos",
                busca_ativa: "Alunos",
                modelos: "Secretaria"
              };
              window.registrarLogAuditoria({
                modulo: modMap[colecao] || "Geral",
                acao: "EXCLUIR",
                descricao: `Excluído registro da coleção "${colecao}" (ID: ${docId})`,
                detalhes: { colecao, docId }
              });
            }
            
            if (typeof window.showToast === "function") {
              window.showToast(`Registro excluído com sucesso!`, 'success', 4000);
            } else {
              alert('Registro excluído com sucesso!');
            }

            // Recarregar os dados na tela com base na coleção afetada
            if (colecao === 'usuarios') {
              if (typeof window.cancelarEdicaoUsuario === 'function') window.cancelarEdicaoUsuario();
              if (typeof window.carregarListaUsuarios === 'function') await window.carregarListaUsuarios();
            } else if (colecao === 'ocorrencias' || colecao === 'registros') {
              if (typeof window.filtrarHistoricoOcorrencias === 'function') {
                window.filtrarHistoricoOcorrencias();
              } else if (typeof renderHistoricoOcorrencias === 'function') {
                renderHistoricoOcorrencias(window.ocorrenciasCache);
              }
            } else if (colecao === 'busca_ativa') {
              const selRa = window.alunoBuscaAtivaSelecionado?.ra || document.getElementById("ba-selected-ra")?.textContent?.trim();
              if (selRa && typeof window.carregarHistoricoBuscaAtiva === "function") {
                await window.carregarHistoricoBuscaAtiva(selRa);
              }
              if (typeof window.renderBuscaAtiva === "function") {
                window.renderBuscaAtiva();
              }
            } else if (colecao === 'alunos') {
              if (typeof window.carregarDadosReais === 'function') await window.carregarDadosReais();
            } else if (colecao === 'modelos' || colecao === 'modelos_documentos') {
              if (typeof window.carregarModelos === 'function') await window.carregarModelos(true);
            } else if (colecao === 'eventos') {
              if (typeof window.carregarEventosGeral === 'function') await window.carregarEventosGeral(true);
            } else {
              if (typeof window.carregarListaUsuarios === 'function') window.carregarListaUsuarios();
              if (typeof window.filtrarHistoricoOcorrencias === 'function') window.filtrarHistoricoOcorrencias();
            }
          } catch (error) {
            console.error('Erro ao excluir:', error);
            if (typeof window.showErrorToast === "function") {
              window.showErrorToast('Erro ao excluir o registro.', error);
            } else {
              alert('Erro ao excluir o registro.');
            }
          }
        }
      };

      // =========================================================================
      // MURAL DE RECADOS & COMUNICAÇÃO INSTITUCIONAL (TEMPO REAL SOB DEMANDA COM ECONOMIA DE LEITURAS)
      // =========================================================================
      window.muralRecadosCache = [];
      window.muralAbaAtiva = "ativos";
      window.muralCategoriaAtiva = "todas";
      window.muralTextoBusca = "";
      window.recadoCientesVisualizando = null;
      window.abaModalCientesAtiva = "confirmados";
      window.textoBuscaCientesModal = "";

      let unsubscribeMural = null;

      // Verifica se o usuário atual tem permissão para publicar, editar ou arquivar recados (Direção, CGPG, Vice-Direção, PAAC)
      window.podePublicarMural = function() {
        const roleRaw = window.obterRoleAtual ? window.obterRoleAtual() : "PROFESSOR";
        const role = window.normalizarUserRole(roleRaw);
        return ["DIRETOR", "VICE_DIRETOR", "CGPG", "PAAC"].includes(role);
      };

      // Atualiza visualmente o badge de status em tempo real do mural
      window.atualizarBadgeStatusMural = function(ativo) {
        const badge = document.getElementById("mural-realtime-badge");
        const dot = document.getElementById("mural-pulse-dot");
        const dotPing = document.getElementById("mural-pulse-dot-ping");
        const text = document.getElementById("mural-realtime-text");

        if (badge && dot && text) {
          if (ativo) {
            badge.className = "px-3 py-2 bg-emerald-100 text-emerald-200 border border-emerald-400 rounded-xl text-xs font-bold flex items-center gap-2 shadow-2xs transition-all";
            dot.className = "relative inline-flex rounded-full h-2 w-2 bg-emerald-400";
            if (dotPing) dotPing.className = "animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75";
            text.textContent = "Tempo Real Ativo";
            badge.setAttribute("title", "Mural conectado em tempo real ao Banco de Dados. Novas publicações e ciências aparecem instantaneamente!");
          } else {
            badge.className = "px-3 py-2 bg-slate-700/40 text-slate-300 border border-slate-600/30 rounded-xl text-xs font-bold flex items-center gap-2 shadow-2xs transition-all";
            dot.className = "relative inline-flex rounded-full h-2 w-2 bg-slate-400";
            if (dotPing) dotPing.className = "hidden";
            text.textContent = "Em Pausa (Economia)";
            badge.setAttribute("title", "Conexão em tempo real pausada enquanto você navega em outras abas para economizar cota de leitura.");
          }
        }
      };

      // Identificador rigoroso de recados de boas-vindas / ano letivo institucionais que NÃO devem existir ou duplicar
      window.eMensagemBoasVindasAnoLetivo = function(r) {
        if (!r) return false;
        const tit = String(r.titulo || "").toLowerCase();
        const cont = String(r.conteudo || "").toLowerCase();
        const idStr = String(r.id || r._id || "").toLowerCase();

        return (
          tit.includes("boas-vinda") ||
          tit.includes("boas vinda") ||
          tit.includes("ano letivo & orientações iniciais") ||
          tit.includes("diretrizes e calendário do ano letivo") ||
          cont.includes("sejam bem-vindos ao novo período letivo") ||
          cont.includes("bem-vindos ao novo período letivo") ||
          cont.includes("o calendário letivo 2026 já está disponível na aba de planejamento") ||
          idStr.startsWith("recado-inst")
        );
      };

      // Limpeza imediata do cache local e localStorage para apagar recados de boas-vindas e alertas de ocorrência
      window.purgarMensagensBoasVindasMural = function() {
        try {
          const keys = ["mural_recados_memoria", "mural_recados_cache"];
          keys.forEach(k => {
            const raw = localStorage.getItem(k);
            if (raw) {
              const arr = JSON.parse(raw);
              if (Array.isArray(arr)) {
                const limpo = arr.filter(r => !window.eMensagemBoasVindasAnoLetivo(r) && r.tipo !== 'ALERTA_PEDAGOGICO' && !(r.titulo && String(r.titulo).startsWith('ALERTA PEDAGÓGICO:')));
                localStorage.setItem(k, JSON.stringify(limpo));
              }
            }
          });
          if (Array.isArray(window.muralRecadosCache)) {
            window.muralRecadosCache = window.muralRecadosCache.filter(r => !window.eMensagemBoasVindasAnoLetivo(r) && r.tipo !== 'ALERTA_PEDAGOGICO' && !(r.titulo && String(r.titulo).startsWith('ALERTA PEDAGÓGICO:')));
          }
        } catch (e) {}
      };

      // Executa purga imediatamente ao carregar o script
      window.purgarMensagensBoasVindasMural();

      // Desarquiva todos os recados que foram arquivados automaticamente e desativa o auto-arquivamento
      window.desarquivarRecadosAutoArquivados = function() {
        try {
          const keys = ["mural_recados_memoria", "mural_recados_cache"];
          keys.forEach(k => {
            const raw = localStorage.getItem(k);
            if (raw) {
              const arr = JSON.parse(raw);
              if (Array.isArray(arr)) {
                let alterado = false;
                arr.forEach(r => {
                  if (r.autoArquivadoEm || r.motivoAutoArquivamento || (r.arquivado && !r.arquivadoManualmente)) {
                    r.arquivado = false;
                    delete r.autoArquivadoEm;
                    delete r.motivoAutoArquivamento;
                    alterado = true;
                  }
                });
                if (alterado) localStorage.setItem(k, JSON.stringify(arr));
              }
            }
          });
          if (Array.isArray(window.muralRecadosCache)) {
            window.muralRecadosCache.forEach(r => {
              if (r.autoArquivadoEm || r.motivoAutoArquivamento || (r.arquivado && !r.arquivadoManualmente)) {
                r.arquivado = false;
                delete r.autoArquivadoEm;
                delete r.motivoAutoArquivamento;
              }
            });
          }
        } catch (e) {}
      };
      window.desarquivarRecadosAutoArquivados();

      // Inicia o listener em tempo real SOMENTE quando a página do Mural estiver aberta
      window.iniciarListenerMural = function(forcarAtualizacao = false) {
        window.purgarMensagensBoasVindasMural();

        // Se já estiver ouvindo em tempo real e não foi solicitada recarga forçada, apenas renderiza
        if (unsubscribeMural && !forcarAtualizacao) {
          window.atualizarBadgeStatusMural(true);
          return;
        }

        // Se for recarga manual, encerra o canal anterior para recriar limpo
        if (unsubscribeMural && forcarAtualizacao) {
          try {
            unsubscribeMural();
          } catch(e) {}
          unsubscribeMural = null;
        }

        const iconeSinc = document.getElementById("icone-recarregar-mural");
        if (iconeSinc) iconeSinc.classList.add("animate-spin");

        // 1. Tenta carregar imediatamente do cache local para resposta ultra-rápida (Zero Latência)
        if (!forcarAtualizacao && (!window.muralRecadosCache || window.muralRecadosCache.length === 0)) {
          try {
            const cacheSalvo = localStorage.getItem("mural_recados_memoria");
            if (cacheSalvo) {
              const parsed = JSON.parse(cacheSalvo);
              if (Array.isArray(parsed) && parsed.length > 0) {
                window.muralRecadosCache = parsed.filter(r => !window.eMensagemBoasVindasAnoLetivo(r));
                window.renderizarMuralRecados();
              }
            }
          } catch (eCache) {
            console.warn("Aviso ao ler cache local do mural:", eCache);
          }
        }

        try {
          // Conecta o listener em tempo real com onSnapshot exclusivamente nesta aba
          unsubscribeMural = onSnapshot(collection(db, "mural_recados"), (snapshot) => {
            if (iconeSinc) iconeSinc.classList.remove("animate-spin");
            window.atualizarBadgeStatusMural(true);

            const lista = [];
            snapshot.forEach(docSnap => {
              const data = docSnap.data();
              const item = {
                id: docSnap.id,
                ...data
              };

              // Se for mensagem de boas-vindas do ano letivo ou alerta pedagógico de ocorrência, exclui imediatamente do banco e ignora
              if (window.eMensagemBoasVindasAnoLetivo(item) || item.tipo === 'ALERTA_PEDAGOGICO' || (item.titulo && String(item.titulo).startsWith('ALERTA PEDAGÓGICO:'))) {
                try {
                  deleteDoc(doc(db, "mural_recados", docSnap.id)).catch(() => {});
                } catch(eDel) {}
                return;
              }

              // Se tiver sido arquivado automaticamente, desarquiva imediatamente e limpa flags
              if (item.autoArquivadoEm || item.motivoAutoArquivamento || (item.arquivado && !item.arquivadoManualmente)) {
                item.arquivado = false;
                delete item.autoArquivadoEm;
                delete item.motivoAutoArquivamento;
                try {
                  updateDoc(doc(db, "mural_recados", docSnap.id), {
                    arquivado: false,
                    autoArquivadoEm: null,
                    motivoAutoArquivamento: null
                  }).catch(() => {});
                } catch(eUpd) {}
              }

              lista.push(item);
            });

            // Ordenação automática: Fixados no topo e data decrescente
            lista.sort((a, b) => {
              if (!!b.fixado !== !!a.fixado) return b.fixado ? 1 : -1;
              return new Date(b.data_criacao || 0).getTime() - new Date(a.data_criacao || 0).getTime();
            });

            window.muralRecadosCache = lista;
            try {
              localStorage.setItem("mural_recados_memoria", JSON.stringify(lista));
            } catch (eSave) {}

            window.renderizarMuralRecados();

            // Atualiza modal de cientes em tempo real se estiver aberto
            if (window.recadoCientesVisualizando && typeof window.renderizarCientesModal === "function") {
              window.renderizarCientesModal();
            }

            if (forcarAtualizacao && typeof window.showToast === 'function') {
              window.showToast("Mural de recados sincronizado e conectado em tempo real!", "success", 3000);
            }
          }, (error) => {
            const isPerm = error && (error.code === "permission-denied" || (error.message && error.message.includes("permission")));
            if (isPerm) {
              console.warn("Mural de recados operando em modo de cache local resiliente.");
            } else {
              console.error("Erro no listener em tempo real de mural_recados:", error);
            }
            if (iconeSinc) iconeSinc.classList.remove("animate-spin");
            window.atualizarBadgeStatusMural(true);

            // Carregar cache local filtrado (NUNCA reinjeta recados falsos de boas-vindas)
            let localCache = [];
            try {
              window.purgarMensagensBoasVindasMural();
              const s = localStorage.getItem("mural_recados_memoria");
              if (s) localCache = JSON.parse(s);
            } catch (e) {}

            localCache = (Array.isArray(localCache) ? localCache : []).filter(r => !window.eMensagemBoasVindasAnoLetivo(r));
            window.muralRecadosCache = localCache;
            window.renderizarMuralRecados();
          });
        } catch (errInit) {
          console.error("Falha ao inicializar snapshot do mural:", errInit);
          if (iconeSinc) iconeSinc.classList.remove("animate-spin");
          window.atualizarBadgeStatusMural(false);
        }
      };

      // Mantém o listener do mural sempre ativo (Tempo Real Contínuo no MongoDB Atlas)
      window.pararListenerMural = function() {
        // No MongoDB Atlas não há cobrança por leituras; o canal em tempo real permanece ativo
        window.atualizarBadgeStatusMural(true);
      };

      // Função compatível de carga / recarga do mural
      window.carregarMuralRecados = function(forcarAtualizacao = false) {
        window.iniciarListenerMural(forcarAtualizacao);
      };

      // =========================================================================
      // SISTEMA DE FORMATAÇÃO RICA, MENÇÕES E IMAGENS DO MURAL DE RECADOS
      // =========================================================================

      // Mapeamento de Estilo e Cores Exclusivas por Perfil / Cargo para Menções (@)
      window.obterEstiloPerfilMencao = function(cargoOuRole, nome) {
        const roleNorm = window.normalizarUserRole ? window.normalizarUserRole(cargoOuRole) : "PROFESSOR";
        const cargoStr = String(cargoOuRole || "").toUpperCase();
        const nomeLower = String(nome || "").toLowerCase();

        // 1. Direção Escolar (Âmbar / Dourado Real)
        if (nomeLower.includes("diretor") || nomeLower.includes("direção") || nomeLower.includes("direcao") || roleNorm === "DIRETOR" || cargoStr.includes("DIRETOR")) {
          return {
            role: "DIRETOR",
            label: "Direção",
            badgeClass: "bg-amber-100 text-amber-950 border-amber-300 ring-1 ring-amber-400/30",
            icon: '<i class="fa-solid fa-crown text-amber-600 text-[10px]"></i>'
          };
        }

        // 2. Vice-Direção (Índigo / Real Escuro)
        if (nomeLower.includes("vice") || roleNorm === "VICE_DIRETOR" || cargoStr.includes("VICE")) {
          return {
            role: "VICE_DIRETOR",
            label: "Vice-Direção",
            badgeClass: "bg-indigo-100 text-indigo-950 border-indigo-300 ring-1 ring-indigo-400/30",
            icon: '<i class="fa-solid fa-shield-halved text-indigo-600 text-[10px]"></i>'
          };
        }

        // 3. Coordenação Geral Pedagógica - CGPG (Púrpura / Violeta Acadêmico)
        if (nomeLower.includes("cgpg") || nomeLower.includes("coordena") || roleNorm === "CGPG" || cargoStr.includes("CGPG") || cargoStr.includes("COORDENADOR")) {
          return {
            role: "CGPG",
            label: "CGPG",
            badgeClass: "bg-purple-100 text-purple-950 border-purple-300 ring-1 ring-purple-400/30",
            icon: '<i class="fa-solid fa-book-open-reader text-purple-600 text-[10px]"></i>'
          };
        }

        // 4. Professor Articulador - PAAC (Teal / Verde-Água Articulação)
        if (nomeLower.includes("paac") || roleNorm === "PAAC" || cargoStr.includes("PAAC")) {
          return {
            role: "PAAC",
            label: "PAAC",
            badgeClass: "bg-teal-100 text-teal-950 border-teal-300 ring-1 ring-teal-400/30",
            icon: '<i class="fa-solid fa-chalkboard-user text-teal-600 text-[10px]"></i>'
          };
        }

        // 5. Secretaria e Apoio Administrativo (Laranja / Gestão de Registros)
        if (nomeLower.includes("secretaria") || roleNorm === "SECRETARIA" || cargoStr.includes("SECRETARIA") || cargoStr.includes("ADMIN")) {
          return {
            role: "SECRETARIA",
            label: "Secretaria",
            badgeClass: "bg-orange-100 text-orange-950 border-orange-300 ring-1 ring-orange-400/30",
            icon: '<i class="fa-solid fa-folder-open text-orange-600 text-[10px]"></i>'
          };
        }

        // 6. Grupos Gerais / Equipe Toda (Azul Profundo Institucional)
        if (nomeLower.includes("todos") || nomeLower.includes("equipe") || nomeLower.includes("geral") || cargoOuRole === "EQUIPE") {
          return {
            role: "EQUIPE",
            label: "Equipe",
            badgeClass: "bg-blue-100 text-blue-950 border-blue-300 ring-1 ring-blue-400/30",
            icon: '<i class="fa-solid fa-users text-blue-700 text-[10px]"></i>'
          };
        }

        // 7. Padrão: Professor / Docente (Azul Céu Acadêmico)
        return {
          role: "PROFESSOR",
          label: "Professor(a)",
          badgeClass: "bg-sky-100 text-sky-950 border-sky-300 ring-1 ring-sky-400/30",
          icon: '<i class="fa-solid fa-graduation-cap text-sky-600 text-[10px]"></i>'
        };
      };

      // Parser de Conteúdo Formatado (Negrito, Itálico, Sublinhado, Links, Imagens e Menções Coloridas)
      window.formatarConteudoMural = function(texto) {
        if (!texto) return "";
        let raw = String(texto);

        // 1. Sanitizar tags HTML nativas
        let safe = raw
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;");

        // 2. Imagens: ![alt](url) ou ![alt](data:image...)
        safe = safe.replace(/!\[(.*?)\]\(((?:https?:\/\/|data:image\/)[^\s\)\"]+)\)/g, (match, alt, src) => {
          const safeAlt = (alt || "Imagem do Comunicado").replace(/"/g, '&quot;');
          return `<div class="my-2.5 max-w-sm rounded-xl overflow-hidden border border-slate-200 bg-slate-50 shadow-2xs group relative inline-block">
            <img src="${src}" alt="${safeAlt}" class="w-full max-h-56 object-cover rounded-xl cursor-zoom-in transition group-hover:opacity-95" onclick="window.abrirModalImagemMural('${src}', '${safeAlt}')" loading="lazy" />
            <div class="absolute bottom-2 right-2 px-2 py-0.5 bg-slate-900/80 text-white rounded-md text-[10px] font-bold backdrop-blur-xs pointer-events-none opacity-0 group-hover:opacity-100 transition shadow-sm flex items-center gap-1">
              <i class="fa-solid fa-magnifying-glass-plus text-[9px] text-cyan-300"></i>
              <span>Ampliar Imagem</span>
            </div>
          </div>`;
        });

        // 3. Links Markdown: [Texto do Link](https://...)
        safe = safe.replace(/\[(.*?)\]\((https?:\/\/[^\s\)\"]+)\)/g, (match, text, url) => {
          const safeText = text || url;
          return `<a href="${url}" target="_blank" rel="noopener noreferrer" class="inline-flex items-center gap-1 text-blue-700 hover:text-blue-900 font-bold underline bg-blue-50/80 hover:bg-blue-100 px-1.5 py-0.5 rounded border border-blue-200 transition shadow-2xs break-all"><i class="fa-solid fa-arrow-up-right-from-square text-[10px] text-cyan-600"></i><span>${safeText}</span></a>`;
        });

        // 4. Links diretos na mensagem (ex: https://meet.google.com/...)
        safe = safe.replace(/(?<!href="|src=")(https?:\/\/[^\s<]+)/g, (match, url) => {
          return `<a href="${url}" target="_blank" rel="noopener noreferrer" class="inline-flex items-center gap-1 text-blue-700 hover:text-blue-900 font-bold underline bg-blue-50/80 hover:bg-blue-100 px-1.5 py-0.5 rounded border border-blue-200 transition shadow-2xs break-all"><i class="fa-solid fa-link text-[10px] text-cyan-600"></i><span>${url}</span></a>`;
        });

        // 5. Negrito: **texto** ou <b>texto</b> ou <strong>texto</strong>
        safe = safe.replace(/\*\*(.+?)\*\*/g, '<strong class="font-extrabold text-slate-900">$1</strong>');
        safe = safe.replace(/&lt;b&gt;(.+?)&lt;\/b&gt;/gi, '<strong class="font-extrabold text-slate-900">$1</strong>');
        safe = safe.replace(/&lt;strong&gt;(.+?)&lt;\/strong&gt;/gi, '<strong class="font-extrabold text-slate-900">$1</strong>');

        // 6. Sublinhado: __texto__ ou <u>texto</u>
        safe = safe.replace(/__(.+?)__/g, '<u class="underline decoration-blue-600 decoration-2 font-bold text-slate-900">$1</u>');
        safe = safe.replace(/&lt;u&gt;(.+?)&lt;\/u&gt;/gi, '<u class="underline decoration-blue-600 decoration-2 font-bold text-slate-900">$1</u>');

        // 7. Itálico: *texto* ou <i>texto</i> ou <em>texto</em>
        safe = safe.replace(/(?<!\*)\*([^*]+?)\*(?!\*)/g, '<em class="italic font-serif text-slate-800">$1</em>');
        safe = safe.replace(/&lt;i&gt;(.+?)&lt;\/i&gt;/gi, '<em class="italic font-serif text-slate-800">$1</em>');
        safe = safe.replace(/&lt;em&gt;(.+?)&lt;\/em&gt;/gi, '<em class="italic font-serif text-slate-800">$1</em>');

        // 8. Menções de Professor / Equipe com perfis coloridos:
        // Formato avançado com cargo embutido: @[Nome|CARGO]
        safe = safe.replace(/@\[([^\|\]]+)\|([^\]]+)\]/g, (match, nome, cargo) => {
          const estilo = window.obterEstiloPerfilMencao(cargo, nome);
          return `<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-black tracking-wide border shadow-2xs ${estilo.badgeClass} mx-0.5 my-0.5 align-middle select-none">${estilo.icon}<span>@${nome.trim()}</span><span class="text-[9px] font-bold uppercase opacity-80 ml-0.5">(${estilo.label})</span></span>`;
        });

        // Formato colchete simples: @[Nome]
        safe = safe.replace(/@\[([^\]]+)\]/g, (match, nome) => {
          const estilo = window.obterEstiloPerfilMencao(null, nome);
          return `<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-black tracking-wide border shadow-2xs ${estilo.badgeClass} mx-0.5 my-0.5 align-middle select-none">${estilo.icon}<span>@${nome.trim()}</span><span class="text-[9px] font-bold uppercase opacity-80 ml-0.5">(${estilo.label})</span></span>`;
        });

        // Menção inline simples: @Nome (não casa emails)
        safe = safe.replace(/(^|[\s(])@([A-Za-zÀ-ÿ0-9_\.\-]+(?:\s+[A-Za-zÀ-ÿ0-9_\.\-]+){0,2})(?=[.,!?\s)]|$)/g, (match, prefix, nome) => {
          if (prefix && prefix !== " " && prefix !== "\n" && prefix !== "(") return match;
          const estilo = window.obterEstiloPerfilMencao(null, nome);
          return `${prefix}<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-black tracking-wide border shadow-2xs ${estilo.badgeClass} mx-0.5 my-0.5 align-middle select-none">${estilo.icon}<span>@${nome.trim()}</span><span class="text-[9px] font-bold uppercase opacity-80 ml-0.5">(${estilo.label})</span></span>`;
        });

        // 9. Quebras de linha preservadas
        safe = safe.replace(/\n/g, '<br/>');

        return safe;
      };

      // Helper para verificar se usuário atual está marcado/mencionado no recado
      window.verificarUsuarioMencionadoNoRecado = function(recado, userObj) {
        if (!recado || !recado.conteudo || !userObj) return false;
        const conteudoLower = String(recado.conteudo).toLowerCase();
        const nomeUser = String(userObj.nome || "").toLowerCase().trim();
        const emailUser = String(userObj.email || "").toLowerCase().trim();
        const cargoUser = String(userObj.cargo || "").toLowerCase().trim();

        if (nomeUser && nomeUser.length > 2 && conteudoLower.includes(nomeUser)) return true;
        if (emailUser && conteudoLower.includes(emailUser)) return true;
        if (conteudoLower.includes("@todos") || conteudoLower.includes("@equipe")) return true;

        if (cargoUser === "diretor" && (conteudoLower.includes("@direção") || conteudoLower.includes("@direcao") || conteudoLower.includes("@diretor"))) return true;
        if (cargoUser.includes("vice") && conteudoLower.includes("@vice")) return true;
        if (cargoUser.includes("cgpg") && (conteudoLower.includes("@cgpg") || conteudoLower.includes("@coordena"))) return true;
        if (cargoUser.includes("paac") && conteudoLower.includes("@paac")) return true;
        if (cargoUser === "secretaria" && conteudoLower.includes("@secretaria")) return true;
        if (cargoUser === "professor" && (conteudoLower.includes("@professores") || conteudoLower.includes("@docentes"))) return true;

        return false;
      };

      // Modal de Visualização de Imagem em Tela Cheia (Lightbox)
      window.abrirModalImagemMural = function(src, alt) {
        const modal = document.getElementById("modal-imagem-mural");
        const img = document.getElementById("modal-imagem-src");
        const titulo = document.getElementById("modal-imagem-titulo");
        const link = document.getElementById("modal-imagem-link-download");

        if (img) img.src = src;
        if (titulo) titulo.textContent = alt || "Imagem do Comunicado";
        if (link) link.href = src;

        if (modal) modal.classList.remove("hidden");
      };

      window.fecharModalImagemMural = function() {
        const modal = document.getElementById("modal-imagem-mural");
        if (modal) modal.classList.add("hidden");
      };

      // Inserção de Formatações Rápidas no Textarea
      window.inserirFormatacaoRecado = function(tipo) {
        const textarea = document.getElementById("recado-conteudo");
        if (!textarea) return;

        const start = textarea.selectionStart || 0;
        const end = textarea.selectionEnd || 0;
        const selected = textarea.value.substring(start, end);
        let replacement = "";
        let cursorOffset = 0;

        if (tipo === "negrito") {
          replacement = `**${selected || "texto em negrito"}**`;
          cursorOffset = selected ? replacement.length : 2;
        } else if (tipo === "italico") {
          replacement = `*${selected || "texto em itálico"}*`;
          cursorOffset = selected ? replacement.length : 1;
        } else if (tipo === "sublinhado") {
          replacement = `<u>${selected || "texto sublinhado"}</u>`;
          cursorOffset = selected ? replacement.length : 3;
        } else if (tipo === "link") {
          const url = prompt("Digite ou cole a URL do link (ex: https://exemplo.com):", "https://");
          if (!url) return;
          const textoLink = selected || "Clique aqui para acessar";
          replacement = `[${textoLink}](${url.trim()})`;
          cursorOffset = replacement.length;
        }

        textarea.setRangeText(replacement, start, end, "end");
        textarea.focus();
        window.atualizarPreviaRecadoLive();
      };

      // Alternar Modo de Visualização do Editor (Escrever vs Prévia)
      window.alternarModoEditorRecado = function(modo) {
        const textarea = document.getElementById("recado-conteudo");
        const previewContainer = document.getElementById("recado-preview-container");
        const previewConteudo = document.getElementById("recado-preview-conteudo");
        const btnEscrever = document.getElementById("btn-modo-editor-recado");
        const btnPrevia = document.getElementById("btn-modo-previa-recado");

        if (modo === "previa") {
          if (textarea) textarea.classList.add("hidden");
          if (previewContainer) {
            previewContainer.classList.remove("hidden");
            if (previewConteudo) {
              const valor = textarea ? textarea.value : "";
              previewConteudo.innerHTML = valor.trim() 
                ? window.formatarConteudoMural(valor)
                : '<span class="italic text-slate-400">Nenhum texto digitado ainda para prévia...</span>';
            }
          }

          if (btnEscrever) {
            btnEscrever.className = "px-2.5 py-1 text-slate-600 hover:text-slate-900 font-bold text-[11px] rounded flex items-center gap-1 cursor-pointer transition";
          }
          if (btnPrevia) {
            btnPrevia.className = "px-2.5 py-1 bg-white text-blue-900 font-extrabold text-[11px] rounded shadow-xs flex items-center gap-1 cursor-pointer transition";
          }
        } else {
          if (previewContainer) previewContainer.classList.add("hidden");
          if (textarea) {
            textarea.classList.remove("hidden");
            textarea.focus();
          }

          if (btnEscrever) {
            btnEscrever.className = "px-2.5 py-1 bg-white text-blue-900 font-extrabold text-[11px] rounded shadow-xs flex items-center gap-1 cursor-pointer transition";
          }
          if (btnPrevia) {
            btnPrevia.className = "px-2.5 py-1 text-slate-600 hover:text-slate-900 font-bold text-[11px] rounded flex items-center gap-1 cursor-pointer transition";
          }
        }
      };

      // Atualiza a prévia visual caso o container esteja aberto
      window.atualizarPreviaRecadoLive = function() {
        const textarea = document.getElementById("recado-conteudo");
        const previewContainer = document.getElementById("recado-preview-container");
        const previewConteudo = document.getElementById("recado-preview-conteudo");

        if (previewContainer && !previewContainer.classList.contains("hidden") && previewConteudo && textarea) {
          previewConteudo.innerHTML = textarea.value.trim() 
            ? window.formatarConteudoMural(textarea.value)
            : '<span class="italic text-slate-400">Nenhum texto digitado ainda para prévia...</span>';
        }
      };

      // Compressão e Inserção de Imagem Otimizada
      window.comprimirImagemParaBase64 = function(file) {
        return new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.readAsDataURL(file);
          reader.onload = (event) => {
            const img = new Image();
            img.src = event.target.result;
            img.onload = () => {
              const canvas = document.createElement("canvas");
              let width = img.width;
              let height = img.height;
              const maxDim = 800;

              if (width > height && width > maxDim) {
                height = Math.round((height * maxDim) / width);
                width = maxDim;
              } else if (height > maxDim) {
                width = Math.round((width * maxDim) / height);
                height = maxDim;
              }

              canvas.width = width;
              canvas.height = height;
              const ctx = canvas.getContext("2d");
              ctx.drawImage(img, 0, 0, width, height);

              const base64 = canvas.toDataURL("image/jpeg", 0.75);
              resolve(base64);
            };
            img.onerror = (e) => reject(e);
          };
          reader.onerror = (e) => reject(e);
        });
      };

      window.processarImagemRecado = async function(input) {
        if (!input || !input.files || !input.files[0]) return;
        const file = input.files[0];

        if (!file.type.startsWith("image/")) {
          window.showToast("Por favor, selecione um arquivo de imagem válido (JPG, PNG, WebP).", "warning");
          return;
        }

        try {
          if (typeof window.showToast === 'function') {
            window.showToast("Otimizando imagem para o comunicado...", "info", 2000);
          }

          const base64 = await window.comprimirImagemParaBase64(file);
          const textarea = document.getElementById("recado-conteudo");
          if (textarea) {
            const start = textarea.selectionStart || textarea.value.length;
            const end = textarea.selectionEnd || textarea.value.length;
            const tagImg = `\n\n![${file.name.replace(/\.[^/.]+$/, "")}](${base64})\n\n`;
            textarea.setRangeText(tagImg, start, end, "end");
            textarea.focus();
            window.atualizarPreviaRecadoLive();
          }

          window.alternarMenuImagemRecado(false);
          input.value = "";
          if (typeof window.showToast === 'function') {
            window.showToast("Imagem inserida com sucesso no comunicado!", "success");
          }
        } catch (err) {
          console.error("Erro ao processar imagem:", err);
          window.showToast("Não foi possível carregar a imagem. Tente uma imagem menor.", "error");
        }
      };

      window.inserirImagemPorUrl = function() {
        const inputUrl = document.getElementById("recado-url-imagem");
        if (!inputUrl) return;
        const url = (inputUrl.value || "").trim();

        if (!url || !url.startsWith("http")) {
          window.showToast("Por favor, informe uma URL de imagem válida (começando com http:// ou https://)", "warning");
          return;
        }

        const textarea = document.getElementById("recado-conteudo");
        if (textarea) {
          const start = textarea.selectionStart || textarea.value.length;
          const end = textarea.selectionEnd || textarea.value.length;
          const tagImg = `\n\n![Imagem Anexa](${url})\n\n`;
          textarea.setRangeText(tagImg, start, end, "end");
          textarea.focus();
          window.atualizarPreviaRecadoLive();
        }

        inputUrl.value = "";
        window.alternarMenuImagemRecado(false);
        if (typeof window.showToast === 'function') {
          window.showToast("Imagem adicionada ao comunicado!", "success");
        }
      };

      window.alternarMenuImagemRecado = function(forcar) {
        const popover = document.getElementById("popover-imagem-recado");
        if (!popover) return;
        if (typeof forcar === "boolean") {
          if (forcar) popover.classList.remove("hidden");
          else popover.classList.add("hidden");
        } else {
          popover.classList.toggle("hidden");
        }
        // Fechar menu de menções se abrir imagem
        if (!popover.classList.contains("hidden")) {
          const menuMencoes = document.getElementById("mural-menu-mencoes");
          if (menuMencoes) menuMencoes.classList.add("hidden");
        }
      };

      // Gestão do Menu de Menções de Docentes (@)
      window.alternarMenuMencoesRecado = function(forcar) {
        const menu = document.getElementById("mural-menu-mencoes");
        if (!menu) return;
        if (typeof forcar === "boolean") {
          if (forcar) {
            menu.classList.remove("hidden");
            window.popularMenuMencoesDocentes();
          } else {
            menu.classList.add("hidden");
          }
        } else {
          const abrindo = menu.classList.toggle("hidden") === false;
          if (abrindo) window.popularMenuMencoesDocentes();
        }
        // Fechar menu de imagens se abrir menções
        if (!menu.classList.contains("hidden")) {
          const popImg = document.getElementById("popover-imagem-recado");
          if (popImg) popImg.classList.add("hidden");
        }
      };

      // Lista de Docentes e Cargos para o Menu de Menção
      window.obterListaDocentesEFuncionarios = function() {
        const lista = [];
        const nomesVistos = new Set();

        // 1. Grupos Rápidos Pré-configurados
        const grupos = [
          { nome: "Todos os Professores e Funcionários", cargo: "EQUIPE", isGrupo: true, desc: "Notifica toda a equipe escolar" },
          { nome: "Professores Ensino Fundamental (6º ao 9º)", cargo: "PROFESSOR", isGrupo: true, desc: "Docentes dos Anos Finais" },
          { nome: "Professores Ensino Médio (1ª a 3ª)", cargo: "PROFESSOR", isGrupo: true, desc: "Docentes do Ensino Médio" },
          { nome: "Tutores PEI", cargo: "PROFESSOR", isGrupo: true, desc: "Docentes Tutores de Alunos" },
          { nome: "Equipe Gestora (Direção, Vice, CGPG)", cargo: "DIRETOR", isGrupo: true, desc: "Gestão escolar" },
          { nome: "Professores PAAC", cargo: "PAAC", isGrupo: true, desc: "Articuladores Comunitários" }
        ];

        grupos.forEach(g => {
          lista.push(g);
          nomesVistos.add(g.nome.toLowerCase());
        });

        // 2. Docentes e Usuários Cadastrados no Banco de Dados (window.usuariosCache)
        const usuarios = window.usuariosCache || [];
        usuarios.forEach(u => {
          const nome = (u.nome || u.displayName || u.email || "").trim();
          if (nome && !nomesVistos.has(nome.toLowerCase())) {
            nomesVistos.add(nome.toLowerCase());
            lista.push({
              nome: nome,
              cargo: u.cargo || u.nivelAcesso || u.nivel || "PROFESSOR",
              email: u.email || "",
              isGrupo: false
            });
          }
        });

        // 3. Tutores extraídos dos alunos (window.allStudentsData)
        const alunos = window.allStudentsData || [];
        alunos.forEach(s => {
          const tutor = (s.tutor || "").trim();
          if (tutor && tutor.length > 2 && !nomesVistos.has(tutor.toLowerCase())) {
            nomesVistos.add(tutor.toLowerCase());
            lista.push({
              nome: tutor,
              cargo: "PROFESSOR",
              isGrupo: false,
              desc: "Tutor PEI"
            });
          }
        });

        return lista;
      };

      window.popularMenuMencoesDocentes = function(filtro = "") {
        const container = document.getElementById("lista-mencoes-docentes");
        if (!container) return;

        const todos = window.obterListaDocentesEFuncionarios();
        const fLower = String(filtro || "").toLowerCase().trim();

        const filtrados = todos.filter(item => {
          if (!fLower) return true;
          return item.nome.toLowerCase().includes(fLower) || 
                 String(item.cargo || '').toLowerCase().includes(fLower) ||
                 String(item.desc || '').toLowerCase().includes(fLower);
        });

        if (filtrados.length === 0) {
          container.innerHTML = `<div class="p-3 text-center text-xs text-slate-400 font-medium">Nenhum professor ou funcionário encontrado para "${filtro}".</div>`;
          return;
        }

        container.innerHTML = filtrados.map(item => {
          const estilo = window.obterEstiloPerfilMencao(item.cargo, item.nome);
          const safeNome = item.nome.replace(/'/g, "\\'");
          const safeCargo = (item.cargo || "PROFESSOR").replace(/'/g, "\\'");

          return `
            <button 
              type="button" 
              onclick="window.inserirMencaoDocente('${safeNome}', '${safeCargo}')" 
              class="w-full p-2 hover:bg-slate-100 rounded-lg flex items-center justify-between gap-2 transition text-left cursor-pointer group"
            >
              <div class="flex items-center gap-2 min-w-0">
                <span class="w-6 h-6 rounded-full flex items-center justify-center text-xs shrink-0 ${estilo.badgeClass}">
                  ${estilo.icon}
                </span>
                <div class="truncate">
                  <div class="text-xs font-bold text-slate-800 group-hover:text-blue-900 truncate">
                    ${item.nome}
                  </div>
                  ${item.desc ? `<div class="text-[10px] text-slate-400 font-medium truncate">${item.desc}</div>` : ''}
                </div>
              </div>
              <span class="px-1.5 py-0.5 rounded text-[10px] font-extrabold uppercase shrink-0 ${estilo.badgeClass}">
                ${estilo.label}
              </span>
            </button>
          `;
        }).join("");
      };

      window.filtrarMencoesDocentes = function(valor) {
        window.popularMenuMencoesDocentes(valor);
      };

      window.inserirMencaoDocente = function(nome, cargo) {
        const textarea = document.getElementById("recado-conteudo");
        if (textarea) {
          const start = textarea.selectionStart || textarea.value.length;
          const end = textarea.selectionEnd || textarea.value.length;
          const mencao = `@[${nome}|${cargo}] `;
          textarea.setRangeText(mencao, start, end, "end");
          textarea.focus();
          window.atualizarPreviaRecadoLive();
        }

        window.alternarMenuMencoesRecado(false);
        if (typeof window.showToast === 'function') {
          window.showToast(`Marcado @${nome} com destaque visual de perfil!`, "success", 2500);
        }
      };

      // =========================================================
      // HELPERS GLOBAIS DE CIÊNCIA E PÚBLICO-ALVO DO MURAL
      // =========================================================
      window.usuarioEAlvoDoRecado = function(recado, userOverride) {
        if (!recado) return false;

        const userObj = userOverride || (typeof window.obterIdentificacaoUsuarioCompleta === 'function'
          ? window.obterIdentificacaoUsuarioCompleta()
          : { email: '', nome: 'Usuário', cargo: 'PROFESSOR' });

        const roleAtiva = (typeof window.obterRoleAtual === 'function') ? window.obterRoleAtual() : (userObj.cargo || 'PROFESSOR');
        const myCargo = window.normalizarUserRole ? window.normalizarUserRole(roleAtiva) : String(roleAtiva || '').toUpperCase().trim();
        const myEmail = String(userObj.email || '').toLowerCase().trim();
        const myNome = String(userObj.nome || '').toLowerCase().trim();

        // Determinar tipo de destinatário
        let tipo = recado.destinatarios_tipo;
        if (!tipo) {
          if (!recado.destinatarios || 
              recado.destinatarios === "Todos os Professores e Funcionários" || 
              recado.destinatarios === "Toda a Equipe Escolar (Geral)" ||
              recado.destinatarios === "Todos") {
            tipo = "todos";
          } else if (Array.isArray(recado.destinatarios_cargos) && recado.destinatarios_cargos.length > 0) {
            tipo = "cargos";
          } else if (Array.isArray(recado.destinatarios_especificos) && recado.destinatarios_especificos.length > 0) {
            tipo = "especificos";
          }
        }

        if (!tipo || tipo === 'todos' || tipo === 'geral') {
          const destStr = String(recado.destinatarios || '').trim().toLowerCase();
          if (!destStr || destStr.includes('todos') || destStr.includes('equipe escolar') || destStr.includes('geral')) {
            return true;
          }
          if (destStr.includes('professor') || destStr.includes('docente')) {
            return myCargo.includes('PROFESSOR') || myCargo === 'DOCENTE' || myCargo === 'TUTOR';
          }
          if (destStr.includes('secretaria')) {
            return myCargo.includes('SECRETAR') || myCargo.includes('GOE') || myCargo.includes('AOE');
          }
          if (destStr.includes('coordena') || destStr.includes('cgpg') || destStr.includes('cgpac')) {
            return myCargo.includes('COORDENADOR') || myCargo.includes('CGPG') || myCargo.includes('CGPAC');
          }
          if (destStr.includes('dire')) {
            return myCargo.includes('DIRETOR') || myCargo.includes('VICE');
          }
          if (destStr.includes('paac')) {
            return myCargo.includes('PAAC');
          }
          return true;
        }

        if (tipo === 'cargos') {
          const cargosAlvo = Array.isArray(recado.destinatarios_cargos) ? recado.destinatarios_cargos : [];
          if (cargosAlvo.length === 0) return true;
          return cargosAlvo.some(cg => {
            const cgNorm = window.normalizarUserRole ? window.normalizarUserRole(cg) : String(cg || '').toUpperCase().trim();
            if (cgNorm === myCargo) return true;
            if (cgNorm === 'PROFESSOR' && (myCargo.includes('PROFESSOR') || myCargo === 'DOCENTE' || myCargo === 'TUTOR')) return true;
            if (cgNorm === 'DIRETOR' && (myCargo.includes('DIRETOR') || myCargo.includes('VICE'))) return true;
            if (cgNorm === 'VICE_DIRETOR' && (myCargo.includes('VICE') || myCargo.includes('DIRETOR'))) return true;
            if (cgNorm === 'CGPG' && (myCargo.includes('COORDENADOR') || myCargo.includes('CGPG') || myCargo.includes('CGPAC'))) return true;
            if (cgNorm === 'SECRETARIA' && (myCargo.includes('SECRETAR') || myCargo.includes('GOE') || myCargo.includes('AOE'))) return true;
            if (cgNorm === 'PAAC' && myCargo.includes('PAAC')) return true;
            if (cgNorm === 'OUTROS') return true;
            return false;
          });
        }

        if (tipo === 'especificos') {
          const especificos = Array.isArray(recado.destinatarios_especificos) ? recado.destinatarios_especificos : [];
          if (especificos.length === 0) return true;
          return especificos.some(esp => {
            const espEmail = String(esp.email || '').toLowerCase().trim();
            const espNome = String(esp.nome || '').toLowerCase().trim();
            return (myEmail && espEmail === myEmail) || (myNome && espNome === myNome);
          });
        }

        return true;
      };

      // Helper para verificar se usuário logado deu ciente no recado
      // Garante: "Preciso que marque uma vez só pra cada perfil"
      window.usuarioDeuCienteRecado = function(recado, userOverride) {
        if (!recado || !Array.isArray(recado.cientes)) return false;

        const userObj = userOverride || (typeof window.obterIdentificacaoUsuarioCompleta === 'function'
          ? window.obterIdentificacaoUsuarioCompleta()
          : { email: '', nome: 'Usuário', cargo: 'PROFESSOR' });

        const roleAtiva = (typeof window.obterRoleAtual === 'function') ? window.obterRoleAtual() : (userObj.cargo || 'PROFESSOR');
        const roleNorm = window.normalizarUserRole ? window.normalizarUserRole(roleAtiva) : String(roleAtiva || '').toUpperCase().trim();
        const myEmail = String(userObj.email || '').toLowerCase().trim();
        const myNome = String(userObj.nome || '').toLowerCase().trim();

        return recado.cientes.some(c => {
          const cEmail = String(c.email || '').toLowerCase().trim();
          const cNome = String(c.nome || '').toLowerCase().trim();
          const cCargo = window.normalizarUserRole ? window.normalizarUserRole(c.cargo) : String(c.cargo || '').toUpperCase().trim();

          const coincideIdentidade = (myEmail && cEmail === myEmail) || (myNome && cNome === myNome);
          if (!coincideIdentidade) return false;

          // Se tiver cargo especificado no ciente, compara com o perfil ativo
          if (!c.cargo || cCargo === roleNorm) {
            return true;
          }
          return false;
        });
      };

      // =========================================================
      // IDENTIFICAÇÃO DE DESTINATÁRIOS MARCADOS E AUTO-ARQUIVAMENTO
      // "No mural de recados quando todo mundo marcado der ciência arquive automaticamente o recado."
      // =========================================================
      window.obterListaMarcadosRecado = function(recado) {
        if (!recado) return [];
        const marcados = [];
        const chavesVistas = new Set();

        // 1. Menções diretas no conteúdo do comunicado (@[Nome|Cargo], @[Nome] e @Nome)
        if (recado.conteudo) {
          const texto = String(recado.conteudo);

          // 1.1 Formato avançado @[Nome|Cargo]
          const regexAvancado = /@\[([^\|\]]+)\|([^\]]+)\]/g;
          let m;
          while ((m = regexAvancado.exec(texto)) !== null) {
            const nome = m[1].trim();
            const cargo = m[2].trim();
            const chave = `pessoa:${nome.toLowerCase()}`;
            if (!chavesVistas.has(chave)) {
              chavesVistas.add(chave);
              marcados.push({ tipo: 'pessoa', nome, cargo, chave });
            }
          }

          // 1.2 Formato @[Nome]
          const regexColchete = /@\[([^\]]+)\]/g;
          while ((m = regexColchete.exec(texto)) !== null) {
            const nome = m[1].trim();
            const chave = `pessoa:${nome.toLowerCase()}`;
            if (!chavesVistas.has(chave) && !['todos', 'equipe', 'geral'].includes(nome.toLowerCase())) {
              chavesVistas.add(chave);
              marcados.push({ tipo: 'pessoa', nome, chave });
            }
          }

          // 1.3 Formato @Nome simples
          const regexSimples = /(^|[\s(])@([A-Za-zÀ-ÿ0-9_\.\-]+(?:\s+[A-Za-zÀ-ÿ0-9_\.\-]+){0,2})(?=[.,!?\s)]|$)/g;
          while ((m = regexSimples.exec(texto)) !== null) {
            const prefix = m[1];
            if (prefix && prefix !== " " && prefix !== "\n" && prefix !== "(") continue;
            const nome = m[2].trim();
            const nomeLower = nome.toLowerCase();

            if (['todos', 'equipe', 'geral'].includes(nomeLower)) {
              continue;
            }

            if (nomeLower.includes('secretar')) {
              const chave = 'cargo:secretaria';
              if (!chavesVistas.has(chave)) {
                chavesVistas.add(chave);
                marcados.push({ tipo: 'cargo', cargo: 'SECRETARIA', nome: 'Secretaria', chave });
              }
            } else if (nomeLower.includes('cgpg') || nomeLower.includes('coordena')) {
              const chave = 'cargo:cgpg';
              if (!chavesVistas.has(chave)) {
                chavesVistas.add(chave);
                marcados.push({ tipo: 'cargo', cargo: 'CGPG', nome: 'CGPG', chave });
              }
            } else if (nomeLower.includes('vice')) {
              const chave = 'cargo:vice_diretor';
              if (!chavesVistas.has(chave)) {
                chavesVistas.add(chave);
                marcados.push({ tipo: 'cargo', cargo: 'VICE_DIRETOR', nome: 'Vice-Direção', chave });
              }
            } else if (nomeLower.includes('diretor') || nomeLower.includes('direção')) {
              const chave = 'cargo:diretor';
              if (!chavesVistas.has(chave)) {
                chavesVistas.add(chave);
                marcados.push({ tipo: 'cargo', cargo: 'DIRETOR', nome: 'Direção', chave });
              }
            } else if (nomeLower.includes('paac')) {
              const chave = 'cargo:paac';
              if (!chavesVistas.has(chave)) {
                chavesVistas.add(chave);
                marcados.push({ tipo: 'cargo', cargo: 'PAAC', nome: 'PAAC', chave });
              }
            } else {
              const chave = `pessoa:${nomeLower}`;
              if (!chavesVistas.has(chave) && nome.length >= 2) {
                chavesVistas.add(chave);
                marcados.push({ tipo: 'pessoa', nome, chave });
              }
            }
          }
        }

        // 2. Destinatários específicos cadastrados no recado (recado.destinatarios_especificos)
        if (Array.isArray(recado.destinatarios_especificos) && recado.destinatarios_especificos.length > 0) {
          recado.destinatarios_especificos.forEach(esp => {
            const nome = String(esp.nome || '').trim();
            const email = String(esp.email || '').toLowerCase().trim();
            const chave = email ? `email:${email}` : `pessoa:${nome.toLowerCase()}`;
            if (!chavesVistas.has(chave)) {
              chavesVistas.add(chave);
              marcados.push({
                tipo: 'pessoa',
                nome: nome,
                email: email,
                cargo: esp.cargo,
                chave: chave
              });
            }
          });
        }

        // 3. Destinatários por cargos selecionados (recado.destinatarios_cargos)
        if (recado.destinatarios_tipo === 'cargos' && Array.isArray(recado.destinatarios_cargos) && recado.destinatarios_cargos.length > 0) {
          recado.destinatarios_cargos.forEach(cg => {
            const cgNorm = window.normalizarUserRole ? window.normalizarUserRole(cg) : String(cg || '').toUpperCase().trim();
            const chave = `cargo:${cgNorm.toLowerCase()}`;
            if (!chavesVistas.has(chave)) {
              chavesVistas.add(chave);
              marcados.push({
                tipo: 'cargo',
                cargo: cgNorm,
                nome: cgNorm,
                chave: chave
              });
            }
          });
        }

        return marcados;
      };

      // Verifica se todos os marcados deram ciência no recado
      window.verificarTodosMarcadosDeramCiencia = function(recado) {
        if (!recado) return { todosCientes: false, totalMarcados: 0, marcadosCientes: 0, marcadosPendentes: [] };
        const cientes = Array.isArray(recado.cientes) ? recado.cientes : [];
        const marcados = window.obterListaMarcadosRecado(recado);

        // Se há pessoas ou perfis especificamente marcados
        if (marcados.length > 0) {
          const pendentes = [];
          let confirmados = 0;

          marcados.forEach(item => {
            let deuCiente = false;
            if (item.tipo === 'pessoa') {
              const itemNome = (item.nome || '').toLowerCase().trim();
              const itemEmail = (item.email || '').toLowerCase().trim();

              deuCiente = cientes.some(c => {
                const cNome = (c.nome || '').toLowerCase().trim();
                const cEmail = (c.email || '').toLowerCase().trim();
                if (itemEmail && cEmail && itemEmail === cEmail) return true;
                if (itemNome && cNome) {
                  if (itemNome === cNome) return true;
                  if (cNome.includes(itemNome) || itemNome.includes(cNome)) return true;
                }
                return false;
              });
            } else if (item.tipo === 'cargo') {
              const cargoTarget = window.normalizarUserRole ? window.normalizarUserRole(item.cargo) : String(item.cargo || '').toUpperCase().trim();
              deuCiente = cientes.some(c => {
                const cCargo = window.normalizarUserRole ? window.normalizarUserRole(c.cargo) : String(c.cargo || '').toUpperCase().trim();
                if (cargoTarget === 'PROFESSOR') {
                  return cCargo.includes('PROFESSOR') || cCargo === 'DOCENTE' || cCargo === 'TUTOR';
                }
                if (cargoTarget === 'DIRETOR') {
                  return cCargo.includes('DIRETOR') || cCargo.includes('VICE');
                }
                if (cargoTarget === 'SECRETARIA') {
                  return cCargo.includes('SECRETAR') || cCargo.includes('GOE') || cCargo.includes('AOE');
                }
                if (cargoTarget === 'CGPG') {
                  return cCargo.includes('CGPG') || cCargo.includes('COORD');
                }
                if (cargoTarget === 'PAAC') {
                  return cCargo.includes('PAAC');
                }
                return cCargo === cargoTarget;
              });
            }

            if (deuCiente) {
              confirmados++;
            } else {
              pendentes.push(item.nome || item.cargo);
            }
          });

          return {
            todosCientes: confirmados > 0 && confirmados === marcados.length,
            totalMarcados: marcados.length,
            marcadosCientes: confirmados,
            marcadosPendentes: pendentes
          };
        }

        // Se o recado não tem menções específicas nem público restrito (comunicado aberto geral):
        const usuarios = (Array.isArray(window.usuariosCache) && window.usuariosCache.length > 0)
          ? window.usuariosCache
          : (Array.isArray(window.professoresCache) ? window.professoresCache : []);
        if (usuarios.length > 0 && cientes.length >= usuarios.length) {
          return {
            todosCientes: true,
            totalMarcados: usuarios.length,
            marcadosCientes: cientes.length,
            marcadosPendentes: []
          };
        }

        return {
          todosCientes: false,
          totalMarcados: 0,
          marcadosCientes: cientes.length,
          marcadosPendentes: []
        };
      };

      // Renderiza os recados a partir da memória
      window.renderizarMuralRecados = function() {
        const grid = document.getElementById("mural-recados-grid");
        if (!grid) return;

        window.muralRecadosCache = (window.muralRecadosCache || []).filter(r => !window.eMensagemBoasVindasAnoLetivo(r));
        const todos = window.muralRecadosCache;
        const userObj = (typeof window.obterIdentificacaoUsuarioCompleta === 'function')
          ? window.obterIdentificacaoUsuarioCompleta()
          : { email: auth.currentUser?.email || '', nome: 'Professor', cargo: 'PROFESSOR' };

        const emailUser = String(userObj.email || '').toLowerCase().trim();
        const nomeUser = String(userObj.nome || '').toLowerCase().trim();

        // Helpers delegados para as funções centrais
        const usuarioDeuCiente = (recado) => window.usuarioDeuCienteRecado(recado, userObj);
        const usuarioEAlvoDoRecado = (recado) => window.usuarioEAlvoDoRecado(recado, userObj);

        // DESATIVADO: Arquivamento automático completamente desativado a pedido do usuário.
        // DESARQUIVAMENTO: Desarquiva imediatamente qualquer recado que tenha sido arquivado automaticamente.
        todos.forEach(r => {
          if (r.autoArquivadoEm || r.motivoAutoArquivamento || (r.arquivado && !r.arquivadoManualmente)) {
            r.arquivado = false;
            delete r.autoArquivadoEm;
            delete r.motivoAutoArquivamento;
            try {
              const recadoRef = doc(db, "mural_recados", r.id);
              updateDoc(recadoRef, {
                arquivado: false,
                autoArquivadoEm: null,
                motivoAutoArquivamento: null
              }).catch(() => {});
            } catch (e) {}
          }
        });

        // Cálculos de Resumo em Memória
        let totalAtivos = 0;
        let totalFixados = 0;
        let meusPendentes = 0;
        let totalArquivados = 0;

        todos.forEach(r => {
          const arquivado = !!r.arquivado;
          const fixado = !!r.fixado;
          const ciente = usuarioDeuCiente(r);
          const eAlvo = usuarioEAlvoDoRecado(r);

          if (arquivado) {
            totalArquivados++;
          } else {
            totalAtivos++;
            if (fixado) totalFixados++;
            if (!ciente && eAlvo) meusPendentes++;
          }
        });

        // Atualizar badges do banner
        const elTotalAtivos = document.getElementById("mural-badge-total-ativos");
        const elTotalFixados = document.getElementById("mural-badge-total-fixados");
        const elMeusPendentes = document.getElementById("mural-badge-meus-pendentes");
        const elTotalArquivados = document.getElementById("mural-badge-total-arquivados");
        const elPillAtivos = document.getElementById("mural-pill-count-ativos");
        const elPillArquivados = document.getElementById("mural-pill-count-arquivados");

        if (elTotalAtivos) elTotalAtivos.textContent = totalAtivos;
        if (elTotalFixados) elTotalFixados.textContent = totalFixados;
        if (elMeusPendentes) elMeusPendentes.textContent = meusPendentes;
        if (elTotalArquivados) elTotalArquivados.textContent = totalArquivados;
        if (elPillAtivos) elPillAtivos.textContent = totalAtivos;
        if (elPillArquivados) elPillArquivados.textContent = totalArquivados;

        // Atualizar visibilidade do botão de novo recado
        const btnNovo = document.getElementById("btn-novo-recado-mural");
        if (btnNovo) {
          if (window.podePublicarMural()) {
            btnNovo.classList.remove("hidden");
          } else {
            btnNovo.classList.add("hidden");
          }
        }

        // Ajusta classes do container de acordo com o modo de layout selecionado
        const modoLayout = window.muralModoLayout || "grid";
        if (modoLayout === "feed") {
          grid.className = "grid grid-cols-1 max-w-4xl mx-auto gap-5 items-start w-full";
        } else {
          grid.className = "grid grid-cols-1 lg:grid-cols-2 gap-4 sm:gap-6 items-start w-full";
        }

        const btnGrid = document.getElementById("btn-mural-layout-grid");
        const btnFeed = document.getElementById("btn-mural-layout-feed");
        if (btnGrid && btnFeed) {
          if (modoLayout === "grid") {
            btnGrid.className = "p-1.5 bg-white text-blue-900 shadow-2xs rounded-lg text-xs font-bold transition cursor-pointer";
            btnFeed.className = "p-1.5 text-slate-600 hover:text-slate-900 rounded-lg text-xs font-bold transition cursor-pointer";
          } else {
            btnGrid.className = "p-1.5 text-slate-600 hover:text-slate-900 rounded-lg text-xs font-bold transition cursor-pointer";
            btnFeed.className = "p-1.5 bg-white text-blue-900 shadow-2xs rounded-lg text-xs font-bold transition cursor-pointer";
          }
        }

        // Filtragem por Aba, Categoria e Texto
        const aba = window.muralAbaAtiva || "ativos";
        const cat = window.muralCategoriaAtiva || "todas";
        const busca = (window.muralTextoBusca || "").toLowerCase().trim();

        let filtrados = todos.filter(r => {
          const arquivado = !!r.arquivado;
          const prioridade = String(r.prioridade || 'Normal');
          const ciente = usuarioDeuCiente(r);

          if (aba === "ativos" && arquivado) return false;
          if (aba === "arquivados" && !arquivado) return false;
          if (aba === "urgentes") {
            if (arquivado) return false;
            if (prioridade !== "Urgente" && prioridade !== "Importante") return false;
          }
          if (aba === "pendentes") {
            if (arquivado) return false;
            if (ciente) return false;
            if (!usuarioEAlvoDoRecado(r)) return false;
          }

          if (cat !== "todas") {
            if ((r.categoria || "") !== cat) return false;
          }

          if (busca) {
            const titulo = String(r.titulo || "").toLowerCase();
            const conteudo = String(r.conteudo || "").toLowerCase();
            const autor = String(r.autor_nome || "").toLowerCase();
            const categoriaStr = String(r.categoria || "").toLowerCase();
            if (!titulo.includes(busca) && !conteudo.includes(busca) && !autor.includes(busca) && !categoriaStr.includes(busca)) {
              return false;
            }
          }

          return true;
        });

        // Ordenação: Fixados no topo, seguidos pela data de criação mais recente
        filtrados.sort((a, b) => {
          const fixA = a.fixado ? 1 : 0;
          const fixB = b.fixado ? 1 : 0;
          if (fixA !== fixB) return fixB - fixA;

          const timeA = new Date(a.data_criacao || a.createdAt || 0).getTime() || 0;
          const timeB = new Date(b.data_criacao || b.createdAt || 0).getTime() || 0;
          return timeB - timeA;
        });

        if (filtrados.length === 0) {
          let msgVazia = "Nenhum recado ativo encontrado no mural no momento.";
          let iconeVazio = "fa-envelope-open";
          if (aba === "arquivados") {
            msgVazia = "Nenhum recado arquivado em memória. Todos os comunicados arquivados ficarão salvos aqui para consulta histórica.";
            iconeVazio = "fa-box-archive";
          } else if (aba === "urgentes") {
            msgVazia = "Nenhum recado urgente ou importante pendente no momento.";
            iconeVazio = "fa-circle-check";
          } else if (aba === "pendentes") {
            msgVazia = "Parabéns! Você já confirmou ciência em todos os recados ativos.";
            iconeVazio = "fa-clipboard-check";
          }

          grid.innerHTML = `
            <div class="col-span-full py-12 px-6 text-center bg-white rounded-2xl border border-slate-200 shadow-2xs space-y-3">
              <div class="w-14 h-14 mx-auto rounded-2xl bg-blue-50 text-blue-900 flex items-center justify-center text-2xl font-bold border border-blue-100">
                <i class="fa-solid ${iconeVazio}"></i>
              </div>
              <h4 class="text-sm font-black text-slate-800">Mural Atualizado</h4>
              <p class="text-xs text-slate-500 max-w-md mx-auto leading-relaxed">${msgVazia}</p>
              ${window.podePublicarMural() ? `
                <button onclick="window.abrirModalNovoRecado()" class="mt-2 px-4 py-2 bg-blue-900 hover:bg-blue-800 text-white font-bold text-xs rounded-xl shadow-xs transition cursor-pointer">
                  <i class="fa-solid fa-plus-circle mr-1.5 text-cyan-300"></i> Publicar Recado
                </button>
              ` : ''}
            </div>
          `;
          return;
        }

        const podeGerenciar = window.podePublicarMural();

        grid.innerHTML = filtrados.map(r => {
          const isFixado = !!r.fixado;
          const isArquivado = !!r.arquivado;
          const prioridade = r.prioridade || "Normal";
          const cientes = Array.isArray(r.cientes) ? r.cientes : [];
          const totalCientes = cientes.length;
          const cienteAtual = usuarioDeuCiente(r);
          const eAlvo = usuarioEAlvoDoRecado(r);
          const usuarioMencionado = window.verificarUsuarioMencionadoNoRecado(r, userObj);
          const infoMarcados = typeof window.verificarTodosMarcadosDeramCiencia === 'function'
            ? window.verificarTodosMarcadosDeramCiencia(r)
            : { todosCientes: false, totalMarcados: 0, marcadosCientes: 0 };

          let rotuloAlvoCurto = "Perfil Específico";
          if (r.destinatarios_tipo === "cargos" && Array.isArray(r.destinatarios_cargos) && r.destinatarios_cargos.length > 0) {
            const mapCargos = {
              "PROFESSOR": "Professores",
              "PROFESSORES": "Professores",
              "DIRETOR": "Direção",
              "VICE_DIRETOR": "Vice-Direção",
              "CGPG": "CGPG",
              "PAAC": "PAAC",
              "SECRETARIA": "Secretaria",
              "COORDENACAO": "Coordenação"
            };
            rotuloAlvoCurto = r.destinatarios_cargos.map(c => mapCargos[c] || c).join(", ");
          } else if (r.destinatarios_tipo === "especificos" && Array.isArray(r.destinatarios_especificos) && r.destinatarios_especificos.length > 0) {
            rotuloAlvoCurto = r.destinatarios_especificos.length === 1 ? (r.destinatarios_especificos[0].nome || "Docente") : `${r.destinatarios_especificos.length} Docentes`;
          } else if (r.destinatarios && r.destinatarios !== "Todos os Professores e Funcionários" && r.destinatarios !== "Toda a Equipe Escolar (Geral)" && r.destinatarios !== "Todos") {
            rotuloAlvoCurto = r.destinatarios.replace(/^Cargos:\s*/i, "").replace(/^Específico:\s*/i, "");
          }
          if (rotuloAlvoCurto.length > 24) {
            rotuloAlvoCurto = rotuloAlvoCurto.slice(0, 22) + "...";
          }

          let badgePrioridade = '<span class="px-2.5 py-0.5 bg-slate-100 text-slate-700 rounded-md text-[11px] font-bold">Normal</span>';
          if (prioridade === "Importante") {
            badgePrioridade = '<span class="px-2.5 py-0.5 bg-amber-100 text-amber-900 border border-amber-300 rounded-md text-[11px] font-black"><i class="fa-solid fa-star text-amber-600 mr-1"></i>Importante</span>';
          } else if (prioridade === "Urgente") {
            badgePrioridade = '<span class="px-2.5 py-0.5 bg-rose-100 text-rose-800 border border-rose-300 rounded-md text-[11px] font-black animate-pulse"><i class="fa-solid fa-triangle-exclamation text-rose-600 mr-1"></i>Urgente</span>';
          }

          let dataFmt = "Recente";
          try {
            if (r.data_criacao) {
              const d = new Date(r.data_criacao);
              dataFmt = d.toLocaleDateString("pt-BR", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" });
            }
          } catch (e) {}

          const autorNome = r.autor_nome || "Equipe Gestora";
          const autorCargo = r.autor_cargo || "DIREÇÃO";
          const inicial = autorNome.charAt(0).toUpperCase() || "G";

          let borderCard = "border-slate-200/90";
          let bgHeader = "bg-slate-50/70";
          if (usuarioMencionado && !cienteAtual) {
            borderCard = "border-blue-400 ring-2 ring-blue-500/30";
            bgHeader = "bg-blue-50/70";
          } else if (isFixado) {
            borderCard = "border-amber-300 ring-2 ring-amber-400/25";
            bgHeader = "bg-amber-50/60";
          } else if (prioridade === "Urgente") {
            borderCard = "border-rose-300";
            bgHeader = "bg-rose-50/50";
          }

          if (isArquivado) {
            borderCard = "border-purple-200 opacity-85";
            bgHeader = "bg-purple-50/50";
          }

          const conteudoFormatado = window.formatarConteudoMural(r.conteudo || "Sem conteúdo.");

          return `
            <div 
              onclick="window.abrirModalVisualizarRecado('${r.id}')"
              class="bg-white rounded-2xl border ${borderCard} shadow-sm hover:shadow-md hover:border-blue-300 flex flex-col justify-between overflow-hidden transition cursor-pointer h-full group"
              title="Clique no recado para abrir a mensagem completa em janela"
            >
              <!-- Cabeçalho do Card de Recado -->
              <div class="p-4 sm:p-5 ${bgHeader} border-b border-slate-100 space-y-2.5">
                <div class="flex items-start justify-between gap-2">
                  <div class="flex items-center gap-1.5 flex-wrap min-w-0 flex-1">
                    ${isFixado ? `
                      <span class="px-2.5 py-0.5 bg-amber-500 text-white rounded-md text-[10px] font-black flex items-center gap-1 shadow-2xs">
                        <i class="fa-solid fa-thumbtack text-[9px]"></i> Fixado
                      </span>
                    ` : ''}
                    ${usuarioMencionado && !cienteAtual ? `
                      <span class="px-2.5 py-0.5 bg-blue-600 text-white rounded-md text-[10px] font-black flex items-center gap-1 shadow-2xs animate-pulse">
                        <i class="fa-solid fa-at text-[9px]"></i> Marcado
                      </span>
                    ` : ''}
                    ${isArquivado ? `
                      <span class="px-2.5 py-0.5 bg-purple-600 text-white rounded-md text-[10px] font-black flex items-center gap-1 shadow-2xs" title="${r.motivoAutoArquivamento || 'Recado arquivado'}">
                        <i class="fa-solid fa-box-archive text-[9px]"></i> ${r.autoArquivadoEm ? 'Arquivado Auto' : 'Arquivado'}
                      </span>
                    ` : infoMarcados.totalMarcados > 0 ? `
                      <span class="px-2 py-0.5 bg-sky-100 text-sky-900 border border-sky-300 rounded-md text-[10px] font-bold flex items-center gap-1 shadow-2xs" title="${infoMarcados.marcadosCientes} de ${infoMarcados.totalMarcados} destinatários marcados confirmaram ciência">
                        <i class="fa-solid fa-users text-[9px] text-sky-700"></i> ${infoMarcados.marcadosCientes}/${infoMarcados.totalMarcados} marcados
                      </span>
                    ` : ''}
                    ${badgePrioridade}
                    <span class="px-2.5 py-0.5 bg-blue-50 text-blue-900 border border-blue-200 rounded-md text-[11px] font-bold truncate max-w-[160px]">
                      ${r.categoria || "Geral"}
                    </span>
                  </div>

                  <!-- Ações Administrativas do Recado (Direção, CGPG, Vice-Direção, PAAC) -->
                  ${podeGerenciar ? `
                    <div class="flex items-center gap-1 shrink-0 bg-white/90 rounded-xl p-1 border border-slate-200 shadow-2xs" onclick="event.stopPropagation()">
                      <button 
                        type="button" 
                        onclick="event.stopPropagation(); window.alternarFixarRecado('${r.id}')" 
                        class="p-1.5 text-slate-500 hover:text-amber-600 hover:bg-amber-50 rounded-lg transition cursor-pointer"
                        title="${isFixado ? 'Desafixar do topo' : 'Fixar no topo do mural'}"
                      >
                        <i class="fa-solid fa-thumbtack text-xs ${isFixado ? 'text-amber-500' : ''}"></i>
                      </button>

                      <button 
                        type="button" 
                        onclick="event.stopPropagation(); window.editarRecado('${r.id}')" 
                        class="p-1.5 text-slate-500 hover:text-blue-700 hover:bg-blue-50 rounded-lg transition cursor-pointer"
                        title="Editar comunicado"
                      >
                        <i class="fa-solid fa-pen-to-square text-xs"></i>
                      </button>

                      <button 
                        type="button" 
                        onclick="event.stopPropagation(); window.arquivarRecado('${r.id}')" 
                        class="p-1.5 text-slate-500 hover:text-purple-700 hover:bg-purple-50 rounded-lg transition cursor-pointer"
                        title="${isArquivado ? 'Desarquivar e reativar' : 'Arquivar em memória'}"
                      >
                        <i class="fa-solid fa-box-archive text-xs ${isArquivado ? 'text-purple-600' : ''}"></i>
                      </button>

                      <button 
                        type="button" 
                        onclick="event.stopPropagation(); window.excluirRecado('${r.id}')" 
                        class="p-1.5 text-slate-500 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition cursor-pointer"
                        title="Excluir recado permanentemente"
                      >
                        <i class="fa-solid fa-trash-can text-xs"></i>
                      </button>
                    </div>
                  ` : ''}
                </div>

                <!-- Título do Comunicado -->
                <div class="flex items-start justify-between gap-2">
                  <h4 
                    class="text-base sm:text-lg font-black text-slate-900 leading-snug group-hover:text-blue-900 transition flex-1 break-words"
                  >
                    ${r.titulo || "Aviso Institucional"}
                  </h4>
                  <span class="inline-flex items-center gap-1 text-[11px] font-bold text-blue-700 bg-blue-50 group-hover:bg-blue-100 group-hover:text-blue-950 px-2.5 py-1 rounded-lg shrink-0 transition">
                    <i class="fa-solid fa-envelope-open-text text-[11px] text-cyan-600"></i>
                    <span>Ver Janela</span>
                  </span>
                </div>

                <!-- Metadados de Autoria e Data -->
                <div class="flex items-center justify-between text-xs text-slate-500 pt-2 border-t border-slate-200/60">
                  <div class="flex items-center gap-2 min-w-0 flex-1 truncate">
                    <div class="w-6 h-6 rounded-full bg-blue-900 text-cyan-300 flex items-center justify-center font-black text-[10px] shrink-0 shadow-2xs">
                      ${inicial}
                    </div>
                    <div class="truncate text-xs">
                      <span class="font-bold text-slate-800">${autorNome}</span>
                      <span class="text-[10px] text-blue-900 font-extrabold uppercase ml-1.5 px-2 py-0.5 bg-blue-100 rounded-md">
                        ${autorCargo}
                      </span>
                    </div>
                  </div>
                  <span class="shrink-0 font-medium text-[11px] text-slate-400 ml-2">${dataFmt}</span>
                </div>
              </div>

              <!-- Corpo do Recado (Exibição Completa Sem Truncamento) -->
              <div class="p-4 sm:p-5 flex-1 space-y-3 flex flex-col justify-between">
                <div class="text-[13px] sm:text-sm text-slate-700 font-normal leading-relaxed break-words mural-recado-body">
                  ${conteudoFormatado}
                </div>

                ${r.destinatarios ? `
                  <div class="pt-2 flex items-center gap-2 text-xs text-slate-600 font-medium border-t border-slate-100">
                    <i class="fa-solid fa-users text-blue-700 text-xs shrink-0"></i>
                    <span class="truncate">Destinado a: <strong class="text-slate-800">${r.destinatarios}</strong></span>
                  </div>
                ` : ''}
              </div>

              <!-- Rodapé do Card: Ações de Ciência e Leitura -->
              <div class="p-3.5 sm:p-4 bg-slate-50 border-t border-slate-100 flex items-center justify-between gap-2.5" onclick="event.stopPropagation()">
                <!-- Botão para Abrir Lista de Docentes Cientes -->
                <button 
                  type="button" 
                  onclick="event.stopPropagation(); window.abrirModalCientes('${r.id}')" 
                  class="px-3 py-1.5 bg-white hover:bg-slate-100 text-blue-900 border border-slate-200 rounded-xl text-xs font-bold transition flex items-center gap-1.5 cursor-pointer shadow-2xs shrink-0"
                  title="Ver quem já deu ciência"
                >
                  <i class="fa-solid fa-clipboard-check text-cyan-600"></i>
                  <span>${totalCientes} Ciente${totalCientes === 1 ? '' : 's'}</span>
                </button>

                <!-- Botão / Status de Ciência do Usuário Atual -->
                <div class="flex items-center gap-2">
                  ${cienteAtual ? `
                    <span class="px-3 py-1.5 bg-emerald-100 text-emerald-900 border border-emerald-300 rounded-xl text-xs font-black flex items-center gap-1.5 shadow-2xs">
                      <i class="fa-solid fa-circle-check text-emerald-600"></i>
                      <span>Ciente</span>
                    </span>
                  ` : isArquivado ? `
                    <span class="text-xs text-slate-400 font-bold italic">Arquivado</span>
                  ` : eAlvo ? `
                    <button 
                      type="button" 
                      onclick="event.stopPropagation(); window.darCienteRecado('${r.id}')" 
                      class="px-4 py-1.5 bg-emerald-600 hover:bg-emerald-500 text-white font-black rounded-xl text-xs shadow-xs transition flex items-center gap-1.5 cursor-pointer"
                    >
                      <i class="fa-solid fa-check"></i>
                      <span>Confirmar Ciência</span>
                    </button>
                  ` : `
                    <span class="px-2.5 py-1.5 bg-slate-100 text-slate-600 border border-slate-200 rounded-xl text-[11px] font-bold flex items-center gap-1.5 shadow-2xs" title="Todos podem visualizar este comunicado, mas a confirmação de ciência é restrita ao público-alvo: ${r.destinatarios || 'perfil específico'}">
                      <i class="fa-solid fa-lock text-slate-400 text-[10px]"></i>
                      <span>Ciência: ${rotuloAlvoCurto}</span>
                    </span>
                  `}
                </div>
              </div>
            </div>
          `;
        }).join("");
      };

      // Alternar Modo de Visualização do Layout (Grade 2 Colunas / Feed 1 Coluna Ampla)
      window.muralModoLayout = localStorage.getItem("mural_modo_layout") || "grid";
      window.alternarModoLayoutMural = function(modo) {
        window.muralModoLayout = modo;
        try {
          localStorage.setItem("mural_modo_layout", modo);
        } catch (e) {}
        window.renderizarMuralRecados();
      };

      // Listener global para fechar modais do mural com tecla Escape
      if (!window.__muralKeydownEscRegistrado) {
        window.__muralKeydownEscRegistrado = true;
        window.addEventListener("keydown", (e) => {
          if (e.key === "Escape") {
            if (window.recadoAbertoVisualizacaoCompleta) {
              window.fecharModalVisualizarRecado();
            }
            if (document.getElementById("modal-cientes-recado") && !document.getElementById("modal-cientes-recado").classList.contains("hidden")) {
              window.fecharModalCientes();
            }
            if (document.getElementById("modal-imagem-mural") && !document.getElementById("modal-imagem-mural").classList.contains("hidden")) {
              window.fecharModalImagemMural();
            }
          }
        });
      };

      // Alternar Abas do Mural (Ativos, Urgentes, Pendentes, Arquivados em Memória)
      window.filtrarMuralAba = function(aba) {
        window.muralAbaAtiva = aba;
        const tabs = ["ativos", "urgentes", "pendentes", "arquivados"];

        tabs.forEach(t => {
          const btn = document.getElementById(`mural-tab-${t}`);
          if (btn) {
            if (t === aba) {
              btn.className = "px-2.5 sm:px-3 py-1.5 bg-white text-blue-950 font-black rounded-lg shadow-sm text-xs flex items-center gap-1.5 transition cursor-pointer whitespace-nowrap shrink-0";
            } else {
              btn.className = "px-2.5 sm:px-3 py-1.5 text-slate-600 hover:text-slate-900 font-bold rounded-lg text-xs flex items-center gap-1.5 transition cursor-pointer whitespace-nowrap shrink-0";
            }
          }
        });

        window.renderizarMuralRecados();
      };

      // Filtrar por Categoria
      window.filtrarMuralPorCategoria = function(categoria) {
        window.muralCategoriaAtiva = categoria;
        window.renderizarMuralRecados();
      };

      // Filtrar por Texto de Pesquisa
      window.filtrarMuralPorTexto = function(texto) {
        window.muralTextoBusca = texto || "";
        window.renderizarMuralRecados();
      };

      // =========================================================
      // GERENCIAMENTO DE DESTINATÁRIOS / PÚBLICO DA CIÊNCIA
      // =========================================================
      window.atualizarModoDestinatariosRecado = function(tipo) {
        const modo = tipo || (document.getElementById("recado-modo-publico")?.value) || (document.getElementById("recado-destinatarios-tipo-select")?.value) || "todos";
        const modoNormalizado = (modo === "geral" || modo === "todos") ? "todos" : modo;

        const inputTipo = document.getElementById("recado-destinatarios-tipo");
        if (inputTipo) inputTipo.value = modoNormalizado;

        const selectModo = document.getElementById("recado-modo-publico");
        if (selectModo && selectModo.value !== modoNormalizado) {
          selectModo.value = modoNormalizado;
        }

        const boxCargos = document.getElementById("container-destinatarios-cargos");
        const boxEspec = document.getElementById("container-destinatarios-especificos");

        if (boxCargos) {
          if (modoNormalizado === "cargos") boxCargos.classList.remove("hidden");
          else boxCargos.classList.add("hidden");
        }

        if (boxEspec) {
          if (modoNormalizado === "especificos") {
            boxEspec.classList.remove("hidden");
            window.renderizarListaDocentesEspecificosRecado();
          } else {
            boxEspec.classList.add("hidden");
          }
        }

        window.atualizarResumoDestinatariosRecado();
      };

      window.atualizarResumoDestinatariosRecado = function() {
        const modo = document.getElementById("recado-destinatarios-tipo")?.value || "todos";
        const inputResumo = document.getElementById("recado-destinatarios");
        const textoResumoEl = document.getElementById("texto-resumo-publico-recado");

        let textoFormatado = "Toda a Equipe Escolar (Geral)";

        if (modo === "cargos") {
          const checkboxes = document.querySelectorAll("#container-destinatarios-cargos input[type='checkbox']:checked");
          const cargosSelecionados = Array.from(checkboxes).map(cb => cb.value);
          const inputCargos = document.getElementById("recado-destinatarios-cargos");
          if (inputCargos) inputCargos.value = JSON.stringify(cargosSelecionados);

          if (cargosSelecionados.length === 0) {
            textoFormatado = "Nenhum cargo selecionado (Marque ao menos um)";
          } else {
            const labelsMap = {
              "PROFESSOR": "Professores",
              "PROFESSORES": "Professores",
              "DIRETOR": "Direção",
              "VICE_DIRETOR": "Vice-Direção",
              "CGPG": "CGPG",
              "PAAC": "PAAC",
              "SECRETARIA": "Secretaria",
              "COORDENACAO": "Coordenação"
            };
            const nomesCargos = cargosSelecionados.map(c => labelsMap[c] || c);
            textoFormatado = "Cargos: " + nomesCargos.join(", ");
          }
        } else if (modo === "especificos") {
          let listaEspec = [];
          try {
            const raw = document.getElementById("recado-destinatarios-especificos")?.value || "[]";
            listaEspec = JSON.parse(raw);
          } catch (e) {
            listaEspec = [];
          }

          const contadorEl = document.getElementById("contador-especificos-selecionados");
          if (contadorEl) {
            contadorEl.textContent = `${listaEspec.length} selecionado(s)`;
          }

          if (listaEspec.length === 0) {
            textoFormatado = "Nenhum docente selecionado (Selecione abaixo)";
          } else if (listaEspec.length === 1) {
            textoFormatado = "Específico: " + (listaEspec[0].nome || listaEspec[0].email);
          } else {
            textoFormatado = `${listaEspec.length} Docentes Específicos selecionados`;
          }
        }

        if (inputResumo) inputResumo.value = textoFormatado;
        if (textoResumoEl) {
          textoResumoEl.innerHTML = `Ciência exigida de: <strong>${textoFormatado}</strong>`;
        }
      };

      window.obterListaTodosUsuariosMural = function() {
        let lista = [];
        if (Array.isArray(window.usuariosCache) && window.usuariosCache.length > 0) {
          lista = window.usuariosCache;
        } else if (typeof MOCK_AUTH_USERS !== "undefined") {
          lista = Object.values(MOCK_AUTH_USERS);
        }
        return lista;
      };

      window.renderizarListaDocentesEspecificosRecado = function(filtroTexto = "") {
        const container = document.getElementById("lista-checkboxes-docentes-recado") || document.getElementById("lista-docentes-especificos-recado");
        if (!container) return;

        const todosUsuarios = window.obterListaTodosUsuariosMural();
        let selecionados = [];
        try {
          const raw = document.getElementById("recado-destinatarios-especificos")?.value || "[]";
          selecionados = JSON.parse(raw);
        } catch (e) {
          selecionados = [];
        }

        const busca = (filtroTexto || "").toLowerCase().trim();
        const filtrados = todosUsuarios.filter(u => {
          if (!busca) return true;
          const n = String(u.nome || "").toLowerCase();
          const e = String(u.email || "").toLowerCase();
          const c = String(u.cargo || u.nivelAcesso || "").toLowerCase();
          return n.includes(busca) || e.includes(busca) || c.includes(busca);
        });

        if (filtrados.length === 0) {
          container.innerHTML = '<div class="p-3 text-center text-xs text-slate-400 font-medium">Nenhum docente encontrado para esta busca.</div>';
          return;
        }

        container.innerHTML = filtrados.map(u => {
          const email = String(u.email || "").toLowerCase().trim();
          const nome = String(u.nome || u.email || "Docente").trim();
          const cargo = u.cargo || u.nivelAcesso || "PROFESSOR";
          const isSelected = selecionados.some(s => (email && String(s.email || "").toLowerCase().trim() === email) || (nome && String(s.nome || "").toLowerCase().trim() === nome.toLowerCase()));

          return `
            <label class="flex items-center justify-between p-2 rounded-lg hover:bg-purple-50/70 border border-slate-200 hover:border-purple-300 bg-white cursor-pointer transition text-xs select-none">
              <div class="flex items-center gap-2 min-w-0 pr-2">
                <input 
                  type="checkbox" 
                  value="${email || nome}" 
                  ${isSelected ? "checked" : ""} 
                  onchange="window.alternarSelecaoDocenteEspecificoRecado('${email}', '${encodeURIComponent(nome)}', '${cargo}', this.checked)"
                  class="rounded text-purple-900 accent-purple-900 focus:ring-purple-500 shrink-0 cursor-pointer w-4 h-4"
                />
                <div class="truncate">
                  <span class="font-bold text-slate-800">${nome}</span>
                  <span class="text-[11px] text-slate-400 ml-1 truncate">(${cargo})</span>
                </div>
              </div>
              <span class="text-[10px] text-slate-400 truncate max-w-[140px] shrink-0">${email}</span>
            </label>
          `;
        }).join("");
      };

      window.filtrarDocentesEspecificosRecado = function(query) {
        window.renderizarListaDocentesEspecificosRecado(query);
      };

      window.alternarSelecaoDocenteEspecificoRecado = function(email, nomeEncoded, cargo, isChecked) {
        const nome = decodeURIComponent(nomeEncoded || "");
        const emailNorm = String(email || "").toLowerCase().trim();
        const nomeNorm = String(nome || "").toLowerCase().trim();

        const inputHidden = document.getElementById("recado-destinatarios-especificos");
        if (!inputHidden) return;

        let selecionados = [];
        try {
          selecionados = JSON.parse(inputHidden.value || "[]");
        } catch (e) {
          selecionados = [];
        }

        if (isChecked) {
          const jaExiste = selecionados.some(s => (emailNorm && String(s.email || "").toLowerCase().trim() === emailNorm) || (nomeNorm && String(s.nome || "").toLowerCase().trim() === nomeNorm));
          if (!jaExiste) {
            selecionados.push({ email: emailNorm, nome: nome, cargo: cargo || "PROFESSOR" });
          }
        } else {
          selecionados = selecionados.filter(s => {
            const sEmail = String(s.email || "").toLowerCase().trim();
            const sNome = String(s.nome || "").toLowerCase().trim();
            if (emailNorm && sEmail === emailNorm) return false;
            if (nomeNorm && sNome === nomeNorm) return false;
            return true;
          });
        }

        inputHidden.value = JSON.stringify(selecionados);
        window.atualizarResumoDestinatariosRecado();
      };

      // Abertura do Modal de Novo Recado
      window.abrirModalNovoRecado = function() {
        if (!window.podePublicarMural()) {
          if (typeof window.showToast === 'function') {
            window.showToast("Apenas Direção, CGPG, Vice-Direção e PAAC têm permissão para publicar recados.", "warning", 4000);
          }
          return;
        }

        const form = document.getElementById("form-novo-recado");
        if (form) form.reset();

        document.getElementById("recado-id").value = "";
        document.getElementById("modal-recado-titulo-modal").textContent = "Publicar Novo Recado no Mural";
        document.getElementById("btn-confirmar-salvar-recado-texto").textContent = "Publicar no Mural";

        // Reset dos controles granulares de público
        const selectTipo = document.getElementById("recado-modo-publico");
        if (selectTipo) selectTipo.value = "todos";
        const inputTipo = document.getElementById("recado-destinatarios-tipo");
        if (inputTipo) inputTipo.value = "todos";
        const inputCargos = document.getElementById("recado-destinatarios-cargos");
        if (inputCargos) inputCargos.value = "[]";
        const inputEspec = document.getElementById("recado-destinatarios-especificos");
        if (inputEspec) inputEspec.value = "[]";

        const checkboxes = document.querySelectorAll("#container-destinatarios-cargos input[type='checkbox']");
        checkboxes.forEach(cb => cb.checked = false);

        window.atualizarModoDestinatariosRecado("todos");

        if (typeof window.alternarModoEditorRecado === "function") {
          window.alternarModoEditorRecado("escrever");
        }
        if (typeof window.alternarMenuImagemRecado === "function") {
          window.alternarMenuImagemRecado(false);
        }
        if (typeof window.alternarMenuMencoesRecado === "function") {
          window.alternarMenuMencoesRecado(false);
        }

        document.getElementById("modal-novo-recado").classList.remove("hidden");
      };

      window.fecharModalNovoRecado = function() {
        const modal = document.getElementById("modal-novo-recado");
        if (modal) modal.classList.add("hidden");
        if (typeof window.alternarMenuImagemRecado === "function") {
          window.alternarMenuImagemRecado(false);
        }
        if (typeof window.alternarMenuMencoesRecado === "function") {
          window.alternarMenuMencoesRecado(false);
        }
      };

      // Editar Recado existente
      window.editarRecado = function(recadoId) {
        if (!window.podePublicarMural()) return;

        const recado = (window.muralRecadosCache || []).find(r => r.id === recadoId);
        if (!recado) return;

        document.getElementById("recado-id").value = recado.id;
        document.getElementById("recado-titulo").value = recado.titulo || "";
        document.getElementById("recado-categoria").value = recado.categoria || "Direção & Gestão";
        document.getElementById("recado-prioridade").value = recado.prioridade || "Normal";
        document.getElementById("recado-destinatarios").value = recado.destinatarios || "Todos os Professores e Funcionários";
        document.getElementById("recado-conteudo").value = recado.conteudo || "";
        document.getElementById("recado-fixado").checked = !!recado.fixado;

        // Configura público granular ao editar
        let tipoSalvo = recado.destinatarios_tipo || (recado.destinatarios === "Todos os Professores e Funcionários" ? "todos" : "todos");
        if (tipoSalvo === "geral") tipoSalvo = "todos";

        const selectTipo = document.getElementById("recado-modo-publico");
        if (selectTipo) selectTipo.value = tipoSalvo;
        const inputTipo = document.getElementById("recado-destinatarios-tipo");
        if (inputTipo) inputTipo.value = tipoSalvo;

        const cargosSalvos = Array.isArray(recado.destinatarios_cargos) ? recado.destinatarios_cargos : [];
        const inputCargos = document.getElementById("recado-destinatarios-cargos");
        if (inputCargos) inputCargos.value = JSON.stringify(cargosSalvos);

        const checkboxes = document.querySelectorAll("#container-destinatarios-cargos input[type='checkbox']");
        checkboxes.forEach(cb => {
          cb.checked = cargosSalvos.includes(cb.value);
        });

        const especSalvos = Array.isArray(recado.destinatarios_especificos) ? recado.destinatarios_especificos : [];
        const inputEspec = document.getElementById("recado-destinatarios-especificos");
        if (inputEspec) inputEspec.value = JSON.stringify(especSalvos);

        window.atualizarModoDestinatariosRecado(tipoSalvo);

        document.getElementById("modal-recado-titulo-modal").textContent = "Editar Comunicado do Mural";
        document.getElementById("btn-confirmar-salvar-recado-texto").textContent = "Salvar Alterações";

        if (typeof window.alternarModoEditorRecado === "function") {
          window.alternarModoEditorRecado("escrever");
        }
        if (typeof window.alternarMenuImagemRecado === "function") {
          window.alternarMenuImagemRecado(false);
        }
        if (typeof window.alternarMenuMencoesRecado === "function") {
          window.alternarMenuMencoesRecado(false);
        }

        document.getElementById("modal-novo-recado").classList.remove("hidden");
      };

      // Salvar (Criar ou Atualizar) Recado no Banco de Dados e Atualizar Memória
      window.salvarRecadoMural = async function(event) {
        if (event) event.preventDefault();

        if (!window.podePublicarMural()) {
          window.showToast("Acesso restrito: Apenas Direção, CGPG, Vice-Direção e PAAC podem publicar recados.", "warning");
          return;
        }

        const id = document.getElementById("recado-id").value;
        const titulo = document.getElementById("recado-titulo").value.trim();
        const categoria = document.getElementById("recado-categoria").value;
        const prioridade = document.getElementById("recado-prioridade").value;
        const conteudo = document.getElementById("recado-conteudo").value.trim();
        const fixado = document.getElementById("recado-fixado").checked;

        // Extrai configurações de público-alvo granular
        let destinatariosTipo = document.getElementById("recado-destinatarios-tipo")?.value || "todos";
        if (destinatariosTipo === "geral") destinatariosTipo = "todos";

        let destinatariosCargos = [];
        try {
          const rawCargos = document.getElementById("recado-destinatarios-cargos")?.value || "[]";
          destinatariosCargos = JSON.parse(rawCargos);
        } catch (e) {
          destinatariosCargos = [];
        }

        let destinatariosEspecificos = [];
        try {
          const rawEspec = document.getElementById("recado-destinatarios-especificos")?.value || "[]";
          destinatariosEspecificos = JSON.parse(rawEspec);
        } catch (e) {
          destinatariosEspecificos = [];
        }

        const destinatarios = document.getElementById("recado-destinatarios")?.value || "Todos os Professores e Funcionários";

        if (!titulo || !conteudo) {
          window.showToast("Por favor, preencha o título e a mensagem do recado.", "warning");
          return;
        }

        if (destinatariosTipo === "cargos" && destinatariosCargos.length === 0) {
          window.showToast("Selecione pelo menos um cargo para o público da ciência.", "warning");
          return;
        }

        if (destinatariosTipo === "especificos" && destinatariosEspecificos.length === 0) {
          window.showToast("Selecione pelo menos um docente específico para o público da ciência.", "warning");
          return;
        }

        const btnSalvar = document.getElementById("btn-confirmar-salvar-recado");
        const btnSalvarTexto = document.getElementById("btn-confirmar-salvar-recado-texto");
        if (btnSalvar) btnSalvar.disabled = true;
        if (btnSalvarTexto) btnSalvarTexto.textContent = "Gravando...";

        const userObj = (typeof window.obterIdentificacaoUsuarioCompleta === 'function')
          ? window.obterIdentificacaoUsuarioCompleta()
          : { email: auth.currentUser?.email || '', nome: 'Equipe Gestora', cargo: 'DIRETOR' };

        try {
          if (id) {
            // Edição
            const recadoRef = doc(db, "mural_recados", id);
            const dadosAtualizados = {
              titulo,
              categoria,
              prioridade,
              destinatarios,
              destinatarios_tipo: destinatariosTipo,
              destinatarios_cargos: destinatariosCargos,
              destinatarios_especificos: destinatariosEspecificos,
              conteudo,
              fixado,
              atualizadoEm: new Date().toISOString(),
              autorAtualizacao: userObj.nome
            };

            await updateDoc(recadoRef, dadosAtualizados);

            // Atualiza em memória imediatamente
            const idx = window.muralRecadosCache.findIndex(r => r.id === id);
            if (idx >= 0) {
              window.muralRecadosCache[idx] = {
                ...window.muralRecadosCache[idx],
                ...dadosAtualizados
              };
            }

            window.showToast("Recado atualizado com sucesso!", "success");
          } else {
            // Novo Recado
            const agoraIso = new Date().toISOString();
            const novoRecado = {
              titulo,
              categoria,
              prioridade,
              destinatarios,
              destinatarios_tipo: destinatariosTipo,
              destinatarios_cargos: destinatariosCargos,
              destinatarios_especificos: destinatariosEspecificos,
              conteudo,
              fixado,
              arquivado: false,
              data_criacao: agoraIso,
              autor_nome: userObj.nome,
              autor_email: userObj.email,
              autor_cargo: userObj.cargo,
              cientes: [
                {
                  nome: userObj.nome,
                  email: userObj.email,
                  cargo: userObj.cargo,
                  data: agoraIso
                }
              ]
            };

            let docId = "recado-" + Date.now();
            try {
              const docRef = await addDoc(collection(db, "mural_recados"), novoRecado);
              docId = docRef.id;
            } catch (errDb) {
              console.warn("Mural salvando em modo local resiliente:", errDb?.message || errDb);
            }
            novoRecado.id = docId;

            // Insere na memória
            window.muralRecadosCache.unshift(novoRecado);
            window.showToast("Recado publicado com sucesso no mural!", "success");
          }

          try {
            localStorage.setItem("mural_recados_memoria", JSON.stringify(window.muralRecadosCache));
          } catch (e) {}

          window.fecharModalNovoRecado();
          window.renderizarMuralRecados();

        } catch (err) {
          console.warn("Recado mantido no armazenamento local:", err?.message || err);
          window.fecharModalNovoRecado();
          window.renderizarMuralRecados();
        } finally {
          if (btnSalvar) btnSalvar.disabled = false;
          if (btnSalvarTexto) btnSalvarTexto.textContent = id ? "Salvar Alterações" : "Publicar no Mural";
        }
      };

      // Confirmação de Ciência (Professor / Funcionário) com trava anti-duplicação por perfil e validação de público-alvo
      window.darCienteRecado = async function(recadoId) {
        if (window._processandoCiencia && window._processandoCiencia[recadoId]) {
          return;
        }

        const userObj = (typeof window.obterIdentificacaoUsuarioCompleta === 'function')
          ? window.obterIdentificacaoUsuarioCompleta()
          : { email: auth.currentUser?.email || '', nome: 'Professor', cargo: 'PROFESSOR' };

        const emailUser = String(userObj.email || '').toLowerCase().trim();
        const nomeUser = String(userObj.nome || '').trim();
        const cargoUser = (typeof window.obterRoleAtual === 'function') ? window.obterRoleAtual() : (userObj.cargo || 'PROFESSOR');

        const recado = (window.muralRecadosCache || []).find(r => r.id === recadoId);
        if (!recado) return;

        // 1. Validação de público-alvo: todos podem ver, mas só o público-alvo pode dar ciência
        if (typeof window.usuarioEAlvoDoRecado === 'function' && !window.usuarioEAlvoDoRecado(recado, userObj)) {
          window.showToast(`A confirmação de ciência é restrita aos destinatários designados (${recado.destinatarios || 'perfil específico'}).`, "warning", 3500);
          return;
        }

        if (!Array.isArray(recado.cientes)) {
          recado.cientes = [];
        }

        // 2. Trava anti-duplicação: marca uma única vez para cada perfil
        if (typeof window.usuarioDeuCienteRecado === 'function' && window.usuarioDeuCienteRecado(recado, userObj)) {
          window.showToast("Você já confirmou ciência neste comunicado.", "info", 2500);
          return;
        }

        if (!window._processandoCiencia) window._processandoCiencia = {};
        window._processandoCiencia[recadoId] = true;

        const registroCiencia = {
          nome: nomeUser,
          email: emailUser,
          cargo: cargoUser,
          data: new Date().toISOString()
        };

        // Atualização instantânea em memória local
        recado.cientes.push(registroCiencia);

        if (typeof window.renderizarMuralRecados === 'function') {
          window.renderizarMuralRecados();
        }

        // Se o modal de visualização detalhada estiver aberto para este recado, atualiza em tempo real
        if (window.recadoAbertoVisualizacaoCompleta === recadoId && typeof window.abrirModalVisualizarRecado === 'function') {
          window.abrirModalVisualizarRecado(recadoId);
        }

        try {
          localStorage.setItem("mural_recados_memoria", JSON.stringify(window.muralRecadosCache));
        } catch (e) {}

        // Persistência robusta no Banco de Dados com array limpo e consistente
        try {
          const recadoRef = doc(db, "mural_recados", recadoId);
          await updateDoc(recadoRef, {
            cientes: recado.cientes
          });
          window.showToast("Ciência confirmada com sucesso!", "success", 2500);
        } catch (errDb) {
          console.warn("Aviso ao persistir ciência no Banco de Dados:", errDb);
          window.showToast("Ciência salva localmente.", "info", 2000);
        } finally {
          setTimeout(() => {
            if (window._processandoCiencia) delete window._processandoCiencia[recadoId];
          }, 500);
        }
      };

      // Alternar Fixação do Recado no Topo
      window.alternarFixarRecado = async function(recadoId) {
        if (!window.podePublicarMural()) return;
        const recado = (window.muralRecadosCache || []).find(r => r.id === recadoId);
        if (!recado) return;

        recado.fixado = !recado.fixado;
        window.renderizarMuralRecados();

        try {
          const recadoRef = doc(db, "mural_recados", recadoId);
          await updateDoc(recadoRef, { fixado: recado.fixado });
          window.showToast(recado.fixado ? "Recado fixado no topo!" : "Recado desafixado.", "info");
          try {
            localStorage.setItem("mural_recados_memoria", JSON.stringify(window.muralRecadosCache));
          } catch (e) {}
        } catch (err) {
          console.error("Erro ao fixar recado:", err);
        }
      };

      // Arquivar / Desarquivar Recado (Mantendo em memória para consulta permanente)
      window.arquivarRecado = async function(recadoId) {
        if (!window.podePublicarMural()) return;
        const recado = (window.muralRecadosCache || []).find(r => r.id === recadoId);
        if (!recado) return;

        const novoStatus = !recado.arquivado;
        recado.arquivado = novoStatus;
        recado.arquivadoManualmente = novoStatus;
        if (!novoStatus) {
          delete recado.autoArquivadoEm;
          delete recado.motivoAutoArquivamento;
        }
        window.renderizarMuralRecados();

        try {
          const recadoRef = doc(db, "mural_recados", recadoId);
          await updateDoc(recadoRef, { 
            arquivado: novoStatus,
            arquivadoManualmente: novoStatus,
            autoArquivadoEm: null,
            motivoAutoArquivamento: null
          });
          window.showToast(novoStatus ? "Recado arquivado! Ele continuará salvo na memória para consulta." : "Recado restaurado para os ativos!", "success");
          try {
            localStorage.setItem("mural_recados_memoria", JSON.stringify(window.muralRecadosCache));
          } catch (e) {}
        } catch (err) {
          console.error("Erro ao arquivar recado:", err);
        }
      };

      // Excluir Recado Permanentemente
      window.excluirRecado = async function(recadoId) {
        if (!window.podePublicarMural()) return;
        const recado = (window.muralRecadosCache || []).find(r => r.id === recadoId);
        if (!recado) return;

        if (!confirm(`Tem certeza que deseja excluir o recado "${recado.titulo}" do mural?`)) {
          return;
        }

        window.muralRecadosCache = window.muralRecadosCache.filter(r => r.id !== recadoId);
        window.renderizarMuralRecados();

        try {
          await deleteDoc(doc(db, "mural_recados", recadoId));
          window.showToast("Recado excluído permanentemente.", "success");
          try {
            localStorage.setItem("mural_recados_memoria", JSON.stringify(window.muralRecadosCache));
          } catch (e) {}
        } catch (err) {
          console.error("Erro ao excluir recado:", err);
          window.showToast("Erro ao excluir recado no banco de dados.", "error");
        }
      };

      // =========================================================
      // MODAL DE VISUALIZAÇÃO COMPLETA DE RECADO LONGO / DETALHES
      // =========================================================
      window.recadoAbertoVisualizacaoCompleta = null;

      window.abrirModalVisualizarRecado = function(recadoId) {
        const recado = (window.muralRecadosCache || []).find(r => r.id === recadoId);
        if (!recado) return;

        window.recadoAbertoVisualizacaoCompleta = recadoId;
        const modal = document.getElementById("modal-visualizar-recado");
        if (!modal) return;

        const isFixado = !!recado.fixado;
        const isArquivado = !!recado.arquivado;
        const prioridade = recado.prioridade || "Normal";
        const cientes = Array.isArray(recado.cientes) ? recado.cientes : [];
        const totalCientes = cientes.length;
        const userObj = typeof window.obterIdentificacaoUsuarioCompleta === "function" ? window.obterIdentificacaoUsuarioCompleta() : { email: '', nome: 'Usuário', cargo: 'PROFESSOR' };
        const cienteAtual = typeof window.usuarioDeuCienteRecado === "function" ? window.usuarioDeuCienteRecado(recado, userObj) : false;
        const eAlvo = typeof window.usuarioEAlvoDoRecado === "function" ? window.usuarioEAlvoDoRecado(recado, userObj) : true;
        const usuarioMencionado = typeof window.verificarUsuarioMencionadoNoRecado === "function" ? window.verificarUsuarioMencionadoNoRecado(recado, userObj) : false;

        // Renderizar Badges
        const badgesContainer = document.getElementById("modal-view-recado-badges");
        if (badgesContainer) {
          let htmlBadges = "";
          if (isFixado) {
            htmlBadges += `<span class="px-2.5 py-1 bg-amber-500 text-white rounded-lg text-[11px] font-black flex items-center gap-1 shadow-2xs"><i class="fa-solid fa-thumbtack text-[10px]"></i> Fixado no Topo</span>`;
          }
          if (usuarioMencionado && !cienteAtual) {
            htmlBadges += `<span class="px-2.5 py-1 bg-blue-600 text-white rounded-lg text-[11px] font-black flex items-center gap-1 shadow-2xs animate-bounce"><i class="fa-solid fa-at text-[10px]"></i> Você foi Marcado</span>`;
          }
          if (isArquivado) {
            htmlBadges += `<span class="px-2.5 py-1 bg-purple-600 text-white rounded-lg text-[11px] font-black flex items-center gap-1"><i class="fa-solid fa-box-archive text-[10px]"></i> Arquivado em Memória</span>`;
          }
          if (prioridade === "Importante") {
            htmlBadges += `<span class="px-2.5 py-1 bg-amber-100 text-amber-900 border border-amber-300 rounded-lg text-[11px] font-black"><i class="fa-solid fa-star text-amber-600 mr-1"></i>Importante</span>`;
          } else if (prioridade === "Urgente") {
            htmlBadges += `<span class="px-2.5 py-1 bg-rose-100 text-rose-800 border border-rose-300 rounded-lg text-[11px] font-black animate-pulse"><i class="fa-solid fa-triangle-exclamation text-rose-600 mr-1"></i>Urgente</span>`;
          } else {
            htmlBadges += `<span class="px-2.5 py-1 bg-slate-100 text-slate-700 rounded-lg text-[11px] font-bold">Normal</span>`;
          }
          htmlBadges += `<span class="px-2.5 py-1 bg-blue-50 text-blue-900 border border-blue-200 rounded-lg text-[11px] font-bold">${recado.categoria || "Geral"}</span>`;
          badgesContainer.innerHTML = htmlBadges;
        }

        // Título
        const tituloEl = document.getElementById("modal-view-recado-titulo");
        if (tituloEl) tituloEl.textContent = recado.titulo || "Aviso Institucional";

        // Autoria e Data
        const autorNome = recado.autor_nome || "Equipe Gestora";
        const autorCargo = recado.autor_cargo || "DIREÇÃO";
        const inicial = autorNome.charAt(0).toUpperCase() || "G";

        const autorEl = document.getElementById("modal-view-recado-autor");
        if (autorEl) autorEl.textContent = autorNome;

        const cargoEl = document.getElementById("modal-view-recado-cargo");
        if (cargoEl) cargoEl.textContent = autorCargo;

        const avatarEl = document.getElementById("modal-view-recado-avatar");
        if (avatarEl) avatarEl.textContent = inicial;

        let dataFmt = "Recente";
        try {
          if (recado.data_criacao) {
            const d = new Date(recado.data_criacao);
            dataFmt = d.toLocaleDateString("pt-BR", { day: "2-digit", month: "long", year: "numeric", hour: "2-digit", minute: "2-digit" });
          }
        } catch(e) {}
        const dataEl = document.getElementById("modal-view-recado-data");
        if (dataEl) dataEl.textContent = dataFmt;

        // Destinatários
        const destBox = document.getElementById("modal-view-recado-destinatarios-box");
        const destEl = document.getElementById("modal-view-recado-destinatarios");
        if (destBox && destEl) {
          if (recado.destinatarios) {
            destEl.textContent = recado.destinatarios;
            destBox.classList.remove("hidden");
          } else {
            destBox.classList.add("hidden");
          }
        }

        // Conteúdo Completo Formatado
        const conteudoEl = document.getElementById("modal-view-recado-conteudo");
        if (conteudoEl) {
          conteudoEl.innerHTML = window.formatarConteudoMural(recado.conteudo || "Sem conteúdo.");
        }

        // Contagem de cientes
        const countCientesEl = document.getElementById("modal-view-recado-count-cientes");
        if (countCientesEl) {
          countCientesEl.textContent = `${totalCientes} Ciente${totalCientes === 1 ? '' : 's'}`;
        }

        // Status de Ciência / Botão Interativo
        const statusCienciaContainer = document.getElementById("modal-view-recado-status-ou-btn-ciente");
        if (statusCienciaContainer) {
          if (cienteAtual) {
            statusCienciaContainer.innerHTML = `
              <span class="px-4 py-2 bg-emerald-100 text-emerald-900 border border-emerald-300 rounded-xl text-xs font-black flex items-center gap-1.5 shadow-2xs">
                <i class="fa-solid fa-circle-check text-emerald-600 text-sm"></i>
                <span>Ciente Confirmado</span>
              </span>
            `;
          } else if (isArquivado) {
            const motivo = recado.motivoAutoArquivamento || (recado.autoArquivadoEm ? "Todos os destinatários marcados confirmaram ciência." : "Recado arquivado para consulta histórica.");
            statusCienciaContainer.innerHTML = `
              <div class="flex items-center gap-2 flex-wrap">
                <span class="px-3.5 py-1.5 bg-purple-100 text-purple-950 border border-purple-300 rounded-xl text-xs font-black flex items-center gap-1.5 shadow-2xs">
                  <i class="fa-solid fa-box-archive text-purple-700"></i>
                  <span>Recado Arquivado</span>
                </span>
                <span class="text-xs text-purple-800 font-semibold italic">${motivo}</span>
              </div>
            `;
          } else if (eAlvo) {
            statusCienciaContainer.innerHTML = `
              <button 
                type="button" 
                onclick="window.darCienteRecado('${recado.id}');" 
                class="px-5 py-2 bg-emerald-600 hover:bg-emerald-500 text-white font-black rounded-xl text-xs shadow-md transition flex items-center gap-2 cursor-pointer"
              >
                <i class="fa-solid fa-check text-white"></i>
                <span>Confirmar Ciência Agora</span>
              </button>
            `;
          } else {
            statusCienciaContainer.innerHTML = `
              <span class="px-4 py-2 bg-slate-100 text-slate-600 border border-slate-200 rounded-xl text-xs font-bold flex items-center gap-2 shadow-2xs" title="Todos podem visualizar este comunicado, mas a confirmação de ciência é restrita aos destinatários designados.">
                <i class="fa-solid fa-lock text-slate-400 text-sm"></i>
                <span>Ciência Restrita ao Perfil Alvo (${recado.destinatarios || 'Específico'})</span>
              </span>
            `;
          }
        }

        modal.classList.remove("hidden");
      };

      window.fecharModalVisualizarRecado = function() {
        const modal = document.getElementById("modal-visualizar-recado");
        if (modal) modal.classList.add("hidden");
        window.recadoAbertoVisualizacaoCompleta = null;
      };

      window.abrirModalCientesDoRecadoAberto = function() {
        if (window.recadoAbertoVisualizacaoCompleta) {
          window.abrirModalCientes(window.recadoAbertoVisualizacaoCompleta);
        }
      };

      // =========================================================
      // MODAL DE CONFIRMAÇÕES DE CIÊNCIA (CIENTES)
      // =========================================================
      window.abrirModalCientes = function(recadoId) {
        window.recadoCientesVisualizando = recadoId;
        window.abaModalCientesAtiva = "confirmados";
        window.textoBuscaCientesModal = "";

        const recado = (window.muralRecadosCache || []).find(r => r.id === recadoId);
        const sub = document.getElementById("modal-cientes-subtitulo");
        if (sub && recado) {
          sub.textContent = `Recado: "${recado.titulo}"`;
        }

        const inputBusca = document.getElementById("modal-cientes-busca-input");
        if (inputBusca) inputBusca.value = "";

        window.renderizarCientesModal();
        document.getElementById("modal-cientes-recado").classList.remove("hidden");
      };

      window.fecharModalCientes = function() {
        const modal = document.getElementById("modal-cientes-recado");
        if (modal) modal.classList.add("hidden");
      };

      window.alternarAbaModalCientes = function(aba) {
        window.abaModalCientesAtiva = aba;
        const btnConf = document.getElementById("btn-tab-cientes-confirmados");
        const btnPend = document.getElementById("btn-tab-cientes-pendentes");

        if (btnConf && btnPend) {
          if (aba === "confirmados") {
            btnConf.className = "px-3.5 py-1.5 bg-blue-900 text-white font-bold text-xs rounded-xl transition cursor-pointer flex items-center gap-1.5 shadow-2xs";
            btnPend.className = "px-3.5 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl transition cursor-pointer flex items-center gap-1.5";
          } else {
            btnConf.className = "px-3.5 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl transition cursor-pointer flex items-center gap-1.5";
            btnPend.className = "px-3.5 py-1.5 bg-blue-900 text-white font-bold text-xs rounded-xl transition cursor-pointer flex items-center gap-1.5 shadow-2xs";
          }
        }

        window.renderizarCientesModal();
      };

      window.filtrarCientesModal = function(texto) {
        window.textoBuscaCientesModal = texto || "";
        window.renderizarCientesModal();
      };

      window.renderizarCientesModal = function() {
        const recadoId = window.recadoCientesVisualizando;
        const recado = (window.muralRecadosCache || []).find(r => r.id === recadoId);
        const container = document.getElementById("modal-cientes-lista-container");
        if (!container || !recado) return;

        const cientesConfirmados = Array.isArray(recado.cientes) ? recado.cientes : [];

        // Monta lista de todos os usuários do sistema cadastrados (para comparar quem está pendente)
        let todosUsuarios = [];
        if (Array.isArray(window.usuariosCache) && window.usuariosCache.length > 0) {
          todosUsuarios = window.usuariosCache;
        } else if (typeof MOCK_AUTH_USERS !== "undefined") {
          todosUsuarios = Object.values(MOCK_AUTH_USERS);
        }

        // Filtra os usuários que pertencem ao público-alvo deste recado
        const tipoAlvo = recado.destinatarios_tipo || (recado.destinatarios === "Todos os Professores e Funcionários" ? "geral" : "");
        let usuariosAlvo = todosUsuarios;

        const especificos = Array.isArray(recado.destinatarios_especificos) && recado.destinatarios_especificos.length > 0
          ? recado.destinatarios_especificos
          : (Array.isArray(recado.professoresSelecionados) ? recado.professoresSelecionados : []);

        // Obter marcados via menção se existirem
        const listaMarcados = typeof window.obterListaMarcadosRecado === 'function' ? window.obterListaMarcadosRecado(recado) : [];
        const pessoasMarcadas = listaMarcados.filter(m => m && m.tipo === 'pessoa' && !['todos', 'equipe', 'geral', 'escola'].includes((m.nome || '').toLowerCase()));

        if (tipoAlvo === "especificos" || especificos.length > 0 || (pessoasMarcadas.length > 0 && tipoAlvo !== "cargos")) {
          const listaBase = especificos.length > 0 ? especificos : pessoasMarcadas;
          const alvosConstruidos = [];
          const vistos = new Set();

          listaBase.forEach(esp => {
            const espNome = String(esp.nome || '').trim();
            const espEmail = String(esp.email || '').toLowerCase().trim();
            const normNome = espNome.toLowerCase();

            // Tenta encontrar em todosUsuarios
            const achado = todosUsuarios.find(u => {
              const uEmail = String(u.email || '').toLowerCase().trim();
              const uNome = String(u.nome || '').toLowerCase().trim();
              if (espEmail && uEmail && espEmail === uEmail) return true;
              if (normNome && uNome && (normNome === uNome || normNome.includes(uNome) || uNome.includes(normNome))) return true;
              return false;
            });

            const chave = espEmail || normNome;
            if (chave && !vistos.has(chave)) {
              vistos.add(chave);
              if (achado) {
                alvosConstruidos.push(achado);
              } else {
                alvosConstruidos.push({
                  nome: espNome,
                  email: espEmail,
                  cargo: esp.cargo || 'Docente Marcado'
                });
              }
            }
          });

          if (alvosConstruidos.length > 0) {
            usuariosAlvo = alvosConstruidos;
          }
        } else if (tipoAlvo === "cargos") {
          const cargosAlvo = Array.isArray(recado.destinatarios_cargos) ? recado.destinatarios_cargos : [];
          if (cargosAlvo.length > 0) {
            usuariosAlvo = todosUsuarios.filter(u => {
              const myCargo = String(u.cargo || u.nivelAcesso || "").toUpperCase().trim();
              return cargosAlvo.some(cg => {
                const cgNorm = String(cg || "").toUpperCase().trim();
                if (cgNorm === myCargo) return true;
                if (cgNorm === 'PROFESSORES' && (myCargo.includes('PROFESSOR') || myCargo === 'DOCENTE')) return true;
                if (cgNorm === 'DIRECAO' && (myCargo.includes('DIRETOR') || myCargo.includes('VICE'))) return true;
                if (cgNorm === 'COORDENACAO' && (myCargo.includes('COORDENADOR') || myCargo.includes('CGPG') || myCargo.includes('CGPAC'))) return true;
                if (cgNorm === 'SECRETARIA' && (myCargo.includes('SECRETAR') || myCargo.includes('GOE') || myCargo.includes('AOE'))) return true;
                if (cgNorm === 'PAAC' && myCargo.includes('PAAC')) return true;
                if (cgNorm === 'OUTROS') return true;
                return false;
              });
            });
          }
        }

        // Calcula pendentes considerando apenas o público-alvo esperado
        const pendentes = usuariosAlvo.filter(u => {
          const uEmail = String(u.email || '').toLowerCase().trim();
          const uNome = String(u.nome || '').toLowerCase().trim();
          return !cientesConfirmados.some(c => {
            const cEmail = String(c.email || '').toLowerCase().trim();
            const cNome = String(c.nome || '').toLowerCase().trim();
            return (uEmail && cEmail === uEmail) || (uNome && cNome === uNome);
          });
        });

        // Atualiza contadores
        const elTotalConf = document.getElementById("modal-cientes-total-confirmados");
        const elTotalPend = document.getElementById("modal-cientes-total-pendentes");
        if (elTotalConf) elTotalConf.textContent = cientesConfirmados.length;
        if (elTotalPend) elTotalPend.textContent = pendentes.length;

        const aba = window.abaModalCientesAtiva || "confirmados";
        const busca = (window.textoBuscaCientesModal || "").toLowerCase().trim();

        let listaExibir = aba === "confirmados" ? cientesConfirmados : pendentes;

        if (busca) {
          listaExibir = listaExibir.filter(item => {
            const n = String(item.nome || '').toLowerCase();
            const e = String(item.email || '').toLowerCase();
            const c = String(item.cargo || item.nivelAcesso || '').toLowerCase();
            return n.includes(busca) || e.includes(busca) || c.includes(busca);
          });
        }

        if (listaExibir.length === 0) {
          container.innerHTML = `
            <div class="p-6 text-center text-xs text-slate-500 font-bold bg-slate-50 rounded-xl border border-slate-200">
              ${aba === "confirmados" ? "Nenhum docente confirmado nesta busca." : "Nenhum docente pendente nesta busca."}
            </div>
          `;
          return;
        }

        container.innerHTML = listaExibir.map(item => {
          const nome = item.nome || item.email || "Docente";
          const email = item.email || "—";
          const cargo = item.cargo || item.nivelAcesso || "PROFESSOR";
          const inicial = nome.charAt(0).toUpperCase();

          let dataFmt = "";
          if (item.data) {
            try {
              const d = new Date(item.data);
              dataFmt = d.toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" });
            } catch (e) {}
          }

          return `
            <div class="p-2.5 sm:p-3 bg-slate-50 border border-slate-200 rounded-xl flex items-center justify-between gap-3">
              <div class="flex items-center gap-2.5 min-w-0">
                <div class="w-8 h-8 rounded-xl ${aba === 'confirmados' ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'} font-black text-xs flex items-center justify-center shrink-0">
                  ${inicial}
                </div>
                <div class="truncate">
                  <div class="text-xs font-bold text-slate-900 truncate">${nome}</div>
                  <div class="text-[11px] text-slate-500 truncate">${email} &bull; <span class="uppercase font-semibold text-blue-900">${cargo}</span></div>
                </div>
              </div>

              <div class="text-right shrink-0">
                ${aba === 'confirmados' ? `
                  <span class="px-2 py-0.5 bg-emerald-100 text-emerald-900 border border-emerald-200 rounded text-[10px] font-black flex items-center gap-1">
                    <i class="fa-solid fa-check text-emerald-600"></i> ${dataFmt || 'Confirmado'}
                  </span>
                ` : `
                  <span class="px-2 py-0.5 bg-amber-100 text-amber-900 border border-amber-200 rounded text-[10px] font-black flex items-center gap-1">
                    <i class="fa-solid fa-clock text-amber-600"></i> Pendente
                  </span>
                `}
              </div>
            </div>
          `;
        }).join("");
      };

      // Copiar Lista de Cientes para a Área de Transferência
      window.copiarListaCientes = function() {
        const recadoId = window.recadoCientesVisualizando;
        const recado = (window.muralRecadosCache || []).find(r => r.id === recadoId);
        if (!recado) return;

        const cientes = Array.isArray(recado.cientes) ? recado.cientes : [];
        if (cientes.length === 0) {
          window.showToast("Nenhum docente ciente registrado para copiar.", "info");
          return;
        }

        const linhas = [
          `COMPROVANTE DE CIÊNCIA - EE CLÓVIS DE LUCCA`,
          `Comunicado: ${recado.titulo}`,
          `Data de Publicação: ${recado.data_criacao || '—'}`,
          `Total de Confirmações: ${cientes.length}`,
          `-------------------------------------------`,
          ...cientes.map((c, i) => `${i + 1}. ${c.nome} (${c.cargo || 'Docente'}) - ${c.data ? new Date(c.data).toLocaleString('pt-BR') : 'Confirmado'}`)
        ].join("\n");

        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(linhas).then(() => {
            window.showToast("Lista de cientes copiada para a área de transferência!", "success");
          }).catch(() => {
            window.showToast("Não foi possível copiar automaticamente.", "warning");
          });
        } else {
          window.showToast("Área de transferência não suportada neste navegador.", "info");
        }
      };

      // Elementos do DOM
      const loginScreen = document.getElementById("loginScreen");
      const mainPanel = document.getElementById("mainPanel");
      const loginForm = document.getElementById("loginForm");
      const emailInput = document.getElementById("email");
      const passwordInput = document.getElementById("password");
      const errorMessage = document.getElementById("errorMessage");
      const errorText = document.getElementById("errorText");
      const btnLogin = document.getElementById("btnLogin");
      const btnLogout = document.getElementById("btnLogout");
      const userEmailDisplay = document.getElementById("userEmailDisplay");

      // Ocultar mensagem de erro ao digitar
      if (emailInput) emailInput.addEventListener("input", () => errorMessage && errorMessage.classList.add("hidden"));
      if (passwordInput) passwordInput.addEventListener("input", () => errorMessage && errorMessage.classList.add("hidden"));

      // Funcionalidade "Exibir Senha" no Login
      const btnTogglePassword = document.getElementById("btnTogglePassword");
      const btnTogglePasswordIcon = document.getElementById("btnTogglePasswordIcon");
      const iconTogglePassword = document.getElementById("iconTogglePassword");
      const iconTogglePasswordInline = document.getElementById("iconTogglePasswordInline");
      const textTogglePassword = document.getElementById("textTogglePassword");

      function alternarVisibilidadeSenhaLogin() {
        if (!passwordInput) return;
        const ehSenha = passwordInput.type === "password";
        passwordInput.type = ehSenha ? "text" : "password";

        if (iconTogglePassword) {
          iconTogglePassword.className = ehSenha ? "fa-regular fa-eye-slash text-xs" : "fa-regular fa-eye text-xs";
        }
        if (iconTogglePasswordInline) {
          iconTogglePasswordInline.className = ehSenha ? "fa-regular fa-eye-slash text-sm text-cyan-600" : "fa-regular fa-eye text-sm";
        }
        if (textTogglePassword) {
          textTogglePassword.textContent = ehSenha ? "Ocultar senha" : "Exibir senha";
        }
      }

      if (btnTogglePassword) btnTogglePassword.addEventListener("click", alternarVisibilidadeSenhaLogin);
      if (btnTogglePasswordIcon) btnTogglePasswordIcon.addEventListener("click", alternarVisibilidadeSenhaLogin);

      // Restaurar e-mail lembrado se existir
      try {
        const emailSalvo = localStorage.getItem("clovis_lembrar_email");
        if (emailSalvo && emailInput) {
          emailInput.value = emailSalvo;
          const chkLembrar = document.getElementById("chkLembrarLogin");
          if (chkLembrar) chkLembrar.checked = true;
        }
      } catch (e) {}

      // Matrix de Permissão de Abas por Nível de Acesso (RBAC - Presença Diária & IA liberada para todos os perfis)
      window.PERMISSOES_ABAS = {
        DIRETOR: ["inicio", "mural", "alunos", "dashboard-notas", "presenca-diaria", "professores", "registros", "secretaria", "busca-ativa", "agenda", "admin", "dash-projetos-pei", "rotina-pdca", "horarios", "substituicao-pei", "dashboard", "dashboard-atrasos", "auditoria", "comparativo-frequencia"],
        VICE_DIRETOR: ["inicio", "mural", "alunos", "dashboard-notas", "presenca-diaria", "professores", "registros", "secretaria", "busca-ativa", "agenda", "admin", "dash-projetos-pei", "rotina-pdca", "horarios", "substituicao-pei", "dashboard", "dashboard-atrasos", "auditoria", "comparativo-frequencia"],
        "VICE-DIRETOR": ["inicio", "mural", "alunos", "dashboard-notas", "presenca-diaria", "professores", "registros", "secretaria", "busca-ativa", "agenda", "admin", "dash-projetos-pei", "rotina-pdca", "horarios", "substituicao-pei", "dashboard", "dashboard-atrasos", "auditoria", "comparativo-frequencia"],
        CGPG: ["inicio", "mural", "alunos", "dashboard-notas", "presenca-diaria", "professores", "registros", "secretaria", "busca-ativa", "agenda", "admin", "dash-projetos-pei", "rotina-pdca", "horarios", "substituicao-pei", "dashboard", "dashboard-atrasos", "comparativo-frequencia"],
        CGPCG: ["inicio", "mural", "alunos", "dashboard-notas", "presenca-diaria", "professores", "registros", "secretaria", "busca-ativa", "agenda", "admin", "dash-projetos-pei", "rotina-pdca", "horarios", "substituicao-pei", "dashboard", "dashboard-atrasos", "comparativo-frequencia"],
        PROFESSOR_PAAC: ["inicio", "mural", "alunos", "dashboard-notas", "presenca-diaria", "professores", "registros", "agenda", "admin", "dash-projetos-pei", "rotina-pdca", "horarios", "substituicao-pei", "dashboard", "dashboard-atrasos"],
        PAAC: ["inicio", "mural", "alunos", "dashboard-notas", "presenca-diaria", "professores", "registros", "agenda", "admin", "dash-projetos-pei", "rotina-pdca", "horarios", "substituicao-pei", "dashboard", "dashboard-atrasos"],
        PROFESSOR: ["inicio", "mural", "alunos", "dashboard-notas", "registros", "agenda", "admin", "dash-projetos-pei", "rotina-pdca", "horarios", "dashboard", "dashboard-atrasos"],
        SECRETARIA: ["inicio", "mural", "alunos", "dashboard-notas", "presenca-diaria", "professores", "registros", "secretaria", "busca-ativa", "agenda", "admin", "dash-projetos-pei", "horarios", "substituicao-pei", "dashboard", "dashboard-atrasos", "comparativo-frequencia"]
      };

      // Normaliza qualquer string de cargo/nível para um dos perfis oficiais
      window.normalizarUserRole = function(rawRole) {
        if (!rawRole) return "PROFESSOR";
        const str = String(rawRole).trim().toUpperCase();
        if (str === "DIRETOR" || str === "DIREÇÃO" || str === "DIRECAO") return "DIRETOR";
        if (str.includes("VICE") || str === "VICE_DIRETOR" || str === "VICE-DIRETOR") return "VICE_DIRETOR";
        if (str.includes("CGPG") || str.includes("COORDENA") || str.includes("COORDENADOR") || str.includes("CGPCG")) return "CGPG";
        if (str.includes("SECRETARIA")) return "SECRETARIA";
        if (str === "PAAC" || str === "PROFESSOR_PAAC" || (str.includes("PAAC") && !str.includes("PROFESSOR"))) return "PAAC";
        if (str.includes("PROFESSOR") || str.includes("TUTOR") || str.includes("DOCENTE")) return "PROFESSOR";
        if (str.includes("DIRETOR")) return "DIRETOR";
        return "PROFESSOR";
      };

      // Determinar perfil real do usuário logado e perfil efetivo (simulado ou real)
      window.obterRoleAtual = function() {
        const usuarioSalvo = localStorage.getItem("usuarioLogado");
        let realRole = "PROFESSOR";
        if (usuarioSalvo) {
          try {
            const userObj = JSON.parse(usuarioSalvo);
            realRole = window.normalizarUserRole(userObj.nivelAcesso || userObj.nivel || userObj.cargo || userObj.userRole);
          } catch (e) {
            console.warn("Erro ao ler role de usuarioLogado:", e);
          }
        }
        window.realUserRole = realRole;

        const containerSimulador = document.getElementById("container-simulador-cargo");
        const simuladorCargo = document.getElementById("simulador-cargo");

        let effectiveRole = realRole;

        // O simulador de nível de acesso fica visível EXCLUSIVAMENTE quando o usuário real for DIRETOR
        if (realRole === "DIRETOR") {
          if (containerSimulador) containerSimulador.classList.remove("hidden");
          const valSimulador = simuladorCargo ? simuladorCargo.value : "DIRETOR";
          effectiveRole = window.normalizarUserRole(valSimulador);
        } else {
          if (containerSimulador) containerSimulador.classList.add("hidden");
          effectiveRole = realRole;
        }

        window.userRole = effectiveRole;
        window.usuarioAtualRole = effectiveRole;
        return effectiveRole;
      };

      // Rastreamento Infalível: Captura Objeto de Identificação Completa do Usuário
      window.obterIdentificacaoUsuarioCompleta = function() {
        if (typeof window.obterUsuarioAtivoCompleto === "function") {
          return window.obterUsuarioAtivoCompleto();
        }

        const currentUser = (typeof auth !== "undefined" && auth.currentUser) ? auth.currentUser : null;
        let email = currentUser?.email?.trim() || "";
        let displayName = currentUser?.displayName?.trim() || "";
        let role = (typeof window.obterRoleAtual === "function" ? window.obterRoleAtual() : "PROFESSOR") || "PROFESSOR";

        if (typeof localStorage !== "undefined") {
          const rawSaved = localStorage.getItem("usuarioLogado");
          if (rawSaved) {
            try {
              const uObj = JSON.parse(rawSaved);
              if (!displayName) displayName = (uObj.nome || uObj.nomeCompleto || uObj.displayName || "").trim();
              if (!email && uObj.email) email = String(uObj.email).trim();
              if (uObj.nivelAcesso || uObj.nivel || uObj.cargo) {
                role = uObj.nivelAcesso || uObj.nivel || uObj.cargo;
              }
            } catch (e) {}
          }
          if (!displayName) displayName = (localStorage.getItem("usuario_nome") || localStorage.getItem("usuario_logado") || "").trim();
          if (!email) email = (localStorage.getItem("usuario_email") || "").trim();
        }

        if (!displayName || ["USUARIO", "USUÁRIO", "USUÁRIO NÃO IDENTIFICADO", "USUÁRIO DESCONHECIDO", "GESTAO", "GESTAO ESCOLAR"].includes(displayName.toUpperCase())) {
          if (email && email.includes("@")) {
            displayName = email.split("@")[0].replace(/\.|_/g, " ").replace(/\b\w/g, l => l.toUpperCase());
          } else {
            displayName = "Usuário do Sistema";
          }
        }

        // Se houver função de obter role ativo (incluindo simulador de perfil), prioriza o papel ativo
        if (typeof window.obterRoleAtual === "function") {
          role = window.obterRoleAtual() || role;
        }

        const emailFinal = email || "usuario@escola.sp.gov.br";
        const textoCompleto = `${displayName} (${emailFinal} - ${role})`;

        return {
          nome: displayName,
          email: emailFinal,
          cargo: role,
          formatoCompleto: textoCompleto,
          textoCompleto: textoCompleto
        };
      };

      window.obterUsuarioLogadoMural = window.obterIdentificacaoUsuarioCompleta;

      // SISTEMA DE TRILHA DE AUDITORIA & LOGS (GLOBAL)
      window.registrarLogAuditoria = async function(param1, acaoArg, descArg, detalhesArg) {
        let modulo, acao, descricao, detalhes;
        if (param1 && typeof param1 === 'object') {
          ({ modulo, acao, descricao, detalhes = {} } = param1);
        } else {
          modulo = param1;
          acao = acaoArg;
          descricao = descArg;
          detalhes = detalhesArg || {};
        }

        try {
          const userDetails = (typeof window.obterIdentificacaoUsuarioCompleta === "function") 
            ? window.obterIdentificacaoUsuarioCompleta() 
            : { nome: "Usuário", email: "usuario@escola.sp.gov.br", cargo: "PROFESSOR", textoCompleto: "Usuário do Sistema" };

          const nomeUser = userDetails.nome || "Usuário";
          const emailUser = userDetails.email || "";
          const cargoUser = userDetails.cargo || "PROFESSOR";
          const textoComp = userDetails.textoCompleto || userDetails.formatoCompleto || `${nomeUser} (${emailUser} - ${cargoUser})`;

          const novoLog = {
            id: "log-" + Date.now(),
            timestamp: new Date().toISOString(),
            modulo: modulo || "Geral",
            acao: acao || "ATUALIZAR",
            descricao: descricao || "",
            usuarioNome: nomeUser,
            usuarioEmail: emailUser,
            usuarioRole: cargoUser,
            usuarioCompleto: textoComp,
            detalhes: detalhes || {}
          };

          try {
            await addDoc(collection(db, "audit_logs"), novoLog);
          } catch (errDb) {
            console.warn("Log de auditoria armazenado localmente:", errDb?.message || errDb);
          }

          // Mantém no cache em memória e localStorage
          window.allAuditLogsCache = [novoLog, ...(window.allAuditLogsCache || [])].slice(0, 400);
          try {
            localStorage.setItem("audit_logs_cache", JSON.stringify(window.allAuditLogsCache));
          } catch (e) {}
        } catch (err) {
          console.warn("Aviso ao registrar log de auditoria:", err?.message || err);
        }
      };

      window.abrirRelatorioAuditoria = function() {
        if (typeof window.switchTab === "function") {
          window.switchTab("auditoria");
        } else {
          const modal = document.getElementById("modal-auditoria-logs");
          if (modal) modal.classList.remove("hidden");
          window.carregarLogsAuditoria();
        }
      };

      window.fecharRelatorioAuditoria = function() {
        const modal = document.getElementById("modal-auditoria-logs");
        if (modal) modal.classList.add("hidden");
      };

      window.allAuditLogsCache = [];

      window.carregarLogsAuditoria = async function() {
        const tbodyPage = document.getElementById("tabela-audit-page-body");
        const tbodyModal = document.getElementById("tabela-audit-logs-body");
        if (!tbodyPage && !tbodyModal) return;

        if (tbodyPage) tbodyPage.innerHTML = '<tr><td colspan="5" class="p-6 text-center font-bold text-slate-500">Carregando histórico...</td></tr>';
        if (tbodyModal) tbodyModal.innerHTML = '<tr><td colspan="5" class="p-4 text-center font-bold text-slate-500">Carregando histórico...</td></tr>';

        try {
          // Consulta sob demanda com getDocs (sem listener onSnapshot aberto para poupar reads)
          const q = query(collection(db, "audit_logs"), orderBy("timestamp", "desc"), limit(400));
          const snapshot = await getDocs(q);

          const logs = [];
          snapshot.forEach(docSnap => {
            logs.push({ id: docSnap.id, ...docSnap.data() });
          });

          // Garantir ordenação cronológica rigorosa (mais recente no topo)
          const getTimeMs = (ts) => {
            if (!ts) return 0;
            if (typeof ts === "string") return new Date(ts).getTime() || 0;
            if (ts.toDate) return ts.toDate().getTime() || 0;
            if (ts.seconds) return ts.seconds * 1000;
            if (typeof ts === "number") return ts;
            return new Date(ts).getTime() || 0;
          };

          logs.sort((a, b) => getTimeMs(b.timestamp) - getTimeMs(a.timestamp));
          window.allAuditLogsCache = logs.slice(0, 400);
          try {
            localStorage.setItem("audit_logs_cache", JSON.stringify(window.allAuditLogsCache));
          } catch (e) {}
          window.filtrarEExibirLogsAuditoria();
        } catch (err) {
          const isPerm = err && (err.code === "permission-denied" || (err.message && err.message.includes("permission")));
          if (isPerm) {
            console.warn("Audit logs operando em modo de cache local resiliente.");
          } else {
            console.error("Erro ao carregar audit_logs:", err);
          }

          let localLogs = [];
          try {
            const raw = localStorage.getItem("audit_logs_cache");
            if (raw) localLogs = JSON.parse(raw);
          } catch (e) {}

          if (!localLogs || localLogs.length === 0) {
            localLogs = [
              {
                id: "log-init-1",
                timestamp: new Date().toISOString(),
                modulo: "Sistema",
                acao: "INICIALIZAÇÃO",
                descricao: "Módulos de gestão escolar e segurança carregados com sucesso.",
                usuarioNome: "Gestão Escolar",
                usuarioEmail: "diretor@clovis.com",
                cargo: "DIRETOR"
              }
            ];
            try {
              localStorage.setItem("audit_logs_cache", JSON.stringify(localLogs));
            } catch (e) {}
          }

          window.allAuditLogsCache = localLogs;
          window.filtrarEExibirLogsAuditoria();
        }
      };

      window.filtrarEExibirLogsAuditoria = function() {
        const logs = window.allAuditLogsCache || [];

        const moduloFiltro = document.getElementById("audit-filtro-modulo")?.value || "";
        const acaoFiltro = document.getElementById("audit-filtro-acao")?.value || "";
        const buscaFiltro = (document.getElementById("audit-filtro-busca")?.value || "").toLowerCase().trim();

        const filtrados = logs.filter(log => {
          if (moduloFiltro) {
            const modLog = (log.modulo || "").toLowerCase();
            const modF = moduloFiltro.toLowerCase();
            if (modF.includes("dossiê") || modF.includes("dossie")) {
              if (!modLog.includes("dossiê") && !modLog.includes("dossie") && !modLog.includes("ficha")) return false;
            } else if (modF.includes("registro") || modF.includes("ocorrência") || modF.includes("ocorrencia")) {
              if (!modLog.includes("registro") && !modLog.includes("ocorrência") && !modLog.includes("ocorrencia")) return false;
            } else if (modF.includes("busca")) {
              if (!modLog.includes("busca")) return false;
            } else if (modF.includes("aluno")) {
              if (!modLog.includes("aluno")) return false;
            } else {
              if (modLog !== modF) return false;
            }
          }
          if (acaoFiltro && (log.acao || "") !== acaoFiltro) return false;
          if (buscaFiltro) {
            const desc = (log.descricao || "").toLowerCase();
            const userCompleto = (log.usuarioCompleto || `${log.usuarioNome || ''} ${log.usuarioEmail || ''} ${log.usuarioRole || log.cargo || ''}`).toLowerCase();
            const mod = (log.modulo || "").toLowerCase();
            const acao = (log.acao || "").toLowerCase();
            if (!desc.includes(buscaFiltro) && !userCompleto.includes(buscaFiltro) && !mod.includes(buscaFiltro) && !acao.includes(buscaFiltro)) {
              return false;
            }
          }
          return true;
        });

        // Atualizar Métricas dos Cards
        const total = logs.length;
        const totalCriar = logs.filter(l => l.acao === "CRIAR").length;
        const totalAtualizar = logs.filter(l => l.acao === "ATUALIZAR").length;
        const totalExcluir = logs.filter(l => l.acao === "EXCLUIR").length;

        if (document.getElementById("audit-metric-total")) document.getElementById("audit-metric-total").textContent = total;
        if (document.getElementById("audit-metric-criar")) document.getElementById("audit-metric-criar").textContent = totalCriar;
        if (document.getElementById("audit-metric-atualizar")) document.getElementById("audit-metric-atualizar").textContent = totalAtualizar;
        if (document.getElementById("audit-metric-excluir")) document.getElementById("audit-metric-excluir").textContent = totalExcluir;

        if (document.getElementById("audit-contador-exibidos")) {
          document.getElementById("audit-contador-exibidos").textContent = `Exibindo ${filtrados.length} de ${total} registros`;
        }

        // Renderizar Tabela da Página
        const tbodyPage = document.getElementById("tabela-audit-page-body");
        if (tbodyPage) {
          if (filtrados.length === 0) {
            tbodyPage.innerHTML = window.getMascoteSaraEmptyStateHtml('Nenhum log de auditoria encontrado!', 'Tente alterar os filtros de módulo, ação ou intervalo de datas.', 5);
          } else {
            let html = "";
            filtrados.forEach(log => {
              let dataFmt = "-";
              if (log.timestamp) {
                try {
                  dataFmt = typeof log.timestamp === "string" ? new Date(log.timestamp).toLocaleString("pt-BR") : (log.timestamp.toDate ? log.timestamp.toDate().toLocaleString("pt-BR") : new Date(log.timestamp).toLocaleString("pt-BR"));
                } catch(e) { dataFmt = "-"; }
              }
              const bgBadge = log.acao === "CRIAR" ? "bg-emerald-100 text-emerald-800 border border-emerald-300" : log.acao === "EXCLUIR" ? "bg-rose-100 text-rose-800 border border-rose-300" : "bg-amber-100 text-amber-800 border border-amber-300";
              const userDisplay = log.usuarioCompleto || (log.usuarioNome ? `${log.usuarioNome} (${log.usuarioEmail || ''} - ${log.usuarioRole || log.cargo || ''})` : "Usuário");

              html += `
                <tr class="hover:bg-slate-50 transition-colors border-b border-slate-100">
                  <td class="p-3 font-mono text-[11px] text-slate-600 font-bold">${dataFmt}</td>
                  <td class="p-3 font-black text-blue-950">${log.modulo || "Geral"}</td>
                  <td class="p-3 text-center"><span class="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase ${bgBadge}">${log.acao || "ATUALIZAR"}</span></td>
                  <td class="p-3 font-semibold text-slate-800 leading-snug">${log.descricao || "-"}</td>
                  <td class="p-3 font-bold text-slate-700">${userDisplay}</td>
                </tr>
              `;
            });
            tbodyPage.innerHTML = html;
          }
        }

        // Renderizar Tabela do Modal (se houver)
        const tbodyModal = document.getElementById("tabela-audit-logs-body");
        if (tbodyModal) {
          if (filtrados.length === 0) {
            tbodyModal.innerHTML = '<tr><td colspan="5" class="p-4 text-center text-slate-400">Nenhum log registrado até o momento.</td></tr>';
          } else {
            let html = "";
            filtrados.forEach(log => {
              let dataFmt = "-";
              if (log.timestamp) {
                try {
                  dataFmt = typeof log.timestamp === "string" ? new Date(log.timestamp).toLocaleString("pt-BR") : (log.timestamp.toDate ? log.timestamp.toDate().toLocaleString("pt-BR") : new Date(log.timestamp).toLocaleString("pt-BR"));
                } catch(e) { dataFmt = "-"; }
              }
              const bgBadge = log.acao === "CRIAR" ? "bg-emerald-100 text-emerald-800" : log.acao === "EXCLUIR" ? "bg-rose-100 text-rose-800" : "bg-amber-100 text-amber-800";
              const userDisplay = log.usuarioCompleto || (log.usuarioNome ? `${log.usuarioNome} (${log.usuarioEmail || ''} - ${log.usuarioRole || log.cargo || ''})` : "Usuário");

              html += `
                <tr class="hover:bg-slate-50 border-b border-slate-100">
                  <td class="p-3 font-mono text-[11px] text-slate-500">${dataFmt}</td>
                  <td class="p-3 font-extrabold text-blue-900">${log.modulo || "Geral"}</td>
                  <td class="p-3 text-center"><span class="px-2 py-0.5 rounded text-[10px] font-black uppercase ${bgBadge}">${log.acao || "ATUALIZAR"}</span></td>
                  <td class="p-3 font-semibold text-slate-800">${log.descricao || "-"}</td>
                  <td class="p-3 font-bold text-slate-700">${userDisplay}</td>
                </tr>
              `;
            });
            tbodyModal.innerHTML = html;
          }
        }
      };

      // Retorna a identificação textual completa: Nome (email - CARGO)
      window.obterNomeUsuarioAtual = function() {
        return window.obterIdentificacaoUsuarioCompleta().textoCompleto;
      };

      // Formatação de autor para exibição transparente nas tabelas e dossiê
      window.formatarAutorOcorrencia = function(autorRaw, recordObj) {
        const currentDetails = (typeof window.obterIdentificacaoUsuarioCompleta === "function") ? window.obterIdentificacaoUsuarioCompleta() : null;
        let str = String(autorRaw || "").trim();

        if (!str || ["USUARIO", "USUÁRIO", "USUÁRIO NÃO IDENTIFICADO", "USUÁRIO DESCONHECIDO", "GESTAO", "GESTAO ESCOLAR"].includes(str.toUpperCase())) {
          if (recordObj?.autor_nome || recordObj?.autor_email) {
            const n = recordObj.autor_nome || (recordObj.autor_email ? recordObj.autor_email.split('@')[0] : "Usuário");
            const e = recordObj.autor_email || "";
            const c = recordObj.autor_cargo || recordObj.cargo || "PROFESSOR";
            str = `${n} (${e}${c ? ' - ' + c : ''})`;
          } else if (recordObj?.autor_criacao?.textoCompleto) {
            str = recordObj.autor_criacao.textoCompleto;
          } else if (currentDetails) {
            str = currentDetails.textoCompleto;
          } else {
            str = "Usuário Registrado";
          }
        } else if (!str.includes("(")) {
          const email = recordObj?.autor_email || currentDetails?.email || "";
          const cargo = recordObj?.autor_cargo || recordObj?.cargo || currentDetails?.cargo || "";
          if (email && cargo) {
            str = `${str} (${email} - ${cargo})`;
          } else if (email) {
            str = `${str} (${email})`;
          } else if (cargo) {
            str = `${str} (${cargo})`;
          }
        }

        // Exibição do Histórico de Edição
        if (recordObj && (recordObj.editado_por_nome || recordObj.editado_por_email || recordObj.data_ultima_edicao)) {
          const edNome = recordObj.editado_por_nome || (recordObj.editado_por_email ? recordObj.editado_por_email.split('@')[0] : "Usuário");
          const edEmail = recordObj.editado_por_email || "";
          const edCargo = recordObj.editado_por_cargo || "";
          const edData = recordObj.data_ultima_edicao ? new Date(recordObj.data_ultima_edicao).toLocaleDateString("pt-BR") : "";

          let edText = edNome;
          if (edEmail && edCargo) edText = `${edNome} (${edEmail} - ${edCargo})`;
          else if (edEmail) edText = `${edNome} (${edEmail})`;
          else if (edCargo) edText = `${edNome} (${edCargo})`;

          str += `<span class="block text-[10px] text-amber-700 italic font-medium mt-0.5" title="Editado por ${edText}">✏️ Editado por: ${edText}${edData ? ' em ' + edData : ''}</span>`;
        }

        return str;
      };

      // Abrir formulário de ocorrência pré-selecionando o aluno e marcando CONVIVA SP
      window.registrarConvivaAluno = function(ra) {
        if (!ra) return;
        if (typeof window.switchTab === "function") {
          window.switchTab("registros");
        } else if (typeof window.mostrarAba === "function") {
          window.mostrarAba("registros");
        }
        if (typeof window.selecionarAlunoParaOcorrencia === "function") {
          window.selecionarAlunoParaOcorrencia(ra);
        }
        setTimeout(() => {
          const chkConviva = document.getElementById("oc-registrado-conviva");
          if (chkConviva) {
            chkConviva.checked = true;
            document.getElementById("oc-container-codigo-conviva")?.classList.remove("hidden");
          }
        }, 100);
      };

      window.checarIsPerfilPedagogico = function() {
        const role = window.obterRoleAtual ? window.obterRoleAtual() : "";
        const cargoLogado = String(role || "").toUpperCase().trim();
        return ['CGPG', 'CGPCG', 'PAAC', 'PROFESSOR', 'PROFESSOR_PAAC'].includes(cargoLogado) ||
               cargoLogado.includes('PROFESSOR') || cargoLogado.includes('CGPG') || cargoLogado.includes('PAAC') || cargoLogado.includes('CGPCG');
      };

      // ALTERNAR VISIBILIDADE DO MÓDULO CONVIVA SP (Apenas para Questões Disciplinares)
      window.atualizarVisibilidadeConviva = function(selectEl) {
        if (!selectEl) return;
        const id = selectEl.id;
        const val = (selectEl.value || '').trim().toUpperCase();
        const isDisciplinar = val.includes("DISCIPLINAR");

        let boxId = "";
        let chkId = "";
        let containerCodId = "";
        let inputCodId = "";

        if (id === "tipo-registro") {
          boxId = "container-conviva-registro";
          chkId = "oc-registrado-conviva";
          containerCodId = "oc-container-codigo-conviva";
          inputCodId = "oc-codigo-conviva";
        } else if (id === "modal-acao-tipo") {
          boxId = "modal-acao-box-conviva";
          chkId = "modal-acao-conviva";
          containerCodId = "modal-acao-container-codigo-conviva";
          inputCodId = "modal-acao-codigo-conviva";
          const chkDossieNotif = document.getElementById("modal-acao-notificar-direcao");
          if (chkDossieNotif) chkDossieNotif.checked = false;
        } else if (id === "edit-ocorrencia-tipo") {
          boxId = "edit-oc-box-conviva";
          chkId = "edit-oc-registrado-conviva";
          containerCodId = "edit-oc-container-codigo-conviva";
          inputCodId = "edit-oc-codigo-conviva";
        }

        if (boxId) {
          const box = document.getElementById(boxId);
          const chk = document.getElementById(chkId);
          const containerCod = document.getElementById(containerCodId);
          const inputCod = document.getElementById(inputCodId);

          if (box) {
            if (isDisciplinar) {
              box.classList.remove("hidden");
            } else {
              box.classList.add("hidden");
              if (chk) chk.checked = false;
              if (containerCod) containerCod.classList.add("hidden");
              if (inputCod) inputCod.value = "";
            }
          }
        }
      };

      // HELPER RBAC: Apenas SECRETARIA, CGPG, DIRETOR e VICE_DIRETOR podem registrar Dispensa / Afastamento Legal
      window.podeRegistrarDispensa = function() {
        const roleRaw = window.obterRoleAtual ? window.obterRoleAtual() : "PROFESSOR";
        const roleNorm = window.normalizarUserRole
          ? window.normalizarUserRole(roleRaw)
          : String(roleRaw || "").toUpperCase().replace(/-/g, "_").trim();
        return ["SECRETARIA", "CGPG", "DIRETOR", "VICE_DIRETOR"].includes(roleNorm);
      };

      window.isOcorrenciaDispensa = function(oc) {
        if (!oc) return false;
        if (oc.isDispensa === true) return true;
        const tipoStr = String(oc.tipo || "").toUpperCase();
        const catStr = String(oc.categoria || "").toUpperCase();
        return (
          (tipoStr.includes("DISPENSA") || tipoStr.includes("AFASTAMENTO LEGAL") || catStr.includes("DISPENSA")) &&
          Boolean(oc.dataInicio || oc.dataFim)
        ) || tipoStr.includes("DISPENSA / AFASTAMENTO");
      };

      window.atualizarVisibilidadeDispensaAtraso = function(selectEl) {
        if (!selectEl) return;
        const id = selectEl.id;
        const valUpper = String(selectEl.value || "").trim().toUpperCase();
        const isDispensa = valUpper.includes("DISPENSA") || valUpper.includes("AFASTAMENTO");
        const isAtraso = valUpper.includes("ATRASO");
        const agoraHHMM = new Date().toTimeString().slice(0, 5);
        const hojeIso = new Date().toISOString().split("T")[0];

        if (id === "tipo-registro") {
          const contDisp = document.getElementById("container-dispensa-ocorrencia");
          const ini = document.getElementById("oc-dispensa-inicio");
          const fim = document.getElementById("oc-dispensa-fim");
          if (contDisp) {
            const pode = window.podeRegistrarDispensa();
            contDisp.classList.toggle("hidden", !(isDispensa && pode));
            if (isDispensa && pode) {
              if (ini && !ini.value) ini.value = hojeIso;
              if (fim && !fim.value) fim.value = hojeIso;
              if (ini) ini.required = true;
              if (fim) fim.required = true;
            } else {
              if (ini) ini.required = false;
              if (fim) fim.required = false;
            }
          }
          const contAtr = document.getElementById("container-atraso-ocorrencia");
          const inpHora = document.getElementById("oc-hora-atraso");
          if (contAtr) {
            contAtr.classList.toggle("hidden", !isAtraso);
            if (isAtraso && inpHora && !inpHora.value) inpHora.value = agoraHHMM;
          }
        } else if (id === "modal-acao-tipo") {
          const contDisp = document.getElementById("modal-acao-container-dispensa");
          const ini = document.getElementById("modal-acao-dispensa-inicio");
          const fim = document.getElementById("modal-acao-dispensa-fim");
          if (contDisp) {
            const pode = window.podeRegistrarDispensa();
            contDisp.classList.toggle("hidden", !(isDispensa && pode));
            if (isDispensa && pode) {
              if (ini && !ini.value) ini.value = hojeIso;
              if (fim && !fim.value) fim.value = hojeIso;
            }
          }
          const contAtr = document.getElementById("modal-acao-container-atraso");
          const inpHora = document.getElementById("modal-acao-hora-atraso");
          if (contAtr) {
            contAtr.classList.toggle("hidden", !isAtraso);
            if (isAtraso && inpHora && !inpHora.value) inpHora.value = agoraHHMM;
          }
        } else if (id === "edit-ocorrencia-tipo") {
          const contDisp = document.getElementById("edit-oc-container-dispensa");
          if (contDisp) {
            contDisp.classList.toggle("hidden", !isDispensa);
          }
        }
      };

      // Registro direto de Dispensa / Afastamento Legal pelo painel exclusivo do Dossiê
      window.salvarDispensaPeloDossie = async function() {
        if (!window.podeRegistrarDispensa()) {
          window.showToast("Apenas Secretaria, CGPG, Direção e Vice-Direção possuem permissão para registrar dispensas com datas.", "warning");
          return;
        }
        const ra = document.getElementById("modal-aluno-ra-hidden")?.value;
        if (!ra) {
          window.showToast("Salve primeiro o cadastro do estudante antes de registrar uma dispensa.", "warning");
          return;
        }
        const dataInicio = document.getElementById("dossie-dispensa-inicio")?.value || "";
        const dataFim = document.getElementById("dossie-dispensa-fim")?.value || "";
        const motivoDispensa = document.getElementById("dossie-dispensa-motivo")?.value || "Atestado Médico";
        const obs = (document.getElementById("dossie-dispensa-obs")?.value || "").trim();

        if (!dataInicio || !dataFim) {
          window.showToast("Informe a Data Início e a Data Fim da dispensa.", "warning");
          return;
        }
        if (dataFim < dataInicio) {
          window.showToast("A Data Fim da dispensa não pode ser anterior à Data Início.", "warning");
          return;
        }

        const btn = document.getElementById("btn-salvar-dispensa-dossie");
        if (btn) {
          btn.disabled = true;
          btn.innerHTML = `<i class="fa-solid fa-spinner animate-spin text-xs"></i><span>Salvando Dispensa...</span>`;
        }

        try {
          const userDetails = window.obterIdentificacaoUsuarioCompleta ? window.obterIdentificacaoUsuarioCompleta() : { email: "", nome: "", cargo: "", textoCompleto: "" };
          const aluno = (window.allStudentsData || []).find(s => String(s.ra) === String(ra)) || {};
          const dtIniBr = dataInicio.split("-").reverse().join("/");
          const dtFimBr = dataFim.split("-").reverse().join("/");
          const diasDispensa = Math.max(1, Math.round((new Date(`${dataFim}T12:00:00`).getTime() - new Date(`${dataInicio}T12:00:00`).getTime()) / 86400000) + 1);
          const descFinal = `Dispensa / Afastamento Legal (${motivoDispensa}) no período de ${dtIniBr} a ${dtFimBr} (${diasDispensa} dia(s)).${obs ? " Obs: " + obs : ""}`;

          // REGRA CRÍTICA DE INTEGRAÇÃO (JSON): estritamente proibido incluir id ou _id no payload enviado ao banco
          const dispensaPayload = {
            ra: String(ra),
            nomeAluno: String(aluno.nome || "").toUpperCase(),
            turma: String(aluno.turma || "").toUpperCase(),
            tipo: "Dispensa / Afastamento Legal",
            categoria: "Dispensa / Afastamento Legal",
            titulo: `Dispensa Legal (${motivoDispensa})`,
            encaminhamento: "Afastamento justificado sincronizado com Presença Diária (3ª Métrica)",
            descricao: descFinal,
            isDispensa: true,
            isAtraso: false,
            dataInicio: dataInicio,
            dataFim: dataFim,
            motivoDispensa: motivoDispensa,
            diasDispensa: diasDispensa,
            data: new Date().toISOString(),
            usuario: userDetails.textoCompleto,
            autor: userDetails.textoCompleto,
            registradoPor: userDetails.textoCompleto,
            autor_email: userDetails.email,
            autor_nome: userDetails.nome,
            autor_cargo: userDetails.cargo,
            cargo: userDetails.cargo
          };

          const docRef = await addDoc(collection(db, "ocorrencias"), dispensaPayload);
          const dispensaLocal = { ...dispensaPayload, id: docRef.id };

          if (!Array.isArray(window.ocorrenciasTopLevel)) window.ocorrenciasTopLevel = [];
          window.ocorrenciasTopLevel.unshift(dispensaLocal);

          const registroDispensaAluno = {
            dataInicio: dataInicio,
            dataFim: dataFim,
            motivoDispensa: motivoDispensa,
            diasDispensa: diasDispensa,
            descricao: descFinal,
            registradoPor: userDetails.textoCompleto,
            data: dispensaPayload.data
          };

          const resumoAnt = aluno.acoes_2026 || "";
          const novaLinha = `[${new Date().toLocaleDateString("pt-BR")}] DISPENSA (${dtIniBr} a ${dtFimBr}): ${motivoDispensa}${obs ? " - " + obs : ""}`;
          const novoResumo = resumoAnt ? `${resumoAnt}\n${novaLinha}` : novaLinha;

          const studentDocRef = doc(db, "alunos", String(ra));
          try {
            await updateDoc(studentDocRef, {
              acoes_2026: novoResumo.toUpperCase(),
              ocorrencias: arrayUnion(dispensaPayload),
              dispensas: arrayUnion(registroDispensaAluno)
            });
          } catch (eUpd) {
            await setDoc(studentDocRef, {
              acoes_2026: novoResumo.toUpperCase(),
              ocorrencias: arrayUnion(dispensaPayload),
              dispensas: arrayUnion(registroDispensaAluno)
            }, { merge: true });
          }

          if (aluno) {
            aluno.acoes_2026 = novoResumo.toUpperCase();
            if (!Array.isArray(aluno.ocorrencias)) aluno.ocorrencias = [];
            aluno.ocorrencias.push(dispensaLocal);
            if (!Array.isArray(aluno.dispensas)) aluno.dispensas = [];
            aluno.dispensas.push(registroDispensaAluno);
          }

          if (typeof window.consolidarHistoricoOcorrenciasGlobais === "function") {
            window.consolidarHistoricoOcorrenciasGlobais();
          }
          if (typeof window.carregarHistoricoAcoesModal === "function") {
            await window.carregarHistoricoAcoesModal(ra);
          }

          const elObs = document.getElementById("dossie-dispensa-obs");
          if (elObs) elObs.value = "";

          if (typeof window.registrarLogAuditoria === "function") {
            window.registrarLogAuditoria({
              modulo: "Dossiê do Aluno",
              acao: "CRIAR",
              descricao: `Registrada Dispensa (${dtIniBr} a ${dtFimBr} - ${motivoDispensa}) para ${aluno.nome || ra}`,
              detalhes: { ra, dataInicio, dataFim, motivoDispensa }
            });
          }

          window.showToast(`Dispensa registrada (${dtIniBr} a ${dtFimBr}) e sincronizada com a Presença Diária!`, "success");
        } catch (err) {
          window.showErrorToast("Erro ao registrar dispensa do estudante.", err);
        } finally {
          if (btn) {
            btn.disabled = false;
            btn.innerHTML = `<i class="fa-solid fa-calendar-check text-xs"></i><span>Registrar Dispensa e Afastar na Presença</span>`;
          }
        }
      };

      // POPULAR/FILTRAR DROPDOWN DE CATEGORIAS DE REGISTRO CONFORME O PERFIL
      window.popularSelectCategoriasOcorrencia = function(selectEl) {
        if (!selectEl) return;
        const roleRaw = window.obterRoleAtual ? window.obterRoleAtual() : "PROFESSOR";
        const roleNorm = window.normalizarUserRole
          ? window.normalizarUserRole(roleRaw)
          : String(roleRaw || "").toUpperCase().replace(/-/g, "_").trim();
        const role = String(roleRaw || "").toUpperCase().trim();
        const currentVal = selectEl.value;

        let optionsList = [];
        if (role === "PROFESSOR" || role === "PROFESSOR_PAAC" || role === "PAAC" || roleNorm === "PROFESSOR" || roleNorm === "PROFESSOR_PAAC") {
          // PROFESSOR: Apenas opções pedagógicas (sem Atraso, Saída Antecipada nem Dispensa)
          optionsList = [
            { val: "Tutoria e Acolhimento", label: "Tutoria e Acolhimento" },
            { val: "Questão Pedagógica", label: "Questão Pedagógica" }
          ];
        } else if (role === "SECRETARIA" || roleNorm === "SECRETARIA") {
          optionsList = [
            { val: "Atraso", label: "Atraso" },
            { val: "Dispensa / Afastamento Legal", label: "Dispensa / Afastamento Legal (Com Datas)" },
            { val: "Saída Antecipada", label: "Saída Antecipada" },
            { val: "Questão Disciplinar", label: "Questão Disciplinar" },
            { val: "Contato WhatsApp/Ligação", label: "Contato WhatsApp/Ligação" },
            { val: "Registro na SED", label: "Registro na SED" },
            { val: "Outros", label: "Outros" }
          ];
        } else {
          // DIRETOR, VICE_DIRETOR, CGPG
          optionsList = [
            { val: "Tutoria e Acolhimento", label: "Tutoria e Acolhimento" },
            { val: "Questão Pedagógica", label: "Questão Pedagógica" },
            { val: "Questão Disciplinar", label: "Questão Disciplinar" },
            { val: "Atraso", label: "Atraso" },
            { val: "Dispensa / Afastamento Legal", label: "Dispensa / Afastamento Legal (Com Datas)" },
            { val: "Saída Antecipada", label: "Saída Antecipada" },
            { val: "Contato WhatsApp/Ligação", label: "Contato WhatsApp/Ligação" },
            { val: "Registro na SED", label: "Registro na SED" },
            { val: "Encaminhamento - Conselho Tutelar", label: "Encaminhamento - Conselho Tutelar" },
            { val: "Encaminhamento - Ministério Público", label: "Encaminhamento - Ministério Público" },
            { val: "Outros", label: "Outros" }
          ];
        }

        selectEl.innerHTML = optionsList.map(o => `<option value="${o.val}">${o.label}</option>`).join('');
        if (currentVal && optionsList.some(o => o.val === currentVal)) {
          selectEl.value = currentVal;
        }

        // Registrar listener para atualizar visibilidade do motivo, dispensa, atraso e CONVIVA dinamicamente
        selectEl.onchange = function() {
          if (selectEl.id === "tipo-registro" && typeof window.atualizarVisibilidadeMotivoSaida === "function") {
            window.atualizarVisibilidadeMotivoSaida();
          }
          if (typeof window.atualizarVisibilidadeDispensaAtraso === "function") {
            window.atualizarVisibilidadeDispensaAtraso(selectEl);
          }
          if (typeof window.atualizarVisibilidadeConviva === "function") {
            window.atualizarVisibilidadeConviva(selectEl);
          }
        };

        if (selectEl.id === "tipo-registro" && typeof window.atualizarVisibilidadeMotivoSaida === "function") {
          window.atualizarVisibilidadeMotivoSaida();
        }
        if (typeof window.atualizarVisibilidadeDispensaAtraso === "function") {
          window.atualizarVisibilidadeDispensaAtraso(selectEl);
        }
        if (typeof window.atualizarVisibilidadeConviva === "function") {
          window.atualizarVisibilidadeConviva(selectEl);
        }
      };

      // Alternar visibilidade e obrigatoriedade do campo "Motivo da Saída"
      window.atualizarVisibilidadeMotivoSaida = function() {
        const selectTipo = document.getElementById("tipo-registro");
        const containerMotivo = document.getElementById("container-motivo-saida");
        const inputMotivo = document.getElementById("motivo-saida-ante");

        if (!selectTipo || !containerMotivo || !inputMotivo) return;

        if (selectTipo.value === "Saída Antecipada") {
          containerMotivo.classList.remove("hidden");
          inputMotivo.required = true;
        } else {
          containerMotivo.classList.add("hidden");
          inputMotivo.required = false;
          inputMotivo.value = "";
        }
      };

      // APLICAR TRAVAS DE EDIÇÃO NO DOSSIÊ/FICHA DO ESTUDANTE
      window.aplicarTravasEdicaoFichaAluno = function() {
        const role = window.obterRoleAtual ? window.obterRoleAtual() : "PROFESSOR";
        const isProfessor = (role === "PROFESSOR_PAAC");
        const isCGPG = (role === "CGPG");

        const elStatus = document.getElementById("modal-edit-status");
        const elSegmento = document.getElementById("modal-edit-segmento");
        const elNome = document.getElementById("modal-edit-nome");
        const elRaInput = document.getElementById("modal-edit-ra-input");
        const elTurma = document.getElementById("modal-edit-turma");
        const elRecomposicao = document.getElementById("modal-edit-recomposicao");
        const elAEE = document.getElementById("modal-edit-aee");
        const elTutor = document.getElementById("modal-edit-tutor");
        const elClube = document.getElementById("modal-edit-clube");
        const elEletiva = document.getElementById("modal-edit-eletiva");
        const elProtagonismo = document.getElementById("modal-edit-protagonismo");
        const elPv = document.getElementById("modal-edit-pv");
        const elEvolucao = document.getElementById("modal-edit-evolucao");
        const elAcoes2026 = document.getElementById("modal-edit-acoes2026");
        const btnSalvarModal = document.getElementById("btn-salvar-modal");

        const atalhosProtagonismo = document.querySelectorAll("#form-modal-ficha button[onclick*='toggleProtagonismoTag']");

        if (isProfessor) {
          // PROFESSOR_PAAC: Ficha estritamente read-only em dados cadastrais, notas e pareceres
          if (elStatus) elStatus.disabled = true;
          if (elSegmento) elSegmento.disabled = true;
          if (elNome) { elNome.readOnly = true; }
          if (elRaInput) { elRaInput.readOnly = true; }
          if (elTurma) elTurma.readOnly = true;
          if (elRecomposicao) elRecomposicao.disabled = true;
          if (elAEE) elAEE.disabled = true;
          if (elTutor) elTutor.readOnly = true;
          if (elClube) elClube.readOnly = true;
          if (elEletiva) elEletiva.readOnly = true;
          if (elProtagonismo) elProtagonismo.readOnly = true;
          if (elPv) elPv.readOnly = true;
          if (elEvolucao) elEvolucao.readOnly = true;
          if (elAcoes2026) elAcoes2026.readOnly = true;

          if (btnSalvarModal) btnSalvarModal.classList.add("hidden");
          atalhosProtagonismo.forEach(btn => btn.classList.add("hidden"));
        } else if (isCGPG) {
          // CGPG: Bloqueia dados cadastrais e notas. Permite alterar 'Eletiva', 'Projeto de Vida' e 'Parecer Pedagógico' (elEvolucao)
          if (elStatus) elStatus.disabled = true;
          if (elSegmento) elSegmento.disabled = true;
          if (elNome) { elNome.readOnly = true; }
          if (elRaInput) { elRaInput.readOnly = true; }
          if (elTurma) elTurma.readOnly = true;
          if (elRecomposicao) elRecomposicao.disabled = true;
          if (elAEE) elAEE.disabled = true;
          if (elTutor) elTutor.readOnly = true;
          if (elClube) elClube.readOnly = true;
          if (elProtagonismo) elProtagonismo.readOnly = true;
          if (elAcoes2026) elAcoes2026.readOnly = true;
          atalhosProtagonismo.forEach(btn => btn.classList.add("hidden"));

          // Liberados para o CGPG:
          if (elEletiva) elEletiva.readOnly = false;
          if (elPv) elPv.readOnly = false;
          if (elEvolucao) elEvolucao.readOnly = false;

          if (btnSalvarModal) btnSalvarModal.classList.remove("hidden");
        } else {
          // SECRETARIA, DIRETOR e VICE_DIRETOR: Permissão Total de Edição (Nome, RA, Turma, etc.)
          if (elStatus) elStatus.disabled = false;
          if (elSegmento) elSegmento.disabled = false;
          if (elNome) { elNome.readOnly = false; elNome.removeAttribute("disabled"); }
          if (elRaInput) { elRaInput.readOnly = false; elRaInput.removeAttribute("disabled"); }
          if (elTurma) elTurma.readOnly = false;
          if (elRecomposicao) elRecomposicao.disabled = false;
          if (elAEE) elAEE.disabled = false;
          if (elTutor) elTutor.readOnly = false;
          if (elClube) elClube.readOnly = false;
          if (elEletiva) elEletiva.readOnly = false;
          if (elProtagonismo) elProtagonismo.readOnly = false;
          if (elPv) elPv.readOnly = false;
          if (elEvolucao) elEvolucao.readOnly = false;
          if (elAcoes2026) elAcoes2026.readOnly = false;

          if (btnSalvarModal) btnSalvarModal.classList.remove("hidden");
          atalhosProtagonismo.forEach(btn => btn.classList.remove("hidden"));
        }

        // Botão de Ajuste Manual SED no cabeçalho de frequência do dossiê (Exclusivo Direção / Vice-Direção)
        const btnAjusteFreqModal = document.getElementById("btn-ajustar-freq-sed-modal");
        if (btnAjusteFreqModal) {
          const isDirecao = (role === "DIRETOR" || role === "VICE_DIRETOR");
          if (isDirecao) {
            btnAjusteFreqModal.classList.remove("hidden");
          } else {
            btnAjusteFreqModal.classList.add("hidden");
          }
        }

        // Botão de Geração de Parecer Pedagógico com IA (Exclusivo Direção, Vice-Direção e CGPG)
        const btnGerarParecerIA = document.getElementById("btn-gerar-parecer-ia");
        if (btnGerarParecerIA) {
          const roleNorm = String(role || "").toUpperCase().replace(/-/g, '_').trim();
          const canGerarParecer = (roleNorm === "DIRETOR" || roleNorm === "VICE_DIRETOR" || roleNorm === "CGPG" || roleNorm.includes("DIRETOR") || roleNorm.includes("VICE") || roleNorm.includes("CGPG"));
          if (canGerarParecer) {
            btnGerarParecerIA.classList.remove("hidden");
          } else {
            btnGerarParecerIA.classList.add("hidden");
          }
        }

        // Controle de Notificação à Direção no Dossiê (Exclusivo para Professor e por padrão NUNCA notifica)
        const containerDossieNotif = document.getElementById("container-dossie-notificar-direcao");
        const chkDossieNotif = document.getElementById("modal-acao-notificar-direcao");
        const roleNormDossie = window.normalizarUserRole ? window.normalizarUserRole(role) : String(role || "").toUpperCase();
        const isDocenteDossie = (roleNormDossie === "PROFESSOR" || roleNormDossie === "PROFESSOR_PAAC" || role === "PROFESSOR_PAAC" || role === "PROFESSOR");
        if (containerDossieNotif) {
          if (isDocenteDossie) {
            containerDossieNotif.classList.remove("hidden");
          } else {
            containerDossieNotif.classList.add("hidden");
          }
        }
        if (chkDossieNotif) {
          chkDossieNotif.checked = false; // Por padrão não notifica a direção, só se o professor marcar mesmo
        }

        // Controle do Painel de Dispensa / Afastamento Legal no Dossiê (Exclusivo Secretaria, CGPG, Direção e Vice)
        const contDispDossie = document.getElementById("container-dossie-dispensa-rapida");
        if (contDispDossie) {
          const podeDispensa = typeof window.podeRegistrarDispensa === "function" ? window.podeRegistrarDispensa() : false;
          contDispDossie.classList.toggle("hidden", !podeDispensa);
          if (podeDispensa) {
            const hojeIso = new Date().toISOString().split("T")[0];
            const elIni = document.getElementById("dossie-dispensa-inicio");
            const elFim = document.getElementById("dossie-dispensa-fim");
            if (elIni && !elIni.value) elIni.value = hojeIso;
            if (elFim && !elFim.value) elFim.value = hojeIso;
          }
        }
      };

      // Função de Atualização Global de Permissões e Visibilidade de Abas (RBAC Estrito no DOM)
      window.atualizarVisibilidadeAbasEPermissoes = function() {
        const roleRaw = window.obterRoleAtual ? window.obterRoleAtual() : "PROFESSOR";
        const role = String(roleRaw || "").toUpperCase().trim();
        const abasPermitidas = (window.PERMISSOES_ABAS && (window.PERMISSOES_ABAS[role] || window.PERMISSOES_ABAS[window.normalizarUserRole(role)])) || ["mural", "alunos", "registros"];

        const todasAbas = ["inicio", "mural", "alunos", "dashboard-notas", "dashboard-atrasos", "presenca-diaria", "professores", "rotina-pdca", "agenda", "registros", "busca-ativa", "horarios", "substituicao-pei", "dash-projetos-pei", "secretaria", "comparativo-frequencia", "dashboard", "admin", "auditoria"];

        todasAbas.forEach(tab => {
          const ehPermitida = abasPermitidas.includes(tab);
          const navEl = document.getElementById(`nav-${tab}`);
          if (navEl) {
            if (ehPermitida) {
              navEl.classList.remove("hidden");
            } else {
              navEl.classList.add("hidden");
            }
          }
          const mobEl = document.getElementById(`mob-grid-${tab}`);
          if (mobEl) {
            if (ehPermitida) {
              mobEl.classList.remove("hidden");
            } else {
              mobEl.classList.add("hidden");
            }
          }
        });

        // Visibilidade do botão de novo recado no mural conforme o perfil (Direção, CGPG, Vice-Direção, PAAC)
        const btnNovoRecadoMural = document.getElementById("btn-novo-recado-mural");
        if (btnNovoRecadoMural) {
          if (typeof window.podePublicarMural === "function" && window.podePublicarMural()) {
            btnNovoRecadoMural.classList.remove("hidden");
          } else {
            btnNovoRecadoMural.classList.add("hidden");
          }
        }

        // Botão Tutoria Coletiva (disponível para todos os perfis pedagógicos EXCETO SECRETARIA)
        const btnTutoriaColetiva = document.getElementById("btn-tutoria-coletiva-massa");
        if (btnTutoriaColetiva) {
          if (role === "SECRETARIA") {
            btnTutoriaColetiva.classList.add("hidden");
          } else {
            btnTutoriaColetiva.classList.remove("hidden");
          }
        }

        // Se a aba ativa atual não for permitida para o perfil, redireciona para Mural
        const activeTab = window.currentActiveTab || "inicio";
        if (!abasPermitidas.includes(activeTab)) {
          if (typeof window.switchTab === "function") {
            window.switchTab("inicio");
          }
        } else {
          // Re-aplica estilização do menu conforme o estado de permissão e aba ativa
          todasAbas.forEach(tab => {
            const navEl = document.getElementById(`nav-${tab}`);
            if (navEl && abasPermitidas.includes(tab)) {
              if (tab === activeTab) {
                navEl.className = "tab-btn group w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-bold bg-gradient-to-r from-cyan-400 to-cyan-300 text-slate-950 shadow-md shadow-cyan-500/20 cursor-pointer transition-all duration-200";
              } else {
                navEl.className = "tab-btn group w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium text-slate-300 hover:bg-slate-800/80 hover:text-white transition-all duration-200 cursor-pointer";
              }
            }
          });
        }

        if (typeof window.atualizarPermissoesCargo === "function") {
          window.atualizarPermissoesCargo();
        }

        window.dispatchEvent(new CustomEvent("taborrolechange"));
      };

      // Lógica de Permissões baseada no Cargo
      const simuladorCargo = document.getElementById("simulador-cargo");

      function atualizarPermissoesCargo() {
        // 1. Filtrar opções da lista suspensa de ocorrencias/registros
        window.popularSelectCategoriasOcorrencia(document.getElementById("tipo-registro"));
        window.popularSelectCategoriasOcorrencia(document.getElementById("modal-acao-tipo"));
        window.popularSelectCategoriasOcorrencia(document.getElementById("edit-ocorrencia-tipo"));

        const role = window.obterRoleAtual ? window.obterRoleAtual() : "PROFESSOR";
        const isPerfilPedagogico = window.checarIsPerfilPedagogico ? window.checarIsPerfilPedagogico() : false;
        const podeDeletar = window.podeExcluir();

        // Adaptação da Interface do Módulo de Registros (Tabs e Atrasos em Massa)
        const btnLancarAtrasosMassa = document.getElementById("btn-lancar-atrasos-massa");
        const btnDisciplina = document.getElementById("tab-registros-disciplina");
        const btnAtraso = document.getElementById("tab-registros-atraso");
        const btnRotina = document.getElementById("tab-registros-rotina");

        if (isPerfilPedagogico) {
          if (btnLancarAtrasosMassa) btnLancarAtrasosMassa.classList.add("hidden");
          if (btnDisciplina) btnDisciplina.classList.add("hidden");
          if (btnAtraso) btnAtraso.classList.add("hidden");
          if (btnRotina) btnRotina.classList.remove("hidden");
          window.abaAtivaRegistros = 'rotina';
        } else {
          if (btnLancarAtrasosMassa) btnLancarAtrasosMassa.classList.remove("hidden");
          if (btnDisciplina) btnDisciplina.classList.remove("hidden");
          if (btnAtraso) btnAtraso.classList.remove("hidden");
          if (btnRotina) btnRotina.classList.remove("hidden");
        }

        // 2. Bloqueio visual global dos botões de exclusão (Lixeira/Trash)
        document.querySelectorAll('[data-action="excluir"], .btn-excluir, .btn-trash, button[onclick*="deletar"], button[onclick*="excluir"]').forEach(el => {
          if (!podeDeletar) {
            el.classList.add("hidden");
            el.setAttribute("disabled", "true");
          } else {
            el.classList.remove("hidden");
            el.removeAttribute("disabled");
          }
        });

        // 3. Trava de botões cadastrais/edição na Aba Alunos
        const btnNovoAluno = document.querySelector("button[onclick*='abrirModalNovoAluno']");
        const btnImportarSed = document.querySelector("button[onclick*='abrirModalImportarSed']");
        const btnModoPlanilha = document.getElementById("btn-modo-planilha");
        const btnAtribuirLote = document.getElementById("btn-atribuir-lote");

        if (role === "PROFESSOR_PAAC" || role === "CGPG") {
          if (btnNovoAluno) btnNovoAluno.classList.add("hidden");
          if (btnImportarSed) btnImportarSed.classList.add("hidden");
          if (btnModoPlanilha) btnModoPlanilha.classList.add("hidden");
        } else {
          if (btnNovoAluno) btnNovoAluno.classList.remove("hidden");
          if (btnImportarSed) btnImportarSed.classList.remove("hidden");
          if (btnModoPlanilha) btnModoPlanilha.classList.remove("hidden");
        }

        // Controle de visibilidade para ações em massa (DIRETOR / VICE_DIRETOR)
        document.querySelectorAll(".secao-direcao-massa").forEach(el => {
          if (role === "DIRETOR" || role === "VICE_DIRETOR") {
            el.classList.remove("hidden");
          } else {
            el.classList.add("hidden");
          }
        });
        if (btnAtribuirLote) {
          if (role === "DIRETOR" || role === "VICE_DIRETOR") {
            btnAtribuirLote.classList.remove("hidden");
          } else {
            btnAtribuirLote.classList.add("hidden");
          }
        }

        // 4. Aplicar travas na ficha do aluno
        if (typeof window.aplicarTravasEdicaoFichaAluno === "function") {
          window.aplicarTravasEdicaoFichaAluno();
        }

        // 5. Visibilidade do painel e botão de Migração de Dados (Apenas DIRETOR)
        const btnMigrar = document.getElementById("btn-migrar-backup-acoes");
        const painelMigracao = document.getElementById("painel-migracao-db");
        if (btnMigrar) {
          if (role === "DIRETOR") {
            btnMigrar.classList.remove("hidden");
            btnMigrar.removeAttribute("disabled");
          } else {
            btnMigrar.classList.add("hidden");
            btnMigrar.setAttribute("disabled", "true");
          }
        }
        if (painelMigracao) {
          if (role === "DIRETOR") {
            painelMigracao.classList.remove("hidden");
          } else {
            painelMigracao.classList.add("hidden");
          }
        }

        // 6. Ocultar/Exibir seções exclusivas de Gestão na aba Admin (DIRETOR e VICE_DIRETOR)
        document.querySelectorAll(".secao-admin-diretor").forEach(el => {
          if (role === "DIRETOR" || role === "VICE_DIRETOR" || role === "VICE-DIRETOR") {
            el.classList.remove("hidden");
          } else {
            el.classList.add("hidden");
          }
        });

        // 7. Acesso ao Módulo de Auditoria (Exclusivo para DIRETOR)
        const btnAuditoria = document.getElementById("container-btn-auditoria");
        if (btnAuditoria) {
          if (role === "DIRETOR") {
            btnAuditoria.classList.remove("hidden");
          } else {
            btnAuditoria.classList.add("hidden");
          }
        }
      }

      window.atualizarPermissoesCargo = atualizarPermissoesCargo;

      if (simuladorCargo) {
        simuladorCargo.addEventListener("change", () => {
          window.atualizarVisibilidadeAbasEPermissoes();
        });
      }

      // Lógica de Busca Inteligente (Autocomplete) e Registro de Ocorrência na aba Registros
      const inputBuscarAluno = document.getElementById("buscar-aluno-input");
      const btnLimparBusca = document.getElementById("btn-limpar-busca-aluno");
      const dropdownResultados = document.getElementById("dropdown-alunos-resultados");
      const cardAlunoEncontrado = document.getElementById("card-aluno-encontrado");
      const alunoEncontradoNome = document.getElementById("aluno-encontrado-nome");
      const alunoEncontradoRa = document.getElementById("aluno-encontrado-ra");
      const alunoEncontradoTurma = document.getElementById("aluno-encontrado-turma");
      const formOcorrencia = document.getElementById("form-ocorrencia");
      const descricaoRegistro = document.getElementById("descricao-registro");
      const btnSalvarRegistro = document.getElementById("btn-salvar-registro");
      const inputSearchHistorico = document.getElementById("search-historico-ocorrencias");
      const tabelaHistoricoBody = document.getElementById("tabela-historico-ocorrencias-body");

      let alunoAtual = null;
      // ocorrenciasCache mantido em window.ocorrenciasCache
      window.ocorrenciasCache = window.ocorrenciasCache || [];

      // Função para fechar o dropdown
      function fecharDropdownAlunos() {
        if (dropdownResultados) {
          dropdownResultados.classList.add("hidden");
          dropdownResultados.innerHTML = "";
        }
      }

      // Função acionada ao clicar em um aluno da lista suspensa
      window.selecionarAlunoParaOcorrencia = function(ra) {
        if (!ra) return;

        let aluno = (window.allStudentsData || []).find(s => String(s.ra || "").trim() === String(ra).trim());
        if (!aluno) {
          const cleanTarget = String(ra).replace(/\D/g, "").substring(0, 12);
          aluno = (window.allStudentsData || []).find(s => String(s.ra || "").replace(/\D/g, "").substring(0, 12) === cleanTarget);
        }

        if (!aluno) return;

        alunoAtual = {
          ra: aluno.ra,
          nome: (aluno.nome || "ALUNO SEM NOME").toUpperCase(),
          turma: (aluno.turma || "-").toUpperCase()
        };

        if (alunoEncontradoNome) alunoEncontradoNome.textContent = alunoAtual.nome;
        if (alunoEncontradoRa) alunoEncontradoRa.textContent = alunoAtual.ra;
        if (alunoEncontradoTurma) alunoEncontradoTurma.textContent = alunoAtual.turma;

        cardAlunoEncontrado?.classList.remove("hidden");
        formOcorrencia?.classList.remove("hidden");

        if (inputBuscarAluno) {
          inputBuscarAluno.value = `${alunoAtual.nome} (RA: ${alunoAtual.ra} | TURMA: ${alunoAtual.turma})`;
        }
        if (btnLimparBusca) {
          btnLimparBusca.classList.remove("hidden");
        }

        fecharDropdownAlunos();

        if (typeof atualizarPermissoesCargo === "function") {
          atualizarPermissoesCargo();
        }
      };

      // Função de busca dinâmica/autocomplete em tempo real (evento input) no array local allStudentsData
      function realizarBuscaAutocomplete(queryText) {
        if (!dropdownResultados) return;

        const term = String(queryText || "").trim().toLowerCase();
        if (term.length === 0) {
          fecharDropdownAlunos();
          if (btnLimparBusca) btnLimparBusca.classList.add("hidden");
          return;
        }

        if (btnLimparBusca) btnLimparBusca.classList.remove("hidden");

        const termClean = term.replace(/\D/g, "");
        const termNorm = typeof normalizarTextoBusca === "function" ? normalizarTextoBusca(queryText) : String(queryText || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase();
        const termTokens = termNorm ? termNorm.split(/\s+/).filter(Boolean) : [];

        // Filtro em memória sem novas requisições de leitura ao banco
        const correspondencias = (window.allStudentsData || []).filter(student => {
          const sNomeNorm = student._nomeNorm || (typeof normalizarTextoBusca === "function" ? normalizarTextoBusca(student.nome) : String(student.nome || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase());
          const ra = String(student.ra || "").toLowerCase();
          const raClean = student._raClean || ra.replace(/\D/g, "");
          const turma = String(student.turma || "").toLowerCase();

          if (termClean.length >= 3 && raClean.includes(termClean)) return true;
          if (ra.includes(term) || turma.includes(term)) return true;
          return termTokens.length > 0 && termTokens.every(tk => sNomeNorm.includes(tk));
        });

        // REGRA DE GESTÃO POR EXCEÇÃO: Ordenar candidatos do maior risco (menor frequência) para o menor
        correspondencias.sort((a, b) => {
          const getVal = (st) => {
            const v = st.presenca_anual || st.presenca_26_06 || st.presenca_15_06 || st.presenca || st.presenca_atual;
            if (v === undefined || v === null || v === "" || v === "—") return 999;
            const n = parseFloat(String(v).replace("%", "").replace(",", "."));
            return isNaN(n) ? 999 : n;
          };
          return getVal(a) - getVal(b);
        });

        const correspondenciasTop = correspondencias.slice(0, 20);

        if (correspondenciasTop.length === 0) {
          const safeTerm = queryText.replace(/"/g, '&quot;').replace(/'/g, "\\'");
          dropdownResultados.innerHTML = `
            <div class="p-4 text-center">
              <i class="fa-solid fa-user-slash text-slate-300 text-sm mb-1.5 block"></i>
              <p class="text-slate-500 font-medium text-xs mb-2">Nenhum aluno em memória para "${queryText}"</p>
              <button 
                type="button" 
                onclick="window.buscarAlunoDiretoNoBancoComTermo('${safeTerm}')" 
                class="px-3 py-1.5 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 border border-indigo-200 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1.5 mx-auto cursor-pointer"
              >
                <i class="fa-solid fa-cloud-arrow-down text-xs"></i>
                <span>Buscar "${queryText}" no Banco Completo</span>
              </button>
            </div>
          `;
          dropdownResultados.classList.remove("hidden");
          return;
        }

        let html = "";
        correspondenciasTop.forEach(student => {
          const nome = (student.nome || "SEM NOME").toUpperCase();
          const ra = student.ra || "-";
          const turma = (student.turma || "-").toUpperCase();
          const status = (student.status || "ativo").toUpperCase();

          let statusBadgeClass = "bg-emerald-50 text-emerald-700 border-emerald-200";
          if (status !== "ATIVO") statusBadgeClass = "bg-slate-100 text-slate-600 border-slate-200";

          html += `
            <div 
              onclick="selecionarAlunoParaOcorrencia('${ra}')"
              class="p-3 hover:bg-cyan-50 cursor-pointer transition flex items-center justify-between gap-3 group"
            >
              <div class="min-w-0 flex-1">
                <span class="font-bold text-slate-800 text-xs block group-hover:text-blue-900 truncate">${nome}</span>
                <div class="flex items-center gap-2 text-[11px] text-slate-500 mt-0.5">
                  <span>RA: <strong class="font-mono text-blue-800">${ra}</strong></span>
                  <span>|</span>
                  <span>Turma: <strong class="text-slate-700">${turma}</strong></span>
                </div>
              </div>
              <span class="px-2 py-0.5 ${statusBadgeClass} border text-[9px] font-bold rounded uppercase tracking-wider shrink-0">${status}</span>
            </div>
          `;
        });

        dropdownResultados.innerHTML = html;
        dropdownResultados.classList.remove("hidden");
      }

      if (inputBuscarAluno) {
        inputBuscarAluno.addEventListener("input", (e) => {
          realizarBuscaAutocomplete(e.target.value);
        });

        inputBuscarAluno.addEventListener("focus", (e) => {
          if (e.target.value.trim().length > 0) {
            realizarBuscaAutocomplete(e.target.value);
          }
        });
      }

      if (btnLimparBusca) {
        btnLimparBusca.addEventListener("click", () => {
          if (inputBuscarAluno) inputBuscarAluno.value = "";
          btnLimparBusca.classList.add("hidden");
          fecharDropdownAlunos();
          cardAlunoEncontrado?.classList.add("hidden");
          formOcorrencia?.classList.add("hidden");
          alunoAtual = null;
        });
      }

      // Fechar a lista suspensa ao clicar fora
      document.addEventListener("click", (e) => {
        if (inputBuscarAluno && dropdownResultados) {
          if (!inputBuscarAluno.contains(e.target) && !dropdownResultados.contains(e.target)) {
            fecharDropdownAlunos();
          }
        }
      });

      // Listener para alternar exibição do campo Motivo da Saída Antecipada e Notificação à Direção
      const elSelectTipoReg = document.getElementById("tipo-registro");
      if (elSelectTipoReg) {
        elSelectTipoReg.addEventListener("change", () => {
          if (typeof window.atualizarVisibilidadeMotivoSaida === "function") {
            window.atualizarVisibilidadeMotivoSaida();
          }
          const chkNotificar = document.getElementById("oc-notificar-direcao");
          const containerNotif = document.getElementById("container-notificar-direcao");
          const roleAtual = window.obterRoleAtual ? window.obterRoleAtual() : "PROFESSOR";
          const roleNorm = window.normalizarUserRole ? window.normalizarUserRole(roleAtual) : "PROFESSOR";
          const isProfessor = (roleNorm === "PROFESSOR");

          if (containerNotif) {
            if (isProfessor) {
              containerNotif.classList.remove("hidden");
            } else {
              containerNotif.classList.add("hidden");
            }
          }
          // Por padrão NÃO notifica a direção, só se o professor marcar mesmo
          if (chkNotificar) {
            chkNotificar.checked = false;
          }
        });
      }

      // Submissão do Formulário de Registro de Ocorrência
      if (formOcorrencia) {
        formOcorrencia.addEventListener("submit", async (e) => {
          e.preventDefault();
          if (!alunoAtual) {
            window.showToast("Por favor, selecione um aluno na busca antes de salvar o registro.", 'warning');
            return;
          }

          const btnSalvar = btnSalvarRegistro || document.getElementById("btn-salvar-registro");

          const elTipo = document.getElementById("tipo-registro");
          const tipo = elTipo ? elTipo.value : "Tutoria e Acolhimento";
          const elDesc = document.getElementById("descricao-registro");
          let descricao = elDesc ? elDesc.value.trim() : "";
          const elMotivo = document.getElementById("motivo-saida-ante");
          const motivoSaida = elMotivo ? elMotivo.value.trim() : "";

          if (tipo === "Saída Antecipada") {
            if (!motivoSaida) {
              window.showToast("Por favor, informe o motivo da saída antecipada.", 'warning');
              if (elMotivo) elMotivo.focus();
              return;
            }
            if (!descricao.startsWith("Motivo:")) {
              descricao = `Motivo: ${motivoSaida} - ${descricao}`;
            }
          }

          if (!descricao) {
            window.showToast("Por favor, preencha a descrição detalhada do registro.", 'warning');
            return;
          }

          const chkCiencia = document.getElementById("oc-ciencia-responsavel");
          const inputDataCiencia = document.getElementById("oc-data-ciencia");
          const chkConviva = document.getElementById("oc-registrado-conviva");
          const inputCodConviva = document.getElementById("oc-codigo-conviva");

          const cienciaResponsavel = chkCiencia ? chkCiencia.checked : false;
          const dataCiencia = cienciaResponsavel ? (inputDataCiencia?.value || new Date().toISOString().split('T')[0]) : "";
          const registradoConviva = chkConviva ? chkConviva.checked : false;
          const codigoConviva = registradoConviva ? (inputCodConviva?.value.trim().toUpperCase() || "") : "";

          const tipoLower = (tipo || "").toLowerCase();
          const isDispensa = tipoLower.includes("dispensa") || tipoLower.includes("afastamento");

          if (isDispensa && !(window.podeRegistrarDispensa && window.podeRegistrarDispensa())) {
            window.showToast("Apenas Secretaria, CGPG, Direção e Vice-Direção podem registrar Dispensa / Afastamento Legal.", 'warning');
            return;
          }

          let dispensaInicio = "";
          let dispensaFim = "";
          let dispensaMotivo = "";
          let diasDispensa = 0;

          if (isDispensa) {
            dispensaInicio = document.getElementById("oc-dispensa-inicio")?.value || "";
            dispensaFim = document.getElementById("oc-dispensa-fim")?.value || "";
            dispensaMotivo = document.getElementById("oc-dispensa-motivo")?.value || "Atestado Médico";
            if (!dispensaInicio || !dispensaFim) {
              window.showToast("Informe a Data Início e Data Fim da Dispensa / Afastamento Legal.", 'warning');
              return;
            }
            if (dispensaFim < dispensaInicio) {
              window.showToast("A Data Fim da dispensa não pode ser anterior à Data Início.", 'warning');
              return;
            }
            diasDispensa = Math.max(1, Math.round((new Date(`${dispensaFim}T12:00:00`).getTime() - new Date(`${dispensaInicio}T12:00:00`).getTime()) / 86400000) + 1);
            const dtIniBr = dispensaInicio.split("-").reverse().join("/");
            const dtFimBr = dispensaFim.split("-").reverse().join("/");
            if (!descricao.includes(dtIniBr)) {
              descricao = `[Dispensa ${dispensaMotivo}: ${dtIniBr} a ${dtFimBr}] ${descricao}`;
            }
          }

          const descLower = (descricao || "").toLowerCase();
          const isAtraso = !isDispensa && (tipoLower.includes("atraso") || descLower.includes("atraso") || descLower.includes("atrasos"));
          const horaRealAtraso = isAtraso ? (document.getElementById("oc-hora-atraso")?.value || new Date().toTimeString().slice(0, 5)) : "";

          if (isAtraso && horaRealAtraso && !descricao.includes(horaRealAtraso)) {
            descricao = `${descricao} (Chegada às ${horaRealAtraso})`;
          }

          if (btnSalvar) {
            btnSalvar.disabled = true;
            btnSalvar.innerHTML = `<i class="fa-solid fa-spinner animate-spin text-xs"></i><span>Salvando...</span>`;
          }

          try {
            const userDetails = window.obterIdentificacaoUsuarioCompleta();
            const autorFinal = userDetails.textoCompleto;
            const editOcId = document.getElementById("ocorrencia-id")?.value;

            if (editOcId) {
              // É EDIÇÃO: Atualizar o documento existente preservando autor original e gravando auditoria da edição
              const docRef = doc(db, "ocorrencias", editOcId);
              const payloadEdicao = {
                tipo: tipo,
                descricao: descricao,
                isAtraso: isAtraso,
                isDispensa: isDispensa,
                cienciaResponsavel: cienciaResponsavel,
                dataCiencia: dataCiencia,
                registradoConviva: registradoConviva,
                codigoConviva: codigoConviva,
                protocoloConviva: codigoConviva,
                updatedAt: new Date().toISOString(),
                data_atualizacao: new Date().toISOString(),
                editado_por_email: userDetails.email,
                editado_por_nome: userDetails.nome,
                editado_por_cargo: userDetails.cargo,
                editado_por_completo: userDetails.textoCompleto,
                data_ultima_edicao: new Date().toISOString()
              };
              if (isAtraso && horaRealAtraso) {
                payloadEdicao.horaRealAtraso = horaRealAtraso;
                payloadEdicao.horarioAtraso = horaRealAtraso;
              }
              if (isDispensa) {
                payloadEdicao.dataInicio = dispensaInicio;
                payloadEdicao.dataFim = dispensaFim;
                payloadEdicao.motivoDispensa = dispensaMotivo;
                payloadEdicao.diasDispensa = diasDispensa;
              }
              await updateDoc(docRef, payloadEdicao);

              if (typeof window.registrarLogAuditoria === "function") {
                window.registrarLogAuditoria({
                  modulo: "Alunos",
                  acao: "ATUALIZAR",
                  descricao: `Atualizada ocorrência (${tipo}) de ${alunoAtual.nome} (${alunoAtual.turma || ''})`,
                  detalhes: { ra: alunoAtual.ra, tipo, descricao }
                });
              }

              if (Array.isArray(window.ocorrenciasTopLevel)) {
                const item = window.ocorrenciasTopLevel.find(o => o.id === editOcId);
                if (item) {
                  Object.assign(item, payloadEdicao);
                }
              }

              window.showToast("Registro de ocorrência atualizado no banco de dados com sucesso!", 'success');
              const inputOcId = document.getElementById("ocorrencia-id");
              if (inputOcId) inputOcId.value = "";
            } else {
              const chkNotificarDirecao = document.getElementById("oc-notificar-direcao");
              const roleAtualForm = window.obterRoleAtual ? window.obterRoleAtual() : "PROFESSOR";
              const roleNormForm = window.normalizarUserRole ? window.normalizarUserRole(roleAtualForm) : "PROFESSOR";
              const isDocenteForm = (roleNormForm === "PROFESSOR" || roleNormForm === "PROFESSOR_PAAC" || roleAtualForm === "PROFESSOR_PAAC");
              const notificarDirecao = (isDocenteForm && chkNotificarDirecao && chkNotificarDirecao.checked) ? true : false;

              // É NOVO REGISTRO: Criar um documento do zero com rastreabilidade completa.
              // REGRA CRÍTICA DE INTEGRAÇÃO (JSON): estritamente proibido criar ou incluir id ou _id
              const novaOcorrencia = {
                ra: alunoAtual.ra,
                nomeAluno: alunoAtual.nome,
                turma: alunoAtual.turma || "",
                tipo: tipo,
                categoria: tipo,
                descricao: descricao,
                isAtraso: isAtraso,
                isDispensa: isDispensa,
                notificarDirecao: notificarDirecao,
                notificarGestao: notificarDirecao,
                notificacaoDirecaoPendente: notificarDirecao,
                notificadoEm: notificarDirecao ? new Date().toISOString() : null,
                notificadoPor: notificarDirecao ? autorFinal : null,
                cienciaResponsavel: cienciaResponsavel,
                dataCiencia: dataCiencia,
                registradoConviva: registradoConviva,
                codigoConviva: codigoConviva,
                protocoloConviva: codigoConviva,
                data: new Date().toISOString(),
                usuario: autorFinal,
                autor: autorFinal,
                registradoPor: autorFinal,
                autor_email: userDetails.email,
                autor_nome: userDetails.nome,
                autor_cargo: userDetails.cargo,
                cargo: userDetails.cargo,
                autor_criacao: {
                  nome: userDetails.nome,
                  email: userDetails.email,
                  cargo: userDetails.cargo,
                  textoCompleto: userDetails.textoCompleto,
                  data: new Date().toISOString()
                }
              };

              if (isAtraso && horaRealAtraso) {
                novaOcorrencia.horaRealAtraso = horaRealAtraso;
                novaOcorrencia.horarioAtraso = horaRealAtraso;
              }
              if (isDispensa) {
                novaOcorrencia.dataInicio = dispensaInicio;
                novaOcorrencia.dataFim = dispensaFim;
                novaOcorrencia.motivoDispensa = dispensaMotivo;
                novaOcorrencia.diasDispensa = diasDispensa;
              }

              const docRef = await addDoc(collection(db, "ocorrencias"), novaOcorrencia);
              const ocorrenciaLocal = { ...novaOcorrencia, id: docRef.id };

              if (!Array.isArray(window.ocorrenciasTopLevel)) window.ocorrenciasTopLevel = [];
              window.ocorrenciasTopLevel.unshift(ocorrenciaLocal);

              // Preserva e faz append no histórico acumulado do aluno (sem campos id ou _id no payload do banco)
              const cleanTargetRa = String(alunoAtual.ra || "").replace(/\D/g, "");
              const stObj = ((window.allStudentsData || [])).find(s => String(s.ra || "").replace(/\D/g, "") === cleanTargetRa);
              if (stObj) {
                const resumoAnt = stObj.acoes_2026 || "";
                const infoCiencia = cienciaResponsavel ? ` (Família Ciente em ${dataCiencia})` : '';
                const infoConviva = registradoConviva ? ` [CONVIVA: ${codigoConviva || 'OK'}]` : '';
                const novaLinha = `[${new Date().toLocaleDateString("pt-BR")}] ${tipo}: ${descricao}${infoCiencia}${infoConviva}`;
                const novoResumo = resumoAnt ? `${resumoAnt}\n${novaLinha}` : novaLinha;
                const targetRa = stObj.ra || alunoAtual.ra;
                const studentDocRef = doc(db, "alunos", String(targetRa));
                const updatePayloadAluno = {
                  acoes_2026: novoResumo.toUpperCase(),
                  ocorrencias: arrayUnion(novaOcorrencia)
                };
                const registroDispensaAluno = isDispensa ? {
                  dataInicio: dispensaInicio,
                  dataFim: dispensaFim,
                  motivoDispensa: dispensaMotivo,
                  diasDispensa: diasDispensa,
                  descricao: descricao,
                  registradoPor: autorFinal,
                  data: novaOcorrencia.data
                } : null;
                if (registroDispensaAluno) {
                  updatePayloadAluno.dispensas = arrayUnion(registroDispensaAluno);
                }

                try {
                  await updateDoc(studentDocRef, updatePayloadAluno);
                } catch (eUpd) {
                  await setDoc(studentDocRef, updatePayloadAluno, { merge: true });
                }
                stObj.acoes_2026 = novoResumo.toUpperCase();
                if (!Array.isArray(stObj.ocorrencias)) stObj.ocorrencias = [];
                stObj.ocorrencias.push(ocorrenciaLocal);
                if (registroDispensaAluno) {
                  if (!Array.isArray(stObj.dispensas)) stObj.dispensas = [];
                  stObj.dispensas.push(registroDispensaAluno);
                }
              }

              window.showToast(
                isDispensa
                  ? "Dispensa registrada e sincronizada automaticamente com a Presença Diária!"
                  : "Registro de ocorrência salvo no banco de dados com sucesso!",
                'success'
              );

              if (typeof window.registrarLogAuditoria === "function") {
                window.registrarLogAuditoria({
                  modulo: "Alunos",
                  acao: "CRIAR",
                  descricao: `Registrada nova ocorrência (${tipo}) para ${alunoAtual.nome} (${alunoAtual.turma || ''})`,
                  detalhes: { ra: alunoAtual.ra, tipo, descricao }
                });
              }

              // Gatilho Automático de 3 Atrasos no Mês
              if ((isAtraso || String(tipo || "").toUpperCase().includes("ATRASO")) && typeof window.verificarGatilhoAtrasosMes === "function") {
                await window.verificarGatilhoAtrasosMes(stObj || alunoAtual);
              }
            }

            // Atualização local e consolidação do Master Feed em tempo real
            if (typeof window.consolidarHistoricoOcorrenciasGlobais === "function") {
              window.consolidarHistoricoOcorrenciasGlobais();
            } else {
              renderHistoricoOcorrencias(window.ocorrenciasCache || []);
            }
            if (elDesc) elDesc.value = "";
            if (chkCiencia) chkCiencia.checked = false;
            if (inputDataCiencia) inputDataCiencia.value = "";
            if (chkConviva) chkConviva.checked = false;
            if (inputCodConviva) inputCodConviva.value = "";
            document.getElementById('oc-container-data-ciencia')?.classList.add('hidden');
            document.getElementById('oc-container-codigo-conviva')?.classList.add('hidden');
          } catch (err) {
            window.showErrorToast("Erro de conexão com o banco de dados! A alteração não foi salva. Verifique sua internet.", err);
          } finally {
            if (btnSalvar) {
              btnSalvar.disabled = false;
              btnSalvar.innerHTML = `<i class="fa-solid fa-floppy-disk text-xs"></i><span>Salvar Registro</span>`;
            }
          }
        });
      }

      // Função para renderizar widget de alunos mais reincidentes
      function renderAlunosReincidentesWidget(countMapInput, lista) {
        const widgetContainer = document.getElementById("lista-alunos-reincidentes-widget");
        const countBadge = document.getElementById("reincidentes-count");
        if (!widgetContainer) return;

        const isPerfilPedagogico = typeof window.checarIsPerfilPedagogico === "function" ? window.checarIsPerfilPedagogico() : false;

        // Supressão de Dados na Fonte: Perfis pedagógicos veem apenas Tutoria e Questões Pedagógicas
        const listaPermitida = (lista || []).filter(registro => {
          if (!registro) return false;
          if (!isPerfilPedagogico) return true; // Diretor, Vice e Secretaria veem tudo
          const tipo = (registro.tipo || registro.categoria || registro.descricao || '').toUpperCase();
          return tipo.includes('TUTORIA') || tipo.includes('PEDAGÓGICA') || tipo.includes('PEDAGOGICA');
        });

        // Filtrar EXCLUSIVAMENTE ocorrências do tipo disciplinar / Conviva
        const ocorrenciasDisciplinares = (listaPermitida || []).filter(oc => {
          return typeof window.isOcorrenciaDisciplinarOuConviva === "function" 
            ? window.isOcorrenciaDisciplinarOuConviva(oc) 
            : false;
        });

        // Contabiliza reincidência por RA estritamente sobre ocorrências disciplinares
        const countMapDisciplinar = {};
        ocorrenciasDisciplinares.forEach(oc => {
          const raKey = String(oc?.ra || "").trim();
          if (raKey) {
            countMapDisciplinar[raKey] = (countMapDisciplinar[raKey] || 0) + 1;
          }
        });

        const reincidentes = Object.entries(countMapDisciplinar)
          .filter(([ra, count]) => count >= 2)
          .sort((a, b) => b[1] - a[1]);

        if (countBadge) countBadge.textContent = `${reincidentes.length} Reincidente(s)`;

        if (reincidentes.length === 0) {
          widgetContainer.innerHTML = `
            <div class="col-span-full p-3 text-center text-xs text-slate-500 italic bg-white rounded-lg border border-slate-200">
              <i class="fa-solid fa-shield-check text-emerald-600 mr-1.5"></i> Nenhum estudante com múltiplas ocorrências disciplinares acumuladas. Todos os registros são pontuais.
            </div>
          `;
          return;
        }

        let html = "";
        reincidentes.slice(0, 8).forEach(([ra, totalCount]) => {
          const ocExemplo = (ocorrenciasDisciplinares || []).find(item => String(item?.ra).trim() === ra) || (lista || []).find(item => String(item?.ra).trim() === ra);
          const nomeUpper = (ocExemplo?.nomeAluno || "ESTUDANTE").toUpperCase();
          const turmaUpper = (ocExemplo?.turma || "-").toUpperCase();

          html += `
            <div class="p-3 bg-white border border-amber-300 rounded-xl shadow-2xs hover:border-amber-500 transition flex flex-col justify-between gap-2">
              <div class="flex items-start justify-between gap-1">
                <div class="min-w-0 flex-1">
                  <button 
                    type="button" 
                    onclick="window.navegarEAbrirFichaAluno('${ra}')" 
                    class="cursor-pointer text-blue-600 hover:text-blue-800 hover:underline font-semibold text-xs uppercase block truncate text-left transition-colors"
                    title="Clique para abrir a ficha do aluno no Módulo Alunos"
                  >
                    ${nomeUpper}
                  </button>
                  <p class="text-[10px] text-slate-500 font-mono mt-0.5">RA: ${ra} • ${turmaUpper}</p>
                </div>
                <span class="px-2 py-0.5 bg-amber-600 text-white font-black text-[10px] rounded-md shrink-0 shadow-2xs">
                  ${totalCount}x Ocorrências
                </span>
              </div>
              <div class="flex items-center justify-end border-t border-slate-100 pt-2 mt-1">
                <button 
                  type="button"
                  onclick="window.selecionarAlunoParaOcorrencia('${ra}')"
                  class="px-2.5 py-1 bg-amber-600 hover:bg-amber-700 text-white font-extrabold rounded text-[10px] uppercase tracking-wider transition cursor-pointer flex items-center gap-1 shadow-2xs"
                >
                  <i class="fa-solid fa-pen-to-square text-[9px]"></i>
                  <span>Nova Ocorrência</span>
                </button>
              </div>
            </div>
          `;
        });

        widgetContainer.innerHTML = html;
      }

      // Preencher Select de Turmas nos Filtros de Ocorrência
      function atualizarSelectTurmasFiltroOcorrencias() {
        const selectTurmaFiltro = document.getElementById("filter-historico-turma");
        if (!selectTurmaFiltro) return;

        const turmasPadrao = [
          "6A", "6B", "7A", "7B", "8A", "8B", "9A", "9B",
          "1A", "1B", "2A", "2B", "3A", "3B",
          "6º ANO A", "6º ANO B", "7º ANO A", "7º ANO B", "8º ANO A", "8º ANO B", "9º ANO A", "9º ANO B",
          "1ª SÉRIE A EM", "1ª SÉRIE B EM", "2ª SÉRIE A EM", "2ª SÉRIE B EM", "3ª SÉRIE A EM", "3ª SÉRIE B EM"
        ];

        const turmasSet = new Set(turmasPadrao);
        ((window.allStudentsData || [])).forEach(s => {
          if (s?.turma) turmasSet.add(String(s.turma).toUpperCase().trim());
        });
        ((window.ocorrenciasCache || [])).forEach(o => {
          if (o?.turma) turmasSet.add(String(o.turma).toUpperCase().trim());
        });

        const turmasOrdenadas = Array.from(turmasSet).filter(Boolean).sort();
        const valAtual = (selectTurmaFiltro.value || "").trim();

        let htmlOptions = `<option value="Todas as Turmas">Todas as Turmas (${turmasOrdenadas.length})</option>`;
        turmasOrdenadas.forEach(t => {
          htmlOptions += `<option value="${t}">${t}</option>`;
        });
        selectTurmaFiltro.innerHTML = htmlOptions;

        if (valAtual && valAtual.toUpperCase() !== "TODAS AS TURMAS" && turmasOrdenadas.includes(valAtual.toUpperCase())) {
          selectTurmaFiltro.value = valAtual.toUpperCase();
        } else {
          selectTurmaFiltro.value = "Todas as Turmas";
        }
      }

      // Função de Consolidação do Master Feed Global de Ocorrências / Registros
      // Extrai os arrays de ocorrências/registros de TODOS os alunos em tempo real e consolida em um único feed unificado, eliminando duplicidades entre coleções e registros embutidos.
      // =========================================================
      // GATILHO AUTOMÁTICO: 3 ATRASOS NO MÊS -> TERMO DE CIÊNCIA DE FREQUÊNCIA + PAUTA OBRIGATÓRIA DE TUTORIA
      // =========================================================
      window.emitirTermoCienciaFrequenciaGatilho = function(ra, qtdAtrasosMesOverride) {
        if (!ra) return;
        const cleanRa = String(ra).replace(/\D/g, "");
        const aluno = (window.allStudentsData || []).find(s => String(s.ra || s.id || "").replace(/\D/g, "") === cleanRa || String(s.ra || s.id || "").trim() === String(ra).trim());
        if (!aluno) {
          if (typeof window.showToast === "function") window.showToast("Estudante não localizado para emissão do Termo.", "warning");
          return;
        }

        const agora = new Date();
        const mesAtual = agora.getMonth();
        const anoAtual = agora.getFullYear();
        const nomeMes = agora.toLocaleDateString("pt-BR", { month: "long", year: "numeric" }).toUpperCase();

        const ocorrenciasAluno = Array.isArray(aluno.ocorrencias) ? aluno.ocorrencias : [];
        const atrasosMes = ocorrenciasAluno.filter(oc => {
          const isAtr = oc.isAtraso === true || String(oc.tipo || oc.categoria || "").toUpperCase().includes("ATRASO");
          if (!isAtr) return false;
          const dt = new Date(oc.data || oc.createdAt || 0);
          return !isNaN(dt.getTime()) && dt.getMonth() === mesAtual && dt.getFullYear() === anoAtual;
        });

        const totalMes = qtdAtrasosMesOverride || atrasosMes.length || 3;
        const tutorNome = (aluno.tutor || aluno.tutor_2026 || "A DEFINIR PELA COORDENAÇÃO").toUpperCase();
        const responsavelNome = (aluno.responsavel || aluno.filiacao_1 || "RESPONSÁVEL LEGAL").toUpperCase();
        const dataHojeExtenso = agora.toLocaleDateString("pt-BR", { day: "2-digit", month: "long", year: "numeric" });

        const listaDatasHtml = atrasosMes.length > 0
          ? atrasosMes.slice(0, 8).map((oc, i) => {
              const dtStr = oc.data ? new Date(oc.data).toLocaleDateString("pt-BR") : "-";
              const hrStr = oc.horaRealAtraso || (oc.data ? new Date(oc.data).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" }) : "");
              return `<li style="margin-bottom: 4px;"><strong>${i + 1}º Atraso no mês:</strong> Data ${dtStr} ${hrStr ? `(Chegada às ${hrStr})` : ""} — ${oc.descricao || "Registro de portaria/secretaria"}</li>`;
            }).join("")
          : `<li><strong>Total contabilizado no mês vigente (${nomeMes}):</strong> ${totalMes} registros de entrada com atraso.</li>`;

        const htmlDoc = `
          <div style="font-family: 'Times New Roman', Times, serif; color: #000; line-height: 1.5; max-width: 720px; margin: 0 auto; padding: 16px;">
            <div style="text-align: center; border-bottom: 2px solid #000; padding-bottom: 12px; margin-bottom: 20px;">
              <p style="margin: 0; font-size: 12px; font-weight: bold; text-transform: uppercase;">GOVERNO DO ESTADO DE SÃO PAULO — SECRETARIA DA EDUCAÇÃO</p>
              <p style="margin: 2px 0; font-size: 13px; font-weight: bold; text-transform: uppercase;">DIRETORIA DE ENSINO — PROGRAMA ENSINO INTEGRAL (PEI)</p>
              <h1 style="margin: 4px 0 0 0; font-size: 16px; font-weight: 900; text-transform: uppercase;">EE PROF. CLÓVIS DE LUCCA</h1>
            </div>

            <div style="text-align: center; margin-bottom: 20px;">
              <h2 style="margin: 0; font-size: 15px; font-weight: bold; text-transform: uppercase; text-decoration: underline;">
                TERMO DE CIÊNCIA DE FREQUÊNCIA E PONTUALIDADE ESCOLAR
              </h2>
              <p style="margin: 4px 0 0 0; font-size: 11px; font-weight: bold; color: #333;">
                GATILHO AUTOMÁTICO DE MONITORAMENTO (${totalMes} ATRASOS EM ${nomeMes}) + PAUTA OBRIGATÓRIA DE TUTORIA
              </p>
            </div>

            <div style="border: 1px solid #000; padding: 12px; margin-bottom: 16px; font-size: 12px; background: #f8fafc;">
              <p style="margin: 2px 0;"><strong>ESTUDANTE:</strong> ${(aluno.nome || "").toUpperCase()} &nbsp;|&nbsp; <strong>RA:</strong> ${aluno.ra || "-"} &nbsp;|&nbsp; <strong>TURMA:</strong> ${(aluno.turma || "-").toUpperCase()}</p>
              <p style="margin: 2px 0;"><strong>RESPONSÁVEL LEGAL:</strong> ${responsavelNome} &nbsp;|&nbsp; <strong>CONTATO:</strong> ${aluno.telefone || "-"}</p>
              <p style="margin: 2px 0;"><strong>PROFESSOR(A) TUTOR(A) PEI:</strong> ${tutorNome}</p>
            </div>

            <p style="text-align: justify; font-size: 13px; margin-bottom: 12px;">
              Pelo presente instrumento oficial, a Equipe Gestora da <strong>EE Prof. Clóvis de Lucca</strong> notifica formalmente o(a) estudante acima identificado(a) e seu respectivo Responsável Legal de que foi atingido o gatilho institucional de <strong>${totalMes} (${totalMes === 3 ? "três" : totalMes}) ou mais registros de atraso no mês de ${nomeMes}</strong>.
            </p>

            <div style="border: 1px solid #000; padding: 10px 14px; margin-bottom: 16px; font-size: 12px;">
              <p style="margin: 0 0 6px 0; font-weight: bold; text-transform: uppercase;">Histórico de Atrasos Registrados no Mês Vigente:</p>
              <ul style="margin: 0; padding-left: 18px;">
                ${listaDatasHtml}
              </ul>
            </div>

            <div style="border: 2px solid #000; padding: 12px; margin-bottom: 18px; font-size: 12px;">
              <p style="margin: 0 0 6px 0; font-weight: bold; text-transform: uppercase;">ENCAMINHAMENTO PEDAGÓGICO OBRIGATÓRIO (PROGRAMA ENSINO INTEGRAL):</p>
              <p style="margin: 0; text-align: justify;">
                1. <strong>Pauta Obrigatória na Sessão Semanal de Tutoria:</strong> O(A) Professor(a) Tutor(a) <strong>${tutorNome}</strong> trabalhará obrigatoriamente a organização da rotina matinal, corresponsabilidade e Projeto de Vida na sessão semanal de Tutoria.<br/>
                2. <strong>Compromisso da Família e Estudante:</strong> A pontualidade no Programa Ensino Integral é requisito indispensável para o aproveitamento pedagógico integral e cumprimento da carga horária legal (mínimo de 75% de frequência exigido pela LDB — Lei nº 9.394/96).
              </p>
            </div>

            <p style="text-align: right; font-size: 12px; margin-top: 24px; margin-bottom: 36px;">
              São Paulo, ${dataHojeExtenso}.
            </p>

            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 28px; text-align: center; font-size: 11px; margin-top: 32px;">
              <div>
                <div style="border-top: 1px solid #000; padding-top: 4px; font-weight: bold;">ASSINATURA DO(A) RESPONSÁVEL LEGAL</div>
                <div>${responsavelNome}</div>
              </div>
              <div>
                <div style="border-top: 1px solid #000; padding-top: 4px; font-weight: bold;">CIÊNCIA DO(A) ESTUDANTE</div>
                <div>${(aluno.nome || "").toUpperCase()}</div>
              </div>
              <div>
                <div style="border-top: 1px solid #000; padding-top: 4px; font-weight: bold;">PROFESSOR(A) TUTOR(A) — PAUTA SEMANAL</div>
                <div>${tutorNome}</div>
              </div>
              <div>
                <div style="border-top: 1px solid #000; padding-top: 4px; font-weight: bold;">DIREÇÃO / COORDENAÇÃO DE GESTÃO PEDAGÓGICA</div>
                <div>EE PROF. CLÓVIS DE LUCCA</div>
              </div>
            </div>
          </div>
        `;

        const modalDoc = document.getElementById("modal-documento-impressao");
        const areaDoc = document.getElementById("documento-impressao-area");
        if (modalDoc && areaDoc) {
          areaDoc.innerHTML = htmlDoc;
          modalDoc.classList.remove("hidden");
        }
      };

      window.verificarGatilhoAtrasosMes = async function(alunoObj) {
        if (!alunoObj) return false;
        const cleanRa = String(alunoObj.ra || alunoObj.id || "").replace(/\D/g, "");
        const st = (window.allStudentsData || []).find(s => String(s.ra || s.id || "").replace(/\D/g, "") === cleanRa) || alunoObj;
        const raStr = String(st.ra || st.id || "").trim();
        if (!raStr) return false;

        const agora = new Date();
        const mesAtual = agora.getMonth();
        const anoAtual = agora.getFullYear();
        const chaveMes = `${anoAtual}-${String(mesAtual + 1).padStart(2, "0")}`;

        const ocorrenciasAluno = Array.isArray(st.ocorrencias) ? st.ocorrencias : [];
        const atrasosNoMes = ocorrenciasAluno.filter(oc => {
          if (!oc) return false;
          const isAtr = oc.isAtraso === true || String(oc.tipo || oc.categoria || "").toUpperCase().includes("ATRASO");
          if (!isAtr) return false;
          const dt = new Date(oc.data || oc.createdAt || 0);
          return !isNaN(dt.getTime()) && dt.getMonth() === mesAtual && dt.getFullYear() === anoAtual;
        });

        const qtdMes = atrasosNoMes.length;
        if (qtdMes >= 3 && qtdMes % 3 === 0) {
          const marcadorGatilho = `[GATILHO AUTOMÁTICO ${qtdMes} ATRASOS - ${chaveMes}]`;
          const jaGerouPautaNesteMarco = ocorrenciasAluno.some(oc =>
            String(oc.descricao || oc.titulo || "").includes(marcadorGatilho)
          );

          if (!jaGerouPautaNesteMarco) {
            const tutorNome = (st.tutor || st.tutor_2026 || "Tutoria PEI").trim();
            const dataIso = agora.toISOString();
            const descPauta = `${marcadorGatilho} PAUTA OBRIGATÓRIA NA SESSÃO SEMANAL DE TUTORIA (${tutorNome}): Estudante atingiu ${qtdMes} atrasos no mês (${chaveMes}). Emitido Termo de Ciência de Frequência imediato e agendada intervenção pedagógica de pontualidade.`;

            // REGRA CRÍTICA (AGENTS.md / GEMINI.md): NUNCA incluir id ou _id no objeto enviado ao banco de dados
            const pautaTutoriaPayload = {
              ra: raStr,
              nomeAluno: String(st.nome || "").toUpperCase(),
              turma: String(st.turma || "").toUpperCase(),
              titulo: `PAUTA OBRIGATÓRIA DE TUTORIA — ${qtdMes} ATRASOS NO MÊS`,
              descricao: descPauta,
              categoria: "Tutoria e Acolhimento",
              tipo: "Tutoria e Acolhimento",
              encaminhamento: `Sessão semanal de Tutoria com ${tutorNome} e assinatura do Termo de Ciência de Frequência`,
              tutorResponsavel: tutorNome,
              gatilhoAutomaticoAtraso: true,
              qtdAtrasosGatilho: qtdMes,
              mesReferenciaGatilho: chaveMes,
              cienciaResponsavel: false,
              dataCiencia: "",
              registradoConviva: false,
              data: dataIso,
              usuario: `SISTEMA AUTOMÁTICO • Tutor: ${tutorNome}`,
              autor: tutorNome,
              registradoPor: tutorNome
            };

            try {
              const docRefPauta = await addDoc(collection(db, "ocorrencias"), pautaTutoriaPayload);
              const pautaLocal = { ...pautaTutoriaPayload, id: docRefPauta.id };

              if (!Array.isArray(window.ocorrenciasTopLevel)) window.ocorrenciasTopLevel = [];
              window.ocorrenciasTopLevel.unshift(pautaLocal);

              const resumoAnt = st.acoes_2026 || "";
              const novaLinhaResumo = `[${agora.toLocaleDateString("pt-BR")}] GATILHO 3 ATRASOS (TUTORIA + TERMO): ${descPauta}`;
              const novoResumo = resumoAnt ? `${resumoAnt}\n${novaLinhaResumo}` : novaLinhaResumo;

              const studentDocRef = doc(db, "alunos", raStr);
              await setDoc(studentDocRef, {
                acoes_2026: novoResumo.toUpperCase(),
                pautaTutoriaObrigatoriaPendente: true,
                ultimoGatilhoAtrasosMes: chaveMes,
                ocorrencias: arrayUnion(pautaTutoriaPayload)
              }, { merge: true });

              st.acoes_2026 = novoResumo.toUpperCase();
              st.pautaTutoriaObrigatoriaPendente = true;
              if (!Array.isArray(st.ocorrencias)) st.ocorrencias = [];
              st.ocorrencias.push(pautaLocal);
            } catch (errGatilho) {
              console.warn("Aviso ao gravar pauta automática de tutoria:", errGatilho);
            }

            if (typeof window.showToast === "function") {
              window.showToast(`⚡ GATILHO AUTOMÁTICO (${qtdMes} Atrasos no Mês): Termo de Ciência emitido e Pauta Obrigatória incluída na Tutoria de ${st.nome}!`, "warning");
            }

            window.emitirTermoCienciaFrequenciaGatilho(raStr, qtdMes);
            return true;
          }
        }
        return false;
      };

      // Função de Consolidação do Master Feed Global de Ocorrências / Registros (Otimizada O(N + M))
      window.consolidarHistoricoOcorrenciasGlobais = function() {
        if (!window.allStudentsData || !Array.isArray(window.allStudentsData)) {
          window.ocorrenciasCache = [];
          return [];
        }

        const feedGlobal = [];
        const seenIds = new Set();
        const seenSignatures = new Set();

        const studentByRaMap = new Map();
        (window.allStudentsData || []).forEach(s => {
          if (!s) return;
          const sRa = String(s.ra || s.id || "").trim();
          const cleanRa = sRa.replace(/\D/g, "");
          if (sRa) studentByRaMap.set(sRa, s);
          if (cleanRa) studentByRaMap.set(cleanRa, s);
        });

        const obterAssinaturaOcorrencia = (oc, raFallback) => {
          if (!oc) return "";
          const ra = String(oc.ra || raFallback || "").replace(/\D/g, "");
          const rawDate = String(oc.data || oc.dataRegistro || oc.createdAt || "");
          const dateDay = rawDate.length >= 10 ? rawDate.substring(0, 10) : rawDate;
          const desc = String(oc.descricao || oc.observacao || "").trim().toLowerCase().replace(/\s+/g, " ");
          return `${ra}|${dateDay}|${desc}`;
        };

        // 1. Prioridade para registros top-level da coleção 'ocorrencias'
        if (Array.isArray(window.ocorrenciasTopLevel)) {
          window.ocorrenciasTopLevel.forEach((oc, idx) => {
            if (!oc) return;
            const ocId = oc.id ? String(oc.id).trim() : (oc._id ? String(oc._id).trim() : "");
            if (ocId && seenIds.has(ocId)) return;

            const raKey = String(oc.ra || "").trim();
            const cleanRa = raKey.replace(/\D/g, "");
            const sig = obterAssinaturaOcorrencia(oc, cleanRa);
            if (sig && seenSignatures.has(sig)) return;

            const st = studentByRaMap.get(raKey) || (cleanRa ? studentByRaMap.get(cleanRa) : null);

            const ocFormatada = {
              ...oc,
              id: ocId || `oc_top_${cleanRa}_${idx}`,
              ra: raKey || (st ? String(st.ra || st.id || "").trim() : ""),
              nomeAluno: oc.nomeAluno ? oc.nomeAluno.toUpperCase() : (st?.nome || "ALUNO SEM NOME").toUpperCase(),
              turma: oc.turma ? oc.turma.toUpperCase() : (st?.turma || "").toUpperCase()
            };

            feedGlobal.push(ocFormatada);
            if (ocFormatada.id) seenIds.add(ocFormatada.id);
            if (sig) seenSignatures.add(sig);
          });
        }

        // 2. Extrai e mescla ocorrências embutidas em cada aluno no allStudentsData
        (window.allStudentsData || []).forEach(aluno => {
          const nomeAlunoStr = (aluno.nome || "ALUNO SEM NOME").toUpperCase();
          const raAlunoStr = String(aluno.ra || aluno.id || "").trim();
          const cleanRa = raAlunoStr.replace(/\D/g, "");
          const turmaAlunoStr = (aluno.turma || "").toUpperCase();

          const rawArr = Array.isArray(aluno.ocorrencias)
            ? aluno.ocorrencias
            : (Array.isArray(aluno.registros) ? aluno.registros : []);

          for (let idx = 0; idx < rawArr.length; idx++) {
            const oc = rawArr[idx];
            if (!oc || oc.tipoContato || oc.houveResposta) continue;

            const ocId = oc.id ? String(oc.id).trim() : (oc._id ? String(oc._id).trim() : "");
            if (ocId && seenIds.has(ocId)) continue;

            const sig = obterAssinaturaOcorrencia(oc, cleanRa);
            if (sig && seenSignatures.has(sig)) continue;

            const novoId = ocId || `oc_${cleanRa || raAlunoStr}_${idx}`;
            const ocFormatada = {
              ...oc,
              id: novoId,
              ra: oc.ra ? String(oc.ra).trim() : raAlunoStr,
              nomeAluno: oc.nomeAluno ? oc.nomeAluno.toUpperCase() : nomeAlunoStr,
              turma: oc.turma ? oc.turma.toUpperCase() : turmaAlunoStr
            };

            feedGlobal.push(ocFormatada);
            seenIds.add(novoId);
            if (sig) seenSignatures.add(sig);
          }
        });

        // 3. Ordenação Cronológica Estrita (Mais recente para mais antigo)
        feedGlobal.sort((a, b) => new Date(b.data || b.createdAt || 0) - new Date(a.data || a.createdAt || 0));

        // 4. Contabiliza reincidência e agrupa por RA em O(M) sem loops aninhados
        const countMap = {};
        const ocorrenciasByRaMap = new Map();

        feedGlobal.forEach(oc => {
          const raKey = String(oc.ra || "").trim();
          const cleanRa = raKey.replace(/\D/g, "");
          if (raKey) {
            countMap[raKey] = (countMap[raKey] || 0) + 1;
          }
          const mapKey = cleanRa || raKey;
          if (mapKey) {
            if (!ocorrenciasByRaMap.has(mapKey)) ocorrenciasByRaMap.set(mapKey, []);
            ocorrenciasByRaMap.get(mapKey).push(oc);
          }
        });

        feedGlobal.forEach(oc => {
          const raKey = String(oc.ra || "").trim();
          oc.reincidencia = countMap[raKey] || 1;
        });

        window.ocorrenciasCache = feedGlobal;

        // Sincroniza array de ocorrências em cada objeto de estudante em O(N)
        (window.allStudentsData || []).forEach(s => {
          const raKey = String(s.ra || s.id || "").trim();
          const cleanRa = raKey.replace(/\D/g, "");
          s.ocorrencias = ocorrenciasByRaMap.get(cleanRa || raKey) || [];
        });

        // 5. Atualiza a UI do Módulo Ocorrências e Dashboard de Atrasos
        if (typeof atualizarSelectTurmasFiltroOcorrencias === "function") {
          atualizarSelectTurmasFiltroOcorrencias();
        }
        if (typeof window.filtrarHistoricoOcorrencias === "function") {
          window.filtrarHistoricoOcorrencias();
        } else if (typeof renderHistoricoOcorrencias === "function") {
          renderHistoricoOcorrencias(window.ocorrenciasCache || []);
        }
        if (typeof renderAlunosReincidentesWidget === "function") {
          renderAlunosReincidentesWidget(countMap, window.ocorrenciasCache || []);
        }
        if (typeof window.atualizarDashboardAtrasos === "function") {
          const containerDashAtrasos = document.getElementById("content-dashboard-atrasos");
          if (containerDashAtrasos && !containerDashAtrasos.classList.contains("hidden")) {
            window.atualizarDashboardAtrasos();
          }
        }

        window.dispatchEvent(new CustomEvent("clovis_ocorrencias_updated"));
        return (window.ocorrenciasCache || []);
      };

      async function carregarHistoricoOcorrenciasGeral() {
        if (!window.allStudentsData || (window.allStudentsData || []).length === 0) {
          try {
            const snap = await getDocs(collection(db, "alunos"));
            const novosAlunos = [];
            snap.forEach(docSnap => {
              const al = docSnap.data();
              if (!al.ra) al.ra = docSnap.id;
              novosAlunos.push(al);
            });
            window.allStudentsData = novosAlunos;
          } catch (err) {
            console.error("Erro ao carregar coleção de alunos para histórico:", err);
          }
        }
        if (!window.ocorrenciasTopLevel || (window.ocorrenciasTopLevel || []).length === 0) {
          try {
            const snapOc = await getDocs(collection(db, "ocorrencias"));
            const ocIniciais = [];
            snapOc.forEach(docSnap => {
              ocIniciais.push({ id: docSnap.id, ...docSnap.data() });
            });
            window.ocorrenciasTopLevel = ocIniciais;
          } catch (_errOc) {
            console.warn("Não foi possível carregar ocorrências em carregarHistoricoOcorrenciasGeral:", _errOc);
          }
        }
        return window.consolidarHistoricoOcorrenciasGlobais();
      }

      window.carregarHistoricoOcorrenciasGeral = carregarHistoricoOcorrenciasGeral;

      // Navegação direta do Módulo de Registros/Ocorrências para o Módulo Alunos com Ficha Expandida
      window.navegarEAbrirFichaAluno = function(raTarget) {
        if (!raTarget) return;
        const targetRaStr = String(raTarget).trim();
        const cleanTargetRa = targetRaStr.replace(/\D/g, "");

        // 1. Localizar estudante no estado global
        let alunoObj = ((window.allStudentsData || [])).find(s => {
          const sRa = String(s.ra || s.id || "").trim();
          return sRa === targetRaStr || (cleanTargetRa && sRa.replace(/\D/g, "") === cleanTargetRa);
        });

        // 2. Setar o aluno na busca do Módulo Alunos para filtrar na tabela
        const searchInput = document.getElementById("searchStudent");
        if (searchInput) {
          searchInput.value = alunoObj ? (alunoObj.nome || targetRaStr) : targetRaStr;
          if (typeof window.applyStudentFilters === "function") {
            window.applyStudentFilters();
          } else if (typeof window.filterStudents === "function") {
            window.filterStudents();
          }
        }

        // 3. Alterar a aba/tela ativa do sistema para o Módulo Alunos
        if (typeof window.switchTab === "function") {
          window.switchTab("alunos");
        } else if (typeof window.mostrarAba === "function") {
          window.mostrarAba("alunos");
        }

        // 4. Setar o aluno clicado como selecionado e abrir Ficha / Dossiê do estudante
        const finalRa = alunoObj ? alunoObj.ra : targetRaStr;
        if (typeof window.abrirFichaAluno === "function") {
          window.abrirFichaAluno(finalRa);
        } else if (typeof window.abrirModalFichaAluno === "function") {
          window.abrirModalFichaAluno(finalRa);
        }
      };

      // Marcar Ciência do Responsável de Forma Rápida
      window.marcarCienciaRapida = async function(id) {
        if (!id) return;
        const oc = ((window.ocorrenciasCache || [])).find(i => i.id === id);
        if (!oc) return;

        const hoje = new Date().toISOString().split('T')[0];

        try {
          try {
            await updateDoc(doc(db, "ocorrencias", id), {
              cienciaResponsavel: true,
              dataCiencia: hoje,
              data_atualizacao: new Date().toISOString()
            });
          } catch (eDoc) {}

          oc.cienciaResponsavel = true;
          oc.dataCiencia = hoje;

          const raKey = String(oc.ra || "").trim();
          const st = ((window.allStudentsData || [])).find(s => String(s.ra || "").trim() === raKey);
          if (st && Array.isArray(st.ocorrencias)) {
            const targetOc = st.ocorrencias.find(item => item.id === id || (item.data === oc.data && item.descricao === oc.descricao));
            if (targetOc) {
              targetOc.cienciaResponsavel = true;
              targetOc.dataCiencia = hoje;
              await updateDoc(doc(db, "alunos", String(st.ra)), {
                ocorrencias: st.ocorrencias
              });
            }
          }

          window.showToast("Ciência do responsável registrada com sucesso!", 'success');
          if (typeof window.registrarLogAuditoria === "function") {
            window.registrarLogAuditoria({
              modulo: "Registros / Ocorrências",
              acao: "ATUALIZAR",
              descricao: `Registrada ciência do responsável no registro de ocorrência (ID: ${id})`,
              detalhes: { id, dataCiencia: hoje }
            });
          }
          window.consolidarHistoricoOcorrenciasGlobais();
        } catch (err) {
          console.error("Erro ao registrar ciência do responsável:", err);
          window.showErrorToast("Erro ao atualizar ciência do responsável.", err);
        }
      };

      // Vincular Registro CONVIVA SP de Forma Rápida
      window.vincularConvivaRapido = async function(id) {
        if (!id) return;
        const oc = ((window.ocorrenciasCache || [])).find(i => i.id === id);
        if (!oc) return;

        const cod = prompt("Digite o Código / Protocolo CONVIVA SP para este registro disciplinar:", oc.codigoConviva || "CNV-2026-");
        if (cod === null) return;

        const codFmt = cod.trim().toUpperCase();
        const isDisciplinar = String(oc.tipo || "").toUpperCase().includes("DISCIPLINAR");
        const novoTipo = isDisciplinar ? oc.tipo : "Questão Disciplinar";

        try {
          try {
            await updateDoc(doc(db, "ocorrencias", id), {
              tipo: novoTipo,
              registradoConviva: true,
              codigoConviva: codFmt,
              protocoloConviva: codFmt,
              data_atualizacao: new Date().toISOString()
            });
          } catch (eDoc) {}

          oc.tipo = novoTipo;
          oc.registradoConviva = true;
          oc.codigoConviva = codFmt;
          oc.protocoloConviva = codFmt;

          const raKey = String(oc.ra || "").trim();
          const st = ((window.allStudentsData || [])).find(s => String(s.ra || "").trim() === raKey);
          if (st && Array.isArray(st.ocorrencias)) {
            const targetOc = st.ocorrencias.find(item => item.id === id || (item.data === oc.data && item.descricao === oc.descricao));
            if (targetOc) {
              targetOc.tipo = novoTipo;
              targetOc.registradoConviva = true;
              targetOc.codigoConviva = codFmt;
              targetOc.protocoloConviva = codFmt;
              await updateDoc(doc(db, "alunos", String(st.ra)), {
                ocorrencias: st.ocorrencias
              });
            }
          }

          window.showToast("Registro CONVIVA SP vinculado com sucesso!", 'success');
          if (typeof window.registrarLogAuditoria === "function") {
            window.registrarLogAuditoria({
              modulo: "Registros / Ocorrências",
              acao: "ATUALIZAR",
              descricao: `Vinculado código CONVIVA SP (${codFmt}) no registro de ocorrência (ID: ${id})`,
              detalhes: { id, codigoConviva: codFmt }
            });
          }
          window.consolidarHistoricoOcorrenciasGlobais();
        } catch (err) {
          console.error("Erro ao vincular CONVIVA SP:", err);
          window.showErrorToast("Erro ao salvar vínculo do CONVIVA SP.", err);
        }
      };

      window.limiteRenderHistoricoOcorrencias = 60;
      window._ultimaListaHistoricoOcorrencias = [];

      window.carregarMaisHistoricoOcorrencias = function(mostrarTodos) {
        if (mostrarTodos) {
          window.limiteRenderHistoricoOcorrencias = 99999;
        } else {
          window.limiteRenderHistoricoOcorrencias = (window.limiteRenderHistoricoOcorrencias || 60) + 100;
        }
        renderHistoricoOcorrencias(window._ultimaListaHistoricoOcorrencias || window.ocorrenciasCache || []);
      };

      function renderHistoricoOcorrencias(lista) {
        if (!tabelaHistoricoBody) return;
        window._ultimaListaHistoricoOcorrencias = lista || [];

        if (!lista || lista.length === 0) {
          tabelaHistoricoBody.innerHTML = window.getMascoteSaraEmptyStateHtml('Nenhuma ocorrência ou registro localizado!', 'Sua escola está com o ambiente tranquilo ou ajuste a busca por aluno/turma.', 10);
          return;
        }

        const limite = window.limiteRenderHistoricoOcorrencias || 60;
        const totalRegistros = lista.length;
        const fatiaRender = lista.slice(0, limite);

        let html = "";
        fatiaRender.forEach(oc => {
          const dataFmt = oc.data ? new Date(oc.data).toLocaleString("pt-BR") : "-";
          const nome = (oc.nomeAluno || "ALUNO SEM NOME").toUpperCase();
          const ra = oc.ra || "-";
          const turma = (oc.turma || "-").toUpperCase();
          const tipo = (oc.tipo || "Tutoria e Acolhimento").toUpperCase();
          const desc = oc.descricao || oc.observacao || "-";
          const rawAutor = oc.usuario || oc.autor || oc.registradoPor || "";
          const usuario = window.formatarAutorOcorrencia ? window.formatarAutorOcorrencia(rawAutor, oc) : (rawAutor || "Usuário Registrado");
          const countReinc = oc.reincidencia || 1;

          let tipoTag = "bg-blue-50 text-blue-700 border-blue-200";
          const isDispensaRow = typeof window.isOcorrenciaDispensa === "function" ? window.isOcorrenciaDispensa(oc) : (tipo.includes("DISPENSA") && Boolean(oc.dataInicio || oc.dataFim));
          if (isDispensaRow) tipoTag = "bg-blue-100 text-blue-900 border-blue-300 font-black";
          else if (tipo.includes("DISCIPLINAR")) tipoTag = "bg-red-50 text-red-700 border-red-200";
          else if (tipo.includes("ATRASO")) tipoTag = "bg-amber-50 text-amber-800 border-amber-200 font-bold";
          else if (tipo.includes("WHATSAPP") || tipo.includes("LIGAÇÃO")) tipoTag = "bg-emerald-50 text-emerald-700 border-emerald-200";

          const dispensaPeriodoHtml = isDispensaRow && oc.dataInicio && oc.dataFim
            ? `<div class="mt-1 text-[10px] font-extrabold text-blue-800"><i class="fa-solid fa-calendar-check mr-1"></i>${String(oc.dataInicio).split('-').reverse().join('/')} a ${String(oc.dataFim).split('-').reverse().join('/')}</div>`
            : "";

          const rowBg = countReinc > 1 ? "bg-amber-50 hover:bg-amber-100/60" : "hover:bg-slate-50";
          const reincBadge = countReinc > 1 
            ? `<span class="ml-1 px-1.5 py-0.5 bg-amber-100 text-amber-900 border border-amber-300 font-black text-[9px] rounded uppercase tracking-wider shrink-0">⚠️ ${countReinc}x</span>` 
            : "";

          // Badge Ciência
          const isCiencia = oc.cienciaResponsavel || oc.ciencia_responsavel;
          const dtCienciaFmt = oc.dataCiencia ? (oc.dataCiencia.includes('-') ? oc.dataCiencia.split('-').reverse().join('/') : oc.dataCiencia) : '';
          const htmlCiencia = isCiencia
            ? `<span class="px-2 py-0.5 bg-emerald-50 text-emerald-800 border border-emerald-300 font-bold rounded text-[10px] inline-flex items-center gap-1 shadow-2xs" title="Ciência em ${dtCienciaFmt}"><i class="fa-solid fa-user-check text-emerald-600"></i> Ciente (${dtCienciaFmt || 'Sim'})</span>`
            : `<button type="button" onclick="window.marcarCienciaRapida('${oc.id}')" class="px-2 py-0.5 bg-amber-100 hover:bg-amber-200 text-amber-900 border border-amber-300 font-bold rounded text-[10px] transition cursor-pointer inline-flex items-center gap-1 shadow-2xs" title="Clique para registrar ciência da família"><i class="fa-solid fa-clock text-amber-700"></i> + Ciência</button>`;

          // Badge e Botão CONVIVA SP (Apenas para Questões Disciplinares)
          const isConviva = Boolean(
            oc.protocoloConviva || 
            oc.codigoConviva || 
            oc.codigo_conviva || 
            oc.registradoConviva || 
            oc.registrado_conviva || 
            oc.isConviva || 
            oc.conviva || 
            (oc.tags && Array.isArray(oc.tags) && oc.tags.includes('CONVIVA')) ||
            (oc.tipo && String(oc.tipo).toUpperCase().includes("CONVIVA")) ||
            (oc.categoria && String(oc.categoria).toUpperCase().includes("CONVIVA"))
          );
          const isDisciplinarRow = String(oc.tipo || "").toUpperCase().includes("DISCIPLINAR") || isConviva;
          const codConviva = oc.protocoloConviva || oc.codigoConviva || oc.codigo_conviva || oc.conviva || '';

          const btnConvivaClass = isConviva
            ? "px-2 py-0.5 bg-green-100 hover:bg-green-200 text-green-800 border border-green-500 font-bold rounded text-[10px] inline-flex items-center gap-1 shadow-2xs transition cursor-pointer uppercase"
            : "px-2 py-0.5 bg-slate-100 hover:bg-slate-200 text-slate-700 border border-slate-300 font-bold rounded text-[10px] inline-flex items-center gap-1 shadow-2xs transition cursor-pointer uppercase";

          const htmlConviva = isDisciplinarRow
            ? (isConviva
                ? `<div class="flex items-center gap-1.5 flex-wrap">
                    <span class="px-2 py-0.5 bg-purple-100 text-purple-900 border border-purple-300 font-extrabold rounded text-[10px] inline-flex items-center gap-1 shadow-2xs" title="Registrado no CONVIVA SP"><i class="fa-solid fa-shield-halved text-purple-700"></i> ${codConviva ? '#' + codConviva : 'CONVIVA'}</span>
                    <button type="button" onclick="window.vincularConvivaRapido('${oc.id}')" class="${btnConvivaClass}" title="Registro CONVIVA ativo - Clique para alterar protocolo"><i class="fa-solid fa-shield-halved text-green-700 text-[9px]"></i> + CONVIVA</button>
                   </div>`
                : `<div class="flex items-center gap-1.5 flex-wrap">
                    <span class="px-1.5 py-0.5 bg-slate-100 text-slate-600 border border-slate-300 font-bold rounded text-[9px] inline-flex items-center gap-1 uppercase" title="Registro Salvo Exclusivamente no Histórico Interno"><i class="fa-solid fa-lock text-slate-400"></i> INTERNO</span>
                    <button type="button" onclick="window.vincularConvivaRapido('${oc.id}')" class="${btnConvivaClass}" title="Vincular código CONVIVA SP"><i class="fa-solid fa-plus text-[8px]"></i> + CONVIVA</button>
                   </div>`)
            : `<span class="text-[10px] text-slate-400 italic font-medium">N/A (Pedagógico)</span>`;

          const roleAtual = window.obterRoleAtual ? window.obterRoleAtual() : "PROFESSOR";
          const podeEditarOcorrencia = (typeof window.podeEditarSensivel === "function" ? window.podeEditarSensivel() : true);

          const btnEditarHtml = podeEditarOcorrencia ? `
            <button 
              type="button"
              onclick="window.abrirModalEditarOcorrencia('${oc.id}')"
              class="px-2 py-1 bg-amber-100 hover:bg-amber-200 text-amber-800 font-bold rounded text-[11px] transition cursor-pointer inline-flex items-center gap-1 shadow-2xs mr-1"
              title="Editar Ocorrência"
            >
              <i class="fa-solid fa-pen-to-square text-[10px]"></i>
              <span>Editar</span>
            </button>
          ` : "";

          html += `
            <tr class="${rowBg} transition-colors">
              <td class="px-3.5 py-3 font-mono text-[11px] text-slate-500 whitespace-nowrap">${dataFmt}</td>
              <td class="px-3.5 py-3 font-bold text-slate-800 flex items-center flex-wrap gap-1">
                <button 
                  type="button" 
                  onclick="window.navegarEAbrirFichaAluno('${oc.ra || ra}')" 
                  class="cursor-pointer text-blue-600 hover:text-blue-800 hover:underline font-semibold text-left transition-colors"
                  title="Clique para abrir a ficha do aluno no Módulo Alunos"
                >
                  ${nome}
                </button>
                ${reincBadge}
              </td>
              <td class="px-3.5 py-3 font-mono text-slate-600">${ra}</td>
              <td class="px-3.5 py-3 font-semibold text-slate-700">${turma}</td>
              <td class="px-3.5 py-3">
                <span class="px-2 py-0.5 ${tipoTag} border rounded text-[10px] font-bold uppercase tracking-wider inline-block">
                  ${tipo}
                </span>
                ${dispensaPeriodoHtml}
              </td>
              <td class="px-3.5 py-3 text-slate-600 max-w-xs truncate" title="${desc.replace(/"/g, '&quot;')}">${desc}</td>
              <td class="px-3.5 py-3 whitespace-nowrap">${htmlCiencia}</td>
              <td class="px-3.5 py-3 whitespace-nowrap">${htmlConviva}</td>
              <td class="px-3.5 py-3 text-slate-500 text-[11px]">${usuario}</td>
              <td class="px-3.5 py-3 text-right whitespace-nowrap">
                ${btnEditarHtml}
                <button 
                  type="button"
                  data-action="excluir"
                  data-collection="ocorrencias"
                  data-id="${oc.id}"
                  onclick="window.deletarRegistroUniversal('ocorrencias', '${oc.id}')"
                  class="px-2 py-1 bg-red-100 hover:bg-red-200 text-red-700 font-bold rounded text-[11px] transition cursor-pointer inline-flex items-center gap-1 shadow-2xs"
                  title="Excluir Ocorrência"
                >
                  <i class="fa-solid fa-trash-can text-[10px]"></i>
                  <span>Excluir</span>
                </button>
              </td>
            </tr>
          `;
        });

        if (totalRegistros > limite) {
          const restantes = totalRegistros - limite;
          html += `
            <tr class="bg-slate-50 border-t border-slate-200">
              <td colspan="10" class="px-4 py-3 text-center">
                <div class="flex items-center justify-center gap-3 flex-wrap">
                  <span class="text-xs font-bold text-slate-600">
                    Exibindo <strong>${fatiaRender.length}</strong> de <strong>${totalRegistros}</strong> registros
                  </span>
                  <button
                    type="button"
                    onclick="window.carregarMaisHistoricoOcorrencias(false)"
                    class="px-3.5 py-1.5 bg-blue-600 hover:bg-blue-700 text-white font-extrabold rounded-lg text-xs transition cursor-pointer shadow-2xs"
                  >
                    <i class="fa-solid fa-plus mr-1"></i> Carregar +100 (${restantes} restantes)
                  </button>
                  <button
                    type="button"
                    onclick="window.carregarMaisHistoricoOcorrencias(true)"
                    class="px-3 py-1.5 bg-slate-200 hover:bg-slate-300 text-slate-700 font-bold rounded-lg text-xs transition cursor-pointer"
                  >
                    Mostrar Todos (${totalRegistros})
                  </button>
                </div>
              </td>
            </tr>
          `;
        }

        tabelaHistoricoBody.innerHTML = html;
      }

      // =========================================================
      // LÓGICA DE ABAS DO MÓDULO DE REGISTROS (TODOS vs DISCIPLINA vs ATRASO vs ROTINA/PEDAGÓGICO)
      // =========================================================
      window.abaAtivaRegistros = 'todos';

      window.setAbaAtivaRegistros = function(aba) {
        const isPerfilPedagogico = typeof window.checarIsPerfilPedagogico === "function" ? window.checarIsPerfilPedagogico() : false;
        if (isPerfilPedagogico) {
          window.abaAtivaRegistros = 'rotina';
        } else {
          window.abaAtivaRegistros = aba || 'todos';
        }

        const btnTodos = document.getElementById("tab-registros-todos");
        const btnDisciplina = document.getElementById("tab-registros-disciplina");
        const btnAtraso = document.getElementById("tab-registros-atraso");
        const btnRotina = document.getElementById("tab-registros-rotina");

        const activeClass = "px-4 py-2 rounded-lg text-xs font-bold transition cursor-pointer flex items-center gap-2 bg-white text-indigo-900 border border-indigo-200 shadow-2xs";
        const inactiveClass = "px-4 py-2 rounded-lg text-xs font-bold transition cursor-pointer flex items-center gap-2 bg-transparent text-slate-600 hover:bg-slate-200 border border-transparent";

        if (isPerfilPedagogico) {
          if (btnTodos) btnTodos.classList.add("hidden");
          if (btnDisciplina) btnDisciplina.classList.add("hidden");
          if (btnAtraso) btnAtraso.classList.add("hidden");
          if (btnRotina) btnRotina.classList.remove("hidden");
        } else {
          if (btnTodos) btnTodos.classList.remove("hidden");
          if (btnDisciplina) btnDisciplina.classList.remove("hidden");
          if (btnAtraso) btnAtraso.classList.remove("hidden");
          if (btnRotina) btnRotina.classList.remove("hidden");
        }

        if (btnTodos) btnTodos.className = window.abaAtivaRegistros === 'todos' ? activeClass : inactiveClass;
        if (btnDisciplina) btnDisciplina.className = window.abaAtivaRegistros === 'disciplina' ? activeClass : inactiveClass;
        if (btnAtraso) btnAtraso.className = window.abaAtivaRegistros === 'atraso' ? activeClass : inactiveClass;
        if (btnRotina) btnRotina.className = window.abaAtivaRegistros === 'rotina' ? activeClass : inactiveClass;

        window.filtrarHistoricoOcorrencias();
      };

      window.isOcorrenciaAtraso = function(oc) {
        if (!oc) return false;
        if (typeof window.isOcorrenciaDispensa === "function" && window.isOcorrenciaDispensa(oc)) return false;
        const tipoStr = String(oc?.tipo || "").toUpperCase();
        const catStr = String(oc?.categoria || "").toUpperCase();
        const descStr = String(oc?.descricao || "").toUpperCase();
        return oc?.isAtraso === true || tipoStr.includes("ATRASO") || catStr.includes("ATRASO") || descStr.startsWith("ATRASO");
      };

      window.isOcorrenciaDisciplinarOuConviva = function(oc) {
        if (!oc) return false;
        if (window.isOcorrenciaAtraso(oc)) return false;

        const isConviva = Boolean(
          oc?.protocoloConviva || 
          oc?.codigoConviva || 
          oc?.codigo_conviva || 
          oc?.registradoConviva || 
          oc?.registrado_conviva || 
          oc?.isConviva || 
          oc?.conviva || 
          (oc?.tags && Array.isArray(oc.tags) && oc.tags.includes('CONVIVA')) ||
          (oc?.tipo && String(oc.tipo).toUpperCase().includes("CONVIVA")) ||
          (oc?.categoria && String(oc.categoria).toUpperCase().includes("CONVIVA"))
        );

        if (isConviva) return true;

        const tipoStr = String(oc?.tipo || "").toUpperCase();
        const catStr = String(oc?.categoria || "").toUpperCase();
        const descStr = String(oc?.descricao || "").toUpperCase();

        const isDisciplinar = tipoStr.includes("DISCIPLINAR") ||
                              tipoStr.includes("NEGATIVA") ||
                              tipoStr.includes("SUSPENSÃO") ||
                              tipoStr.includes("ADVERTÊNCIA") ||
                              catStr.includes("DISCIPLINAR") ||
                              catStr.includes("NEGATIVA") ||
                              descStr.includes("AÇÃO DISCIPLINAR") ||
                              descStr.includes("QUESTÃO DISCIPLINAR");

        return isDisciplinar;
      };

      // Função de filtro no frontend para a tabela do histórico de ocorrências
      window.filtrarHistoricoOcorrencias = function() {
        const isPerfilPedagogico = typeof window.checarIsPerfilPedagogico === "function" ? window.checarIsPerfilPedagogico() : false;
        if (isPerfilPedagogico) {
          window.abaAtivaRegistros = 'rotina';
        }

        const inputSearch = document.getElementById("inputSearchHistorico") || 
                            document.getElementById("search-ocorrencia-input") || 
                            document.getElementById("search-historico-ocorrencias");
        const queryText = (inputSearch ? inputSearch.value : "").trim().toLowerCase();

        const filterTurmaEl = document.getElementById("filter-historico-turma");
        const filtroTurmaRaw = (filterTurmaEl ? filterTurmaEl.value : "").trim();
        const selTurmaUpper = filtroTurmaRaw.toUpperCase();

        const filterTipoEl = document.getElementById("filter-historico-tipo");
        const selTipo = (filterTipoEl ? filterTipoEl.value : "Todos").trim();

        const filterConvivaEl = document.getElementById("filter-historico-conviva");
        const selConviva = (filterConvivaEl ? filterConvivaEl.value : "").trim();

        const filterCienciaEl = document.getElementById("filter-historico-ciencia");
        const selCiencia = (filterCienciaEl ? filterCienciaEl.value : "").trim();

        const ocorrenciasGlobaisRaw = (window.ocorrenciasCache || []);

        // Supressão de Dados na Fonte: Perfis pedagógicos (CGPG, PAAC, PROFESSOR) veem Tutoria e Pedagógica; CGPG também vê Dispensa / Afastamento Legal
        const podeVerDispensa = typeof window.podeRegistrarDispensa === "function" ? window.podeRegistrarDispensa() : false;
        const ocorrenciasGlobais = (ocorrenciasGlobaisRaw || []).filter(registro => {
          if (!registro) return false;
          if (!isPerfilPedagogico) return true; // Diretor, Vice e Secretaria veem tudo
          const tipo = (registro.tipo || registro.categoria || registro.descricao || '').toUpperCase();
          if (podeVerDispensa && (registro.isDispensa === true || tipo.includes('DISPENSA') || tipo.includes('AFASTAMENTO'))) {
            return true;
          }
          return tipo.includes('TUTORIA') || tipo.includes('PEDAGÓGICA') || tipo.includes('PEDAGOGICA');
        });

        const isAtrasoFn = typeof window.isOcorrenciaAtraso === "function" 
          ? window.isOcorrenciaAtraso 
          : (oc) => String(oc?.tipo || oc?.categoria || oc?.descricao || '').toUpperCase().includes('ATRASO');

        const isDiscOrConvivaFn = typeof window.isOcorrenciaDisciplinarOuConviva === "function" 
          ? window.isOcorrenciaDisciplinarOuConviva 
          : (oc) => !isAtrasoFn(oc) && String(oc?.tipo || oc?.categoria || oc?.descricao || '').toUpperCase().includes('DISCIPLINAR');

        const comFiltrosGlobais = (ocorrenciasGlobais || []).filter(oc => {
          if (!oc) return false;

          const textFull = `${oc?.nomeAluno || ''} ${oc?.ra || ''} ${oc?.turma || ''} ${oc?.tipo || ''} ${oc?.categoria || ''} ${oc?.descricao || ''} ${oc?.observacao || ''} ${oc?.motivoDispensa || ''} ${oc?.codigoConviva || ''} ${oc?.protocoloConviva || ''} ${oc?.usuario || ''} ${oc?.autor || ''} ${oc?.autor_nome || ''}`.toLowerCase();
          if (queryText && !textFull.includes(queryText)) return false;

          // Filtro por Turma com normalização de tokens (ex: "6A" casa com "6º ANO A")
          const ocTurma = String(oc?.turma || "").trim();
          const isTodasTurmas = !filtroTurmaRaw || 
                                selTurmaUpper === "" || 
                                selTurmaUpper.includes("TODAS");

          if (!isTodasTurmas) {
            const tokenSel = selTurmaUpper.replace(/[^0-9A-Z]/g, '');
            const tokenOc = ocTurma.toUpperCase().replace(/[^0-9A-Z]/g, '');
            if (tokenSel !== tokenOc && !ocTurma.toUpperCase().includes(selTurmaUpper) && !selTurmaUpper.includes(ocTurma.toUpperCase())) {
              return false;
            }
          }

          const isConviva = Boolean(
            oc?.protocoloConviva ||
            oc?.codigoConviva ||
            oc?.codigo_conviva ||
            oc?.registradoConviva || 
            oc?.registrado_conviva || 
            oc?.isConviva || 
            oc?.conviva ||
            (oc?.tags && Array.isArray(oc.tags) && oc.tags.includes('CONVIVA')) ||
            (oc?.tipo && String(oc.tipo).toUpperCase().includes("CONVIVA")) ||
            (oc?.categoria && String(oc.categoria).toUpperCase().includes("CONVIVA"))
          );

          if (selTipo && selTipo !== "Todos" && selTipo !== "") {
            const selTipoUpper = selTipo.toUpperCase();
            const ocTipo = String(oc?.tipo || "").toUpperCase();
            const ocCat = String(oc?.categoria || "").toUpperCase();
            const ocDesc = String(oc?.descricao || "").toUpperCase();

            if (selTipoUpper.includes("PEDAGÓGICA") || selTipoUpper.includes("PEDAGOGICA")) {
              if (!ocTipo.includes("PEDAG") && !ocCat.includes("PEDAG") && !ocDesc.includes("PEDAG")) return false;
            } else if (selTipoUpper.includes("DISCIPLINAR")) {
              if (!ocTipo.includes("DISCIPLINAR") && !ocCat.includes("DISCIPLINAR") && !ocDesc.includes("DISCIPLINAR")) return false;
            } else if (selTipoUpper.includes("TUTORIA") || selTipoUpper.includes("ACOLHIMENTO")) {
              if (!ocTipo.includes("TUTORIA") && !ocTipo.includes("ACOLHIMENTO") && !ocCat.includes("TUTORIA") && !ocDesc.includes("TUTORIA")) return false;
            } else if (selTipoUpper.includes("ATRASO")) {
              if (!isAtrasoFn(oc)) return false;
            } else if (selTipoUpper.includes("DISPENSA")) {
              if (!(oc?.isDispensa === true || ocTipo.includes("DISPENSA") || ocCat.includes("DISPENSA"))) return false;
            } else if (selTipoUpper === "CONVIVA") {
              if (!isConviva) return false;
            } else if (selTipoUpper === "POSITIVA") {
              const isPositiva = ocTipo.includes("POSITIVA") || ocTipo.includes("ELOGIO") || ocTipo.includes("TUTORIA") || ocTipo.includes("ACOLHIMENTO") || ocDesc.includes("ELOGIO") || ocDesc.includes("DESTAQUE");
              if (!isPositiva) return false;
            } else if (selTipoUpper === "NEGATIVA") {
              const isNegativa = ocTipo.includes("NEGATIVA") || ocTipo.includes("DISCIPLINAR") || ocTipo.includes("ATRASO") || ocTipo.includes("SUSPENSÃO") || ocDesc.includes("DISCIPLINAR");
              if (!isNegativa) return false;
            } else {
              if (!ocTipo.includes(selTipoUpper) && !ocCat.includes(selTipoUpper) && !ocDesc.includes(selTipoUpper)) return false;
            }
          }

          if (selConviva === "sim" && !isConviva) return false;
          if (selConviva === "nao" && isConviva) return false;

          const temCiencia = Boolean(oc?.cienciaResponsavel || oc?.ciencia_responsavel);
          if (selCiencia === "sim" && !temCiencia) return false;
          if (selCiencia === "nao" && temCiencia) return false;

          return true;
        });

        // Contadores Dinâmicos
        const countTodos = (comFiltrosGlobais || []).length;
        const countDisciplina = (comFiltrosGlobais || []).filter(oc => isDiscOrConvivaFn(oc)).length;
        const countAtraso = (comFiltrosGlobais || []).filter(oc => isAtrasoFn(oc)).length;
        const countRotina = (comFiltrosGlobais || []).filter(oc => !isDiscOrConvivaFn(oc) && !isAtrasoFn(oc)).length;

        const badgeTodos = document.getElementById("badge-count-todos");
        const badgeDisciplina = document.getElementById("badge-count-disciplina");
        const badgeAtraso = document.getElementById("badge-count-atraso");
        const badgeRotina = document.getElementById("badge-count-rotina");

        if (badgeTodos) badgeTodos.textContent = String(countTodos);
        if (badgeDisciplina) badgeDisciplina.textContent = String(countDisciplina);
        if (badgeAtraso) badgeAtraso.textContent = String(countAtraso);
        if (badgeRotina) badgeRotina.textContent = String(countRotina);

        const abaAtiva = window.abaAtivaRegistros || 'todos';

        // Se o usuário selecionou uma categoria específica ou se a aba ativa for 'todos', exibe tudo que bateu no filtro
        const temFiltroCategoriaExplicito = selTipo && selTipo !== "Todos" && selTipo !== "";
        const dadosParaRenderizar = (comFiltrosGlobais || []).filter(registro => {
          if (!registro) return false;
          if (temFiltroCategoriaExplicito || abaAtiva === 'todos') {
            return true;
          }
          if (abaAtiva === 'disciplina') {
            return isDiscOrConvivaFn(registro);
          } else if (abaAtiva === 'atraso') {
            return isAtrasoFn(registro);
          } else {
            return !isDiscOrConvivaFn(registro) && !isAtrasoFn(registro);
          }
        });

        if (typeof renderHistoricoOcorrencias === "function") {
          renderHistoricoOcorrencias(dadosParaRenderizar || []);
        } else if (typeof window.renderHistoricoOcorrencias === "function") {
          window.renderHistoricoOcorrencias(dadosParaRenderizar || []);
        }
      };

      // Edição de Ocorrências (Modal Admin - Exclusivo DIRETOR e VICE_DIRETOR)
      window.abrirModalEditarOcorrencia = async function(id) {
        if (!id) return;

        if (window.podeEditarSensivel && !window.podeEditarSensivel()) {
          const msg = "Apenas Diretor e Vice-Diretor possuem permissão para editar registros de ocorrências.";
          if (typeof window.showToast === "function") {
            window.showToast(msg, 'warning', 4000);
          } else {
            alert(msg);
          }
          return;
        }

        let oc = ((window.ocorrenciasCache || [])).find(item => String(item.id) === String(id));

        if (!oc && Array.isArray(window.allStudentsData)) {
          for (const st of window.allStudentsData) {
            const stRa = String(st.ra || st.id || "").trim();
            const arr = Array.isArray(st.ocorrencias) ? st.ocorrencias : (Array.isArray(st.registros) ? st.registros : []);
            for (let idx = 0; idx < arr.length; idx++) {
              const item = arr[idx];
              const genId = `oc_${stRa}_${idx}_${item.data ? new Date(item.data).getTime() : ''}`;
              const embId = `emb_${stRa}_${idx}`;
              if (String(item.id) === String(id) || String(item.docId) === String(id) || genId === id || embId === id) {
                oc = {
                  id: id,
                  ra: stRa,
                  nomeAluno: st.nome,
                  turma: st.turma,
                  ...item
                };
                break;
              }
            }
            if (oc) break;
          }
        }

        if (!oc && Array.isArray(window.ocorrenciasTopLevel)) {
          oc = window.ocorrenciasTopLevel.find(item => String(item.id) === String(id));
        }

        if (!oc && !id.startsWith("emb_") && !id.startsWith("oc_local_")) {
          try {
            const snap = await getDoc(doc(db, "ocorrencias", id));
            if (snap.exists()) {
              oc = { id: snap.id, ...snap.data() };
            }
          } catch (e) {
            console.error("Erro ao buscar ocorrência no Banco de Dados:", e);
          }
        }

        if (!oc) {
          if (typeof window.showToast === "function") {
            window.showToast("Ocorrência não encontrada para edição.", 'warning');
          }
          return;
        }

        const idInput = document.getElementById("edit-ocorrencia-id");
        const infoSpan = document.getElementById("edit-ocorrencia-aluno-info");
        const tipoSelect = document.getElementById("edit-ocorrencia-tipo");
        const descTextarea = document.getElementById("edit-ocorrencia-desc");
        const chkCiencia = document.getElementById("edit-oc-ciencia-responsavel");
        const inputDataCiencia = document.getElementById("edit-oc-data-ciencia");
        const chkConviva = document.getElementById("edit-oc-registrado-conviva");
        const inputCodConviva = document.getElementById("edit-oc-codigo-conviva");

        if (idInput) idInput.value = oc.id;
        if (infoSpan) infoSpan.textContent = `${oc.nomeAluno || 'ALUNO'} (RA: ${oc.ra || '-'} | Turma: ${oc.turma || '-'})`;
        
        if (tipoSelect) {
          window.popularSelectCategoriasOcorrencia(tipoSelect);
          tipoSelect.value = oc.tipo || "Tutoria e Acolhimento";
          if (typeof window.atualizarVisibilidadeDispensaAtraso === "function") {
            window.atualizarVisibilidadeDispensaAtraso(tipoSelect);
          }
          if (typeof window.atualizarVisibilidadeConviva === "function") {
            window.atualizarVisibilidadeConviva(tipoSelect);
          }
        }

        const inpEditDispIni = document.getElementById("edit-oc-dispensa-inicio");
        const inpEditDispFim = document.getElementById("edit-oc-dispensa-fim");
        const selEditDispMot = document.getElementById("edit-oc-dispensa-motivo");
        if (inpEditDispIni) inpEditDispIni.value = oc.dataInicio || "";
        if (inpEditDispFim) inpEditDispFim.value = oc.dataFim || "";
        if (selEditDispMot && oc.motivoDispensa) selEditDispMot.value = oc.motivoDispensa;

        if (descTextarea) descTextarea.value = oc.descricao || oc.observacao || "";

        const isCiencia = Boolean(oc.cienciaResponsavel || oc.ciencia_responsavel);
        if (chkCiencia) chkCiencia.checked = isCiencia;
        if (inputDataCiencia) inputDataCiencia.value = oc.dataCiencia || (isCiencia ? new Date().toISOString().split('T')[0] : "");
        document.getElementById('edit-oc-container-data-ciencia')?.classList.toggle('hidden', !isCiencia);

        const isConviva = Boolean(oc.registradoConviva || oc.registrado_conviva);
        if (chkConviva) chkConviva.checked = isConviva;
        if (inputCodConviva) inputCodConviva.value = oc.codigoConviva || oc.codigo_conviva || "";
        document.getElementById('edit-oc-container-codigo-conviva')?.classList.toggle('hidden', !isConviva);

        const modal = document.getElementById("modal-editar-ocorrencia");
        if (modal) modal.classList.remove("hidden");
      };

      window.fecharModalEditarOcorrencia = function() {
        const modal = document.getElementById("modal-editar-ocorrencia");
        if (modal) modal.classList.add("hidden");
      };

      const formEditOc = document.getElementById("form-modal-editar-ocorrencia");
      if (formEditOc) {
        formEditOc.addEventListener("submit", async (e) => {
          e.preventDefault();
          const id = document.getElementById("edit-ocorrencia-id")?.value;
          const tipo = document.getElementById("edit-ocorrencia-tipo")?.value;
          const descricao = document.getElementById("edit-ocorrencia-desc")?.value;

          const chkCiencia = document.getElementById("edit-oc-ciencia-responsavel")?.checked || false;
          const dataCiencia = chkCiencia ? (document.getElementById("edit-oc-data-ciencia")?.value || new Date().toISOString().split('T')[0]) : "";
          const chkConviva = document.getElementById("edit-oc-registrado-conviva")?.checked || false;
          const codigoConviva = chkConviva ? (document.getElementById("edit-oc-codigo-conviva")?.value.trim().toUpperCase() || "") : "";

          const isDispensaEdit = String(tipo || "").toUpperCase().includes("DISPENSA");
          const editDispIni = isDispensaEdit ? (document.getElementById("edit-oc-dispensa-inicio")?.value || "") : "";
          const editDispFim = isDispensaEdit ? (document.getElementById("edit-oc-dispensa-fim")?.value || "") : "";
          const editDispMot = isDispensaEdit ? (document.getElementById("edit-oc-dispensa-motivo")?.value || "Atestado Médico") : "";

          if (isDispensaEdit) {
            if (typeof window.podeRegistrarDispensa === "function" && !window.podeRegistrarDispensa()) {
              window.showToast("Apenas Secretaria, CGPG, Direção e Vice-Direção podem editar Dispensas.", "error");
              return;
            }
            if (!editDispIni || !editDispFim || editDispFim < editDispIni) {
              window.showToast("Informe um período válido (Data Início <= Data Fim) para a dispensa.", "warning");
              return;
            }
          }

          if (!id || !descricao) return;

          const btnSalvar = document.getElementById("btn-salvar-edit-ocorrencia");
          if (btnSalvar) {
            btnSalvar.disabled = true;
            btnSalvar.innerHTML = `<i class="fa-solid fa-spinner animate-spin text-xs"></i><span>Salvando...</span>`;
          }

          try {
            const userDetails = window.obterIdentificacaoUsuarioCompleta ? window.obterIdentificacaoUsuarioCompleta() : { email: '', nome: '', cargo: '', textoCompleto: '' };
            const diasDispensaCalc = isDispensaEdit
              ? Math.max(1, Math.round((new Date(`${editDispFim}T12:00:00`).getTime() - new Date(`${editDispIni}T12:00:00`).getTime()) / 86400000) + 1)
              : 0;
            const payloadUpdate = {
              tipo: tipo,
              categoria: tipo,
              descricao: descricao,
              observacao: descricao,
              isDispensa: isDispensaEdit,
              cienciaResponsavel: chkCiencia,
              dataCiencia: dataCiencia,
              registradoConviva: chkConviva,
              codigoConviva: codigoConviva,
              data_atualizacao: new Date().toISOString(),
              editado_por_email: userDetails.email || "",
              editado_por_nome: userDetails.nome || "",
              editado_por_cargo: userDetails.cargo || "",
              editado_por_completo: userDetails.textoCompleto || "",
              data_ultima_edicao: new Date().toISOString()
            };
            if (isDispensaEdit) {
              payloadUpdate.dataInicio = editDispIni;
              payloadUpdate.dataFim = editDispFim;
              payloadUpdate.motivoDispensa = editDispMot;
              payloadUpdate.diasDispensa = diasDispensaCalc;
            }

            // a) Atualiza documento na coleção 'ocorrencias'
            if (!id.startsWith("emb_") && !id.startsWith("oc_local_")) {
              try {
                await updateDoc(doc(db, "ocorrencias", id), payloadUpdate);
              } catch (eDoc) {
                try {
                  await setDoc(doc(db, "ocorrencias", id), payloadUpdate, { merge: true });
                } catch (eSet) {
                  console.warn("Aviso ao atualizar coleção 'ocorrencias':", eSet);
                }
              }
            }

            // b) Atualiza objeto correspondente no array st.ocorrencias dentro do documento do aluno na coleção 'alunos'
            let raAlunoAfetado = null;
            if (Array.isArray(window.allStudentsData)) {
              for (const st of window.allStudentsData) {
                const arr = Array.isArray(st.ocorrencias) 
                  ? st.ocorrencias 
                  : (Array.isArray(st.registros) ? st.registros : []);
                if (!arr || arr.length === 0) continue;

                const stRa = String(st.ra || st.id || "").trim();
                let alterou = false;

                const novoArray = arr.map((oc, idx) => {
                  const genId = `oc_${stRa}_${idx}_${oc.data ? new Date(oc.data).getTime() : ''}`;
                  const embId = `emb_${stRa}_${idx}`;

                  if ((oc.id && String(oc.id) === String(id)) || 
                      (oc.docId && String(oc.docId) === String(id)) ||
                      genId === id || embId === id) {
                    alterou = true;
                    raAlunoAfetado = stRa;
                    const updatedItem = {
                      ...oc,
                      tipo: tipo,
                      categoria: tipo,
                      descricao: descricao,
                      observacao: descricao,
                      isDispensa: isDispensaEdit,
                      cienciaResponsavel: chkCiencia,
                      dataCiencia: dataCiencia,
                      registradoConviva: chkConviva,
                      codigoConviva: codigoConviva,
                      data_ultima_edicao: new Date().toISOString(),
                      editado_por_nome: userDetails.nome || ""
                    };
                    if (isDispensaEdit) {
                      updatedItem.dataInicio = editDispIni;
                      updatedItem.dataFim = editDispFim;
                      updatedItem.motivoDispensa = editDispMot;
                      updatedItem.diasDispensa = diasDispensaCalc;
                    }
                    delete updatedItem.id;
                    delete updatedItem._id;
                    return updatedItem;
                  }
                  const cleanItem = { ...oc };
                  delete cleanItem.id;
                  delete cleanItem._id;
                  return cleanItem;
                });

                if (alterou) {
                  st.ocorrencias = novoArray;
                  if (st.registros) st.registros = novoArray;

                  if (stRa) {
                    const studentDocRef = doc(db, "alunos", stRa);
                    try {
                      await updateDoc(studentDocRef, { ocorrencias: novoArray });
                    } catch (eUpd) {
                      try {
                        await setDoc(studentDocRef, { ocorrencias: novoArray }, { merge: true });
                      } catch (eSet) {
                        console.error("Erro ao atualizar array de ocorrencias no Banco de Dados:", eSet);
                      }
                    }
                  }
                  break;
                }
              }
            }

            if (Array.isArray(window.ocorrenciasCache)) {
              const itemCache = window.ocorrenciasCache.find(o => String(o.id) === String(id));
              if (itemCache) {
                itemCache.tipo = tipo;
                itemCache.categoria = tipo;
                itemCache.descricao = descricao;
                itemCache.observacao = descricao;
                itemCache.isDispensa = isDispensaEdit;
                if (isDispensaEdit) {
                  itemCache.dataInicio = editDispIni;
                  itemCache.dataFim = editDispFim;
                  itemCache.motivoDispensa = editDispMot;
                  itemCache.diasDispensa = diasDispensaCalc;
                }
                itemCache.cienciaResponsavel = chkCiencia;
                itemCache.dataCiencia = dataCiencia;
                itemCache.registradoConviva = chkConviva;
                itemCache.codigoConviva = codigoConviva;
                itemCache.data_ultima_edicao = new Date().toISOString();
              }
            }

            if (Array.isArray(window.ocorrenciasTopLevel)) {
              const itemTop = window.ocorrenciasTopLevel.find(o => String(o.id) === String(id));
              if (itemTop) {
                itemTop.tipo = tipo;
                itemTop.categoria = tipo;
                itemTop.descricao = descricao;
                itemTop.observacao = descricao;
                itemTop.isDispensa = isDispensaEdit;
                if (isDispensaEdit) {
                  itemTop.dataInicio = editDispIni;
                  itemTop.dataFim = editDispFim;
                  itemTop.motivoDispensa = editDispMot;
                  itemTop.diasDispensa = diasDispensaCalc;
                }
                itemTop.cienciaResponsavel = chkCiencia;
                itemTop.dataCiencia = dataCiencia;
                itemTop.registradoConviva = chkConviva;
                itemTop.codigoConviva = codigoConviva;
                if (itemTop.ra && !raAlunoAfetado) raAlunoAfetado = String(itemTop.ra).trim();
              }
            }

            // c) Atualiza o cache em memória e chama filtrarHistoricoOcorrencias() sem fetch no banco
            if (typeof window.consolidarHistoricoOcorrenciasGlobais === "function") {
              window.consolidarHistoricoOcorrenciasGlobais();
            }
            if (typeof window.filtrarHistoricoOcorrencias === "function") {
              window.filtrarHistoricoOcorrencias();
            } else if (typeof renderHistoricoOcorrencias === "function") {
              renderHistoricoOcorrencias(window.ocorrenciasCache);
            }
            window.dispatchEvent(new CustomEvent("clovis_ocorrencias_updated"));

            // d) Se o Dossiê do Aluno estiver aberto, recarrega a timeline de ações imediatamente
            const targetRaDossie = raAlunoAfetado || window.currentDossieRa;
            const modalFicha = document.getElementById("modal-ficha-aluno");
            if (targetRaDossie && modalFicha && !modalFicha.classList.contains("hidden") && typeof window.carregarHistoricoAcoesModal === "function") {
              await window.carregarHistoricoAcoesModal(targetRaDossie);
            }

            // e) Registrar Log de Auditoria
            if (typeof window.registrarLogAuditoria === "function") {
              window.registrarLogAuditoria({
                modulo: "Alunos",
                acao: "ATUALIZAR",
                descricao: `Editado registro de ocorrência (ID: ${id}, Tipo: ${tipo}) do aluno RA: ${raAlunoAfetado || 'N/A'}`,
                detalhes: { id, tipo, descricao, cienciaResponsavel: chkCiencia, registradoConviva: chkConviva, codigoConviva }
              });
            }

            if (typeof window.showToast === "function") {
              window.showToast("Ocorrência atualizada com sucesso no banco e dossiê!", 'success');
            }
            window.fecharModalEditarOcorrencia();
          } catch (err) {
            console.error("Erro ao atualizar ocorrência:", err);
            if (typeof window.showErrorToast === "function") {
              window.showErrorToast("Erro ao salvar alterações da ocorrência.", err);
            }
          } finally {
            if (btnSalvar) {
              btnSalvar.disabled = false;
              btnSalvar.innerHTML = `<i class="fa-solid fa-floppy-disk text-xs"></i><span>Salvar Alterações</span>`;
            }
          }
        });
      }

      // =========================================================
      // LÓGICA DE LANÇAMENTO EM MASSA DE ATRASOS (PLANILHA DINÂMICA POR TURMA)
      // =========================================================
      window.getAlunosGlobal = function() {
        if (Array.isArray(window.allStudentsData) && window.allStudentsData.length > 0) {
          return window.allStudentsData;
        }
        if (Array.isArray(window.lastFilteredStudentsData) && window.lastFilteredStudentsData.length > 0) {
          return window.lastFilteredStudentsData;
        }
        try {
          const lcA = localStorage.getItem("alunos_cache");
          if (lcA) {
            const parsed = JSON.parse(lcA);
            if (Array.isArray(parsed) && parsed.length > 0) {
              window.allStudentsData = parsed;
              return parsed;
            }
          }
        } catch (e) {}
        return [];
      };

      window.abrirModalLancarAtrasosMassa = async function() {
        const modal = document.getElementById("modal-lancar-atrasos-massa");
        const selectTurma = document.getElementById("massa-atraso-select-turma");

        let alunos = window.getAlunosGlobal();

        // Se o array de alunos estiver vazio na memória, busca do Banco de Dados
        if (!alunos || alunos.length === 0) {
          try {
            if (typeof db !== "undefined") {
              const snap = await getDocs(collection(db, "alunos"));
              const novos = [];
              snap.forEach(docSnap => {
                const al = docSnap.data();
                if (!al.ra) al.ra = docSnap.id;
                novos.push(al);
              });
              if (novos.length > 0) {
                if (typeof window.allStudentsData !== "undefined") window.allStudentsData = novos;
                
                alunos = novos;
              }
            }
          } catch (err) {
            console.error("Erro ao carregar alunos para atrasos em massa:", err);
          }
        }

        // Extração estrita e ordenada das turmas disponíveis
        const turmasDisponiveis = [...new Set((alunos || []).map(a => a?.turma).filter(Boolean))].sort();

        if (selectTurma) {
          let htmlOptions = `<option value="">-- SELECIONE UMA TURMA --</option>`;
          turmasDisponiveis.forEach(turma => {
            htmlOptions += `<option value="${turma}">${turma}</option>`;
          });
          selectTurma.innerHTML = htmlOptions;
          selectTurma.value = "";
        }

        window.onSelecionarTurmaMassaAtrasos();
        if (modal) modal.classList.remove("hidden");
      };

      window.fecharModalLancarAtrasosMassa = function() {
        const modal = document.getElementById("modal-lancar-atrasos-massa");
        if (modal) modal.classList.add("hidden");
      };

      window.onSelecionarTurmaMassaAtrasos = function() {
        const selectTurma = document.getElementById("massa-atraso-select-turma");
        const container = document.getElementById("massa-atraso-tabela-container");
        const countBadge = document.getElementById("massa-atraso-count-badge");

        const turmaSelecionada = (selectTurma?.value || "").trim();

        if (!container) return;

        if (!turmaSelecionada) {
          container.innerHTML = `
            <div class="text-center py-12 px-4 bg-slate-50 border border-dashed border-slate-300 rounded-2xl">
              <i class="fa-solid fa-table text-3xl text-slate-300 mb-2 block"></i>
              <p class="text-xs font-bold text-slate-600 uppercase">NENHUMA TURMA SELECIONADA</p>
              <p class="text-[11px] text-slate-400 mt-1">Escolha uma turma no campo acima para carregar a lista de estudantes no formato de planilha.</p>
            </div>
          `;
          if (countBadge) countBadge.textContent = "0 preenchido(s)";
          return;
        }

        const alunos = window.getAlunosGlobal();
        const alunosDaTurma = (alunos || []).filter(a => a && (a.turma === turmaSelecionada || String(a.turma || "").toUpperCase().trim() === String(turmaSelecionada).toUpperCase().trim()));

        // Ordenar por nome
        alunosDaTurma.sort((a, b) => String(a?.nome || "").localeCompare(String(b?.nome || "")));

        if (alunosDaTurma.length === 0) {
          container.innerHTML = `
            <div class="text-center py-12 px-4 bg-slate-50 border border-dashed border-slate-300 rounded-2xl">
              <i class="fa-solid fa-user-slash text-3xl text-slate-300 mb-2 block"></i>
              <p class="text-xs font-bold text-slate-600 uppercase">Nenhum aluno encontrado para a turma ${turmaSelecionada}</p>
            </div>
          `;
          if (countBadge) countBadge.textContent = "0 preenchido(s)";
          return;
        }

        let html = `
          <div class="overflow-x-auto rounded-xl border border-slate-200 shadow-2xs">
            <table class="w-full text-left border-collapse">
              <thead>
                <tr class="bg-slate-100 text-slate-700 text-[11px] font-bold uppercase tracking-wider border-b border-slate-200">
                  <th class="px-3 py-2.5 w-12 text-center">#</th>
                  <th class="px-3.5 py-2.5">Estudante</th>
                  <th class="px-3.5 py-2.5 w-44">Hora Real Chegada <span class="text-red-500">*</span></th>
                  <th class="px-3.5 py-2.5">Observação (Opcional)</th>
                </tr>
              </thead>
              <tbody class="divide-y divide-slate-100 text-xs">
        `;

        alunosDaTurma.forEach((aluno, index) => {
          const nome = String(aluno.nome || "ALUNO SEM NOME").toUpperCase();
          const ra = String(aluno.ra || aluno.id || "");
          const raDisplay = aluno.ra ? `RA: ${aluno.ra}` : "SEM RA";

          html += `
            <tr class="hover:bg-amber-50 transition-colors">
              <td class="px-3 py-2 text-center font-mono text-[11px] text-slate-400">${index + 1}</td>
              <td class="px-3.5 py-2">
                <span class="font-bold text-slate-800 block text-xs">${nome}</span>
                <span class="text-[10px] font-mono text-slate-400">${raDisplay}</span>
              </td>
              <td class="px-3.5 py-2">
                <input 
                  type="time" 
                  id="massa-hora-${ra}" 
                  onchange="window.atualizarContadorMassaAtrasos()"
                  oninput="window.atualizarContadorMassaAtrasos()"
                  class="massa-atraso-time-input w-full p-2 bg-white border border-slate-300 rounded-lg text-xs font-mono font-bold text-slate-800 outline-none focus:ring-2 focus:ring-amber-400 shadow-2xs"
                />
              </td>
              <td class="px-3.5 py-2">
                <input 
                  type="text" 
                  id="massa-obs-${ra}" 
                  placeholder="Ex: Chegou no 2º horário / Transporte..." 
                  class="massa-atraso-obs-input w-full p-2 bg-white border border-slate-300 rounded-lg text-xs font-medium text-slate-800 outline-none focus:ring-2 focus:ring-amber-400 uppercase shadow-2xs"
                />
              </td>
            </tr>
          `;
        });

        html += `
              </tbody>
            </table>
          </div>
        `;

        container.innerHTML = html;
        window.atualizarContadorMassaAtrasos();
      };

      window.preencherHoraAtualEmTodosMassaAtrasos = function() {
        const agora = new Date();
        const hh = String(agora.getHours()).padStart(2, '0');
        const mm = String(agora.getMinutes()).padStart(2, '0');
        const horaAtual = `${hh}:${mm}`;

        const inputs = document.querySelectorAll(".massa-atraso-time-input");
        inputs.forEach(inp => {
          inp.value = horaAtual;
        });

        window.atualizarContadorMassaAtrasos();
        if (typeof window.showToast === "function" && inputs.length > 0) {
          window.showToast(`Horário ${horaAtual} preenchido para todos os ${inputs.length} alunos da lista!`, 'info');
        }
      };

      window.limparHorariosMassaAtrasos = function() {
        const timeInputs = document.querySelectorAll(".massa-atraso-time-input");
        const obsInputs = document.querySelectorAll(".massa-atraso-obs-input");
        timeInputs.forEach(inp => inp.value = "");
        obsInputs.forEach(inp => inp.value = "");
        window.atualizarContadorMassaAtrasos();
      };

      window.atualizarContadorMassaAtrasos = function() {
        const timeInputs = document.querySelectorAll(".massa-atraso-time-input");
        let preenchidos = 0;
        timeInputs.forEach(inp => {
          if (inp.value && inp.value.trim() !== "") {
            preenchidos++;
          }
        });

        const countBadge = document.getElementById("massa-atraso-count-badge");
        if (countBadge) {
          countBadge.textContent = `${preenchidos} / ${timeInputs.length} preenchido(s)`;
          if (preenchidos > 0) {
            countBadge.className = "px-3 py-1 bg-amber-600 text-white font-extrabold text-[11px] rounded-full uppercase shadow-2xs";
          } else {
            countBadge.className = "px-3 py-1 bg-slate-300 text-slate-700 font-bold text-[11px] rounded-full uppercase shadow-2xs";
          }
        }
      };

      window.salvarAtrasosEmMassa = function() {
        const selectTurma = document.getElementById("massa-atraso-select-turma");
        const turmaSelecionada = (selectTurma?.value || "").trim();

        if (!turmaSelecionada) {
          if (typeof window.showToast === "function") {
            window.showToast("Por favor, selecione uma turma antes de salvar os atrasos.", 'warning');
          }
          return;
        }

        const alunos = window.getAlunosGlobal ? window.getAlunosGlobal() : ((window.allStudentsData || []));
        // Filtrar alunos da turma selecionada
        const alunosDaTurma = (alunos || []).filter(s => {
          if (!s) return false;
          return s.turma === turmaSelecionada || String(s.turma || "").toUpperCase().trim() === String(turmaSelecionada).toUpperCase().trim();
        });

        // Coletar apenas os alunos com horário de atraso preenchido
        const atrasosParaSalvar = [];
        alunosDaTurma.forEach(aluno => {
          const ra = String(aluno.ra || aluno.id || "");
          const elHora = document.getElementById(`massa-hora-${ra}`);
          const elObs = document.getElementById(`massa-obs-${ra}`);

          const horaVal = elHora ? elHora.value.trim() : "";
          const obsVal = elObs ? elObs.value.trim() : "";

          // REGRA DE OURO: Apenas salvar se horaVal não estiver em branco!
          if (horaVal && horaVal !== "") {
            atrasosParaSalvar.push({
              aluno: aluno,
              hora: horaVal,
              obs: obsVal
            });
          }
        });

        if (atrasosParaSalvar.length === 0) {
          if (typeof window.showToast === "function") {
            window.showToast("Nenhum horário de atraso foi preenchido. Preencha a hora de chegada para ao menos um aluno.", 'warning');
          }
          return;
        }

        const btnSalvar = document.getElementById("btn-salvar-massa-atrasos");
        if (btnSalvar) {
          btnSalvar.disabled = true;
          btnSalvar.innerHTML = `<i class="fa-solid fa-spinner animate-spin text-xs"></i><span>Salvando ${atrasosParaSalvar.length} Atraso(s)...</span>`;
        }

        (async () => {
          try {
            // Unbreakable authorship auditor
            const userDetails = window.obterIdentificacaoUsuarioCompleta ? window.obterIdentificacaoUsuarioCompleta() : { email: '', nome: '', cargo: '', textoCompleto: '' };

            const batch = writeBatch(db);
            const novosRegistrosParaMemoria = [];

            for (const item of atrasosParaSalvar) {
              const al = item.aluno;
              const horaReal = item.hora;
              const observacao = item.obs;

              const agora = new Date();
              const [hh, mm] = String(horaReal).split(':');
              if (hh !== undefined && mm !== undefined) {
                agora.setHours(parseInt(hh, 10), parseInt(mm, 10), 0, 0);
              }
              const dataIsoComHoraReal = agora.toISOString();

              const descFinal = `Atraso registrado na recepção/secretaria. Horário de Chegada: ${horaReal}.${observacao ? ' Obs: ' + observacao : ''}`;

              // 1. Gera o documento na coleção 'ocorrencias' diretamente no batch (SEM id ou _id no payload enviado ao banco)
              const novaOcorrenciaDocRef = doc(collection(db, "ocorrencias"));
              const novoDocId = novaOcorrenciaDocRef.id;

              const novaOcorrenciaPayload = {
                ra: String(al.ra || ""),
                nomeAluno: String(al.nome || "").toUpperCase(),
                turma: String(al.turma || "").toUpperCase(),
                titulo: "Atraso na Entrada",
                categoria: "Atraso",
                tipo: "Atraso",
                encaminhamento: "Monitoramento de Pontualidade / Tutoria PEI",
                descricao: descFinal,
                horaRealAtraso: horaReal,
                isAtraso: true,
                cienciaResponsavel: false,
                dataCiencia: "",
                registradoConviva: false,
                codigoConviva: "",
                protocoloConviva: "",
                data: dataIsoComHoraReal,
                usuario: userDetails.textoCompleto,
                autor: userDetails.textoCompleto,
                registradoPor: userDetails.textoCompleto,
                autor_email: userDetails.email,
                autor_nome: userDetails.nome,
                autor_cargo: userDetails.cargo,
                cargo: userDetails.cargo,
                autor_criacao: {
                  nome: userDetails.nome,
                  email: userDetails.email,
                  cargo: userDetails.cargo,
                  textoCompleto: userDetails.textoCompleto,
                  data: dataIsoComHoraReal
                }
              };

              batch.set(novaOcorrenciaDocRef, novaOcorrenciaPayload);

              // 2. Adiciona atualização do documento do aluno (doc(db, 'alunos', ra)) no batch
              const cleanTargetRa = String(al.ra || "").replace(/\D/g, "");
              const stObj = ((window.allStudentsData || [])).find(s => String(s.ra || "").replace(/\D/g, "") === cleanTargetRa);
              const targetRa = String((stObj && stObj.ra) || al.ra);

              const resumoAnt = (stObj && stObj.acoes_2026) || "";
              const novaLinha = `[${new Date().toLocaleDateString("pt-BR")} ${horaReal}] ATRASO: ${descFinal}`;
              const novoResumo = resumoAnt ? `${resumoAnt}\n${novaLinha}` : novaLinha;

              if (targetRa) {
                const studentDocRef = doc(db, "alunos", targetRa);
                batch.set(studentDocRef, {
                  acoes_2026: novoResumo.toUpperCase(),
                  ocorrencias: arrayUnion(novaOcorrenciaPayload)
                }, { merge: true });
              }

              novosRegistrosParaMemoria.push({
                novaOcorrencia: { ...novaOcorrenciaPayload, id: novoDocId },
                stObj,
                al,
                novoResumo
              });
            }

            // 3. Gravação atômica em batch (1 única operação de escrita)
            await batch.commit();

            // 4. Inserção direta nos arrays locais em memória sem fazer getDocs
            if (!Array.isArray(window.ocorrenciasCache)) window.ocorrenciasCache = [];
            if (!Array.isArray(window.ocorrenciasTopLevel)) window.ocorrenciasTopLevel = [];

            for (const { novaOcorrencia, stObj, al, novoResumo } of novosRegistrosParaMemoria) {
              if (stObj) {
                stObj.acoes_2026 = novoResumo.toUpperCase();
                if (!Array.isArray(stObj.ocorrencias)) stObj.ocorrencias = [];
                stObj.ocorrencias.push(novaOcorrencia);
              }
              window.ocorrenciasTopLevel.unshift(novaOcorrencia);
              window.ocorrenciasCache.unshift(novaOcorrencia);

              if (typeof window.verificarGatilhoAtrasosMes === "function") {
                await window.verificarGatilhoAtrasosMes(stObj || al);
              }
            }

            // 5. Renderização imediata da tabela e atualização do Dashboard de Atrasos
            if (typeof window.consolidarHistoricoOcorrenciasGlobais === "function") {
              window.consolidarHistoricoOcorrenciasGlobais();
            } else if (typeof window.filtrarHistoricoOcorrencias === "function") {
              window.filtrarHistoricoOcorrencias();
            } else if (typeof renderHistoricoOcorrencias === "function") {
              renderHistoricoOcorrencias(window.ocorrenciasCache);
            }

            window.fecharModalLancarAtrasosMassa();
            if (typeof window.showToast === "function") {
              window.showToast(`Lançamento em massa concluído com sucesso! ${novosRegistrosParaMemoria.length} atraso(s) registrado(s) na turma ${turmaSelecionada}.`, 'success');
            }

            if (typeof window.registrarLogAuditoria === "function") {
              window.registrarLogAuditoria({
                modulo: "Alunos",
                acao: "CRIAR",
                descricao: `Lançados ${novosRegistrosParaMemoria.length} atrasos em massa para a turma ${turmaSelecionada}`,
                detalhes: { turma: turmaSelecionada, quantidade: novosRegistrosParaMemoria.length }
              });
            }
          } catch (err) {
            console.error("Erro ao salvar atrasos em massa:", err);
            if (typeof window.showToast === "function") {
              window.showToast("Ocorreu um erro ao registrar os atrasos em massa. Verifique sua conexão.", 'error');
            }
          } finally {
            if (btnSalvar) {
              btnSalvar.disabled = false;
              btnSalvar.innerHTML = `<i class="fa-solid fa-floppy-disk text-xs"></i><span>Salvar Atrasos em Massa</span>`;
            }
          }
        })();
      };

      // ==========================================
      // BOLETIM DIÁRIO DE FREQUÊNCIA & CRUZAMENTO DE FALTAS CONSECUTIVAS C/ IA
      // (Resolução SEDUC nº 39, de 05-09-2023)
      // ==========================================
      window.ultimoBoletimGeradoCache = null;

      // 1. Abrir Modal do Boletim Diário
      window.abrirModalBoletimDiarioIA = function() {
        const modal = document.getElementById("modal-boletim-diario-ia");
        if (!modal) return;

        // Data padrão: hoje
        const dataInput = document.getElementById("boletim-param-data");
        if (dataInput && !dataInput.value) {
          const hojeIso = new Date().toISOString().split("T")[0];
          dataInput.value = hojeIso;
        }

        modal.classList.remove("hidden");
        window.recarregarDadosDataBoletim();
      };

      // 2. Fechar Modal
      window.fecharModalBoletimDiarioIA = function() {
        const modal = document.getElementById("modal-boletim-diario-ia");
        if (modal) modal.classList.add("hidden");
      };

      // 3. Recarregar Dados Conectados do Sistema para a Data
      window.recarregarDadosDataBoletim = function() {
        const dataInput = document.getElementById("boletim-param-data");
        const turnoSelect = document.getElementById("boletim-param-turno");
        const etapaSelect = document.getElementById("boletim-param-etapa");
        const dataVal = dataInput ? dataInput.value : new Date().toISOString().split("T")[0];
        const turnoVal = turnoSelect ? turnoSelect.value : "Manhã";
        const etapaVal = etapaSelect ? etapaSelect.value : "Ensino Fundamental";

        const countAtrasosEl = document.getElementById("boletim-count-atrasos");
        const countSaidasEl = document.getElementById("boletim-count-saidas");
        const countMatriculadosEl = document.getElementById("boletim-count-matriculados");

        // Alunos cadastrados: filtrar estritamente ATIVOS (Censo & LGPD)
        const todosAlunos = window.getAlunosGlobal ? window.getAlunosGlobal() : (window.allStudentsData || []);
        const alunosAtivos = todosAlunos.filter(a => String(a.status || 'ATIVO').trim().toUpperCase() === 'ATIVO');
        
        const isFund = (turma) => {
          const clean = String(turma || '').replace(/[^\d1-9A-Za-z]/g, '').toUpperCase();
          return clean.startsWith('6') || clean.startsWith('7') || clean.startsWith('8') || clean.startsWith('9');
        };
        const isMed = (turma) => {
          const clean = String(turma || '').replace(/[^\d1-9A-Za-z]/g, '').toUpperCase();
          return clean.startsWith('1') || clean.startsWith('2') || clean.startsWith('3');
        };

        // Filtrar matriculados ativos pelo turno/etapa
        const isGeralEtapa = etapaVal.toLowerCase().includes("geral") || etapaVal.toLowerCase().includes("todos");
        const isEtapaFund = !isGeralEtapa && (etapaVal.toLowerCase().includes("fundamental") || etapaVal.toLowerCase().includes("6º ao 9º"));
        const isEtapaMed = !isGeralEtapa && (etapaVal.toLowerCase().includes("médio") || etapaVal.toLowerCase().includes("medio") || etapaVal.toLowerCase().includes("1º ao 3º"));

        let alunosTurno = alunosAtivos;
        if (isGeralEtapa) {
          // GERAL: soma Fundamental (497) + Médio (206) = 703 alunos ativos
          alunosTurno = alunosAtivos.filter(a => isFund(a.turma) || isMed(a.turma));
          if (alunosTurno.length === 0) alunosTurno = alunosAtivos;
        } else if (isEtapaFund) {
          alunosTurno = alunosAtivos.filter(a => isFund(a.turma));
        } else if (isEtapaMed) {
          alunosTurno = alunosAtivos.filter(a => isMed(a.turma));
        }

        const totalAtivosCalculado = alunosTurno.length > 0 
          ? alunosTurno.length 
          : (isGeralEtapa ? 703 : (isEtapaFund ? 497 : 206));

        if (countMatriculadosEl) {
          countMatriculadosEl.textContent = totalAtivosCalculado;
        }

        // Atrasos e Saídas na data selecionada
        const feed = Array.isArray(window.ocorrenciasCache) && window.ocorrenciasCache.length > 0
          ? window.ocorrenciasCache
          : (typeof window.consolidarHistoricoOcorrenciasGlobais === "function" ? window.consolidarHistoricoOcorrenciasGlobais() : []);

        const [yyyy, mm, dd] = (dataVal || "").split("-");
        const dataBrBusca = dd && mm && yyyy ? `${dd}/${mm}/${yyyy}` : "";

        let totalAtrasosData = 0;
        let totalSaidasData = 0;

        feed.forEach(oc => {
          if (!oc) return;
          const ocData = String(oc.data || oc.dataRegistro || oc.createdAt || "");
          const isDaData = ocData.startsWith(dataVal) || (dataBrBusca && ocData.includes(dataBrBusca));
          if (isDaData) {
            if (oc.tipo === "Atraso" || oc.isAtraso) {
              totalAtrasosData++;
            } else if (oc.tipo === "Saída Antecipada") {
              totalSaidasData++;
            }
          }
        });

        if (countAtrasosEl) countAtrasosEl.textContent = totalAtrasosData;
        if (countSaidasEl) countSaidasEl.textContent = totalSaidasData;
      };

