      window.copiarTextoDocumentoSecretaria = async function() {
        const modal = document.getElementById("modal-documento-impressao");
        if (!modal) return;
        try {
          await navigator.clipboard.writeText(modal.innerText);
          window.showToast("Texto do documento copiado com sucesso para a área de transferência!", 'success');
        } catch (err) {
          window.showToast("Selecione e copie o texto manualmente.", 'warning');
        }
      };

      // Event Listeners dos botões de emissão
      document.getElementById("btn-doc-matricula")?.addEventListener("click", () => window.gerarDocumentoOficial("matricula"));
      document.getElementById("btn-doc-frequencia")?.addEventListener("click", () => window.gerarDocumentoOficial("frequencia"));
      document.getElementById("btn-doc-atestado")?.addEventListener("click", () => window.gerarDocumentoOficial("atestado"));
      document.getElementById("btn-doc-termo-frequencia")?.addEventListener("click", () => window.gerarTermoCompromissoFrequencia());
      document.getElementById("btn-gerar-termo-frequencia-ba")?.addEventListener("click", () => window.gerarTermoCompromissoFrequencia());

      // =========================================================
      // MÓDULO 3: BUSCA ATIVA ESCOLAR & NOTIFICAÇÕES LEGAIS (SEDUC-SP)
      // =========================================================
      window.alunoBuscaAtivaSelecionado = null;
      let alunoBuscaAtivaSelecionado = null;
      let buscaAtivaHistoricoCache = [];

      // Funções auxiliares globais de prevenção de ReferenceError
      window.parsePresencaNum = function(val) {
        if (val === undefined || val === null || val === "" || val === "—") return 0;
        if (typeof val === "object" && val !== null) {
          if (val.valor !== undefined) return window.parsePresencaNum(val.valor);
        }
        let numVal = 0;
        if (typeof val === "number") {
          numVal = val;
          if (numVal <= 1 && numVal > 0) numVal = numVal * 100;
        } else {
          let strVal = String(val).trim().replace("%", "").replace(",", ".");
          numVal = parseFloat(strVal);
          if (!isNaN(numVal) && numVal <= 1 && numVal > 0) numVal = numVal * 100;
        }
        return isNaN(numVal) ? 0 : numVal;
      };

      window.parseFreqObj = function(obj, defaultDate = "Sem data") {
        if (!obj) return { valorNum: null, valorStr: "—", dataStr: defaultDate };
        if (typeof obj === "object" && obj !== null) {
          const val = obj.valor !== undefined ? obj.valor : "";
          const num = val !== "" && val !== null && val !== "—" ? window.parsePresencaNum(val) : null;
          const date = obj.data || defaultDate;
          return {
            valorNum: num,
            valorStr: val !== "" && val !== null ? (typeof val === "number" ? val.toFixed(1) + "%" : String(val)) : "—",
            dataStr: date
          };
        } else {
          const num = obj !== "" && obj !== null && obj !== "—" ? window.parsePresencaNum(obj) : null;
          const valStr = typeof obj === "number" ? obj.toFixed(1) + "%" : (obj ? String(obj) : "—");
          return {
            valorNum: num,
            valorStr: valStr,
            dataStr: defaultDate
          };
        }
      };

      window.parseDataToIso = function(dataStr) {
        if (!dataStr) return "";
        if (dataStr.includes("-") && dataStr.length === 10) return dataStr;
        if (dataStr.includes("/")) {
          const parts = dataStr.split("/");
          if (parts.length === 3) {
            const day = parts[0].padStart(2, "0");
            const month = parts[1].padStart(2, "0");
            const year = parts[2].length === 2 ? "20" + parts[2] : parts[2];
            return `${year}-${month}-${day}`;
          }
        }
        return dataStr;
      };

      // Função Auxiliar: Auto-expiração de status de 'Aguardando Retorno dos Pais' após 24h (1 dia)
      window.verificarEAtualizarAutoExpiracaoBa = function(listaContatos) {
        if (!listaContatos || !Array.isArray(listaContatos) || listaContatos.length === 0) return false;

        const agoraMs = Date.now();
        const vinteEQuatroHorasMs = 24 * 60 * 60 * 1000; // 86.400.000 ms (24h / 1 dia)
        let houveAlteracao = false;

        listaContatos.forEach(item => {
          if (!item) return;
          const resp = String(item.houveResposta || "").trim().toLowerCase();

          // Se estiver aguardando retorno dos pais
          if (resp.includes("aguardando")) {
            let timestampMs = 0;

            // 1. Tenta timestamp ISO de criação ou registro
            if (item.dataRegistro || item.createdAt || item.data_criacao) {
              const ts = new Date(item.dataRegistro || item.createdAt || item.data_criacao).getTime();
              if (!isNaN(ts) && ts > 0) timestampMs = ts;
            } else if (item.autor_criacao && item.autor_criacao.data) {
              const ts = new Date(item.autor_criacao.data).getTime();
              if (!isNaN(ts) && ts > 0) timestampMs = ts;
            }

            // 2. Se não houver timestamp ISO, tenta a data do contato (item.data)
            if (timestampMs === 0 && item.data) {
              if (typeof item.data === "string" && item.data.includes("-")) {
                const d = new Date(item.data + "T00:00:00");
                if (!isNaN(d.getTime())) timestampMs = d.getTime();
              } else if (typeof item.data === "string" && item.data.includes("/")) {
                const parts = item.data.split("/");
                if (parts.length === 3) {
                  const d = new Date(`${parts[2]}-${parts[1]}-${parts[0]}T00:00:00`);
                  if (!isNaN(d.getTime())) timestampMs = d.getTime();
                }
              }
            }

            // 3. Se a data/hora for igual ou superior a 24h (1 dia) em relação ao momento atual
            if (timestampMs > 0 && (agoraMs - timestampMs) >= vinteEQuatroHorasMs) {
              const novoStatus = "Não - Sem Resposta / Não Atendeu";
              item.houveResposta = novoStatus;
              item.autoExpirado24h = true;
              houveAlteracao = true;

              // Sincroniza também na cache global se o item estiver presente
              if (Array.isArray(window.todosContatosBaCache)) {
                const cacheItem = window.todosContatosBaCache.find(c => String(c.id) === String(item.id));
                if (cacheItem) {
                  cacheItem.houveResposta = novoStatus;
                  cacheItem.autoExpirado24h = true;
                }
              }

              // Atualiza o documento no Banco de Dados para garantir a persistência
              if (item.id && !item.isSemAcao) {
                try {
                  const docRef = doc(db, "busca_ativa", String(item.id));
                  updateDoc(docRef, {
                    houveResposta: novoStatus,
                    auto_expirado_24h: true,
                    data_auto_expiracao: new Date().toISOString(),
                    updatedAt: new Date().toISOString()
                  }).catch(e => console.error("Erro ao persistir auto-expiração no Banco de Dados:", e));
                } catch (eDoc) {
                  console.error("Erro ao instanciar referência para atualização de auto-expiração:", eDoc);
                }
              }
            }
          }
        });

        return houveAlteracao;
      };

