      // Envio rápido de WhatsApp direto da Busca Ativa de Atrasos
      window.enviarWhatsAppBuscaAtivaAtraso = function(ra) {
        const aluno = (window.allStudentsData || []).find(s => String(s.ra).trim() === String(ra).trim());
        if (!aluno) {
          window.showToast("Estudante não localizado.", "warning");
          return;
        }
        const itemCache = (window.todosAlunosBaAtrasosCache || []).find(x => String(x.ra).trim() === String(ra).trim());
        const qtd = itemCache ? itemCache.qtdPeriodo : (parseInt(aluno.atrasos || "0", 10) || 1);
        const nomeUpper = (aluno.nome || "ESTUDANTE").toUpperCase();
        const turmaUpper = (aluno.turma || "—").toUpperCase();
        const tutorUpper = (aluno.tutor_2026 || aluno.tutor || "Professor(a) Tutor(a)").toUpperCase();

        const msg = qtd >= 3
          ? `COMUNICADO OFICIAL DE BUSCA ATIVA DE ATRASOS - E.E. CLÓVIS DE LUCCA\n\nPrezado(a) responsável pelo(a) estudante ${nomeUpper} (Turma: ${turmaUpper}),\n\nInformamos que o(a) estudante completou ${qtd} atrasos no período na entrada escolar, ativando o protocolo de emissão do Termo de Ciência de Frequência e Pontualidade e pauta obrigatória na sessão semanal de Tutoria PEI (Tutor: ${tutorUpper}).\n\nContamos com o apoio da família para assegurar a entrada pontual no início da 1ª aula. Por favor, confirme o recebimento desta mensagem.\n\nAtenciosamente,\nEquipe Gestora - E.E. Clóvis de Lucca`
          : `AVISO DE PONTUALIDADE (BUSCA ATIVA) - E.E. CLÓVIS DE LUCCA\n\nOlá, responsável pelo(a) estudante ${nomeUpper} (Turma: ${turmaUpper}).\n\nRegistramos ${qtd} atraso(s) recente(s) na chegada às aulas. Lembramos que a pontualidade diária é fundamental para o aproveitamento escolar no PEI e que, ao atingir 3 atrasos no mês, é emitido o Termo de Ciência de Frequência com pauta obrigatória na Tutoria.\n\nPor favor, confirme a ciência deste comunicado.\n\nAtenciosamente,\nEquipe Gestora - E.E. Clóvis de Lucca`;

        const foneRaw = aluno.telefone || aluno.celular || aluno.telefones_adicionais || aluno.contato || "";
        const foneLimpo = String(foneRaw).replace(/\D/g, "");

        if (foneLimpo.length >= 10) {
          const numFinal = foneLimpo.startsWith("55") ? foneLimpo : ("55" + foneLimpo);
          const link = `https://wa.me/${numFinal}?text=${encodeURIComponent(msg)}`;
          const a = document.createElement("a");
          a.href = link;
          a.target = "_blank";
          a.rel = "noopener noreferrer";
          document.body.appendChild(a);
          a.click();
          document.body.removeChild(a);
          window.showToast(`Abrindo WhatsApp para o responsável de ${nomeUpper}...`, "info");
        } else {
          window.registrarContatoRapidoBaAtraso(ra);
          navigator.clipboard?.writeText(msg).catch(() => {});
          window.showToast("Estudante sem telefone celular cadastrado. Ficha de contato aberta com a mensagem copiada!", "info", 4000);
        }
      };

      // Marcar ciência familiar em todos os atrasos pendentes do estudante com 1 clique
      window.marcarCienciaTodosAtrasosAluno = async function(ra) {
        if (!ra) return;
        const raStr = String(ra).trim();
        const raClean = raStr.replace(/\D/g, "") || raStr;
        const dataHoraStr = new Date().toLocaleDateString("pt-BR");

        try {
          let atualizados = 0;
          const pools = [window.ocorrenciasTopLevel, window.ocorrenciasCache];
          pools.forEach(arr => {
            if (!Array.isArray(arr)) return;
            arr.forEach(oc => {
              const ocRa = String(oc.ra || oc.alunoRa || "").trim();
              const ocRaClean = ocRa.replace(/\D/g, "") || ocRa;
              const isAtr = typeof ehRegistroDeAtraso === "function"
                ? ehRegistroDeAtraso(oc)
                : String(oc.tipo || oc.categoria || "").toUpperCase().includes("ATRASO");
              if (isAtr && (ocRa === raStr || ocRaClean === raClean) && !oc.ciencia) {
                oc.ciencia = true;
                oc.cienciaData = dataHoraStr;
                atualizados++;
              }
            });
          });

          const aluno = (window.allStudentsData || []).find(s => String(s.ra).trim() === raStr);
          if (aluno) {
            aluno.sla_busca_ativa = "MONITORANDO";
            aluno.ciencia_atrasos_data = dataHoraStr;
            const acoesArr = Array.isArray(aluno.ocorrencias) ? aluno.ocorrencias : (Array.isArray(aluno.acoes) ? aluno.acoes : []);
            acoesArr.forEach(ac => {
              const isAtr = typeof ehRegistroDeAtraso === "function"
                ? ehRegistroDeAtraso(ac)
                : String(ac.tipo || ac.categoria || "").toUpperCase().includes("ATRASO");
              if (isAtr && !ac.ciencia) {
                ac.ciencia = true;
                ac.cienciaData = dataHoraStr;
              }
            });
          }

          window.renderBuscaAtivaAtrasos(false);
          if (typeof window.atualizarDashboardAtrasos === "function") {
            window.atualizarDashboardAtrasos();
          }

          const docRef = doc(db, "alunos", raStr);
          await updateDoc(docRef, {
            sla_busca_ativa: "MONITORANDO",
            ciencia_atrasos_data: dataHoraStr
          }).catch(() => {});

          window.showToast(`Ciência familiar confirmada para os atrasos do estudante (RA: ${raStr})!`, "success", 3000);
        } catch (err) {
          console.warn("Aviso ao registrar ciência de atrasos:", err);
          window.showToast("Ciência registrada localmente com sucesso!", "info");
        }
      };

      window.excluirAlunoDefinitivo = async function(ra) {
        if (!ra) return;
        const confirmacao = confirm(`Tem certeza que deseja excluir DEFINITIVAMENTE o aluno de RA "${ra}"? Esta ação não poderá ser desfeita!`);
        if (!confirmacao) return;

        try {
          await deleteDoc(doc(db, "alunos", ra));
          // Remover do array local em memória
          window.allStudentsData = (window.allStudentsData || []).filter(s => s.ra !== ra);

          if (typeof window.registrarLogAuditoria === "function") {
            window.registrarLogAuditoria({
              modulo: "Alunos",
              acao: "EXCLUIR",
              descricao: `Excluído definitivamente cadastro do aluno (RA: ${ra})`,
              detalhes: { ra }
            });
          }

          window.showToast("Aluno excluído definitivamente com sucesso.", 'success');

          // Atualizar interface localmente sem re-executar busca no Banco de Dados
          populateFilterSelects(window.allStudentsData || []);
          applyStudentFilters();
          atualizarDashboardGraficos();
          renderBuscaAtiva();
        } catch (err) {
          window.showErrorToast("Erro de conexão com o banco de dados! O aluno não foi excluído. Verifique sua internet.", err);
        }
      };

