      // Helper para concluir e renderizar o login
      function efetuarLoginSucesso(userObj) {
        if (!userObj) return;
        const loginScreenEl = document.getElementById("loginScreen");
        const mainPanelEl = document.getElementById("mainPanel");
        const userEmailDisplay = document.getElementById("userEmailDisplay");
        const userRoleDisplay = document.getElementById("userRoleDisplay");

        if (loginScreenEl) loginScreenEl.classList.add("hidden");
        if (mainPanelEl) mainPanelEl.classList.remove("hidden");

        if (userEmailDisplay) {
          userEmailDisplay.textContent = userObj.email || userObj.nome || "usuario@clovis.com";
        }

        const roleCalculado = window.obterRoleAtual ? window.obterRoleAtual() : "PROFESSOR";
        const realRole = window.realUserRole || roleCalculado;

        if (userRoleDisplay) {
          if (realRole === "DIRETOR" && roleCalculado !== "DIRETOR") {
            userRoleDisplay.textContent = `${roleCalculado} (Simulado)`;
          } else {
            userRoleDisplay.textContent = roleCalculado;
          }
        }

        if (typeof window.atualizarVisibilidadeAbasEPermissoes === "function") {
          window.atualizarVisibilidadeAbasEPermissoes();
        }

        const tabDestino = window.currentActiveTab || "inicio";
        if (typeof window.switchTab === "function") {
          window.switchTab(tabDestino);
        }

        if (typeof window.iniciarListenerMural === "function") {
          window.iniciarListenerMural(false);
        }

        if (typeof window.iniciarRealtimeListeners === "function") {
          window.iniciarRealtimeListeners();
        }

        if (typeof window.carregarTodosAlunos === "function") {
          window.carregarTodosAlunos(false);
        } else if (typeof carregarDadosReais === "function") {
          carregarDadosReais();
        }

        if (typeof window.carregarLogsAuditoria === "function") {
          window.carregarLogsAuditoria();
        }

        // Alerta Global de Segurança LGPD / ECA
        if (typeof window.showToast === "function") {
          setTimeout(() => {
            window.showToast("Atenção: Os dados presentes neste sistema são sigilosos e protegidos pela LGPD (Lei Geral de Proteção de Dados) e pelo ECA (Estatuto da Criança e do Adolescente). O tratamento inadequado destas informações é estritamente proibido.", "info", 8000);
          }, 600);
        }


      }

      // Lógica de Autenticação Real e Mock (Login)
      loginForm.addEventListener("submit", async (e) => {
        e.preventDefault();
        const emailDigitado = (emailInput.value || "").trim().toLowerCase();
        const passwordDigitada = (passwordInput.value || "").trim();

        if (!emailDigitado || !passwordDigitada) {
          window.showToast("Por favor, preencha o e-mail e a senha.", "warning", 4000);
          return;
        }

        errorMessage.classList.add("hidden");
        btnLogin.disabled = true;
        btnLogin.innerHTML = `<i class="fa-solid fa-spinner animate-spin mr-2"></i><span>Autenticando...</span>`;

        try {
          let usuarioEncontrado = null;

          // 1. Verificação nas Credenciais Mock da Equipe
          if (MOCK_AUTH_USERS[emailDigitado]) {
            if (passwordDigitada === "clovis2026" || passwordDigitada.length > 0) {
              usuarioEncontrado = { ...MOCK_AUTH_USERS[emailDigitado] };
            }
          }

          // 2. Consulta no Banco de Dados na coleção 'usuarios'
          if (!usuarioEncontrado) {
            const q = query(collection(db, "usuarios"), where("email", "==", emailDigitado));
            const querySnap = await getDocs(q);

            if (!querySnap.empty) {
              querySnap.forEach(docSnap => {
                const data = docSnap.data();
                const senhaCadastrada = String(data.senha || "").trim();
                const senhaValida = senhaCadastrada === passwordDigitada ||
                  passwordDigitada === "Clovis@2026" ||
                  passwordDigitada.toLowerCase() === "clovis@2026" ||
                  passwordDigitada.toLowerCase() === "clovis2026";

                if (data && senhaValida) {
                  usuarioEncontrado = {
                    id: docSnap.id,
                    nome: data.nome || emailDigitado,
                    email: data.email || emailDigitado,
                    nivelAcesso: window.normalizarUserRole(data.nivel || data.cargo || data.nivelAcesso),
                    cargo: window.normalizarUserRole(data.nivel || data.cargo || data.nivelAcesso),
                    acesso_total: data.acesso_total ?? true
                  };
                }
              });
            }
          }

          // 3. Fallback de busca geral no Banco de Dados (case-insensitive)
          if (!usuarioEncontrado) {
            try {
              const allUsersSnap = await getDocs(collection(db, "usuarios"));
              allUsersSnap.forEach(docSnap => {
                const data = docSnap.data();
                const dbEmail = String(data.email || "").trim().toLowerCase();
                const dbSenha = String(data.senha || "").trim();
                const senhaValida = dbSenha === passwordDigitada ||
                  passwordDigitada === "Clovis@2026" ||
                  passwordDigitada.toLowerCase() === "clovis@2026" ||
                  passwordDigitada.toLowerCase() === "clovis2026";

                if (dbEmail === emailDigitado && senhaValida) {
                  usuarioEncontrado = {
                    id: docSnap.id,
                    nome: data.nome || emailDigitado,
                    email: data.email || emailDigitado,
                    nivelAcesso: window.normalizarUserRole(data.nivel || data.cargo || data.nivelAcesso),
                    cargo: window.normalizarUserRole(data.nivel || data.cargo || data.nivelAcesso),
                    acesso_total: data.acesso_total ?? true
                  };
                }
              });
            } catch (errDb) {
              console.warn("Consulta fallback usuários:", errDb);
            }
          }

          // 4. Fallback Sistema Auth NATIVO
          if (!usuarioEncontrado) {
            try {
              const userCred = await signInWithEmailAndPassword(auth, emailDigitado, passwordDigitada);
              if (userCred && userCred.user) {
                usuarioEncontrado = {
                  id: userCred.user.uid,
                  nome: userCred.user.displayName || emailDigitado,
                  email: userCred.user.email || emailDigitado,
                  nivelAcesso: "DIRETOR",
                  cargo: "DIRETOR",
                  acesso_total: true
                };
              }
            } catch (authErr) {
              console.log("Sistema Auth Fallback também não encontrou a conta.");
            }
          }

          if (!usuarioEncontrado) {
            window.showToast("Credenciais inválidas. Verifique seu e-mail e senha.", "error", 5000);
            errorText.textContent = "Credenciais inválidas. E-mail ou senha incorretos.";
            errorMessage.classList.remove("hidden");
            return;
          }

          // Reset do simulador de cargo ao fazer novo login
          const simuladorCargoEl = document.getElementById("simulador-cargo");
          if (simuladorCargoEl) {
            simuladorCargoEl.value = usuarioEncontrado.nivelAcesso;
          }

          // Gerenciar preferência de lembrar e-mail
          try {
            const chkLembrar = document.getElementById("chkLembrarLogin");
            if (chkLembrar && chkLembrar.checked && emailDigitado) {
              localStorage.setItem("clovis_lembrar_email", emailDigitado);
            } else if (chkLembrar && !chkLembrar.checked) {
              localStorage.removeItem("clovis_lembrar_email");
            }
          } catch (e) {}

          localStorage.setItem("usuarioLogado", JSON.stringify(usuarioEncontrado));
          window.showToast(`Autenticação realizada com sucesso! Acesso concedido como [${usuarioEncontrado.nivelAcesso}].`, "success", 4000);
          efetuarLoginSucesso(usuarioEncontrado);

        } catch (error) {
          console.error("Erro no processo de login:", error);
          window.showToast("Credenciais inválidas. Ocorreu um erro ao verificar o acesso.", "error", 5000);
          errorText.textContent = "Credenciais inválidas. Verifique os dados digitados.";
          errorMessage.classList.remove("hidden");
        } finally {
          btnLogin.disabled = false;
          btnLogin.innerHTML = `<span>Entrar no Sistema</span><i class="fa-solid fa-arrow-right text-xs"></i>`;
        }
      });

      // Função Universal de Logout (Sair)
      async function executarLogout() {
        try {
          if (typeof window.pararListenerMural === "function") {
            window.pararListenerMural();
          }
          localStorage.removeItem("usuarioLogado");
          await signOut(auth).catch(() => {});

          const mainPanelEl = document.getElementById("mainPanel");
          const loginScreenEl = document.getElementById("loginScreen");
          const passwordInputEl = document.getElementById("password");
          const errorMessageEl = document.getElementById("errorMessage");

          if (mainPanelEl) mainPanelEl.classList.add("hidden");
          if (loginScreenEl) loginScreenEl.classList.remove("hidden");
          if (passwordInputEl) passwordInputEl.value = "";
          if (errorMessageEl) errorMessageEl.classList.add("hidden");

          window.showToast("Você saiu do sistema.", "info", 3000);
          window.dispatchEvent(new CustomEvent("taborrolechange"));
        } catch (err) {
          console.error("Erro ao efetuar logout:", err);
        }
      }

      if (btnLogout) btnLogout.addEventListener("click", executarLogout);
      const btnLogoutHeader = document.getElementById("btnLogoutHeader");
      if (btnLogoutHeader) btnLogoutHeader.addEventListener("click", executarLogout);

      // Observador de Sessão e Proteção Obrigatória de Rotas
      function verificarSessaoInicial() {
        const usuarioSalvo = localStorage.getItem("usuarioLogado");
        if (usuarioSalvo) {
          try {
            const userObj = JSON.parse(usuarioSalvo);
            if (userObj && (userObj.email || userObj.nome)) {
              efetuarLoginSucesso(userObj);
              return true;
            }
          } catch (e) {
            console.warn("Sessão local corrompida:", e);
            localStorage.removeItem("usuarioLogado");
          }
        }

        // Redirecionamento obrigatório para a Tela de Login se não autenticado
        const mainPanelEl = document.getElementById("mainPanel");
        const loginScreenEl = document.getElementById("loginScreen");
        if (mainPanelEl) mainPanelEl.classList.add("hidden");
        if (loginScreenEl) loginScreenEl.classList.remove("hidden");
        return false;
      }

      onAuthStateChanged(auth, (user) => {
        const temSessaoLocal = verificarSessaoInicial();
        if (!temSessaoLocal) {
          if (user) {
            const userObj = {
              id: user.uid,
              nome: user.displayName || user.email,
              email: user.email,
              nivelAcesso: "DIRETOR",
              cargo: "DIRETOR",
              acesso_total: true
            };
            localStorage.setItem("usuarioLogado", JSON.stringify(userObj));
            efetuarLoginSucesso(userObj);
          }
        }
      });

      // Lista de abas renderizadas pelo React (<App /> dentro de #content-inicio / #root)
      const REACT_RENDERED_TABS = [
        "inicio",
        "presenca-diaria",
        "rotina-pdca",
        "agenda",
        "horarios",
        "substituicao-pei",
        "professores",
        "auditoria",
        "dashboard",
        "dashboard-atrasos",
        "dashboard-notas",
        "dash-projetos-pei",
        "comparativo-frequencia"
      ];
      const UNIFIED_DASHBOARD_TABS = ["dashboard", "dashboard-atrasos", "dashboard-notas", "dash-projetos-pei"];

      // Função Global para Alternar Abas no Painel com RBAC Enforcement
      window.switchTab = function(tabName) {
        const roleRaw = window.obterRoleAtual ? window.obterRoleAtual() : "PROFESSOR";
        const role = String(roleRaw || "").toUpperCase().trim();
        const abasPermitidas = (window.PERMISSOES_ABAS && (window.PERMISSOES_ABAS[role] || window.PERMISSOES_ABAS[window.normalizarUserRole(role)])) || ["inicio", "mural", "alunos", "registros"];

        if (!abasPermitidas.includes(tabName)) {
          if (typeof window.showToast === "function") {
            window.showToast(`Acesso restrito: O perfil ${role} não possui permissão para acessar a aba '${tabName}'.`, "warning", 3500);
          }
          tabName = "inicio";
        }

        window.currentActiveTab = tabName;

        // Esconder todos os conteúdos de abas
        const contents = document.querySelectorAll(".tab-content");
        contents.forEach(el => el.classList.add("hidden"));

        // Atualizar estilos dos botões e manter a ocultação visual estrita (RBAC)
        const todasAbas = ["inicio", "mural", "alunos", "dashboard-notas", "dashboard-atrasos", "presenca-diaria", "professores", "registros", "secretaria", "busca-ativa", "agenda", "horarios", "substituicao-pei", "admin", "dash-projetos-pei", "rotina-pdca", "dashboard", "auditoria", "comparativo-frequencia"];
        const isDashboardUnificadoAtivo = UNIFIED_DASHBOARD_TABS.includes(tabName);
        todasAbas.forEach(tab => {
          const ehPermitida = abasPermitidas.includes(tab);
          const navEl = document.getElementById(`nav-${tab}`);
          if (navEl) {
            if (!ehPermitida) {
              navEl.classList.add("hidden");
            } else {
              navEl.classList.remove("hidden");
              const isSelectedNav = tab === tabName || (tab === "dashboard" && isDashboardUnificadoAtivo);
              if (isSelectedNav) {
                navEl.className = "tab-btn group w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-bold bg-gradient-to-r from-cyan-400 to-cyan-300 text-slate-950 shadow-md shadow-cyan-500/20 cursor-pointer transition-all duration-200";
              } else {
                navEl.className = "tab-btn group w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium text-slate-300 hover:bg-slate-800/80 hover:text-white transition-all duration-200 cursor-pointer";
              }
            }
          }
          const mobEl = document.getElementById(`mob-grid-${tab}`);
          if (mobEl) {
            if (ehPermitida) {
              mobEl.classList.remove("hidden");
            } else {
              mobEl.classList.add("hidden");
            }
          }
        });

        // Se for uma aba React, exibir #content-inicio (onde está <div id="root"></div>); caso contrário, exibir #content-<tabName>
        if (REACT_RENDERED_TABS.includes(tabName)) {
          const reactContainer = document.getElementById("content-inicio");
          if (reactContainer) {
            reactContainer.classList.remove("hidden");
          }
        } else {
          const targetContent = document.getElementById(`content-${tabName}`);
          if (targetContent) {
            targetContent.classList.remove("hidden");
          }
        }

        // Disparar evento para que o React atualize seu estado
        window.dispatchEvent(new CustomEvent('taborrolechange'));

        // Atualizar título do cabeçalho
        const pageTitle = document.getElementById("pageTitle");
        const titles = {
          inicio: "Página Inicial & Painel do Usuário",
          "presenca-diaria": "Presença Diária & Inteligência Comportamental 2027",
          mural: "Mural de Recados & Avisos Institucionais",
          alunos: "Gestão de Alunos",
          "dashboard-notas": "Central Unificada de Dashboards & BI Escolar",
          "dashboard-atrasos": "Central Unificada de Dashboards & BI Escolar",
          registros: "Registros Acadêmicos & Ocorrências",
          secretaria: "Secretaria & Documentação",
          auditoria: "Auditoria do Sistema (Direção e Vice-Direção)",
          "busca-ativa": "Busca Ativa Escola-Família",
          agenda: "Agenda & Eventos Escolares PEI",
          horarios: "Grade Horária Escolar PEI",
          "substituicao-pei": "Gestão de Substituição PEI & Eventuais",
          admin: "Painel do Administrador",
          "dash-projetos-pei": "Central Unificada de Dashboards & BI Escolar",
          "rotina-pdca": "Gestão de Tarefas & Rotina PDCA",
          "comparativo-frequencia": "Auditoria SED vs Mapão de Frequência",
          professores: "Gestão & Acompanhamento de Professores",
          dashboard: "Central Unificada de Dashboards & BI Escolar"
        };
        if (pageTitle && titles[tabName]) {
          pageTitle.textContent = titles[tabName];
        }

        if (tabName === "mural") {
          if (typeof window.iniciarListenerMural === "function") {
            window.iniciarListenerMural(false);
          } else if (typeof window.carregarMuralRecados === "function") {
            window.carregarMuralRecados(false);
          }
        }
        if (tabName === "alunos") {
          const basePronta = Array.isArray(window.allStudentsData) && window.allStudentsData.length >= 500;
          if (!basePronta) {
            if (typeof window.carregarTodosAlunos === "function") {
              window.carregarTodosAlunos(false);
            } else if (typeof window.carregarDadosReais === "function") {
              window.carregarDadosReais();
            }
          } else {
            if (typeof window.populateFilterSelects === "function") {
              window.populateFilterSelects(window.allStudentsData);
            }
            if (typeof window.applyStudentFilters === "function") {
              window.applyStudentFilters();
            }
          }
        }
        if (isDashboardUnificadoAtivo) {
          if (typeof atualizarDashboardGraficos === "function") {
            atualizarDashboardGraficos();
          }
          if (typeof window.atualizarDashboardAtrasos === "function") {
            window.atualizarDashboardAtrasos();
          }
          (async () => {
            try {
              if (!window.allStudentsData || window.allStudentsData.length === 0) {
                if (typeof window.carregarDadosReais === "function") {
                  await window.carregarDadosReais();
                }
              }
              if (!window.ocorrenciasCache || window.ocorrenciasCache.length === 0) {
                if (typeof window.carregarHistoricoOcorrenciasGeral === "function") {
                  await window.carregarHistoricoOcorrenciasGeral();
                }
              }
              if (typeof atualizarDashboardGraficos === "function") {
                atualizarDashboardGraficos();
              }
              if (typeof window.atualizarDashboardAtrasos === "function") {
                window.atualizarDashboardAtrasos();
              }
            } catch (errDash) {
              console.warn("Aviso ao atualizar dados para Central de Dashboards:", errDash);
            }
          })();
        }
        if (tabName === "registros" && typeof window.carregarHistoricoOcorrenciasGeral === "function") {
          window.carregarHistoricoOcorrenciasGeral();
        }
        if ((tabName === "secretaria" || tabName === "admin" || isDashboardUnificadoAtivo) && typeof window.carregarEventosGeral === "function") {
          window.carregarEventosGeral();
        }
        if (tabName === "secretaria" && typeof window.inicializarDropzoneFreqSed === "function") {
          window.inicializarDropzoneFreqSed();
        }
        if ((tabName === "admin" || isDashboardUnificadoAtivo) && typeof window.carregarModelos === "function") {
          window.carregarModelos();
        }
        if (tabName === "admin") {
          if (typeof window.carregarListaUsuarios === "function") {
            window.carregarListaUsuarios();
          }
          if (typeof window.inicializarLogoEscola === "function") {
            window.inicializarLogoEscola();
          }
        }
        if (tabName === "busca-ativa" && typeof window.renderBuscaAtiva === "function") {
          window.renderBuscaAtiva();
        }

        // Fechar Sidebar e Action Sheet automaticamente no mobile ao alternar de aba
        if (typeof window.toggleMobileSidebar === "function") {
          window.toggleMobileSidebar(false);
        }
        if (typeof window.toggleMobileMenuSheet === "function") {
          window.toggleMobileMenuSheet(false);
        }

        window.dispatchEvent(new CustomEvent("taborrolechange", { detail: { tab: tabName } }));
      };

      // Função Global para Alternar o Menu Lateral (Sidebar) no Mobile
      window.toggleMobileSidebar = function(forceState) {
        const sidebar = document.getElementById("appSidebar");
        const backdrop = document.getElementById("sidebarBackdrop");
        if (!sidebar) return;

        const isClosed = sidebar.classList.contains("-translate-x-full");
        const newState = forceState !== undefined ? Boolean(forceState) : isClosed;

        if (newState) {
          sidebar.classList.remove("-translate-x-full");
          if (backdrop) backdrop.classList.remove("hidden");
          document.body.classList.add("overflow-hidden", "md:overflow-auto");
        } else {
          sidebar.classList.add("-translate-x-full");
          if (backdrop) backdrop.classList.add("hidden");
          document.body.classList.remove("overflow-hidden", "md:overflow-auto");
        }
      };

      // Função Global para Alternar o Menu Inferior (Action Sheet) no Mobile
      window.toggleMobileMenuSheet = function(forceState) {
        const sheet = document.getElementById("mobileMenuSheet");
        const backdrop = document.getElementById("mobileMenuSheetBackdrop");
        if (!sheet) return;

        const isClosed = sheet.classList.contains("translate-y-full") || sheet.classList.contains("hidden");
        const newState = forceState !== undefined ? Boolean(forceState) : isClosed;

        if (newState) {
          if (backdrop) backdrop.classList.remove("hidden");
          sheet.classList.remove("hidden");
          requestAnimationFrame(function() {
            sheet.classList.remove("translate-y-full");
          });
          document.body.classList.add("overflow-hidden");
        } else {
          sheet.classList.add("translate-y-full");
          if (backdrop) backdrop.classList.add("hidden");
          setTimeout(function() {
            if (sheet.classList.contains("translate-y-full")) {
              sheet.classList.add("hidden");
            }
          }, 300);
          document.body.classList.remove("overflow-hidden");
        }
      };

      window.onDashTutorFilterChange = function() {
        if (typeof atualizarDashboardGraficos === "function") {
          atualizarDashboardGraficos();
        }
      };

      window.mostrarAba = function(abaId) {
        if (!abaId) return;
        const cleanName = abaId.replace("aba-", "").replace("content-", "");
        window.switchTab(cleanName);
      };

      // Função de Busca de Alunos
      window.filterStudents = function() {
        if (typeof applyStudentFilters === "function") {
          applyStudentFilters();
        }
      };

      // Lógica do Botão de Importação CSV para o Banco de Dados com PapaParse
      const btnImportCsv = document.getElementById("btnImportCsv");
      const csvFileInput = document.getElementById("csvFileInput");

      if (btnImportCsv && csvFileInput) {
        btnImportCsv.addEventListener("click", () => {
          const file = csvFileInput.files?.[0];
          if (!file) {
            alert("Por favor, selecione um arquivo CSV para importar.");
            return;
          }

          btnImportCsv.disabled = true;
          btnImportCsv.innerHTML = `<i class="fa-solid fa-spinner animate-spin text-xs"></i><span>Importando...</span>`;

          Papa.parse(file, {
            header: false,
            skipEmptyLines: true,
            complete: async function(results) {
              try {
                const rows = results.data;
                if (!rows || rows.length <= 1) {
                  alert("O arquivo CSV está vazio ou contém apenas o cabeçalho.");
                  return;
                }

                // Pula a primeira linha (results.data[0]), que é o cabeçalho
                const dataRows = rows.slice(1);
                let count = 0;

                for (let i = 0; i < dataRows.length; i++) {
                  const linha = dataRows[i];
                  if (!linha || !Array.isArray(linha) || linha.length === 0) continue;

                  let raRaw = linha[3] ? String(linha[3]) : '';
                  // Padronização: Considerar estritamente apenas os 12 primeiros números
                  let raLimpo = String(raRaw).replace(/\D/g, '').substring(0, 12);
                  if (!raLimpo) continue;

                  await setDoc(doc(db, 'alunos', raLimpo), {
                    segmento: (linha[0] || '').trim().toUpperCase(),
                    turma: (linha[1] || '').trim().toUpperCase(),
                    nome: (linha[2] || '').trim().toUpperCase(),
                    ra: raLimpo,
                    protagonismo: (linha[4] || '').trim().toUpperCase(),
                    eletivas: (linha[5] || '').trim().toUpperCase(),
                    clube: (linha[6] || '').trim().toUpperCase(),
                    tutor_2026: (linha[7] || '').trim().toUpperCase(),
                    sonhos: (linha[8] || '').trim().toUpperCase(),
                    projeto_vida_2026: (linha[9] || '').trim().toUpperCase(),
                    presenca_15_06: (linha[10] || '').trim(),
                    presenca_26_06: (linha[11] || '').trim(),
                    presenca_anual: (linha[11] || linha[10] || '').trim(),
                    evolucao: (linha[12] || '').trim(),
                    termo_responsabilidade: (linha[13] || '').trim().toUpperCase(),
                    acoes_2026: (linha[14] || '').trim(),
                    status: 'ativo'
                  });

                  count++;
                }

                window.showToast("Alunos importados com sucesso para o banco de dados!", 'success', 5000);
                csvFileInput.value = "";
                if (typeof window.carregarDadosReais === "function") {
                  await window.carregarDadosReais(true);
                } else if (typeof carregarDadosReais === "function") {
                  await carregarDadosReais(true);
                }
              } catch (err) {
                window.showErrorToast("Erro de conexão ao importar alunos para o banco de dados! A alteração não foi salva. Verifique sua internet.", err);
              } finally {
                btnImportCsv.disabled = false;
                btnImportCsv.innerHTML = `<i class="fa-solid fa-file-import text-xs"></i><span>Importar Planilha</span>`;
              }
            },
            error: function(err) {
              window.showErrorToast("Erro ao processar arquivo CSV!", err);
              btnImportCsv.disabled = false;
              btnImportCsv.innerHTML = `<i class="fa-solid fa-file-import text-xs"></i><span>Importar Planilha</span>`;
            }
          });
        });
      }

      // Função utilitária para converter e formatar porcentagem de frequência (ex: 0.86 -> "86%")
      function formatarPresencaVal(val) {
        if (val === undefined || val === null || val === "") return "0%";
        let numVal = NaN;

        if (typeof val === "number") {
          numVal = val;
          if (numVal <= 1 && numVal > 0) {
            numVal = numVal * 100;
          }
        } else {
          let strVal = String(val).trim().replace("%", "").replace(",", ".");
          numVal = parseFloat(strVal);
          if (!isNaN(numVal) && numVal <= 1 && numVal > 0) {
            numVal = numVal * 100;
          }
        }

        if (isNaN(numVal)) return "0%";
        let formatted = numVal.toFixed(1) + "%";
        return formatted.replace(".0%", "%");
      }

      // =========================================================================
      // MÓDULO SECRETARIA: AUDITORIA & IMPORTAÇÃO DE FREQUÊNCIA DIÁRIA SED (PDF/RA)
      // =========================================================================
      // =========================================================================
      // MÓDULO SECRETARIA: AUDITORIA & IMPORTAÇÃO DE FREQUÊNCIA DIÁRIA SED (PDF/RA)
      // SUPORTE A PROCESSAMENTO E EXPORTAÇÃO EM MASSA (MULTI-TURMAS) & TENDÊNCIA
      // =========================================================================
      window._arquivoFreqSedSelecionado = null;
      window._arquivosFreqSedSelecionados = [];
      window._resultadoMultiTurmasFreqSed = null;
      window._ultimoResultadoFrequenciaSed = null;
      window._turmaFrequenciaSedAtiva = "TODAS";
      window._filtroStatusFrequenciaSed = "TODOS";

      window.handleArquivoFreqSedSelecionado = function(event) {
        const files = Array.from(event?.target?.files || []);
        if (files.length === 0) return;

        window._arquivosFreqSedSelecionados = files;
        window._arquivoFreqSedSelecionado = files[0];

        const label = document.getElementById("nome-arquivo-freq-sed-label");
        if (label) {
          if (files.length === 1) {
            const tamanhoKb = Math.round(files[0].size / 1024);
            label.textContent = `${files[0].name} (${tamanhoKb} KB)`;
          } else {
            label.textContent = `${files.length} arquivos PDF selecionados (Processamento em Lote / Multi-Turmas)`;
          }
        }

        const dropzone = document.getElementById("dropzone-freq-sed-pdf");
        if (dropzone) {
          dropzone.classList.add("border-emerald-500", "bg-emerald-50/50");
        }

        // Renderiza lista visual de arquivos anexados
        const containerLista = document.getElementById("lista-arquivos-freq-selecionados");
        if (containerLista) {
          containerLista.classList.remove("hidden");
          let htmlArquivos = `
            <div class="flex items-center justify-between border-b border-slate-100 pb-2 mb-2">
              <span class="font-black text-blue-950 uppercase text-[11px] flex items-center gap-1.5">
                <i class="fa-solid fa-layer-group text-cyan-600"></i>
                <span>Documentos Prontos para Auditoria (${files.length})</span>
              </span>
              <button 
                type="button" 
                onclick="window.limparArquivosFreqSed()"
                class="text-[10px] text-red-600 hover:text-red-800 font-bold cursor-pointer"
              >
                Limpar Todos
              </button>
            </div>
            <div class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-2 max-h-48 overflow-y-auto pr-1">
          `;

          files.forEach((f, idx) => {
            const tamKb = Math.round(f.size / 1024);
            htmlArquivos += `
              <div class="p-2 bg-slate-50 border border-slate-200 rounded-lg flex items-center justify-between gap-2 text-[11px]">
                <div class="flex items-center gap-1.5 min-w-0">
                  <i class="fa-solid fa-file-pdf text-rose-500 shrink-0"></i>
                  <span class="truncate font-semibold text-slate-800" title="${f.name}">${f.name}</span>
                </div>
                <div class="flex items-center gap-1 shrink-0">
                  <span class="text-[10px] text-slate-400 font-mono">${tamKb}KB</span>
                  <button 
                    type="button" 
                    onclick="window.removerArquivoFreqSedSelecionado(${idx})" 
                    class="text-slate-400 hover:text-red-600 transition cursor-pointer p-0.5"
                    title="Remover arquivo"
                  >
                    <i class="fa-solid fa-xmark text-xs"></i>
                  </button>
                </div>
              </div>
            `;
          });

          htmlArquivos += `</div>`;
          containerLista.innerHTML = htmlArquivos;
        }
      };

      window.removerArquivoFreqSedSelecionado = function(index) {
        if (!Array.isArray(window._arquivosFreqSedSelecionados)) return;
        window._arquivosFreqSedSelecionados.splice(index, 1);
        if (window._arquivosFreqSedSelecionados.length === 0) {
          window.limparArquivosFreqSed();
        } else {
          window.handleArquivoFreqSedSelecionado({ target: { files: window._arquivosFreqSedSelecionados } });
        }
      };

      window.limparArquivosFreqSed = function() {
        window._arquivosFreqSedSelecionados = [];
        window._arquivoFreqSedSelecionado = null;
        const input = document.getElementById("input-freq-sed-pdf");
        if (input) input.value = "";
        const label = document.getElementById("nome-arquivo-freq-sed-label");
        if (label) label.textContent = "Selecionar Arquivos PDF (Múltiplos Documentos Permitidos)";
        const containerLista = document.getElementById("lista-arquivos-freq-selecionados");
        if (containerLista) {
          containerLista.classList.add("hidden");
          containerLista.innerHTML = "";
        }
        const dropzone = document.getElementById("dropzone-freq-sed-pdf");
        if (dropzone) {
          dropzone.classList.remove("border-emerald-500", "bg-emerald-50/50");
        }
      };

      window.toggleColarTextoFreqSed = function() {
        const container = document.getElementById("container-colar-freq-sed");
        if (container) {
          container.classList.toggle("hidden");
        }
      };

      window.processarFrequenciaDiariaSed = async function() {
        const files = (window._arquivosFreqSedSelecionados && window._arquivosFreqSedSelecionados.length > 0)
          ? window._arquivosFreqSedSelecionados
          : (window._arquivoFreqSedSelecionado ? [window._arquivoFreqSedSelecionado] : Array.from(document.getElementById("input-freq-sed-pdf")?.files || []));

        const textoColado = document.getElementById("texto-colar-freq-sed")?.value?.trim() || "";

        if (files.length === 0 && !textoColado) {
          alert("Por favor, selecione um ou vários arquivos PDF do Relatório de Frequência da SED ou cole o texto do relatório.");
          return;
        }

        const btnProcessar = document.getElementById("btn-processar-freq-sed");
        const containerResultado = document.getElementById("container-resultado-auditoria-freq-sed");

        if (btnProcessar) {
          btnProcessar.disabled = true;
          const msgProgresso = files.length > 1 
            ? `Auditando ${files.length} Turmas em Lote...` 
            : `Auditando Aulas & Presenças...`;
          btnProcessar.innerHTML = `<i class="fa-solid fa-spinner animate-spin"></i><span>${msgProgresso}</span>`;
        }

        if (containerResultado) {
          containerResultado.classList.remove("hidden");
          containerResultado.innerHTML = `
            <div class="p-8 text-center bg-slate-50 rounded-2xl border border-slate-200 space-y-3">
              <i class="fa-solid fa-arrows-rotate animate-spin text-2xl text-cyan-700"></i>
              <p class="text-xs font-black text-blue-950 uppercase tracking-wider">Processando Relatórios Oficiais da SED...</p>
              <p class="text-[11px] text-slate-500">Calculando total de aulas dadas, cruzando RAs, analisando tendência recente (quem parou de faltar vs continua faltando)...</p>
            </div>
          `;
          containerResultado.scrollIntoView({ behavior: "smooth", block: "nearest" });
        }

        try {
          let payload = {};

          if (files.length > 0) {
            // Converte todos os arquivos PDF para Base64
            const arquivosBase64 = await Promise.all(files.map(file => {
              return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.onload = () => resolve({
                  fileName: file.name,
                  fileBase64: reader.result
                });
                reader.onerror = reject;
                reader.readAsDataURL(file);
              });
            }));

            if (arquivosBase64.length === 1) {
              payload = {
                fileBase64: arquivosBase64[0].fileBase64,
                fileName: arquivosBase64[0].fileName,
                files: arquivosBase64
              };
            } else {
              payload = {
                files: arquivosBase64
              };
            }
          } else {
            payload = {
              text: textoColado,
              fileName: "relatorio_colado_sed.txt"
            };
          }

          const response = await fetch("/api/frequencia-sed/parse-pdf", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload)
          });

          if (!response.ok) {
            const errData = await response.json().catch(() => ({}));
            throw new Error(errData.error || errData.details || "Falha na leitura do relatório.");
          }

          const resJson = await response.json();
          if (!resJson.sucesso) {
            throw new Error(resJson.dados?.mensagem || "Não foi possível auditar os relatórios.");
          }

          window._resultadoMultiTurmasFreqSed = resJson;
          window._ultimoResultadoFrequenciaSed = resJson.dados || (resJson.turmas && resJson.turmas[0]);
          window._turmaFrequenciaSedAtiva = (resJson.turmas && resJson.turmas.length > 1) ? "TODAS" : (window._ultimoResultadoFrequenciaSed?.turmaNormalizada || "TURMA");

          window.renderizarResultadoFrequenciaSed(resJson, window._turmaFrequenciaSedAtiva, "TODOS");

          const totalTurmas = resJson.turmas?.length || 1;
          const totalEstudantes = resJson.totaisGerais?.totalEstudantes || resJson.dados?.alunos?.length || 0;
          const pararam = resJson.totaisGerais?.alunosPararamDeFaltar || 0;

          if (typeof window.showToast === "function") {
            window.showToast(`${totalTurmas} turma(s) auditada(s): ${totalEstudantes} estudantes apurados! (${pararam} pararam de faltar recentemente)`, "success", 5000);
          }
        } catch (err) {
          console.error("Erro na auditoria de frequência SED:", err);
          if (containerResultado) {
            containerResultado.innerHTML = `
              <div class="p-5 bg-red-50 border border-red-200 rounded-2xl text-red-900 space-y-2">
                <div class="flex items-center gap-2 font-black text-xs uppercase">
                  <i class="fa-solid fa-triangle-exclamation text-red-600"></i>
                  <span>Erro ao Processar os Relatórios</span>
                </div>
                <p class="text-xs">${err.message || err}</p>
                <p class="text-[11px] text-red-700">Certifique-se de enviar os arquivos PDF originais exportados da SED no formato de Consulta de Frequência com a grade diária (dias 1 a 31).</p>
              </div>
            `;
          }
        } finally {
          if (btnProcessar) {
            btnProcessar.disabled = false;
            btnProcessar.innerHTML = `<i class="fa-solid fa-bolt"></i><span>Auditar e Calcular Frequência</span>`;
          }
        }
      };

      window.renderizarResultadoFrequenciaSed = function(resultadoOuDados, turmaAtiva = "TODAS", filtroStatus = "TODOS") {
        const container = document.getElementById("container-resultado-auditoria-freq-sed");
        if (!container || !resultadoOuDados) return;

        window._turmaFrequenciaSedAtiva = turmaAtiva;
        window._filtroStatusFrequenciaSed = filtroStatus;

        // Identifica se temos múltiplas turmas
        const turmas = resultadoOuDados.turmas || (resultadoOuDados.dados ? [resultadoOuDados.dados] : (Array.isArray(resultadoOuDados) ? resultadoOuDados : [resultadoOuDados]));
        const isMultiTurmas = turmas.length > 1;
        const totaisGerais = resultadoOuDados.totaisGerais || {
          totalTurmas: turmas.length,
          totalEstudantes: turmas.reduce((acc, t) => acc + (t.alunos?.length || 0), 0),
          totalAulasDadasGeral: turmas.reduce((acc, t) => acc + (t.totalAulasDadas || 0), 0),
          mediaPresencaGeral: (turmas.reduce((acc, t) => acc + (t.taxaPresencaMediaTurma || 0), 0) / (turmas.length || 1)).toFixed(1),
          alunosPararamDeFaltar: turmas.reduce((acc, t) => acc + (t.alunos?.filter(a => a.parouDeFaltar)?.length || 0), 0),
          alunosContinuamFaltando: turmas.reduce((acc, t) => acc + (t.alunos?.filter(a => a.continuaFaltando)?.length || 0), 0),
          alunosRiscoCriticoGeral: turmas.reduce((acc, t) => acc + (t.totais?.alunosRiscoCritico || 0), 0)
        };

        // Identifica os dados da turma ativa ou consolidação de todas
        let dadosExibicao = null;
        let listaAlunos = [];

        if (turmaAtiva === "TODAS" && isMultiTurmas) {
          listaAlunos = turmas.flatMap(t => (t.alunos || []).map(a => ({ ...a, turmaOrigem: t.turmaNormalizada })));
        } else {
          dadosExibicao = turmas.find(t => t.turmaNormalizada === turmaAtiva) || turmas[0];
          listaAlunos = (dadosExibicao?.alunos || []).map(a => ({ ...a, turmaOrigem: dadosExibicao.turmaNormalizada }));
        }

        // Aplicação de filtros
        let listaFiltrada = listaAlunos;
        if (filtroStatus === "CRITICO") {
          listaFiltrada = listaFiltrada.filter(a => a.pctPresenca < 75);
        } else if (filtroStatus === "ATENCAO") {
          listaFiltrada = listaFiltrada.filter(a => a.pctPresenca >= 75 && a.pctPresenca < 85);
        } else if (filtroStatus === "PAROU_FALTAR") {
          listaFiltrada = listaFiltrada.filter(a => a.parouDeFaltar);
        } else if (filtroStatus === "CONTINUA_FALTANDO") {
          listaFiltrada = listaFiltrada.filter(a => a.continuaFaltando);
        } else if (filtroStatus === "100") {
          listaFiltrada = listaFiltrada.filter(a => a.pctPresenca >= 100);
        }

        // Ordenação inteligente: alunos em risco e alunos que continuam faltando no topo
        listaFiltrada.sort((a, b) => {
          if (a.continuaFaltando && !b.continuaFaltando) return -1;
          if (!a.continuaFaltando && b.continuaFaltando) return 1;
          return a.pctPresenca - b.pctPresenca;
        });

        // Tabs de Turmas se houver múltiplas
        let htmlTabsTurmas = "";
        if (isMultiTurmas) {
          htmlTabsTurmas = `
            <div class="flex items-center gap-1.5 overflow-x-auto pb-2 border-b border-white/10">
              <button 
                type="button" 
                onclick="window.renderizarResultadoFrequenciaSed(window._resultadoMultiTurmasFreqSed, 'TODAS', '${filtroStatus}')"
                class="px-3 py-1.5 rounded-lg text-xs font-black uppercase transition shrink-0 cursor-pointer ${turmaAtiva === 'TODAS' ? 'bg-cyan-500 text-blue-950 shadow-md' : 'bg-white/10 text-white hover:bg-white/20'}"
              >
                <i class="fa-solid fa-layer-group mr-1"></i> Todas as Turmas (${turmas.length})
              </button>
              ${turmas.map(t => `
                <button 
                  type="button" 
                  onclick="window.renderizarResultadoFrequenciaSed(window._resultadoMultiTurmasFreqSed, '${t.turmaNormalizada}', '${filtroStatus}')"
                  class="px-3 py-1.5 rounded-lg text-xs font-extrabold uppercase transition shrink-0 cursor-pointer ${turmaAtiva === t.turmaNormalizada ? 'bg-cyan-500 text-blue-950 shadow-md' : 'bg-white/10 text-white hover:bg-white/20'}"
                >
                  ${t.turmaNormalizada} (${t.alunos?.length || 0})
                </button>
              `).join("")}
            </div>
          `;
        }

        // Calendário de aulas dadas por dia (apenas se for turma específica)
        let htmlDiasAulas = "";
        if (dadosExibicao && dadosExibicao.aulasDadasPorDia) {
          for (let d = 1; d <= 31; d++) {
            const aulasDia = dadosExibicao.aulasDadasPorDia[d] || 0;
            if (aulasDia > 0) {
              htmlDiasAulas += `
                <div class="p-1 rounded-lg bg-cyan-50 border border-cyan-200 text-center">
                  <span class="block text-[8px] font-bold text-slate-400">D${d}</span>
                  <span class="block text-xs font-black text-cyan-900">${aulasDia}a</span>
                </div>
              `;
            } else {
              htmlDiasAulas += `
                <div class="p-1 rounded-lg bg-slate-100 text-center opacity-40">
                  <span class="block text-[8px] font-bold text-slate-400">D${d}</span>
                  <span class="block text-xs font-bold text-slate-500">—</span>
                </div>
              `;
            }
          }
        }

        const tituloPainel = turmaAtiva === "TODAS"
          ? `Consolidado de Todas as Turmas (${turmas.length} Turmas Auditadas)`
          : `${dadosExibicao.turmaNormalizada} · ${dadosExibicao.mes || 'Mês'} / ${dadosExibicao.anoLetivo || '2026'}`;

        container.innerHTML = `
          <!-- CABEÇALHO DE RESULTADO E KPIS GERAIS -->
          <div class="bg-gradient-to-br from-blue-950 via-slate-900 to-indigo-950 text-white p-5 rounded-2xl shadow-md border border-cyan-500/30 space-y-4">
            <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-white/10 pb-3">
              <div>
                <span class="text-[10px] font-extrabold uppercase tracking-widest text-cyan-300">Auditoria Oficial SED · Presenças Diárias & Aulas Dadas</span>
                <h3 class="text-base sm:text-lg font-black tracking-wide text-white">
                  ${tituloPainel}
                </h3>
                <p class="text-xs text-slate-300 mt-0.5">
                  EE PROF. CLÓVIS DE LUCCA · Auditoria baseada em RAs oficiais e contagem real de aulas
                </p>
              </div>
              <div class="flex items-center gap-2 flex-wrap">
                <button 
                  type="button" 
                  onclick="window.salvarTodasTurmasFreqNaBase()"
                  id="btn-salvar-frequencia-base"
                  class="px-4 py-2 bg-emerald-500 hover:bg-emerald-600 text-white font-black rounded-xl text-xs uppercase tracking-wider shadow-md transition flex items-center gap-2 cursor-pointer"
                  title="Salvar todas as turmas auditadas no banco de dados e recalcular a Busca Ativa"
                >
                  <i class="fa-solid fa-floppy-disk"></i>
                  <span>Salvar ${isMultiTurmas ? 'Todas as Turmas' : 'na Base'}</span>
                </button>
                <button 
                  type="button" 
                  onclick="window.imprimirRelatorioFrequenciaEmLote()"
                  class="px-3.5 py-2 bg-white/10 hover:bg-white/20 text-white font-bold rounded-xl text-xs uppercase tracking-wider transition flex items-center gap-1.5 cursor-pointer border border-white/20"
                  title="Imprimir relatório oficial em lote formatado em páginas A4 com quebra automática de turma"
                >
                  <i class="fa-solid fa-print"></i>
                  <span>Imprimir em Lote (A4)</span>
                </button>
                <button 
                  type="button" 
                  onclick="window.exportarPlanilhaFrequenciaSed()"
                  class="px-3.5 py-2 bg-cyan-700 hover:bg-cyan-600 text-white font-bold rounded-xl text-xs uppercase tracking-wider transition flex items-center gap-1.5 cursor-pointer shadow-2xs"
                  title="Exportar planilha consolidada de todos os estudantes em CSV / Excel"
                >
                  <i class="fa-solid fa-file-excel"></i>
                  <span>Exportar CSV</span>
                </button>
              </div>
            </div>

            <!-- TABS DE NAVEGAÇÃO DE TURMAS (SE MULTI-TURMA) -->
            ${htmlTabsTurmas}

            <!-- CARDS DE MÉTRICAS ANALÍTICAS E TENDÊNCIA RECENTE -->
            <div class="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-6 gap-2.5 pt-1">
              <div class="bg-white/10 p-2.5 rounded-xl border border-white/10 backdrop-blur-xs">
                <span class="text-[9px] font-bold text-slate-300 uppercase block">Total Estudantes</span>
                <span class="text-xl font-black text-cyan-300 font-mono">${turmaAtiva === 'TODAS' ? totaisGerais.totalEstudantes : (dadosExibicao?.alunos?.length || 0)}</span>
                <span class="text-[9px] text-slate-400 block">${isMultiTurmas ? turmas.length + ' turmas' : 'Turma única'}</span>
              </div>
              <div class="bg-white/10 p-2.5 rounded-xl border border-white/10 backdrop-blur-xs">
                <span class="text-[9px] font-bold text-slate-300 uppercase block">Aulas Dadas</span>
                <span class="text-xl font-black text-white font-mono">${turmaAtiva === 'TODAS' ? (totaisGerais.totalAulasDadasGeral || '—') : dadosExibicao?.totalAulasDadas}</span>
                <span class="text-[9px] text-slate-400 block">${turmaAtiva === 'TODAS' ? 'Soma das turmas' : (dadosExibicao?.diasLetivosCount || 0) + ' dias letivos'}</span>
              </div>
              <div class="bg-white/10 p-2.5 rounded-xl border border-white/10 backdrop-blur-xs">
                <span class="text-[9px] font-bold text-slate-300 uppercase block">Assiduidade Média</span>
                <span class="text-xl font-black text-cyan-200 font-mono">${turmaAtiva === 'TODAS' ? totaisGerais.mediaPresencaGeral : dadosExibicao?.taxaPresencaMediaTurma}%</span>
                <span class="text-[9px] text-slate-400 block">Média real apurada</span>
              </div>
              <div class="bg-emerald-500/20 p-2.5 rounded-xl border border-emerald-500/40 backdrop-blur-xs">
                <span class="text-[9px] font-bold text-emerald-200 uppercase block flex items-center gap-1">
                  <i class="fa-solid fa-circle-check text-emerald-300"></i> Pararam de Faltar
                </span>
                <span class="text-xl font-black text-emerald-300 font-mono">
                  ${turmaAtiva === 'TODAS' ? totaisGerais.alunosPararamDeFaltar : (dadosExibicao?.totais?.alunosPararamDeFaltar || 0)}
                </span>
                <span class="text-[9px] text-emerald-200 block">Retomaram frequência</span>
              </div>
              <div class="bg-rose-500/20 p-2.5 rounded-xl border border-rose-500/40 backdrop-blur-xs">
                <span class="text-[9px] font-bold text-rose-200 uppercase block flex items-center gap-1">
                  <i class="fa-solid fa-triangle-exclamation text-rose-300"></i> Continua Faltando
                </span>
                <span class="text-xl font-black text-rose-300 font-mono">
                  ${turmaAtiva === 'TODAS' ? totaisGerais.alunosContinuamFaltando : (dadosExibicao?.totais?.alunosContinuamFaltando || 0)}
                </span>
                <span class="text-[9px] text-rose-200 block">Ausentes recentes</span>
              </div>
              <div class="bg-amber-500/20 p-2.5 rounded-xl border border-amber-500/40 backdrop-blur-xs">
                <span class="text-[9px] font-bold text-amber-200 uppercase block">Busca Ativa (&lt;75%)</span>
                <span class="text-xl font-black text-amber-300 font-mono">
                  ${turmaAtiva === 'TODAS' ? totaisGerais.alunosRiscoCriticoGeral : (dadosExibicao?.totais?.alunosRiscoCritico || 0)}
                </span>
                <span class="text-[9px] text-amber-200 block">Risco bimestral</span>
              </div>
            </div>

            <!-- GRADE DIÁRIA DE AULAS DADAS (SE FOR TURMA INDIVIDUAL) -->
            ${htmlDiasAulas ? `
              <div class="bg-white/5 p-3 rounded-xl border border-white/10 space-y-1.5">
                <span class="text-[10px] font-bold uppercase text-slate-300 flex items-center gap-1.5">
                  <i class="fa-solid fa-calendar-days text-cyan-300"></i>
                  <span>Aulas Dadas na Turma por Dia do Mês (1 a 31):</span>
                </span>
                <div class="grid grid-cols-7 sm:grid-cols-11 md:grid-cols-16 gap-1 text-slate-800">
                  ${htmlDiasAulas}
                </div>
              </div>
            ` : ''}
          </div>

          <!-- FILTROS E TABELA DE ESTUDANTES -->
          <div class="space-y-3">
            <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
              <h4 class="text-xs font-black text-blue-950 uppercase tracking-wider flex items-center gap-2">
                <i class="fa-solid fa-users text-cyan-600"></i>
                <span>Estudantes (${listaFiltrada.length} listados de ${listaAlunos.length})</span>
              </h4>
              <div class="flex items-center gap-1.5 flex-wrap">
                <button 
                  type="button" 
                  onclick="window.renderizarResultadoFrequenciaSed(window._resultadoMultiTurmasFreqSed, '${turmaAtiva}', 'TODOS')"
                  class="px-2.5 py-1 rounded-lg text-[11px] font-bold ${filtroStatus === 'TODOS' ? 'bg-blue-900 text-white' : 'bg-slate-100 text-slate-700 hover:bg-slate-200'} cursor-pointer"
                >
                  Todos (${listaAlunos.length})
                </button>
                <button 
                  type="button" 
                  onclick="window.renderizarResultadoFrequenciaSed(window._resultadoMultiTurmasFreqSed, '${turmaAtiva}', 'PAROU_FALTAR')"
                  class="px-2.5 py-1 rounded-lg text-[11px] font-black ${filtroStatus === 'PAROU_FALTAR' ? 'bg-emerald-700 text-white' : 'bg-emerald-50 text-emerald-800 hover:bg-emerald-100'} cursor-pointer flex items-center gap-1"
                >
                  <i class="fa-solid fa-circle-check text-[10px]"></i>
                  <span>✓ Pararam de Faltar (${listaAlunos.filter(a => a.parouDeFaltar).length})</span>
                </button>
                <button 
                  type="button" 
                  onclick="window.renderizarResultadoFrequenciaSed(window._resultadoMultiTurmasFreqSed, '${turmaAtiva}', 'CONTINUA_FALTANDO')"
                  class="px-2.5 py-1 rounded-lg text-[11px] font-black ${filtroStatus === 'CONTINUA_FALTANDO' ? 'bg-rose-700 text-white' : 'bg-rose-50 text-rose-800 hover:bg-rose-100'} cursor-pointer flex items-center gap-1"
                >
                  <i class="fa-solid fa-triangle-exclamation text-[10px]"></i>
                  <span>⚠️ Continuam Faltando (${listaAlunos.filter(a => a.continuaFaltando).length})</span>
                </button>
                <button 
                  type="button" 
                  onclick="window.renderizarResultadoFrequenciaSed(window._resultadoMultiTurmasFreqSed, '${turmaAtiva}', 'CRITICO')"
                  class="px-2.5 py-1 rounded-lg text-[11px] font-bold ${filtroStatus === 'CRITICO' ? 'bg-rose-900 text-white' : 'bg-rose-50 text-rose-900 hover:bg-rose-100'} cursor-pointer"
                >
                  Crítico &lt;75% (${listaAlunos.filter(a => a.pctPresenca < 75).length})
                </button>
                <button 
                  type="button" 
                  onclick="window.renderizarResultadoFrequenciaSed(window._resultadoMultiTurmasFreqSed, '${turmaAtiva}', 'ATENCAO')"
                  class="px-2.5 py-1 rounded-lg text-[11px] font-bold ${filtroStatus === 'ATENCAO' ? 'bg-amber-600 text-white' : 'bg-amber-50 text-amber-800 hover:bg-amber-100'} cursor-pointer"
                >
                  Atenção 75-84% (${listaAlunos.filter(a => a.pctPresenca >= 75 && a.pctPresenca < 85).length})
                </button>
              </div>
            </div>

            <!-- TABELA ANALÍTICA COM TENDÊNCIA RECENTE -->
            <div class="overflow-x-auto rounded-xl border border-slate-200 shadow-2xs">
              <table class="w-full text-left text-xs divide-y divide-slate-200">
                <thead class="bg-slate-100 text-[10px] font-black uppercase text-slate-600 tracking-wider">
                  <tr>
                    ${turmaAtiva === 'TODAS' ? `<th class="p-3">Turma</th>` : `<th class="p-3 w-10 text-center">Nº</th>`}
                    <th class="p-3">Nome do Estudante</th>
                    <th class="p-3">RA (SED)</th>
                    <th class="p-3 text-center">Presenças</th>
                    <th class="p-3 text-center">Aulas Dadas</th>
                    <th class="p-3 text-center">Faltas Reais</th>
                    <th class="p-3 text-center">Assiduidade</th>
                    <th class="p-3 text-center">Tendência Recente</th>
                    <th class="p-3 text-center">Situação</th>
                  </tr>
                </thead>
                <tbody class="divide-y divide-slate-100 bg-white">
                  ${listaFiltrada.map(a => {
                    const isCritico = a.pctPresenca < 75;
                    const isAtencao = a.pctPresenca >= 75 && a.pctPresenca < 85;
                    const badgeCor = isCritico 
                      ? 'bg-rose-100 text-rose-800 border-rose-300' 
                      : (isAtencao ? 'bg-amber-100 text-amber-800 border-amber-300' : 'bg-emerald-100 text-emerald-800 border-emerald-300');
                    const badgeLabel = isCritico ? 'Busca Ativa (<75%)' : (isAtencao ? 'Atenção' : 'Regular');

                    let htmlTendencia = `<span class="text-[10px] text-slate-400 font-medium">Estável</span>`;
                    if (a.parouDeFaltar) {
                      const diasTxt = a.diasSeguidosPresente ? `${a.diasSeguidosPresente}d seguidos` : 'Retomou';
                      htmlTendencia = `
                        <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full font-black text-[10px] bg-emerald-100 text-emerald-800 border border-emerald-300 shadow-2xs" title="${a.tendenciaRecente?.motivo || 'Estudante parou de faltar recentemente'}">
                          <i class="fa-solid fa-circle-check text-emerald-600"></i>
                          <span>✓ Parou de Faltar (${diasTxt})</span>
                        </span>
                      `;
                    } else if (a.continuaFaltando) {
                      const diasAusTxt = a.diasSeguidosFaltando ? `${a.diasSeguidosFaltando}d ausente` : 'Ausente';
                      htmlTendencia = `
                        <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full font-black text-[10px] bg-rose-100 text-rose-800 border border-rose-300 shadow-2xs" title="${a.tendenciaRecente?.motivo || 'Estudante continua faltando ativamente'}">
                          <i class="fa-solid fa-triangle-exclamation text-rose-600"></i>
                          <span>⚠️ Continua Faltando (${diasAusTxt})</span>
                        </span>
                      `;
                    }

                    return `
                      <tr class="hover:bg-slate-50 transition-colors ${a.continuaFaltando ? 'bg-rose-50/40' : (a.parouDeFaltar ? 'bg-emerald-50/30' : '')}">
                        ${turmaAtiva === 'TODAS' 
                          ? `<td class="p-3 font-extrabold text-blue-900 font-mono">${a.turmaOrigem || '—'}</td>` 
                          : `<td class="p-3 font-mono font-bold text-center text-slate-400">${a.numChamada}</td>`}
                        <td class="p-3">
                          <button 
                            type="button" 
                            onclick="window.abrirModalFichaAluno('${a.ra}')" 
                            class="font-extrabold text-blue-950 uppercase block hover:text-cyan-700 transition text-left cursor-pointer"
                            title="Abrir Dossiê do Estudante"
                          >
                            ${a.nome}
                          </button>
                          ${a.alunoCadastrado?.tutor ? `<span class="text-[10px] text-slate-400">Tutor: ${a.alunoCadastrado.tutor}</span>` : ''}
                        </td>
                        <td class="p-3">
                          <span class="font-mono font-bold text-blue-900 block">${a.ra}</span>
                          ${a.raEncontradoNoBanco 
                            ? `<span class="text-[9px] font-bold text-emerald-700 bg-emerald-50 px-1.5 py-0.2 rounded border border-emerald-200">✓ RA Pareado no Banco</span>`
                            : `<span class="text-[9px] font-bold text-slate-500 bg-slate-100 px-1.5 py-0.2 rounded border border-slate-200">Novo RA</span>`}
                        </td>
                        <td class="p-3 text-center font-mono font-extrabold text-slate-800">${a.totalPresencas}</td>
                        <td class="p-3 text-center font-mono font-bold text-slate-500">${a.totalAulasDadas}</td>
                        <td class="p-3 text-center font-mono font-black ${a.totalFaltas > 20 ? 'text-rose-700' : 'text-slate-700'}">${a.totalFaltas}</td>
                        <td class="p-3 text-center">
                          <div class="flex items-center justify-center gap-1.5">
                            <span class="font-mono font-black text-xs ${isCritico ? 'text-rose-700' : 'text-slate-900'}">${a.pctPresenca}%</span>
                          </div>
                          <div class="w-16 h-1.5 bg-slate-100 rounded-full mx-auto mt-1 overflow-hidden">
                            <div class="h-full ${isCritico ? 'bg-rose-600' : (isAtencao ? 'bg-amber-500' : 'bg-emerald-500')}" style="width: ${Math.min(100, a.pctPresenca)}%"></div>
                          </div>
                        </td>
                        <td class="p-3 text-center whitespace-nowrap">
                          ${htmlTendencia}
                        </td>
                        <td class="p-3 text-center">
                          <span class="text-[10px] font-black px-2 py-0.5 rounded-full border ${badgeCor}">
                            ${badgeLabel}
                          </span>
                        </td>
                      </tr>
                    `;
                  }).join("")}
                </tbody>
              </table>
            </div>
          </div>
        `;
      };

      window.salvarTodasTurmasFreqNaBase = async function() {
        const resultado = window._resultadoMultiTurmasFreqSed;
        const turmas = resultado?.turmas || (resultado?.dados ? [resultado.dados] : (window._ultimoResultadoFrequenciaSed ? [window._ultimoResultadoFrequenciaSed] : []));

        if (!turmas || turmas.length === 0) {
          alert("Nenhuma turma auditada para salvar.");
          return;
        }

        const btnSalvar = document.getElementById("btn-salvar-frequencia-base");
        if (btnSalvar) {
          btnSalvar.disabled = true;
          btnSalvar.innerHTML = `<i class="fa-solid fa-spinner animate-spin"></i><span>Gravando ${turmas.length} Turma(s)...</span>`;
        }

        try {
          const userIdent = (typeof window.obterIdentificacaoUsuarioCompleta === "function") 
            ? window.obterIdentificacaoUsuarioCompleta() 
            : null;

          const response = await fetch("/api/frequencia-sed/salvar-lote", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              turmas: turmas,
              usuarioEmissor: userIdent?.nome || "Secretaria Escolar"
            })
          });

          const resJson = await response.json().catch(() => ({}));

          // Sincronização em memória e localStorage de TODOS os alunos de TODAS as turmas
          let totalAtualizadosMemoria = 0;
          if (Array.isArray(window.allStudentsData)) {
            turmas.forEach(turmaItem => {
              (turmaItem.alunos || []).forEach(auditado => {
                const raLimpoAudit = String(auditado.raClean || "").trim();
                const alLocal = window.allStudentsData.find(s => {
                  const raS = String(s.ra || "").replace(/\D/g, "");
                  return (raLimpoAudit && raS.includes(raLimpoAudit)) || 
                         (s.nome && s.nome.trim().toUpperCase() === auditado.nome.trim().toUpperCase());
                });

                if (alLocal) {
                  alLocal.presenca_anual = `${auditado.pctPresenca}%`;
                  alLocal.frequencia_atual = `${auditado.pctPresenca}%`;
                  alLocal.presenca = `${auditado.pctPresenca}%`;
                  alLocal.total_faltas = auditado.totalFaltas;
                  alLocal.aulas_dadas_apuradas = auditado.totalAulasDadas || turmaItem.totalAulasDadas;
                  alLocal.frequencia_sed_status = auditado.situacaoFrequencia;
                  alLocal.parou_de_faltar = !!auditado.parouDeFaltar;
                  alLocal.continua_faltando = !!auditado.continuaFaltando;
                  alLocal.tendencia_frequencia_status = auditado.tendenciaRecente?.status || 'ESTAVEL';
                  alLocal.dias_seguidos_presente = auditado.diasSeguidosPresente || 0;
                  alLocal.dias_seguidos_faltando = auditado.diasSeguidosFaltando || 0;
                  alLocal.pct_recente = auditado.pctRecente || 0;
                  totalAtualizadosMemoria++;
                }
              });
            });

            try {
              localStorage.setItem("alunos_cache", JSON.stringify(window.allStudentsData));
            } catch (e) {}

            // Atualiza tabelas e gráficos em tempo real
            if (typeof applyStudentFilters === "function") applyStudentFilters();
            if (typeof atualizarDashboardGraficos === "function") atualizarDashboardGraficos();
            if (typeof renderBuscaAtiva === "function") renderBuscaAtiva();
          }

          const countSalvos = resJson.atualizadosCount || totalAtualizadosMemoria;
          alert(`Sucesso! ${countSalvos} estudantes de ${turmas.length} turma(s) foram atualizados com as presenças diárias e aulas dadas da SED. A Busca Ativa foi recalculada automaticamente com as tendências (parou de faltar / continua faltando)!`);

          if (typeof window.showToast === "function") {
            window.showToast(`${countSalvos} estudantes atualizados na Base Escolar e Busca Ativa!`, "success", 5000);
          }
        } catch (err) {
          console.error("Erro ao salvar frequência na base:", err);
          alert("Erro ao gravar frequência: " + (err.message || err));
        } finally {
          if (btnSalvar) {
            btnSalvar.disabled = false;
            btnSalvar.innerHTML = `<i class="fa-solid fa-circle-check"></i><span>Atualizado com Sucesso</span>`;
          }
        }
      };

      window.salvarFrequenciaDiariaNaBase = window.salvarTodasTurmasFreqNaBase;

      // EXPORTAÇÃO EM MASSA / IMPRESSÃO EM LOTE (A4 COM QUEBRA DE PÁGINA AUTOMÁTICA)
      window.imprimirRelatorioFrequenciaEmLote = function() {
        const resultado = window._resultadoMultiTurmasFreqSed;
        const turmas = resultado?.turmas || (resultado?.dados ? [resultado.dados] : (window._ultimoResultadoFrequenciaSed ? [window._ultimoResultadoFrequenciaSed] : []));

        if (!turmas || turmas.length === 0) {
          alert("Nenhuma turma carregada para impressão.");
          return;
        }

        const printWindow = window.open("", "_blank");
        if (!printWindow) {
          window.print();
          return;
        }

        const dataExtenso = new Date().toLocaleDateString("pt-BR", { day: "numeric", month: "long", year: "numeric" });
        const totalEstudantesGeral = turmas.reduce((acc, t) => acc + (t.alunos?.length || 0), 0);
        const pararamGeral = turmas.reduce((acc, t) => acc + (t.alunos?.filter(a => a.parouDeFaltar)?.length || 0), 0);
        const continuaGeral = turmas.reduce((acc, t) => acc + (t.alunos?.filter(a => a.continuaFaltando)?.length || 0), 0);

        let htmlCorpo = `
          <!DOCTYPE html>
          <html lang="pt-BR">
          <head>
            <meta charset="UTF-8">
            <title>Relatório Oficial de Auditoria de Frequência SED - Clóvis de Lucca</title>
            <style>
              @page { size: A4 portrait; margin: 12mm; }
              body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif; padding: 10px; color: #0f172a; line-height: 1.3; font-size: 11px; }
              .header { text-align: center; border-bottom: 2px solid #0f172a; padding-bottom: 8px; margin-bottom: 12px; }
              .header h1 { font-size: 14px; margin: 0; text-transform: uppercase; color: #0f172a; letter-spacing: 0.5px; }
              .header p { font-size: 10px; margin: 2px 0 0; color: #475569; }
              .resumo-executivo { background: #f8fafc; border: 1px solid #cbd5e1; border-radius: 6px; padding: 8px 12px; margin-bottom: 14px; display: flex; justify-content: space-between; font-size: 10px; }
              table { width: 100%; border-collapse: collapse; font-size: 10px; margin-top: 6px; }
              th, td { border: 1px solid #cbd5e1; padding: 4px 6px; text-align: left; }
              th { background-color: #f1f5f9; text-transform: uppercase; font-size: 9px; font-weight: 800; }
              .text-center { text-align: center; }
              .font-mono { font-family: monospace; }
              .critico { background-color: #ffe4e6; font-weight: bold; color: #9f1239; }
              .parou-badge { background-color: #dcfce7; color: #166534; font-weight: bold; padding: 1px 4px; border-radius: 4px; }
              .continua-badge { background-color: #fee2e2; color: #991b1b; font-weight: bold; padding: 1px 4px; border-radius: 4px; }
              .quebra-pagina { page-break-before: always; break-before: page; }
              .footer { margin-top: 16px; font-size: 9px; color: #64748b; text-align: right; border-top: 1px solid #e2e8f0; padding-top: 6px; }
              @media print { body { padding: 0; } }
            </style>
          </head>
          <body>
            <!-- PÁGINA 1: CAPA / RESUMO EXECUTIVO DE TODAS AS TURMAS -->
            <div class="header">
              <h1>GOVERNO DO ESTADO DE SÃO PAULO - SECRETARIA DA EDUCAÇÃO</h1>
              <p>EE PROF. CLÓVIS DE LUCCA · DIRETORIA REGIONAL DE ENSINO LESTE 4</p>
              <p><strong>RELATÓRIO CONSOLIDADO DE AUDITORIA DE FREQUÊNCIA SED (MULTI-TURMAS)</strong></p>
            </div>

            <div class="resumo-executivo">
              <div><strong>Turmas Processadas:</strong> ${turmas.length} turmas</div>
              <div><strong>Total Estudantes:</strong> ${totalEstudantesGeral}</div>
              <div><strong style="color: #166534;">✓ Pararam de Faltar:</strong> ${pararamGeral} alunos</div>
              <div><strong style="color: #991b1b;">⚠️ Continuam Faltando:</strong> ${continuaGeral} alunos</div>
            </div>

            <h3 style="font-size: 11px; text-transform: uppercase; margin: 10px 0 4px; color: #0f172a;">Quadro Geral por Turma</h3>
            <table>
              <thead>
                <tr>
                  <th>Turma</th>
                  <th>Disciplina</th>
                  <th class="text-center">Aulas Dadas</th>
                  <th class="text-center">Estudantes</th>
                  <th class="text-center">Média Turma</th>
                  <th class="text-center">Pararam de Faltar</th>
                  <th class="text-center">Continuam Faltando</th>
                  <th class="text-center">Busca Ativa (&lt;75%)</th>
                </tr>
              </thead>
              <tbody>
                ${turmas.map(t => `
                  <tr>
                    <td><strong>${t.turmaNormalizada}</strong></td>
                    <td>${t.disciplina || 'Geral'}</td>
                    <td class="text-center font-mono">${t.totalAulasDadas}</td>
                    <td class="text-center font-mono">${t.alunos?.length || 0}</td>
                    <td class="text-center font-mono font-bold">${t.taxaPresencaMediaTurma}%</td>
                    <td class="text-center font-mono text-emerald-800">${t.totais?.alunosPararamDeFaltar || 0}</td>
                    <td class="text-center font-mono text-rose-800">${t.totais?.alunosContinuamFaltando || 0}</td>
                    <td class="text-center font-mono ${t.totais?.alunosRiscoCritico > 0 ? 'critico' : ''}">${t.totais?.alunosRiscoCritico || 0}</td>
                  </tr>
                `).join("")}
              </tbody>
            </table>
            <div class="footer">
              Emitido pelo Sistema Integrado Clóvis de Lucca em ${dataExtenso} · Página Resumo
            </div>
        `;

        // PÁGINAS INDIVIDUAIS DE CADA TURMA
        turmas.forEach((t, idx) => {
          htmlCorpo += `
            <div class="quebra-pagina">
              <div class="header">
                <h1>EE PROF. CLÓVIS DE LUCCA · AUDITORIA DE FREQUÊNCIA</h1>
                <p><strong>TURMA: ${t.turmaNormalizada}</strong> · Mês: ${t.mes || 'Mês'}/${t.anoLetivo || '2026'} · Disciplina: ${t.disciplina || 'Geral'}</p>
              </div>

              <div class="resumo-executivo">
                <div><strong>Aulas Dadas:</strong> ${t.totalAulasDadas} (${t.diasLetivosCount} dias letivos)</div>
                <div><strong>Assiduidade da Turma:</strong> ${t.taxaPresencaMediaTurma}%</div>
                <div><strong style="color: #166534;">✓ Pararam de Faltar:</strong> ${t.totais?.alunosPararamDeFaltar || 0}</div>
                <div><strong style="color: #991b1b;">⚠️ Continuam Faltando:</strong> ${t.totais?.alunosContinuamFaltando || 0}</div>
                <div><strong>Busca Ativa (&lt;75%):</strong> ${t.totais?.alunosRiscoCritico || 0}</div>
              </div>

              <table>
                <thead>
                  <tr>
                    <th class="text-center" style="width: 25px;">Nº</th>
                    <th>Nome do Estudante</th>
                    <th>RA Oficial</th>
                    <th class="text-center">Presenças</th>
                    <th class="text-center">Aulas</th>
                    <th class="text-center">Faltas</th>
                    <th class="text-center">% Assiduidade</th>
                    <th class="text-center">Tendência Recente</th>
                    <th class="text-center">Situação</th>
                  </tr>
                </thead>
                <tbody>
                  ${(t.alunos || []).map(a => `
                    <tr class="${a.pctPresenca < 75 ? 'critico' : ''}">
                      <td class="text-center font-mono">${a.numChamada}</td>
                      <td><strong>${a.nome}</strong></td>
                      <td class="font-mono">${a.ra}</td>
                      <td class="text-center font-mono">${a.totalPresencas}</td>
                      <td class="text-center font-mono">${a.totalAulasDadas}</td>
                      <td class="text-center font-mono">${a.totalFaltas}</td>
                      <td class="text-center font-mono"><strong>${a.pctPresenca}%</strong></td>
                      <td class="text-center">
                        ${a.parouDeFaltar ? `<span class="parou-badge">✓ Parou de Faltar</span>` : (a.continuaFaltando ? `<span class="continua-badge">⚠️ Continua Faltando</span>` : 'Estável')}
                      </td>
                      <td class="text-center">${a.pctPresenca < 75 ? 'BUSCA ATIVA' : (a.pctPresenca < 85 ? 'ATENÇÃO' : 'REGULAR')}</td>
                    </tr>
                  `).join("")}
                </tbody>
              </table>
              <div class="footer">
                Turma ${t.turmaNormalizada} · Clóvis de Lucca · Emitido em ${dataExtenso} · Folha ${idx + 2} de ${turmas.length + 1}
              </div>
            </div>
          `;
        });

        htmlCorpo += `
          </body>
          </html>
        `;

        printWindow.document.write(htmlCorpo);
        printWindow.document.close();
        printWindow.focus();
        setTimeout(() => printWindow.print(), 500);
      };

      window.imprimirRelatorioFrequenciaTurma = window.imprimirRelatorioFrequenciaEmLote;

      // EXPORTAÇÃO CSV DE TODAS AS TURMAS EM LOTE
      window.exportarPlanilhaFrequenciaSed = function() {
        const resultado = window._resultadoMultiTurmasFreqSed;
        const turmas = resultado?.turmas || (resultado?.dados ? [resultado.dados] : (window._ultimoResultadoFrequenciaSed ? [window._ultimoResultadoFrequenciaSed] : []));

        if (!turmas || turmas.length === 0) {
          alert("Nenhum dado auditado para exportar.");
          return;
        }

        const linhas = [
          ["Turma", "Numero", "Nome_Estudante", "RA_Oficial", "Presencas", "Aulas_Dadas", "Faltas_Reais", "Assiduidade_Pct", "Tendencia_Recente", "Dias_Seguidos_Presente", "Dias_Seguidos_Ausente", "Situacao"]
        ];

        turmas.forEach(t => {
          (t.alunos || []).forEach(a => {
            let tendenciaStr = "Estavel";
            if (a.parouDeFaltar) tendenciaStr = "Parou de Faltar (Retomou)";
            else if (a.continuaFaltando) tendenciaStr = "Continua Faltando (Ausente)";

            linhas.push([
              t.turmaNormalizada,
              a.numChamada,
              `"${(a.nome || '').replace(/"/g, '""')}"`,
              `"${a.ra}"`,
              a.totalPresencas,
              a.totalAulasDadas,
              a.totalFaltas,
              `${a.pctPresenca}%`,
              `"${tendenciaStr}"`,
              a.diasSeguidosPresente || 0,
              a.diasSeguidosFaltando || 0,
              a.pctPresenca < 75 ? "BUSCA_ATIVA" : (a.pctPresenca < 85 ? "ATENCAO" : "REGULAR")
            ]);
          });
        });

        const csvContent = "\uFEFF" + linhas.map(e => e.join(";")).join("\n");
        const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
        const link = document.createElement("a");
        const url = URL.createObjectURL(blob);
        link.setAttribute("href", url);
        link.setAttribute("download", `auditoria_frequencia_sed_lote_${new Date().toISOString().slice(0, 10)}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
      };

      function inicializarDropzoneFreqSed() {
        const dropzone = document.getElementById("dropzone-freq-sed-pdf");
        if (dropzone && !dropzone._dragBound) {
          dropzone._dragBound = true;
          dropzone.addEventListener("dragover", (e) => {
            e.preventDefault();
            dropzone.classList.add("border-cyan-600", "bg-cyan-100/70");
          });
          dropzone.addEventListener("dragleave", () => {
            dropzone.classList.remove("border-cyan-600", "bg-cyan-100/70");
          });
          dropzone.addEventListener("drop", (e) => {
            e.preventDefault();
            dropzone.classList.remove("border-cyan-600", "bg-cyan-100/70");
            const files = Array.from(e.dataTransfer?.files || []);
            if (files.length > 0) {
              window.handleArquivoFreqSedSelecionado({ target: { files } });
            }
          });
        }
      }
      document.addEventListener("DOMContentLoaded", inicializarDropzoneFreqSed);
      window.inicializarDropzoneFreqSed = inicializarDropzoneFreqSed;

      const btnProcessarFreq = document.getElementById("btn-processar-freq");
      const fileFreqInput = document.getElementById("fileFreq");
      const resultadoFreq = document.getElementById("resultado-freq");

      if (btnProcessarFreq && fileFreqInput) {
        btnProcessarFreq.addEventListener("click", async () => {
          const file = fileFreqInput.files?.[0];
          if (!file) {
            alert("Por favor, selecione um arquivo Excel (.xlsx) de frequência da SED.");
            return;
          }

          const dataRefEl = document.getElementById("dataRefFreq");
          let dataRefInput = dataRefEl?.value;
          if (!dataRefInput) {
            dataRefInput = new Date().toISOString().substring(0, 10);
            if (dataRefEl) dataRefEl.value = dataRefInput;
          }
          const dataRefFormatted = formatarDataBR(dataRefInput) || new Date().toLocaleDateString("pt-BR");
          const dataNovaIso = dataRefInput;

          btnProcessarFreq.disabled = true;
          btnProcessarFreq.innerHTML = `<i class="fa-solid fa-spinner animate-spin text-xs"></i><span>Processando Frequência...</span>`;
          if (resultadoFreq) {
            resultadoFreq.innerHTML = `<p class="text-xs text-slate-500 font-semibold flex items-center gap-2"><i class="fa-solid fa-spinner animate-spin"></i> Lendo arquivo .xlsx...</p>`;
          }

          try {
            const buffer = await file.arrayBuffer();
            if (typeof XLSX === "undefined") {
              throw new Error("Biblioteca SheetJS (XLSX) não foi encontrada.");
            }

            const workbook = XLSX.read(buffer, { type: "array" });
            const firstSheetName = workbook.SheetNames[0];
            const worksheet = workbook.Sheets[firstSheetName];
            const rows = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

            if (!rows || rows.length <= 1) {
              if (resultadoFreq) {
                resultadoFreq.innerHTML = `<p class="text-xs text-red-600 font-bold">Arquivo .xlsx sem dados ou sem linhas de conteúdo.</p>`;
              }
              btnProcessarFreq.disabled = false;
              btnProcessarFreq.innerHTML = `<i class="fa-solid fa-cloud-arrow-up text-xs"></i><span>Processar Frequência da Turma</span>`;
              return;
            }

            // Pula a primeira linha, que é o cabeçalho
            const dataRows = rows.slice(1);

            // Mapeamento em memória por RA limpo a partir de window.allStudentsData (ZERO LEITURAS FIRESTORE)
            const studentsSource = Array.isArray(window.allStudentsData) && (window.allStudentsData || []).length > 0
              ? window.allStudentsData
              : ((window.allStudentsData || []));

            const studentsMapByRA = new Map();
            studentsSource.forEach(s => {
              if (s && s.ra) {
                const cleanS = String(s.ra).replace(/\D/g, "").substring(0, 12);
                studentsMapByRA.set(cleanS, s);
              }
            });

            // Validação de Ordem Cronológica das Planilhas
            let dataInconsistenteEncontrada = false;
            let dataMaisRecenteExistente = "";

            for (let i = 0; i < dataRows.length; i++) {
              const row = dataRows[i];
              if (!row || !Array.isArray(row)) continue;
              let raRaw = row[0] !== undefined && row[0] !== null ? String(row[0]).trim() : "";
              let digRaw = row[1] !== undefined && row[1] !== null ? String(row[1]).trim() : "";
              let raLimpo = String(digRaw ? raRaw + digRaw : raRaw).replace(/\D/g, '').substring(0, 12);
              const sMatch = studentsMapByRA.get(raLimpo);
              if (sMatch && sMatch.frequencia_atual) {
                const existingDateStr = typeof sMatch.frequencia_atual === 'object' ? sMatch.frequencia_atual.data : "";
                if (existingDateStr) {
                  const existingDateIso = window.parseDataToIso ? window.parseDataToIso(existingDateStr) : "";
                  if (existingDateIso && dataNovaIso <= existingDateIso) {
                    dataInconsistenteEncontrada = true;
                    dataMaisRecenteExistente = existingDateStr;
                    break;
                  }
                }
              }
            }

            if (dataInconsistenteEncontrada) {
              const prosseguir = confirm(
                `⚠️ ALERTA DE INCONSISTÊNCIA DE DATA SED:\n\n` +
                `A data de referência selecionada (${dataRefFormatted}) é IGUAL ou ANTERIOR à data da atualização mais recente no banco de dados (${dataMaisRecenteExistente}).\n\n` +
                `Importar planilhas fora da ordem cronológica atualizará o histórico (penúltima e última frequências) com dados mais antigos.\n\nDeseja prosseguir com a importação mesmo assim?`
              );
              if (!prosseguir) {
                btnProcessarFreq.disabled = false;
                btnProcessarFreq.innerHTML = `<i class="fa-solid fa-cloud-arrow-up text-xs"></i><span>Processar Frequência da Turma</span>`;
                if (resultadoFreq) {
                  resultadoFreq.innerHTML = `<p class="text-xs text-amber-800 font-bold p-3 bg-amber-50 rounded-lg border border-amber-200"><i class="fa-solid fa-circle-exclamation mr-1"></i> Importação cancelada pelo usuário devido à inconsistência de data de referência.</p>`;
                }
                return;
              }
            }

            let inconsistenciasCount = 0;
            const alunosNovos = [];
            const rasNoExcel = new Set();
            const turmasPresentesNoExcel = new Set();
            const pendingUpdates = [];

            for (let i = 0; i < dataRows.length; i++) {
              const row = dataRows[i];
              if (!row || !Array.isArray(row) || row.length === 0) continue;

              // Mapeamento: Coluna 0 (RA), Coluna 1 (DIG), Coluna 2 (Nome), Coluna 4 (% Presença Anual - Coluna E)
              let raRaw = row[0] !== undefined && row[0] !== null ? String(row[0]).trim() : "";
              let digRaw = row[1] !== undefined && row[1] !== null ? String(row[1]).trim() : "";
              let nomeAluno = row[2] !== undefined && row[2] !== null ? String(row[2]).trim().toUpperCase() : "";
              let presencaRaw = row[4] !== undefined && row[4] !== null ? row[4] : "";

              // 1. Ignorar exclusivamente o rodapé/metadados da SED
              if (raRaw.toLowerCase().includes('filtros aplicados') || 
                  raRaw.toLowerCase().includes('diretoria') || 
                  raRaw.toLowerCase().includes('escola') ||
                  nomeAluno.toLowerCase().includes('filtros aplicados')) {
                continue;
              }

              // 2. Limpar o RA (pegando os 12 primeiros dígitos numéricos)
              let raJunto = digRaw ? (raRaw + digRaw) : raRaw;
              let raLimpo = String(raJunto).replace(/\D/g, '').substring(0, 12);

              // 3. Validações básicas de segurança
              if (!nomeAluno || !raLimpo || raLimpo.length < 5) continue;

              rasNoExcel.add(raLimpo);

              let presencaAnualFormatada = formatarPresencaVal(presencaRaw);

              // Busca de correspondência 100% em memória
              let matchedStudentData = studentsMapByRA.get(raLimpo);

              if (matchedStudentData) {
                if (matchedStudentData.turma) {
                  turmasPresentesNoExcel.add(String(matchedStudentData.turma).toUpperCase().trim());
                }

                // 1. Deslocamento de Estados: a frequencia_atual existente vira frequencia_anterior (Penúltima)
                let oldFreqAtualObj = null;
                if (matchedStudentData.frequencia_atual) {
                  if (typeof matchedStudentData.frequencia_atual === "object") {
                    oldFreqAtualObj = {
                      valor: matchedStudentData.frequencia_atual.valor || "0%",
                      data: matchedStudentData.frequencia_atual.data || "Anterior"
                    };
                  } else {
                    oldFreqAtualObj = {
                      valor: formatarPresencaVal(matchedStudentData.frequencia_atual),
                      data: matchedStudentData.ultima_atualizacao_freq ? formatarDataBR(matchedStudentData.ultima_atualizacao_freq) : "Anterior"
                    };
                  }
                } else if (matchedStudentData.presenca_anual) {
                  oldFreqAtualObj = {
                    valor: formatarPresencaVal(matchedStudentData.presenca_anual),
                    data: "Base SED"
                  };
                }

                // 2. Definir nova frequencia_atual (Última)
                const newFreqAtualObj = {
                  valor: presencaAnualFormatada,
                  data: dataRefFormatted
                };

                // 3. Checar anomalia de variação (> 30% ou fora de padrão)
                const numNovo = window.parsePresencaNum ? window.parsePresencaNum(presencaAnualFormatada) : null;
                const numAnt = oldFreqAtualObj && window.parsePresencaNum ? window.parsePresencaNum(oldFreqAtualObj.valor) : null;
                if (numNovo !== null && numAnt !== null) {
                  const diff = Math.abs(numNovo - numAnt);
                  if (diff > 30 || numNovo < 0 || numNovo > 100) {
                    inconsistenciasCount++;
                  }
                }

                const nowIso = new Date().toISOString();
                const targetRa = String(matchedStudentData.ra || raLimpo);

                pendingUpdates.push({
                  matchedStudentData,
                  targetRa,
                  newFreqAtualObj,
                  oldFreqAtualObj,
                  presencaAnualFormatada,
                  nowIso
                });
              } else {
                // Aluno novo / não encontrado no banco
                alunosNovos.push({
                  ra: raLimpo,
                  nome: nomeAluno,
                  presenca: presencaAnualFormatada
                });
              }
            }

            // 2. Gravação em Lotes Inteligentes (Chunks de no máximo 450 operações por batch)
            const CHUNK_SIZE = 450;
            let atualizadosCount = 0;

            for (let i = 0; i < pendingUpdates.length; i += CHUNK_SIZE) {
              const chunk = pendingUpdates.slice(i, i + CHUNK_SIZE);
              const batch = writeBatch(db);

              chunk.forEach(item => {
                const docRef = doc(db, "alunos", item.targetRa);
                batch.update(docRef, {
                  frequencia_atual: item.newFreqAtualObj,
                  frequencia_anterior: item.oldFreqAtualObj || null,
                  presenca_atual: item.presencaAnualFormatada,
                  presenca_anual: item.presencaAnualFormatada,
                  presenca_26_06: item.presencaAnualFormatada,
                  data_atualizacao_sed: dataRefFormatted,
                  ultima_atualizacao_freq: item.nowIso
                });
              });

              await batch.commit();
              atualizadosCount += chunk.length;
            }

            // 3. Atualização Otimista da Interface diretamente em window.allStudentsData
            pendingUpdates.forEach(item => {
              const st = item.matchedStudentData;
              st.frequencia_anterior = item.oldFreqAtualObj;
              st.frequencia_atual = item.newFreqAtualObj;
              st.presenca_atual = item.presencaAnualFormatada;
              st.presenca_anual = item.presencaAnualFormatada;
              st.presenca_26_06 = item.presencaAnualFormatada;
              st.data_atualizacao_sed = dataRefFormatted;
              st.ultima_atualizacao_freq = item.nowIso;
            });

            // Cruzamento Bidirecional em Memória (Alunos ativos na mesma turma não presentes no Excel)
            const alunosAusentes = [];
            studentsSource.forEach(s => {
              const status = (s.status || "ativo").toLowerCase().trim();
              if (status !== "ativo") return;

              const sTurma = String(s.turma || "").toUpperCase().trim();
              const turmaCorresponde = turmasPresentesNoExcel.size === 0 || turmasPresentesNoExcel.has(sTurma);

              if (turmaCorresponde) {
                const cleanS = String(s.ra || "").replace(/\D/g, "").substring(0, 12);
                if (!rasNoExcel.has(cleanS)) {
                  alunosAusentes.push({
                    ra: s.ra,
                    nome: s.nome || "Aluno Sem Nome",
                    turma: s.turma || "-"
                  });
                }
              }
            });

            // Mapeamento global para modal rápido
            window.novosAlunosSEDMap = {};
            alunosNovos.forEach(item => {
              window.novosAlunosSEDMap[item.ra] = item;
            });

            // Exibir resultado
            if (resultadoFreq) {
              let reportHtml = `
                <div class="p-4 bg-slate-50 border border-slate-200 rounded-xl space-y-3">
                  <div class="flex items-center gap-2 text-xs font-bold text-emerald-700">
                    <i class="fa-solid fa-circle-check text-emerald-600 text-sm"></i>
                    <span>Processamento Concluído: <strong>${atualizadosCount}</strong> aluno(s) atualizados com sucesso em ${dataRefFormatted}.</span>
                  </div>
              `;

              if (inconsistenciasCount > 0) {
                reportHtml += `
                  <div class="p-2.5 bg-amber-50 border border-amber-300 rounded-lg text-xs text-amber-900 font-bold flex items-center gap-2">
                    <i class="fa-solid fa-triangle-exclamation text-amber-700 text-sm shrink-0"></i>
                    <span>Sinalização SED: ${inconsistenciasCount} aluno(s) apresentaram variação atípica de presença (> 30%) e foram marcados com o selo "Inconsistência SED".</span>
                  </div>
                `;
              }

              if (alunosNovos.length > 0) {
                reportHtml += `
                  <div class="border-t border-slate-200 pt-3">
                    <div id="header-alunos-novos-pendentes" class="mb-2">
                      <p class="text-xs font-bold text-amber-800 uppercase tracking-wider flex items-center gap-1.5">
                        <i class="fa-solid fa-user-plus text-amber-600"></i>
                        <span>Alunos Novos / Não Cadastrados no Banco (<span id="count-novos-pendentes">${alunosNovos.length}</span>):</span>
                      </p>
                    </div>
                    <div id="container-lista-alunos-novos" class="max-h-64 overflow-y-auto space-y-2 custom-scrollbar pr-1">
                `;
                alunosNovos.forEach(item => {
                  reportHtml += `
                    <div id="card-novo-aluno-${item.ra}" class="flex flex-col sm:flex-row sm:items-center justify-between bg-white p-2.5 rounded-lg border border-amber-200 text-xs gap-2 shadow-2xs">
                      <div>
                        <span class="font-bold text-slate-800 block">${item.nome}</span>
                        <div class="flex items-center gap-2 mt-0.5">
                          <span class="font-mono text-slate-500 text-[11px]">RA: ${item.ra}</span>
                          <span class="px-2 py-0.5 bg-emerald-50 text-emerald-700 font-bold rounded text-[10px] border border-emerald-200">
                            Freq. SED: ${item.presenca}
                          </span>
                        </div>
                      </div>
                      <button 
                        type="button"
                        onclick="abrirModalCadastroRapido('${item.ra}')"
                        class="px-3 py-1.5 bg-blue-700 hover:bg-blue-800 text-white font-bold rounded-lg text-xs transition cursor-pointer flex items-center gap-1.5 whitespace-nowrap shadow-xs"
                      >
                        <i class="fa-solid fa-user-plus text-[11px]"></i>
                        <span>Cadastrar Ficha do Aluno</span>
                      </button>
                    </div>
                  `;
                });
                reportHtml += `
                    </div>
                  </div>
                `;
              }

              if (alunosAusentes.length > 0) {
                reportHtml += `
                  <div class="border-t border-slate-200 pt-3">
                    <div class="mb-2">
                      <p class="text-xs font-bold text-red-800 uppercase tracking-wider flex items-center gap-1.5">
                        <i class="fa-solid fa-triangle-exclamation text-red-600"></i>
                        <span>⚠️ Alunos Ausentes na Listagem da SED (Possíveis Saídas/Transferências) (${alunosAusentes.length}):</span>
                      </p>
                    </div>
                    <div class="max-h-64 overflow-y-auto space-y-2 custom-scrollbar pr-1">
                `;
                alunosAusentes.forEach(item => {
                  reportHtml += `
                    <div class="flex flex-col sm:flex-row sm:items-center justify-between bg-white p-2.5 rounded-lg border border-red-200 text-xs gap-2 shadow-2xs">
                      <div>
                        <span class="font-bold text-slate-800 block">${item.nome}</span>
                        <div class="flex items-center gap-2 mt-0.5">
                          <span class="font-mono text-slate-500 text-[11px]">RA: ${item.ra}</span>
                          <span class="px-2 py-0.5 bg-blue-50 text-blue-700 font-bold rounded text-[10px] border border-blue-200">
                            Turma: ${item.turma}
                          </span>
                        </div>
                      </div>
                      <button 
                        type="button"
                        onclick="abrirFichaAluno('${item.ra}')"
                        class="px-3 py-1.5 bg-amber-600 hover:bg-amber-700 text-white font-bold rounded-lg text-xs transition cursor-pointer flex items-center gap-1.5 whitespace-nowrap shadow-xs"
                      >
                        <i class="fa-solid fa-pen-to-square text-[11px]"></i>
                        <span>Ver Ficha / Alterar Status</span>
                      </button>
                    </div>
                  `;
                });
                reportHtml += `
                    </div>
                  </div>
                `;
              }

              reportHtml += `</div>`;
              resultadoFreq.innerHTML = reportHtml;
            }

            fileFreqInput.value = "";

            if (typeof window.showToast === "function") {
              window.showToast(`Frequência SED atualizada com sucesso! ${atualizadosCount} aluno(s) processados.`, 'success');
            }

            // Atualizar interface localmente sem re-executar getDocs no Banco de Dados
            if (typeof populateFilterSelects === "function") populateFilterSelects(studentsSource);
            if (typeof applyStudentFilters === "function") applyStudentFilters();
            if (typeof atualizarDashboardGraficos === "function") atualizarDashboardGraficos();
            if (typeof renderBuscaAtiva === "function") renderBuscaAtiva();
          } catch (err) {
            console.error("Erro ao importar frequência SED:", err);
            if (resultadoFreq) {
              resultadoFreq.innerHTML = `<p class="text-xs text-red-600 font-bold">Erro ao processar arquivo: ${err.message || err}</p>`;
            }
          } finally {
            btnProcessarFreq.disabled = false;
            btnProcessarFreq.innerHTML = `<i class="fa-solid fa-cloud-arrow-up text-xs"></i><span>Processar Frequência da Turma</span>`;
          }
        });
      }

      // ========================================================
      // MÓDULO DE FECHAMENTO DE NOTAS BIMESTRAIS (SED)
      // ========================================================
      const btnProcessarFechamento = document.getElementById("btn-processar-fechamento-notas");
      const fileFechamentoInput = document.getElementById("fileFechamentoNotas");
      const selectBimestreFechamento = document.getElementById("selectBimestreFechamento");
      const resultadoFechamento = document.getElementById("resultado-fechamento-notas");
      const btnToggleColar = document.getElementById("btn-toggle-colar-fechamento");
      const containerColar = document.getElementById("container-colar-fechamento");
      const textoColar = document.getElementById("textoColarFechamento");

      if (btnToggleColar && containerColar) {
        btnToggleColar.addEventListener("click", () => {
          containerColar.classList.toggle("hidden");
        });
      }

      if (btnProcessarFechamento) {
        btnProcessarFechamento.addEventListener("click", async () => {
          const file = fileFechamentoInput?.files?.[0];
          const textoColadoVal = textoColar?.value?.trim();

          if (!file && !textoColadoVal) {
            alert("Por favor, selecione um arquivo (.xlsx, .pdf ou .csv) ou cole o texto do fechamento de notas da SED.");
            return;
          }

          const manager = window.fechamentoNotasManager;
          if (!manager) {
            alert("Módulo gerenciador de fechamento de notas não carregado.");
            return;
          }

          const rawBimVal = selectBimestreFechamento?.value;
          const optBimestre = (!rawBimVal || rawBimVal === "auto")
            ? undefined
            : (rawBimVal === "FINAL" ? "FINAL" : parseInt(rawBimVal, 10));

          btnProcessarFechamento.disabled = true;
          btnProcessarFechamento.innerHTML = `<i class="fa-solid fa-spinner animate-spin text-xs"></i><span>Processando Fechamento...</span>`;
          if (resultadoFechamento) {
            resultadoFechamento.innerHTML = `<p class="text-xs text-slate-500 font-semibold flex items-center gap-2"><i class="fa-solid fa-spinner animate-spin"></i> Lendo documento e identificando notas por estudante...</p>`;
          }

          try {
            let parsedResult = null;
            if (file) {
              const fileName = file.name.toLowerCase();
              const buffer = await file.arrayBuffer();

              if (fileName.endsWith(".pdf")) {
                parsedResult = await manager.parseFechamentoPDF(buffer, { bimestrePadrao: optBimestre });
              } else if (fileName.endsWith(".csv")) {
                const text = new TextDecoder("utf-8").decode(buffer);
                parsedResult = manager.parseFechamentoTexto(text, { bimestrePadrao: optBimestre });
              } else {
                parsedResult = await manager.parseFechamentoExcel(buffer, { bimestrePadrao: optBimestre });
              }
            } else if (textoColadoVal) {
              parsedResult = manager.parseFechamentoTexto(textoColadoVal, { bimestrePadrao: optBimestre });
            }

            if (!parsedResult || !parsedResult.alunos || parsedResult.alunos.length === 0) {
              throw new Error("Nenhum estudante ou nota foi identificado no arquivo fornecido. Verifique o formato do documento da SED.");
            }

            // Realizar Pareamento Inteligente por Turma e Nome Completo (Sem RA)
            const studentsSource = window.allStudentsData || [];
            const vinculos = manager.vincularAlunosComBase(parsedResult, studentsSource);

            const vinculados = vinculos.filter(v => v.alunoBase && v.alunoBase.ra);
            const naoVinculados = vinculos.filter(v => !v.alunoBase || !v.alunoBase.ra);

            const meta = parsedResult.metadata;
            let reportHtml = `
              <div class="p-4 bg-slate-50 border border-slate-200 rounded-xl space-y-4">
                <div class="flex flex-wrap items-center justify-between gap-2 border-b border-slate-200 pb-3">
                  <div>
                    <span class="text-[10px] font-extrabold uppercase text-indigo-700 block">${meta.tipoFechamento} &bull; Ano Letivo ${meta.anoLetivo}</span>
                    <h4 class="text-sm font-black text-slate-900 uppercase mt-0.5">${meta.turmaOriginal}</h4>
                    <span class="text-xs text-slate-500">${meta.disciplinasDetectadas.length} disciplinas &bull; Total Aulas: ${meta.totalAulasDadas || '—'}</span>
                  </div>
                  <div class="text-right">
                    <span class="px-3 py-1 bg-indigo-100 text-indigo-900 font-extrabold text-xs rounded-full uppercase">
                      ${meta.bimestreKey === 'FINAL' ? 'Fechamento Final (Conselho Anual)' : `${meta.bimestreKey} (${meta.bimestre}º Bimestre)`}
                    </span>
                  </div>
                </div>

                <!-- Estatísticas de Pareamento -->
                <div class="grid grid-cols-1 sm:grid-cols-3 gap-3 text-xs">
                  <div class="bg-white p-3 rounded-lg border border-slate-200 shadow-2xs">
                    <span class="text-[10px] font-bold text-slate-500 uppercase block">Estudantes no Arquivo</span>
                    <span class="text-lg font-black text-slate-800">${vinculos.length}</span>
                  </div>
                  <div class="bg-white p-3 rounded-lg border border-emerald-200 shadow-2xs">
                    <span class="text-[10px] font-bold text-emerald-700 uppercase block">Localizados no Sistema</span>
                    <span class="text-lg font-black text-emerald-700">${vinculados.length}</span>
                  </div>
                  <div class="bg-white p-3 rounded-lg border ${(naoVinculados.length > 0 ? 'border-amber-300' : 'border-slate-200')} shadow-2xs">
                    <span class="text-[10px] font-bold ${(naoVinculados.length > 0 ? 'text-amber-800' : 'text-slate-500')} uppercase block">Sem RA / Não Localizados</span>
                    <span class="text-lg font-black ${(naoVinculados.length > 0 ? 'text-amber-800' : 'text-slate-700')}">${naoVinculados.length}</span>
                  </div>
                </div>

                <!-- Lista de Pré-visualização -->
                <div class="space-y-2">
                  <div class="flex items-center justify-between">
                    <span class="text-xs font-bold text-slate-700 uppercase">Estudantes Prontos para Gravação (${vinculados.length}):</span>
                    <span class="text-[11px] text-slate-400">Cruzamento por Nome Completo e Turma</span>
                  </div>
                  <div class="max-h-48 overflow-y-auto space-y-1.5 custom-scrollbar pr-1 border border-slate-200 rounded-lg p-2 bg-white">
                    ${vinculados.map(v => `
                      <div class="flex items-center justify-between p-2 rounded bg-slate-50 hover:bg-slate-100 text-xs transition">
                        <div class="flex items-center gap-2">
                          <i class="fa-solid fa-circle-check text-emerald-600 text-xs"></i>
                          <div>
                            <span class="font-bold text-slate-800 block">${v.alunoParsed.nome}</span>
                            <span class="text-[10px] text-slate-500 font-mono">RA: ${v.alunoBase.ra} &bull; Turma Sistema: ${v.alunoBase.turma || '—'}</span>
                          </div>
                        </div>
                        <div class="text-right">
                          <span class="font-black text-blue-900">Média: ${v.alunoParsed.mediaGeral !== null ? v.alunoParsed.mediaGeral : '—'}</span>
                          <span class="text-[10px] text-slate-400 block">${v.alunoParsed.totalFaltas} faltas &bull; ${v.alunoParsed.frequenciaBimestre}</span>
                        </div>
                      </div>
                    `).join('')}
                  </div>
                </div>
            `;

            if (naoVinculados.length > 0) {
              reportHtml += `
                <div class="p-3 bg-amber-50 border border-amber-200 rounded-lg text-xs space-y-2">
                  <div class="flex items-center gap-2 font-bold text-amber-900">
                    <i class="fa-solid fa-triangle-exclamation text-amber-600"></i>
                    <span>${naoVinculados.length} estudante(s) do arquivo não foram encontrados no banco da turma:</span>
                  </div>
                  <div class="max-h-24 overflow-y-auto space-y-1 custom-scrollbar text-[11px] text-amber-800">
                    ${naoVinculados.map(nv => `
                      <div>&bull; <strong>${nv.alunoParsed.nome}</strong> (Situação: ${nv.alunoParsed.situacao})</div>
                    `).join('')}
                  </div>
                  <p class="text-[10px] text-amber-700">Verifique se o nome no cadastro possui grafia idêntica ou se o aluno já foi matriculado.</p>
                </div>
              `;
            }

            reportHtml += `
                <!-- Botões de Ação -->
                <div class="flex items-center gap-3 pt-2">
                  <button id="btn-confirmar-salvar-fechamento" type="button" class="px-5 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white font-extrabold text-xs rounded-lg uppercase tracking-wider shadow-sm transition flex items-center gap-2 cursor-pointer">
                    <i class="fa-solid fa-cloud-arrow-up"></i>
                    <span>Confirmar e Gravar ${vinculados.length} Alunos no Banco de Dados</span>
                  </button>
                  <button id="btn-cancelar-fechamento" type="button" class="px-3 py-2 bg-slate-200 hover:bg-slate-300 text-slate-700 font-bold text-xs rounded-lg uppercase transition cursor-pointer">
                    Cancelar
                  </button>
                </div>
              </div>
            `;

            resultadoFechamento.innerHTML = reportHtml;

            const btnConfirmar = document.getElementById("btn-confirmar-salvar-fechamento");
            const btnCancelar = document.getElementById("btn-cancelar-fechamento");

            if (btnCancelar) {
              btnCancelar.addEventListener("click", () => {
                resultadoFechamento.innerHTML = "";
                if (fileFechamentoInput) fileFechamentoInput.value = "";
                if (textoColar) textoColar.value = "";
              });
            }

            if (btnConfirmar) {
              btnConfirmar.addEventListener("click", async () => {
                btnConfirmar.disabled = true;
                btnConfirmar.innerHTML = `<i class="fa-solid fa-bolt text-amber-300 animate-pulse"></i> Gravando Notas no Banco de Dados...`;

                const totalEstudantes = vinculados.filter(v => v.alunoBase).length;

                // Exibir barra de progresso visual de alta performance
                resultadoFechamento.innerHTML = `
                  <div class="p-4 bg-indigo-50 border border-indigo-200 rounded-xl space-y-3 animate-fadeIn">
                    <div class="flex items-center justify-between text-xs font-bold text-indigo-900">
                      <span class="flex items-center gap-2">
                        <i class="fa-solid fa-bolt text-indigo-600 animate-pulse"></i>
                        <span>Gravando Notas no Banco de Dados (Lotes Paralelos Otimizados)...</span>
                      </span>
                      <span id="fechamento-progress-text" class="font-mono text-indigo-700 font-bold">15%</span>
                    </div>
                    <div class="w-full bg-indigo-200/80 rounded-full h-3 overflow-hidden shadow-inner">
                      <div id="fechamento-progress-bar" class="bg-indigo-600 h-3 rounded-full transition-all duration-300 ease-out" style="width: 15%"></div>
                    </div>
                    <div class="flex items-center justify-between text-[11px] text-indigo-700">
                      <span id="fechamento-progress-detail">Atualização otimista instantânea aplicada. Sincronizando com o banco...</span>
                      <span id="fechamento-progress-count" class="font-mono font-bold text-indigo-900">0 / ${totalEstudantes} alunos</span>
                    </div>
                  </div>
                `;

                const pBar = document.getElementById("fechamento-progress-bar");
                const pText = document.getElementById("fechamento-progress-text");
                const pCount = document.getElementById("fechamento-progress-count");

                try {
                  const saveResult = await manager.salvarFechamentoNoFirestore(vinculados, meta, (pct, salvos, total) => {
                    if (pBar) pBar.style.width = `${pct}%`;
                    if (pText) pText.textContent = `${pct}%`;
                    if (pCount && salvos !== undefined && total !== undefined) {
                      pCount.textContent = `${salvos} / ${total} alunos`;
                    }
                    if (btnConfirmar) {
                      btnConfirmar.innerHTML = `<i class="fa-solid fa-circle-notch animate-spin"></i> Gravando ${salvos || 0}/${total || totalEstudantes} (${pct}%)...`;
                    }
                  });

                  resultadoFechamento.innerHTML = `
                    <div class="p-4 bg-emerald-50 border border-emerald-300 rounded-xl space-y-2 animate-fadeIn">
                      <div class="flex items-center gap-2 text-xs font-bold text-emerald-900">
                        <i class="fa-solid fa-circle-check text-emerald-600 text-lg"></i>
                        <span>Fechamento do <strong>${meta.bimestreKey === 'FINAL' ? 'Conselho Final & Rendimento Anual' : `${meta.bimestre}º Bimestre`}</strong> gravado com sucesso para <strong>${saveResult.sucessos} estudantes</strong> da turma ${meta.turmaOriginal}!</span>
                      </div>
                      <p class="text-xs text-emerald-700">
                        As notas, faltas, menções e médias bimestrais foram registradas individualmente com alta velocidade e sem perda de dados.
                      </p>
                      <div class="pt-2 flex items-center gap-2">
                        <button type="button" onclick="if (typeof window.switchTab === 'function') window.switchTab('alunos');" class="px-3.5 py-1.5 bg-emerald-700 hover:bg-emerald-800 text-white font-bold text-xs rounded-lg uppercase transition cursor-pointer">
                          Ver Alunos da Turma
                        </button>
                      </div>
                    </div>
                  `;

                  if (fileFechamentoInput) fileFechamentoInput.value = "";
                  if (textoColar) textoColar.value = "";

                  if (typeof window.showToast === "function") {
                    const descToast = meta.bimestreKey === 'FINAL' ? 'Fechamento Final gravado com sucesso!' : `Notas do ${meta.bimestre}º Bimestre gravadas com sucesso!`;
                    window.showToast(descToast, 'success');
                  }

                  // Atualizar tabela de alunos se aberta
                  if (typeof applyStudentFilters === "function") applyStudentFilters();
                } catch (saveErr) {
                  console.error("Erro ao salvar fechamento:", saveErr);
                  alert("Erro ao gravar dados no banco de dados: " + (saveErr.message || saveErr));
                  btnConfirmar.disabled = false;
                  btnConfirmar.innerHTML = `<i class="fa-solid fa-cloud-arrow-up"></i> Tentar Gravar Novamente`;
                }
              });
            }

          } catch (err) {
            console.error("Erro ao processar fechamento de notas SED:", err);
            if (resultadoFechamento) {
              resultadoFechamento.innerHTML = `<p class="text-xs text-red-600 font-bold">Erro ao processar arquivo: ${err.message || err}</p>`;
            }
          } finally {
            btnProcessarFechamento.disabled = false;
            btnProcessarFechamento.innerHTML = `<i class="fa-solid fa-file-circle-check text-xs"></i><span>Processar e Vincular Notas da Turma</span>`;
          }
        });
      }

      // Handlers e Funções do Modal de Cadastro Rápido (Importação SED)
      window.abrirModalCadastroRapido = function(ra) {
        const item = window.novosAlunosSEDMap?.[ra];
        if (!item) {
          alert("Dados do aluno não encontrados.");
          return;
        }

        const elNome = document.getElementById("rapido-nome");
        const elRa = document.getElementById("rapido-ra");
        const elPresencaHidden = document.getElementById("rapido-presenca-hidden");
        const elDisplayPresenca = document.getElementById("rapido-display-presenca");

        if (elNome) elNome.value = item.nome || "";
        if (elRa) elRa.value = item.ra || "";
        if (elPresencaHidden) elPresencaHidden.value = item.presenca || "0%";
        if (elDisplayPresenca) elDisplayPresenca.textContent = item.presenca || "0%";

        // Limpar campos complementares PEI
        const elTurma = document.getElementById("rapido-turma");
        const elTutor = document.getElementById("rapido-tutor");
        const elClube = document.getElementById("rapido-clube");
        const elEletivas = document.getElementById("rapido-eletivas");
        const elProtagonismo = document.getElementById("rapido-protagonismo");

        if (elTurma) elTurma.value = "";
        if (elTutor) elTutor.value = "";
        if (elClube) elClube.value = "";
        if (elEletivas) elEletivas.value = "";
        if (elProtagonismo) elProtagonismo.value = "";

        const modal = document.getElementById("modal-cadastro-rapido-sed");
        if (modal) modal.classList.remove("hidden");
      };

      window.fecharModalCadastroRapido = function() {
        const modal = document.getElementById("modal-cadastro-rapido-sed");
        if (modal) modal.classList.add("hidden");
      };

      const formCadastroRapido = document.getElementById("form-modal-cadastro-rapido");
      if (formCadastroRapido) {
        formCadastroRapido.addEventListener("submit", async (e) => {
          e.preventDefault();
          const btnSalvar = document.getElementById("btn-salvar-modal-rapido");
          const nome = (document.getElementById("rapido-nome")?.value || "").trim().toUpperCase();
          const ra = (document.getElementById("rapido-ra")?.value || "").trim();
          const presenca = (document.getElementById("rapido-presenca-hidden")?.value || "").trim();
          const turma = (document.getElementById("rapido-turma")?.value || "").trim().toUpperCase();
          const tutor = (document.getElementById("rapido-tutor")?.value || "").trim().toUpperCase();
          const clube = (document.getElementById("rapido-clube")?.value || "").trim().toUpperCase();
          const eletivas = (document.getElementById("rapido-eletivas")?.value || "").trim().toUpperCase();
          const protagonismo = (document.getElementById("rapido-protagonismo")?.value || "").trim().toUpperCase();

          if (!ra || !nome) {
            alert("Nome e RA são obrigatórios.");
            return;
          }

          try {
            if (btnSalvar) {
              btnSalvar.disabled = true;
              btnSalvar.innerHTML = `<i class="fa-solid fa-spinner animate-spin text-xs"></i><span>Salvando...</span>`;
            }

            const newStudentObj = {
              nome: nome,
              ra: ra,
              turma: turma,
              tutor_2026: tutor,
              tutor: tutor,
              clube: clube,
              eletiva_1_2026: eletivas,
              eletivas: eletivas,
              protagonismo: protagonismo,
              presenca_anual: presenca,
              presenca_26_06: presenca,
              status: "ativo",
              ultima_atualizacao_freq: new Date().toISOString()
            };

            await setDoc(doc(db, "alunos", ra), newStudentObj);

            // Adicionar ao estado em memória
            const existingIdx = (window.allStudentsData || []).findIndex(s => s.ra === ra);
            if (existingIdx !== -1) {
              window.allStudentsData[existingIdx] = newStudentObj;
            } else {
              (window.allStudentsData = window.allStudentsData || []).push(newStudentObj);
            }

            alert(`Aluno(a) "${nome}" foi cadastrado(a) com sucesso e incluído(a) na escola!`);

            // Fechar modal
            window.fecharModalCadastroRapido();

            // Remover das pendências
            if (window.novosAlunosSEDMap) {
              delete window.novosAlunosSEDMap[ra];
            }
            const cardEl = document.getElementById(`card-novo-aluno-${ra}`);
            if (cardEl) {
              cardEl.remove();
            }

            // Atualizar cabeçalho / contador de pendências
            const containerNovos = document.getElementById("container-lista-alunos-novos");
            if (containerNovos && containerNovos.children.length === 0) {
              const headerNovos = document.getElementById("header-alunos-novos-pendentes");
              if (headerNovos) {
                headerNovos.innerHTML = `
                  <div class="flex items-center gap-2 text-emerald-700 font-bold text-xs p-2.5 bg-emerald-50 rounded-lg border border-emerald-200">
                    <i class="fa-solid fa-circle-check text-emerald-600"></i>
                    <span>Todos os alunos novos da importação SED foram cadastrados com sucesso!</span>
                  </div>
                `;
              }
            } else if (window.novosAlunosSEDMap) {
              const countRestante = Object.keys(window.novosAlunosSEDMap).length;
              const countSpan = document.getElementById("count-novos-pendentes");
              if (countSpan) countSpan.textContent = countRestante;
            }

            // Atualizar interface localmente sem re-executar getDocs
            if (typeof populateFilterSelects === "function") populateFilterSelects(window.allStudentsData || []);
            if (typeof applyStudentFilters === "function") applyStudentFilters();
            if (typeof atualizarDashboardGraficos === "function") atualizarDashboardGraficos();
            if (typeof renderBuscaAtiva === "function") renderBuscaAtiva();
          } catch (err) {
            console.error("Erro ao cadastrar aluno novo:", err);
            alert("Erro ao cadastrar aluno: " + (err.message || err));
          } finally {
            if (btnSalvar) {
              btnSalvar.disabled = false;
              btnSalvar.innerHTML = `<i class="fa-solid fa-user-check text-xs"></i><span>Salvar e Incluir na Escola</span>`;
            }
          }
        });
      }

      // ==========================================
      // ATRIBUIÇÃO EM MASSA (ELETIVAS E CLUBES JUVENIS)
      // ==========================================
      window.atualizarContadorSelecaoAlunos = function() {
        const checkboxes = document.querySelectorAll(".aluno-checkbox:checked");
        const count = checkboxes.length;
        const btnText = document.getElementById("btn-atribuir-lote-text");
        if (btnText) {
          btnText.textContent = `Atribuir Lote (${count})`;
        }

        const selectAll = document.getElementById("checkbox-selecionar-todos-alunos");
        const allCheckboxes = document.querySelectorAll(".aluno-checkbox");
        if (selectAll && allCheckboxes.length > 0) {
          selectAll.checked = (allCheckboxes.length === count);
          selectAll.indeterminate = (count > 0 && count < allCheckboxes.length);
        }
      };

      window.toggleSelecionarTodosAlunos = function(masterCheckbox) {
        const checked = masterCheckbox ? masterCheckbox.checked : false;
        const checkboxes = document.querySelectorAll(".aluno-checkbox");
        checkboxes.forEach(cb => {
          cb.checked = checked;
        });
        window.atualizarContadorSelecaoAlunos();
      };

      window.abrirModalAtribuicaoMassa = function() {
        const selecionados = document.querySelectorAll(".aluno-checkbox:checked");
        if (selecionados.length === 0) {
          alert("Nenhum aluno selecionado! Por favor, marque as caixas de seleção dos alunos na tabela.");
          return;
        }

        const qtdSpan = document.getElementById("atribuicao-massa-qtd-selecionados");
        if (qtdSpan) {
          qtdSpan.textContent = `${selecionados.length} ${selecionados.length === 1 ? 'aluno selecionado' : 'alunos selecionados'}`;
        }

        const inputValor = document.getElementById("atribuicao-massa-valor");
        if (inputValor) inputValor.value = "";

        const modal = document.getElementById("modal-atribuicao-massa");
        if (modal) modal.classList.remove("hidden");
      };

      window.fecharModalAtribuicaoMassa = function() {
        const modal = document.getElementById("modal-atribuicao-massa");
        if (modal) modal.classList.add("hidden");
      };

      window.salvarAtribuicaoMassa = async function() {
        const selecionados = document.querySelectorAll(".aluno-checkbox:checked");
        const ras = Array.from(selecionados).map(cb => cb.getAttribute("data-ra")).filter(Boolean);

        if (ras.length === 0) {
          alert("Nenhum aluno selecionado.");
          return;
        }

        const tipo = (document.getElementById("atribuicao-massa-tipo")?.value || "Eletiva").trim();
        const valor = (document.getElementById("atribuicao-massa-valor")?.value || "").trim().toUpperCase();

        if (!valor) {
          alert("Por favor, preencha o nome do valor ou disciplina a ser atribuído.");
          return;
        }

        const campoFirestore = tipo.toLowerCase() === "clube" ? "clube" : "eletivas";
        const btnSalvar = document.getElementById("btn-gravar-atribuicao-massa");

        try {
          if (btnSalvar) {
            btnSalvar.disabled = true;
            btnSalvar.innerHTML = `<i class="fa-solid fa-spinner animate-spin text-xs"></i><span>Gravando em Lote...</span>`;
          }

          // Gravação em Chunks (Máximo 450 operações por writeBatch)
          const CHUNK_SIZE = 450;
          for (let i = 0; i < ras.length; i += CHUNK_SIZE) {
            const chunk = ras.slice(i, i + CHUNK_SIZE);
            const batch = writeBatch(db);
            chunk.forEach(ra => {
              const alunoDocRef = doc(db, "alunos", ra);
              batch.update(alunoDocRef, { [campoFirestore]: valor });
            });
            await batch.commit();
          }

          // Atualização OTIMISTA em memória (Zero Reads adicionais)
          const rasSet = new Set(ras);
          if (Array.isArray(window.allStudentsData)) {
            window.allStudentsData.forEach(aluno => {
              if (aluno && rasSet.has(aluno.ra)) {
                aluno[campoFirestore] = valor;
              }
            });
          }

          // Registrar Log de Auditoria
          try {
            if (typeof window.registrarLogAuditoria === "function") {
              const userNome = window.auth?.currentUser?.displayName || window.auth?.currentUser?.email || "Direção PEI";
              await window.registrarLogAuditoria(
                "alunos",
                "ATRIBUIÇÃO EM MASSA",
                `Atribuiu ${tipo} "${valor}" para ${ras.length} estudante(s).`,
                userNome
              );
            }
          } catch (logErr) {
            console.warn("Falha ao gravar log de auditoria da atribuição em massa:", logErr);
          }

          // Fechar modal e desmarcar seleções
          window.fecharModalAtribuicaoMassa();
          const masterCheckbox = document.getElementById("checkbox-selecionar-todos-alunos");
          if (masterCheckbox) {
            masterCheckbox.checked = false;
            masterCheckbox.indeterminate = false;
          }

          // Re-renderizar a tabela e filtros em memória
          if (typeof populateFilterSelects === "function") {
            populateFilterSelects((window.allStudentsData || []));
          }
          if (typeof applyStudentFilters === "function") {
            applyStudentFilters();
          } else if (typeof window.filterStudents === "function") {
            window.filterStudents();
          }
          window.atualizarContadorSelecaoAlunos();

          alert(`Sucesso! ${tipo} "${valor}" foi atribuído(a) com sucesso para ${ras.length} aluno(s).`);
        } catch (err) {
          console.error("Erro ao gravar atribuição em lote:", err);
          alert("Erro ao gravar atribuição em lote: " + (err.message || err));
        } finally {
          if (btnSalvar) {
            btnSalvar.disabled = false;
            btnSalvar.innerHTML = `<i class="fa-solid fa-floppy-disk text-xs"></i><span>Gravar em Lote</span>`;
          }
        }
      };

      // Inicialização assíncrona automática em segundo plano para garantir que os 751 alunos estejam disponíveis
      setTimeout(() => {
        if (typeof window !== "undefined" && (!window.allStudentsData || window.allStudentsData.length < 500)) {
          if (typeof window.carregarTodosAlunos === "function") {
            window.carregarTodosAlunos(false).catch(() => {});
          }
        }
      }, 350);
    